window.OTANGSHI_DATA={"meta":{"count":319,"poets":77,"genres":["五言古诗","七言古诗","五言律诗","七言律诗","五言绝句","七言绝句"],"version":"1.0.0"},"poems":[{"id":"001","title":"感遇·其一","author":"张九龄","genre":"五言古诗","yuefu":false,"paragraphs":["孤鸿海上来，","池潢不敢顾。","侧见双翠鸟，","巢在三珠树。","矫矫珍木巅，","得无金丸惧。","美服患人指，","高明逼神恶。","今我游冥冥，","弋者何所慕。"]},{"id":"002","title":"感遇·其二","author":"张九龄","genre":"五言古诗","yuefu":false,"paragraphs":["兰叶春葳蕤，","桂华秋皎洁。","欣欣此生意，","自尔为佳节。","谁知林栖者，","闻风坐相悦。","草木有本心，","何求美人折？"]},{"id":"003","title":"感遇·其三","author":"张九龄","genre":"五言古诗","yuefu":false,"paragraphs":["幽人归独卧，","滞虑洗孤清。","持此谢高鸟，","因之传远情。","日夕怀空意，","人谁感至精？","飞沈理自隔，","何所慰吾诚？"]},{"id":"004","title":"感遇·其四","author":"张九龄","genre":"五言古诗","yuefu":false,"paragraphs":["江南有丹橘，","经冬犹绿林。","岂伊地气暖，","自有岁寒心。","可以荐嘉客，","奈何阻重深！","运命惟所遇，","循环不可寻。","徒言树桃李，","此木岂无阴？"]},{"id":"005","title":"下终南山过斛斯山人宿置酒","author":"李白","genre":"五言古诗","yuefu":false,"paragraphs":["暮从碧山下，","山月随人归，","却顾所来径，","苍苍横翠微。","相携及田家，","童稚开荆扉。","绿竹入幽径，","青萝拂行衣。","欢言得所憩，","美酒聊共挥。","长歌吟松风，","曲尽河星稀。","我醉君复乐，","陶然共忘机。"]},{"id":"006","title":"月下独酌·其一","author":"李白","genre":"五言古诗","yuefu":false,"paragraphs":["花间一壶酒，","独酌无相亲。","举杯邀明月，","对影成三人。","月既不解饮，","影徒随我身。","暂伴月将影，","行乐须及春。","我歌月徘徊，","我舞影零乱。","醒时同交欢，","醉后各分散。","永结无情游，","相期邈云汉。"]},{"id":"007","title":"春思","author":"李白","genre":"五言古诗","yuefu":false,"paragraphs":["燕草如碧丝，","秦桑低绿枝。","当君怀归日，","是妾断肠时。","春风不相识，","何事入罗帏？"]},{"id":"008","title":"望岳","author":"杜甫","genre":"五言古诗","yuefu":false,"paragraphs":["岱宗夫如何，","齐鲁青未了。","造化钟神秀，","阴阳割昏晓。","荡胸生层云，","决眦入归鸟，","会当凌绝顶，","一览众山小。"]},{"id":"009","title":"赠卫八处士","author":"杜甫","genre":"五言古诗","yuefu":false,"paragraphs":["人生不相见，","动如参与商。","今夕复何夕，","共此灯烛光。","少壮能几时，","鬓发各已苍。","访旧半为鬼，","惊呼热中肠。","焉知二十载，","重上君子堂。","昔别君未婚，","儿女忽成行。","怡然敬父执，","问我来何方。","问答乃未已，","驱儿罗酒浆。","夜雨剪春韭，","新炊间黄粱。","主称会面难，","一举累十觞。","十觞亦不醉，","感子故意长。","明日隔山岳，","世事两茫茫。"]},{"id":"010","title":"佳人","author":"杜甫","genre":"五言古诗","yuefu":false,"paragraphs":["绝代有佳人，","幽居在空谷。","自云良家子，","零落依草木。","关中昔丧乱，","兄弟遭杀戮。","官高何足论，","不得收骨肉。","世情恶衰歇，","万事随转烛。","夫婿轻薄儿，","新人美如玉。","合昏尚知时，","鸳鸯不独宿。","但见新人笑，","那闻旧人哭！","在山泉水清，","出山泉水浊。","侍婢卖珠回，","牵萝补茅屋。","摘花不插发，","采柏动盈掬。","天寒翠袖薄，","日暮倚修竹。"]},{"id":"011","title":"梦李白·其一","author":"杜甫","genre":"五言古诗","yuefu":false,"paragraphs":["死别已吞声，","生别常恻恻。","江南瘴疠地，","逐客无消息。","故人入我梦，","明我长相忆。","君今在罗网，","何以有羽翼？","恐非平生魂，","路远不可测。","魂来枫林青，","魂返关塞黑。","落月满屋梁，","犹疑照颜色。","水深波浪阔，","无使蛟龙得。"]},{"id":"012","title":"梦李白·其二","author":"杜甫","genre":"五言古诗","yuefu":false,"paragraphs":["浮云终日行，","游子久不至。","三夜频梦君，","情亲见君意。","告归常局促，","苦道来不易。","江湖多风波，","舟楫恐失坠。","出门搔白首，","若负平生志。","冠盖满京华，","斯人独憔悴。","孰云网恢恢，","将老身反累。","千秋万岁名，","寂寞身后事。"]},{"id":"013","title":"送别","author":"王维","genre":"五言古诗","yuefu":false,"paragraphs":["下马饮君酒，","问君何所之。","君言不得意，","归卧南山陲。","但去莫复闻，","白云无尽时。"]},{"id":"014","title":"送綦毋潜落第还乡","author":"王维","genre":"五言古诗","yuefu":false,"paragraphs":["圣代无隐者，","英灵尽来归。","遂令东山客，","不得顾采薇。","既至金门远，","孰云吾道非？","江淮度寒食，","京洛缝春衣。","置酒长安道，","同心与我违。","行当浮桂棹，","未几拂荆扉。","远树带行客，","孤城当落晖。","吾谋适不用，","勿谓知音稀。"]},{"id":"015","title":"青溪","author":"王维","genre":"五言古诗","yuefu":false,"paragraphs":["言入黄花川，","每逐青溪水。","随山将万转，","趣途无百里。","声喧乱石中，","色静深松里。","漾漾泛菱荇，","澄澄映葭苇。","我心素已闲，","清川澹如此。","请留盘石上，","垂钓将已矣。"]},{"id":"016","title":"渭川田家","author":"王维","genre":"五言古诗","yuefu":false,"paragraphs":["斜光照墟落，","穷巷牛羊归。","野老念牧童，","倚杖候荆扉。","雉雊麦苗秀，","蚕眠桑叶稀。","田夫荷锄立，","相见语依依。","即此羡闲逸，","怅然吟式微。"]},{"id":"017","title":"西施咏","author":"王维","genre":"五言古诗","yuefu":false,"paragraphs":["艳色天下重，","西施宁久微。","朝为越溪女，","暮作吴宫妃。","贱日岂殊众，","贵来方悟稀。","邀人傅脂粉，","不自著罗衣。","君宠益娇态，","君怜无是非。","当时浣纱伴，","莫得同车归。","持谢邻家子，","效颦安可希！"]},{"id":"018","title":"秋登兰山寄张五","author":"孟浩然","genre":"五言古诗","yuefu":false,"paragraphs":["北山白云里，","隐者自怡悦。","相望始登高，","心随雁飞灭。","愁因薄暮起，","兴是清秋发。","时见归村人，","沙行渡头歇。","天边树若荠，","江畔洲如月。","何当载酒来，","共醉重阳节。"]},{"id":"019","title":"夏日南亭怀辛大","author":"孟浩然","genre":"五言古诗","yuefu":false,"paragraphs":["山光忽西落，","池月渐东上。","散发乘夜凉，","开轩卧闲敞。","荷风送香气，","竹露滴清响。","欲取鸣琴弹，","恨无知音赏。","感此怀故人，","中宵劳梦想。"]},{"id":"020","title":"宿业师山房待丁大不至","author":"孟浩然","genre":"五言古诗","yuefu":false,"paragraphs":["夕阳度西岭，","群壑倏已暝。","松月生夜凉，","风泉满清听。","樵人归欲尽，","烟鸟栖初定。","之子期宿来，","孤琴候萝径。"]},{"id":"021","title":"同从弟南斋玩月忆山阴崔少府","author":"王昌龄","genre":"五言古诗","yuefu":false,"paragraphs":["高卧南斋时，","开帷月初吐。","清辉淡水木，","演漾在窗户。","苒苒几盈虚，","澄澄变今古。","美人清江畔，","是夜越吟苦。","千里其如何，","微风吹兰杜。"]},{"id":"022","title":"寻西山隐者不遇","author":"丘为","genre":"五言古诗","yuefu":false,"paragraphs":["绝顶一茅茨，","直上三十里。","扣关无僮仆，","窥室惟案几。","若非巾柴车，","应是钓秋水。","差池不相见，","黾勉空仰止。","草色新雨中，","松声晚窗里。","及兹契幽绝，","自足荡心耳。","虽无宾主意，","颇得清净理。","兴尽方下山，","何必待之子。"]},{"id":"023","title":"春泛若耶溪","author":"綦毋潜","genre":"五言古诗","yuefu":false,"paragraphs":["幽意无断绝，","此去随所偶。","晚风吹行舟，","花路入溪口。","际夜转西壑，","隔山望南斗。","潭烟飞溶溶，","林月低向后。","生事且弥漫，","愿为持竿叟。"]},{"id":"024","title":"宿王昌龄隐居","author":"常建","genre":"五言古诗","yuefu":false,"paragraphs":["清溪深不测，","隐处唯孤云。","松际露微月，","清光犹为君。","茅亭宿花影，","药院滋苔纹。","余亦谢时去，","西山鸾鹤群。"]},{"id":"025","title":"与高适薛据同登慈恩寺浮图","author":"岑参","genre":"五言古诗","yuefu":false,"paragraphs":["塔势如涌出，","孤高耸天宫。","登临出世界，","磴道盘虚空。","突兀压神州，","峥嵘如鬼工。","四角碍白日，","七层摩苍穹。","下窥指高鸟，","俯听闻惊风。","连山若波涛，","奔凑如朝东。","青槐夹驰道，","宫馆何玲珑！","秋色从西来，","苍然满关中。","五陵北原上，","万古青蒙蒙。","净理了可悟，","胜因夙所宗。","誓将挂冠去，","觉道资无穷。"]},{"id":"026","title":"贼退示官吏","author":"元结","genre":"五言古诗","yuefu":false,"paragraphs":["昔岁逢太平，","山林二十年。","泉源在庭户，","洞壑当门前。","井税有常期，","日晏犹得眠。","忽然遭时变，","数岁亲戎旃。","今来典斯郡，","山夷又纷然。","城小贼不屠，","人贫伤可怜。","是以陷邻境，","此州独见全。","使臣将王命，","岂不如贼焉！","令彼征敛者，","迫之如火煎。","谁能绝人命，","以作时世贤。","思欲委符节，","引竿自刺船。","将家就鱼麦，","归老江湖边。"],"prelude":"癸卯岁，西原贼入道州，焚烧杀掠，几尽而去。明年，贼又攻永州，破邵，不犯此州边鄙而退，岂力能制敌欤？盖蒙其伤怜而已！诸史何为忍苦征敛！故作诗一篇以示官吏。"},{"id":"027","title":"郡斋雨中与诸文士燕集","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["兵卫森画戟，","宴寝凝清香。","海上风雨至，","逍遥池阁凉。","烦疴近消散，","嘉宾复满堂。","自惭居处崇，","未睹斯民康。","理会是非遣，","性达形迹忘。","鲜肥属时禁，","蔬果幸见尝。","俯饮一杯酒，","仰聆金玉章。","神欢体自轻，","意欲凌风翔。","吴中盛文史，","群彦今汪洋。","方知大蕃地，","岂曰财赋强。"]},{"id":"028","title":"初发扬子寄元大校书","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["凄凄去亲爱，","泛泛入烟雾。","归棹洛阳人，","残钟广陵树。","今朝为此别，","何处还相遇。","世事波上舟，","沿洄安得住。"]},{"id":"029","title":"寄全椒山中道士","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["今朝郡斋冷，","忽念山中客。","涧底束荆薪，","归来煮白石。","欲持一瓢酒，","远慰风雨夕。","落叶满空山，","何处寻行迹。"]},{"id":"030","title":"长安遇冯著","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["客从东方来，","衣上灞陵雨。","问客何为来，","采山因买斧。","冥冥花正开，","扬扬燕新乳。","昨别今已春，","鬓丝生几缕。"]},{"id":"031","title":"夕次盱眙县","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["落帆逗淮镇，","停舫临孤驿。","浩浩风起波，","冥冥日沈夕。","人归山郭暗，","雁下芦洲白。","独夜忆秦关，","听钟未眠客。"]},{"id":"032","title":"东郊","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["吏舍局终年，","出郊旷清曙。","杨柳散和风，","青山澹吾虑。","依丛适自憩，","缘涧还复去。","微雨霭芳原，","春鸠鸣何处？","乐幽心屡止，","遵事迹犹遽。","终罢斯结庐，","慕陶真可庶。"]},{"id":"033","title":"送杨氏女","author":"韦应物","genre":"五言古诗","yuefu":false,"paragraphs":["永日方戚戚，","出行复悠悠。","女子今有行，","大江溯轻舟。","尔辈苦无恃，","抚念益慈柔。","幼为长所育，","两别泣不休。","对此结中肠，","义往难复留！","自小阙内训，","事姑贻我忧。","赖兹托令门，","仁恤庶无尤。","贫俭诚所尚，","资从岂待周？","孝恭遵妇道，","容止顺其猷。","别离在今晨，","见尔当何秋。","居闲始自遣，","临感忽难收。","归来视幼女，","零泪缘缨流。"]},{"id":"034","title":"晨诣超师院读禅经","author":"柳宗元","genre":"五言古诗","yuefu":false,"paragraphs":["汲井漱寒齿，","清心拂尘服。","闲持贝叶书，","步出东斋读。","真源了无取，","忘迹世所逐。","遗言冀可冥，","缮性何由熟？","道人庭宇静，","苔色连深竹。","日出雾露馀，","青松如膏沐。","澹然离言说，","悟悦心自足。"]},{"id":"035","title":"溪居","author":"柳宗元","genre":"五言古诗","yuefu":false,"paragraphs":["久为簪组累，","幸此南夷谪。","闲依农圃邻，","偶似山林客。","晓耕翻露草，","夜榜响溪石。","来往不逢人，","长歌楚天碧。"]},{"id":"036","title":"塞上曲","author":"王昌龄","genre":"五言古诗","yuefu":true,"paragraphs":["蝉鸣空桑林，","八月萧关道。","出塞复入塞，","处处黄芦草。","从来幽并客，","皆向沙场老。","莫学游侠儿，","矜夸紫骝好。"]},{"id":"037","title":"塞下曲","author":"王昌龄","genre":"五言古诗","yuefu":true,"paragraphs":["饮马渡秋水，","水寒风似刀。","平沙日未没，","黯黯见临洮。","昔日长城战，","咸言意气高。","黄尘足今古，","白骨乱蓬蒿。"]},{"id":"038","title":"关山月","author":"李白","genre":"五言古诗","yuefu":true,"paragraphs":["明月出天山，","苍茫云海间。","长风几万里，","吹度玉门关。","汉下白登道，","胡窥青海湾。","由来征战地，","不见有人还。","戍客望边色，","思归多苦颜。","高楼当此夜，","叹息未应闲。"]},{"id":"039","title":"子夜吴歌·春歌","author":"李白","genre":"五言古诗","yuefu":true,"paragraphs":["秦地罗敷女，","采桑绿水边。","素手青条上，","红妆白日鲜。","蚕饥妾欲去，","五马莫留连。"]},{"id":"040","title":"子夜吴歌·夏歌","author":"李白","genre":"五言古诗","yuefu":true,"paragraphs":["镜湖三百里，","菡萏发荷花。","五月西施采，","人看隘若耶。","回舟不待月，","归去越王家。"]},{"id":"041","title":"子夜吴歌·秋歌","author":"李白","genre":"五言古诗","yuefu":true,"paragraphs":["长安一片月，","万户捣衣声。","秋风吹不尽，","总是玉关情。","何日平胡虏，","良人罢远征？"]},{"id":"042","title":"子夜吴歌·冬歌","author":"李白","genre":"五言古诗","yuefu":true,"paragraphs":["明朝驿使发，","一夜絮征袍。","素手抽针冷，","那堪把剪刀。","裁缝寄远道，","几日到临洮？"]},{"id":"043","title":"长干行","author":"李白","genre":"五言古诗","yuefu":true,"paragraphs":["妾发初覆额，","折花门前剧。","郎骑竹马来，","绕床弄青梅。","同居长干里，","两小无嫌猜。","十四为君妇，","羞颜未尝开。","低头向暗壁，","千唤不一回。","十五始展眉，","愿同尘与灰。","常存抱柱信，","岂上望夫台！","十六君远行，","瞿塘滟滪堆。","五月不可触，","猿鸣天上哀。","门前迟行迹，","一一生绿苔。","苔深不能扫，","落叶秋风早。","八月蝴蝶来，","双飞西园草。","感此伤妾心，","坐愁红颜老。","早晚下三巴，","预将书报家。","相迎不道远，","直至长风沙。"]},{"id":"044","title":"烈女操","author":"孟郊","genre":"五言古诗","yuefu":true,"paragraphs":["梧桐相待老，","鸳鸯会双死。","贞妇贵殉夫，","舍生亦如此。","波澜誓不起，","妾心井中水。"]},{"id":"045","title":"游子吟","author":"孟郊","genre":"五言古诗","yuefu":true,"paragraphs":["慈母手中线，","游子身上衣。","临行密密缝，","意恐迟迟归。","谁言寸草心，","报得三春晖？"]},{"id":"046","title":"登幽州台歌","author":"陈子昂","genre":"五言古诗","yuefu":true,"paragraphs":["前不见古人，","后不见来者。","念天地之悠悠，","独怆然而涕下！"]},{"id":"047","title":"古意","author":"李颀","genre":"七言古诗","yuefu":false,"paragraphs":["男儿事长征，","少小幽燕客。","赌胜马蹄下，","由来轻七尺。","杀人莫敢前，","须如猬毛磔。","黄云陇底白雪飞，","未得报恩不能归。","辽东小妇年十五，","惯弹琵琶解歌舞。","今为羌笛出塞声，","使我三军泪如雨！"]},{"id":"048","title":"送陈章甫","author":"李颀","genre":"七言古诗","yuefu":false,"paragraphs":["四月南风大麦黄，","枣花未落桐叶长。","青山朝别暮还见，","嘶马出门思故乡。","陈侯立身何坦荡，","虬须虎眉仍大颡。","腹中贮书一万卷，","不肯低头在草莽。","东门酤酒饮我曹，","心轻万事皆鸿毛。","醉卧不知白日暮，","有时空望孤云高。","长河浪头连天黑，","津口停舟渡不得。","郑国游人未及家，","洛阳行子空叹息。","闻道故林相识多，","罢官昨日今如何？"]},{"id":"049","title":"琴歌","author":"李颀","genre":"七言古诗","yuefu":false,"paragraphs":["主人有酒欢今夕，","请奏鸣琴广陵客。","月照城头乌半飞，","霜凄万树风入衣。","铜炉华烛烛增辉，","初弹渌水后楚妃。","一声已动物皆静，","四座无言星欲稀。","清淮奉使千馀里，","敢告云山从此始？"]},{"id":"050","title":"听董大弹胡笳声兼寄语弄房给事","author":"李颀","genre":"七言古诗","yuefu":false,"paragraphs":["蔡女昔造胡笳声，","一弹一十有八拍。","胡人落泪沾边草，","汉使断肠对归客。","古戍苍苍烽火寒，","大荒沈沈飞雪白。","先拂商弦后角羽，","四郊秋叶惊摵摵。","董夫子，","通神明，","深山窃听来妖精。","言迟更速皆应手，","将往复旋如有情。","空山百鸟散还合，","万里浮云阴且晴。","嘶酸雏雁失群夜，","断绝胡儿恋母声。","川为静其波，","鸟亦罢其鸣。","乌孙部落家乡远，","逻娑沙尘哀怨生。","幽音变调忽飘洒，","长风吹林雨堕瓦。","迸泉飒飒飞木末，","野鹿呦呦走堂下。","长安城连东掖垣，","凤凰池对青琐门。","高才脱略名与利，","日夕望君抱琴至。"]},{"id":"051","title":"听安万善吹觱篥歌","author":"李颀","genre":"七言古诗","yuefu":false,"paragraphs":["南山截竹为筚篥，","此乐本自龟兹出。","流传汉地曲转奇，","凉州胡人为我吹。","傍邻闻者多叹息，","远客思乡皆泪垂。","世人解听不解赏，","长飙风中自来往。","枯桑老柏寒飕飗，","九雏鸣凤乱啾啾。","龙吟虎啸一时发，","万籁百泉相与秋。","忽然更作渔阳掺，","黄云萧条白日暗。","变调如闻杨柳春，","上林繁花照眼新。","岁夜高堂列明烛，","美酒一杯声一曲。"]},{"id":"052","title":"夜归鹿门山歌","author":"孟浩然","genre":"七言古诗","yuefu":false,"paragraphs":["山寺钟鸣昼已昏，","渔梁渡头争渡喧。","人随沙路向江村，","余亦乘舟归鹿门。","鹿门月照开烟树，","忽到庞公栖隐处。","岩扉松径长寂寥，","惟有幽人自来去。"]},{"id":"053","title":"庐山谣寄卢侍御虚舟","author":"李白","genre":"七言古诗","yuefu":false,"paragraphs":["我本楚狂人，","凤歌笑孔丘。","手持绿玉杖，","朝别黄鹤楼。","五岳寻仙不辞远，","一生好入名山游。","庐山秀出南斗傍，","屏风九叠云锦张。","影落明湖青黛光，","金阙前开二峰长。","银河倒挂三石梁，","香炉瀑布遥相望。","回崖沓障凌苍苍。","翠影红霞映朝日，","鸟飞不到吴天长。","登高壮观天地间，","大江茫茫去不黄。","黄云万里动风色，","白波九道流雪山。","好为庐山谣，","兴因庐山发。","闲窥石镜清我心，","谢公行处苍苔没。","早服还丹无世情，","琴心三叠道初成。","遥见仙人彩云里，","手把芙蓉朝玉京。","先期汗漫九垓上，","愿接卢敖游太清。"]},{"id":"054","title":"梦游天姥吟留别","author":"李白","genre":"七言古诗","yuefu":false,"paragraphs":["海客谈瀛洲，","烟涛微茫信难求。","越人语天姥，","云霓明灭或可睹。","天姥连天向天横，","势拔五岳掩赤城。","天台四万八千丈，","对此欲倒东南倾。","我欲因之梦吴越，","一夜飞渡镜湖月。","湖月照我影，","送我至剡溪。","谢公宿处今尚在，","渌水荡漾清猿啼。","脚著谢公屐，","身登青云梯。","半壁见海日，","空中闻天鸡。","千岩万壑路不定，","迷花倚石忽已暝。","熊咆龙吟殷岩泉，","栗深林兮惊层巅。","云青青兮欲雨，","水澹澹兮生烟。","裂缺霹雳，","丘峦崩摧。","洞天石扇，","訇然中开。","青冥浩荡不见底，","日月照耀金银台。","霓为衣兮风为马，","云之君兮纷纷而来下。","虎鼓瑟兮鸾回车，","仙之人兮列如麻。","忽魂悸以魄动，","恍惊起而长嗟。","惟觉时之枕席，","失向来之烟霞。","世间行乐亦如此，","古来万事东流水。","别君去兮何时还？","且放白鹿青崖间。","须行即骑访名山。","安能摧眉折腰事权贵，","使我不得开心颜！"]},{"id":"055","title":"金陵酒肆留别","author":"李白","genre":"七言古诗","yuefu":false,"paragraphs":["风吹柳花满店香，","吴姬压酒唤客尝。","金陵子弟来相送，","欲行不行各尽觞。","请君试问东流水，","别意与之谁短长？"]},{"id":"056","title":"宣州谢朓楼饯别校书叔云","author":"李白","genre":"七言古诗","yuefu":false,"paragraphs":["弃我去者，","昨日之日不可留。","乱我心者，","今日之日多烦忧！","长风万里送秋雁，","对此可以酣高楼。","蓬莱文章建安骨，","中间小谢又清发。","俱怀逸兴壮思飞，","欲上青天览明月。","抽刀断水水更流，","举杯销愁愁更愁。","人生在世不称意，","明朝散发弄扁舟。"]},{"id":"057","title":"走马川行奉送封大夫出师西征","author":"岑参","genre":"七言古诗","yuefu":false,"paragraphs":["君不见走马川行雪海边，","平沙莽莽黄入天。","轮台九月风夜吼，","一川碎石大如斗。","随风满地石乱走，","匈奴草黄马正肥。","金山西见烟尘飞，","汉家大将西出师。","将军金甲夜不脱，","半夜军行戈相拨。","风头如刀面如割，","马毛带雪汗气蒸。","五花连钱旋作冰，","幕中草檄砚水凝。","虏骑闻之应胆慑，","料知短兵不敢接。","车师西门伫献捷！"]},{"id":"058","title":"轮台歌奉送封大夫出师西征","author":"岑参","genre":"七言古诗","yuefu":false,"paragraphs":["轮台城头夜吹角，","轮台城北旄头落。","羽书昨夜过渠黎，","单于已在金山西。","戍楼西望烟尘黑，","汉兵屯在轮台北。","上将拥旄西出征，","平明吹笛大军行。","四边伐鼓雪海涌，","三军大呼阴山动。","虏塞兵气连云屯，","战场白骨缠草根。","剑河风急雪片阔，","沙口石冻马蹄脱。","亚相勤王甘苦辛，","誓将报主静边尘。","古来青史谁不见，","今见功名胜古人。"]},{"id":"059","title":"白雪歌送武判官归京","author":"岑参","genre":"七言古诗","yuefu":false,"paragraphs":["北风卷地白草折，","胡天八月即飞雪。","忽如一夜春风来，","千树万树梨花开。","散入珠帘湿罗幕，","狐裘不暖锦衾薄。","将军角弓不得控，","都护铁衣冷犹著。","瀚海阑干百丈冰，","愁云黪淡万里凝。","中军置酒饮归客，","胡琴琵琶与羌笛。","纷纷暮雪下辕门，","风掣红旗冻不翻。","轮台东门送君去，","去时雪满天山路。","山回路转不见君，","雪上空留马行处。"]},{"id":"060","title":"韦讽录事宅观曹将军画马图","author":"杜甫","genre":"七言古诗","yuefu":false,"paragraphs":["国初以来画鞍马，","神妙独数江都王。","将军得名三十载，","人间又见真乘黄。","曾貌先帝照夜白，","龙池十日飞霹雳。","内府殷红玛瑙盘，","婕妤传诏才人索。","盘赐将军拜舞归，","轻纨细绮相追飞。","贵戚权门得笔迹，","始觉屏障生光辉。","昔日太宗拳毛騧，","近时郭家狮子花。","今之新图有二马。","复令识者久叹嗟。","此皆骑战一敌万，","缟素漠漠开风沙。","其余七匹亦殊绝，","迥若寒空杂烟雪。","霜蹄蹴踏长楸间，","马官厮养森成列。","可怜九马争神骏，","顾视清高气深稳。","借问苦心爱者谁，","后有韦讽前支盾。","忆昔巡幸新丰宫，","翠花拂天来向东。","腾骧磊落三万匹，","皆与此图筋骨同。","自从献宝朝河宗，","无复射蛟江水中。","君不见，","金粟堆前松柏里。","龙媒去尽鸟呼风。"]},{"id":"061","title":"丹青引赠曹霸将军","author":"杜甫","genre":"七言古诗","yuefu":false,"paragraphs":["将军魏武之子孙，","于今为庶为青门。","英雄割据虽已矣，","文采风流今尚存。","学书初学卫夫人，","但恨无过王右军。","丹青不知老将至，","富贵于我如浮云。","开元之中常引见，","承恩数上南熏殿。","凌烟功臣少颜色，","将军下笔开生面。","良相头上进贤冠，","猛将腰间大羽箭。","褒公鄂公毛发动，","英姿飒爽犹酣战。","先帝天马玉花骢，","画工如山貌不同。","是日牵来赤墀下，","迥立阊阖生长风。","诏谓将军拂绢素，","意匠惨淡经营中。","斯须九重真龙出，","一洗万古凡马空。","玉花却在御榻上，","榻上庭前屹相向。","至尊含笑催赐金，","圉人太仆皆惆怅。","弟子韩干早入室，","亦能画马穷殊相。","干惟画肉不画骨，","忍使骅骝气凋丧。","将军画善盖有神，","偶逢佳士亦写真。","即今漂泊干戈际，","屡貌寻常行路人。","涂穷反遭俗眼白，","世上未有如公贫。","但看古来盛名下，","终日坎壈缠其身！"]},{"id":"062","title":"寄韩谏议","author":"杜甫","genre":"七言古诗","yuefu":false,"paragraphs":["今我不乐思岳阳，","身欲奋飞病在床。","美人娟娟隔秋水，","濯足洞庭望八荒。","鸿飞冥冥日月白，","青枫叶赤天雨霜。","玉京群帝集北斗，","或骑麒麟翳凤凰。","芙蓉旌旗烟雾落，","影动倒景摇潇湘。","星宫之君醉琼浆，","羽人稀少不在旁。","似闻昨者赤松子，","恐是汉代韩张良。","昔随刘氏定长安，","帷幄未改神惨伤。","国家成败吾岂敢，","色难腥腐餐枫香。","周南留滞古所惜，","南极老人应寿昌。","美人胡为隔秋水，","焉得置之贡玉堂？"]},{"id":"063","title":"古柏行","author":"杜甫","genre":"七言古诗","yuefu":false,"paragraphs":["孔明庙前有老柏，","柯如青铜根如石。","双皮溜雨四十围，","黛色参天二千尺。","君臣已与时际会，","树木犹为人爱惜。","云来气接巫峡长，","月出寒通雪山白。","忆昨路绕锦亭东，","先主武侯同閟宫。","崔嵬枝干郊原古，","窈窕丹青户牖空。","落落盘踞虽得地，","冥冥孤高多烈风。","扶持自是神明力，","正直元因造化功。","大厦如倾要梁栋，","万牛回首丘山重。","不露文章世已惊，","未辞剪伐谁能送？","苦心岂免容蝼蚁？","香叶终经宿鸾凤。","志士幽人莫怨嗟，","古来材大难为用！"]},{"id":"064","title":"观公孙大娘弟子舞剑器行","author":"杜甫","genre":"七言古诗","yuefu":false,"paragraphs":["昔有佳人公孙氏，","一舞剑器动四方。","观者如山色沮丧，","天地为之久低昂。","霍如羿射九日落，","矫如群帝骖龙翔。","来如雷霆收震怒，","罢如江海凝清光。","绛唇珠袖两寂寞，","晚有弟子传芬芳。","临颍美人在白帝，","妙舞此曲神扬扬。","与余问答既有以，","感时抚事增惋伤。","先帝侍女八千人，","公孙剑器初第一。","五十年间似反掌，","风尘澒洞昏王室。","梨园子弟散如烟，","女乐馀姿映寒日。","金粟堆前木已拱，","瞿塘石城草萧瑟。","玳筵急管曲复终，","乐极哀来月东出。","老夫不知其所往，","足茧荒山转愁疾。"]},{"id":"065","title":"石鱼湖上醉歌","author":"元结","genre":"七言古诗","yuefu":false,"paragraphs":["石鱼湖，","似洞庭，","夏水欲满君山青。","山为樽，","水为沼，","酒徒历历坐洲鸟。","长风连日作大浪，","不能废人运酒舫。","我持长瓢坐巴丘，","酌饮四座以散愁。"],"prelude":"漫叟以公田米酿酒，因休暇，则载酒于湖上，时取一醉；欢醉中，据湖岸，引臂向鱼取酒，使舫载之，遍饮坐者。意疑倚巴丘，酌於君山之上，诸子环洞庭而坐，酒舫泛泛然，触波涛而往来者，乃作歌以长之。"},{"id":"066","title":"山石","author":"韩愈","genre":"七言古诗","yuefu":false,"paragraphs":["山石荦确行径微，","黄昏到寺蝙蝠飞。","升堂坐阶新雨足，","芭蕉叶大栀子肥。","僧言古壁佛画好，","以火来照所见稀。","铺床拂席置羹饭，","疏粝亦足饱我饥。","夜深静卧百虫绝，","清月出岭光入扉。","天明独去无道路，","出入高下穷烟霏。","山红涧碧纷烂漫，","时见松枥皆十围。","当流赤足蹋涧石，","水声激激风吹衣。","人生如此自可乐，","岂必局束为人鞿！","嗟哉吾党二三子，","安得至老不更归！"]},{"id":"067","title":"八月十五夜赠张功曹","author":"韩愈","genre":"七言古诗","yuefu":false,"paragraphs":["纤云四卷天无河，","清风吹空月舒波。","沙平水息声影绝，","一杯相属君当歌。","君歌声酸辞且苦，","不能听终泪如雨。","洞庭连天九嶷高，","蛟龙出没猩鼯号。","十生九死到官所，","幽居默默如藏逃。","下床畏蛇食畏药，","海气湿蛰熏腥臊。","昨者州前槌大鼓，","嗣皇继圣登夔皋。","赦书一日行万里，","罪从大辟皆除死。","迁者追回流者还，","涤瑕荡垢清朝班。","州家申名使家抑，","坎轲只得移荆蛮。","判司卑官不堪说，","未免捶楚尘埃间。","同时辈流多上道，","天路幽险难追攀。","君歌且休听我歌，","我歌今与君殊科。","一年明月今宵多，","人生由命非由他。","有酒不饮奈明何！"]},{"id":"068","title":"谒衡岳庙遂宿岳寺题门楼","author":"韩愈","genre":"七言古诗","yuefu":false,"paragraphs":["五岳祭秩皆三公，","四方环镇嵩当中。","火维地荒足妖怪，","天假神柄专其雄。","喷云泄雾藏半腹，","虽有绝顶谁能穷？","我来正逢秋雨节，","阴气晦昧无清风。","潜心默祷若有应，","岂非正直能感通！","须臾静扫众峰出，","仰见突兀撑青空。","紫盖连延接天柱，","石廪腾掷堆祝融。","森然魄动下马拜，","松柏一迳趋灵宫。","纷墙丹柱动光彩，","鬼物图画填青红。","升阶伛偻荐脯酒，","欲以菲薄明其衷。","庙令老人识神意，","睢盱侦伺能鞠躬。","手持杯珓导我掷，","云此最吉馀难同。","窜逐蛮荒幸不死，","衣食才足甘长终。","侯王将相望久绝，","神纵欲福难为功！","夜投佛寺上高阁，","星月掩映云曈昽。","猿鸣钟动不知曙，","杲杲寒日生于东。"]},{"id":"069","title":"石鼓歌","author":"韩愈","genre":"七言古诗","yuefu":false,"paragraphs":["张生手持石鼓文，","劝我识作石鼓歌。","少陵无人谪仙死，","才薄将奈石鼓何！","周纲凌迟四海沸，","宣王愤起挥天戈。","大开明堂受朝贺，","诸侯剑佩鸣相磨。","搜于岐阳骋雄俊，","万里禽兽皆遮罗。","镌功勒成告万世，","凿石作鼓隳嵯峨。","从臣才艺咸第一，","拣选撰刻留山阿。","雨淋日炙野火燎，","鬼物守护烦撝呵。","公从何处得纸本？","毫发尽备无差讹。","辞严义密读难晓，","字体不类隶与蝌。","年深岂免有缺画，","快剑砍断生蛟鼍。","鸾翔凤翥众仙下，","珊瑚碧树交枝柯。","金绳铁索锁钮壮，","古鼎跃水龙腾梭。","陋儒编诗不收入，","二雅褊迫无委蛇。","孔子西行不到秦，","掎摭星宿遗羲娥。","嗟予好古生苦晚，","对此涕泪双滂沱。","忆昔初蒙博士征，","其年始改称元和。","故人从军在右辅，","为我度量掘臼科。","濯冠沐浴告祭酒，","如此至宝存岂多！","毡包席裹可立致，","十鼓只载数骆驼。","荐诸太庙比郜鼎，","光价岂止百倍过！","圣恩若许留太学，","诸生讲解得切磋。","观经鸿都尚填咽，","坐见举国来奔波。","剜苔剔藓露节角，","安置妥帖平不颇。","大厦深檐与盖覆，","经历久远期无佗。","中朝大官老于事，","讵肯感激徒媕婀。","牧童敲火牛砺角，","谁复著手为摩挲？","日销月铄就埋没，","六年西顾空吟哦。","羲之俗书趁姿媚，","数纸尚可博白鹅。","继周八代争战罢，","无人收拾理则那。","方今太平日无事，","柄任儒术崇丘轲。","安能以此上论列，","愿借辩口如悬河。","石鼓之歌止于此，","呜呼吾意其蹉跎！"]},{"id":"070","title":"渔翁","author":"柳宗元","genre":"七言古诗","yuefu":false,"paragraphs":["渔翁夜傍西岩宿，","晓汲清湘燃楚烛。","烟销日出不见人，","欸乃一声山水绿。","回看天际下中流，","岩上无心云相逐。"]},{"id":"071","title":"长恨歌","author":"白居易","genre":"七言古诗","yuefu":false,"paragraphs":["汉皇重色思倾国，","御宇多年求不得。","杨家有女初长成，","养在深闺人未识。","天生丽质难自弃，","一朝选在君王侧。","回眸一笑百媚生，","六宫粉黛无颜色。","春寒赐浴华清池，","温泉水滑洗凝脂。","侍儿扶起娇无力，","始是新承恩泽时。","云鬓花颜金步摇，","芙蓉帐暖度春宵。","春宵苦短日高起，","从此君王不早朝。","承欢侍宴无闲暇，","春从春游夜专夜。","后宫佳丽三千人，","三千宠爱在一身。","金星妆成娇侍夜，","玉楼宴罢醉和春。","姊妹弟兄皆列士，","可怜光彩生门户。","遂令天下父母心，","不重生男重生女。","骊宫高处入青云，","仙乐风飘处处闻。","缓歌慢舞凝丝竹，","尽日君王看不足。","渔阳鼙鼓动地来，","惊破霓裳羽衣曲。","九重城阙烟尘生，","千乘万骑西南行。","翠华摇摇行复止，","西出都门百馀里。","六军不发无奈何，","宛转蛾眉马前死。","花钿委地无人收，","翠翘金雀玉搔头。","君王掩面救不得，","回看血泪相和流。","黄埃散漫风萧索，","云栈萦纡登剑阁。","峨嵋山下少人行，","旌旗无光日色薄。","蜀江水碧蜀山青，","圣主朝朝暮暮情。","行宫见月伤心色，","夜雨闻铃肠断声。","天旋地转回龙驭，","到此踌躇不能去。","马嵬坡下泥土中，","不见玉颜空死处。","君臣相顾尽沾衣，","东望都门信马归。","归来池苑皆依旧，","太液芙蓉未央柳。","芙蓉如面柳如眉，","对此如何不泪垂！","春风桃李花开日，","秋雨梧桐叶落时。","西宫南内多秋草，","落叶满阶红不扫。","梨园子弟白发新，","椒房阿监青娥老。","夕殿萤飞思悄然，","孤灯挑尽未成眠。","迟迟钟鼓初长夜，","耿耿星河欲曙天。","鸳鸯瓦冷霜华重，","翡翠衾寒谁与共？","悠悠生死别经年，","魂魄不曾来入梦。","临邛道士鸿都客，","能以精诚致魂魄。","为感君王辗转思，","遂教方士殷勤觅。","排空驭气奔如电，","升天入地求之遍。","上穷碧落下黄泉，","两处茫茫皆不见。","忽闻海上有仙山，","山在虚无缥缈间。","楼阁玲珑五云起，","其中绰约多仙子。","中有一人字太真，","雪肤花貌参差是。","金阙西厢叩玉扃，","转教小玉报双成。","闻道汉家天子使，","九华帐里梦魂惊。","揽衣推枕起徘徊，","珠箔银屏迤逦开。","云鬓半偏新睡觉，","花冠不整下堂来。","风吹仙袂飘飘举，","犹似霓裳羽衣舞。","玉容寂寞泪阑干，","梨花一枝春带雨。","含情凝睇谢君王，","一别音容两渺茫。","昭阳殿里恩爱绝，","蓬莱宫中日月长。","回头下望人寰处，","不见长安见尘雾。","唯将旧物表深情，","钿合金钗寄将去。","钗留一股合一扇，","钗擘黄金合分钿。","但教心似金钿坚，","天上人间会相见。","临别殷勤重寄词，","词中有誓两心知。","七月七日长生殿，","夜半无人私语时。","在天愿作比翼鸟，","在地愿为连理枝。","天长地久有时尽，","此恨绵绵无绝期！"]},{"id":"072","title":"琵琶行","author":"白居易","genre":"七言古诗","yuefu":false,"paragraphs":["浔阳江头夜送客，","枫叶荻花秋瑟瑟。","主人下马客在船，","举酒欲饮无管弦。","醉不成欢惨将别，","别时茫茫江浸月。","忽闻水上琵琶声，","主人忘归客不发。","寻声暗问弹者谁，","琵琶声停欲语迟。","移船相近邀相见，","添酒回灯重开宴。","千呼万唤始出来，","犹抱琵琶半遮面。","转轴拨弦三两声，","未成曲调先有情。","弦弦掩抑声声思，","似诉平生不得志。","低眉信手续续弹，","说尽心中无限事。","轻拢慢捻抹复挑，","初为霓裳后六么。","大弦嘈嘈如急雨，","小弦切切如私语。","嘈嘈切切错杂弹，","大珠小珠落玉盘。","间关莺语花底滑，","幽咽泉流水下滩。","水泉冷涩弦凝绝，","凝绝不通声渐歇。","别有幽愁暗恨生，","此时无声胜有声。","银瓶乍破水浆迸，","铁骑突出刀枪鸣。","曲终收拨当心画，","四弦一声如裂帛。","东船西舫悄无言，","唯见江心秋月白。","沈吟放拨插弦中，","整顿衣裳起敛容。","自言本是京城女，","家在虾蟆陵下住。","十三学得琵琶成，","名属教坊第一部。","曲罢曾教善才服，","妆成每被秋娘妒。","五陵年少争缠头，","一曲红绡不知数。","钿头银篦击节碎，","血色罗裙翻酒污。","今年欢笑复明年，","秋月春风等闲度。","弟走从军阿姨死，","暮去朝来颜色故。","门前冷落车马稀，","老大嫁作商人妇。","商人重利轻别离，","前月浮梁买茶去。","去来江口守空船，","绕船月明江水寒。","夜深忽梦少年事，","梦啼妆泪红阑干。","我闻琵琶已叹息，","又闻此语重唧唧。","同是天涯沦落人，","相逢何必曾相识！","我从去年辞帝京，","谪居卧病浔阳城。","浔阳地僻无音乐，","终岁不闻丝竹声。","住近湓江地低湿，","黄芦苦竹绕宅生。","其间旦暮闻何物？","杜鹃啼血猿哀鸣。","春江花朝秋月夜，","往往取酒还独倾。","岂无山歌与村笛，","呕哑嘲哳难为听！","今夜闻君琵琶语，","如听仙乐耳暂明。","莫辞更坐弹一曲，","为君翻作琵琶行。","感我此言良久立，","却坐促弦弦转急。","凄凄不似向前声，","满座重闻皆掩泣。","座中泣下谁最多，","江州司马青衫湿！"],"prelude":"元和十年，予左迁九江郡司马。明年秋，送客湓浦口，闻船中夜弹琵琶者，听其音，铮铮然有京都声；问其人，本长安倡女，尝学琵琶於穆曹二善才。年长色衰，委身为贾人妇。遂命酒，使快弹数曲，曲罢悯然。自叙少小时欢乐事，今漂沦憔悴，转徙於江湖间。予出官二年恬然自安，感斯人言，是夕，始觉有迁谪意，因为长句歌以赠之，凡六百一十六言，命曰琵琶行。"},{"id":"073","title":"韩碑","author":"李商隐","genre":"七言古诗","yuefu":false,"paragraphs":["元和天子神武姿，","彼何人哉轩与羲。","誓将上雪列圣耻，","坐法宫中朝四夷。","淮西有贼五十载，","封狼生貙貙生罴。","不据山河据平地，","长戈利矛日可麾。","帝得圣相相曰度，","贼斫不死神扶持。","腰悬相印作都统，","阴风惨澹天王旗。","愬武古通作牙爪，","仪曹外郎载笔随。","行军司马智且勇，","十四万众犹虎貔。","入蔡缚贼献太庙，","功无与让恩不訾。","帝曰汝度功第一，","汝从事愈宜为辞。","愈拜稽首蹈且舞，","金石刻画臣能为。","古者世称大手笔，","此事不系于职司。","当仁自古有不让，","言讫屡颔天子颐。","公退斋戒坐小阁，","濡染大笔何淋漓！","点窜尧典舜典字，","涂改清庙生民诗。","文成破体书在纸，","清晨再拜铺丹墀。","表曰臣愈昧死上，","咏神圣功书之碑。","碑高三丈字如斗，","负以灵鳌蟠以螭。","句奇语重喻者少，","谗之天子言其私。","长绳百尺拽碑倒，","粗沙大石相磨治。","公之斯文若元气，","先时已入人肝脾。","汤盘孔鼎有述作，","今无其器存其辞。","呜呼圣皇及圣相，","相与烜赫流淳熙。","公之斯文不示后，","曷与三五相攀追。","愿书万本诵万过，","口角流沫右手胝。","传之七十有二代，","以为封禅玉检明堂基。"]},{"id":"074","title":"燕歌行","author":"高适","genre":"七言古诗","yuefu":true,"paragraphs":["汉家烟尘在东北，","汉将辞家破残贼。","男儿本自重横行，","天子非常赐颜色。","摐金伐鼓下榆关，","旌旆逶迤碣石间。","校尉羽书飞瀚海，","单于猎火照狼山。","山川萧条极边土，","胡骑凭陵杂风雨。","战士军前半死生，","美人帐下犹歌舞。","大漠穷秋塞草衰，","孤城落日斗兵稀。","身当恩遇常轻敌，","力尽关山未解围。","铁衣远戍辛勤久，","玉筋应啼别离后。","少妇城南欲断肠，","征人蓟北空回首。","边庭飘摇那可度，","绝域苍茫更何有！","杀气三时作阵云，","寒声一夜传刁斗。","相看白刃血纷纷，","死节从来岂顾勋？","君不见沙场征战苦，","至今犹忆李将军！"],"prelude":"开元二十六年，客有从御史大夫张公出塞而还者，作燕歌行以示适，感征戍之事，因而和焉。"},{"id":"075","title":"古从军行","author":"李颀","genre":"七言古诗","yuefu":true,"paragraphs":["白日登山望烽火，","黄昏饮马傍交河。","行人刁斗风沙暗，","公主琵琶幽怨多。","野云万里无城郭，","雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，","胡儿眼泪双双落。","闻道玉门犹被遮，","应将性命逐轻车。","年年战骨埋荒外，","空见葡萄入汉家。"]},{"id":"076","title":"洛阳女儿行","author":"王维","genre":"七言古诗","yuefu":true,"paragraphs":["洛阳女儿对门居，","才可容颜十五馀。","良人玉勒乘骢马，","侍女金盘脍鲤鱼。","画阁朱楼尽相望，","红桃绿柳垂檐向。","罗帷送上七香车，","宝扇迎归九华帐。","狂夫富贵在青春，","意气骄奢剧季伦。","自怜碧玉亲教舞，","不惜珊瑚持与人。","春窗曙灭九微火，","九微片片飞花琐。","戏罢曾无理曲时，","妆成只是薰香坐。","城中相识尽繁华，","日夜经过赵李家。","谁怜越女颜如玉，","贫贱江头自浣纱！"]},{"id":"077","title":"老将行","author":"王维","genre":"七言古诗","yuefu":true,"paragraphs":["少年十五二十时，","步行夺得胡马骑。","射杀山中白额虎，","肯数邺下黄须儿！","一身转战三千里，","一剑曾当百万师。","汉兵奋迅如霹雳，","虏骑崩腾畏蒺藜。","卫青不败由天幸，","李广无功缘数奇。","自从弃置便衰朽，","世事蹉跎成白首。","昔时飞箭无全目，","今日垂杨生左肘。","路旁时卖故侯瓜，","门前学种先生柳。","苍茫古木连穷巷，","寥落寒山对虚牖。","誓令疏勒出飞泉，","不似颍川空使酒。","贺兰山下阵如云，","羽檄交驰日夕闻。","节使三河募年少，","诏书五道出将军。","试拂铁衣如雪色，","聊持宝剑动星文。","愿得燕弓射大将，","耻令越甲鸣吾君。","莫嫌旧日云中守，","犹堪一战取功勋！"]},{"id":"078","title":"桃源行","author":"王维","genre":"七言古诗","yuefu":true,"paragraphs":["渔舟逐水爱山春，","两岸桃花夹古津。","坐看红树不知远，","行尽青溪不见人。","山口潜行始隈隩，","山开旷望旋平陆。","遥看一处攒云树，","近入千家散花竹。","樵客初传汉姓名，","居人未改秦衣服。","居人共住武陵源，","还从物外起田园。","月明松下房栊静，","日出云中鸡犬喧。","惊闻俗客争来集，","竞引还家问都邑。","平明闾巷扫花开，","薄暮渔樵乘水入。","初因避地去人间，","及至成仙遂不还。","峡里谁知有人事？","世中遥望空云山。","不疑灵境难闻见，","尘心未尽思乡县。","出洞无论隔山水，","辞家终拟长游衍。","自谓经过旧不迷，","安知峰壑今来变？","当时只记入山深，","青溪几曲到云林。","春来遍是桃花水，","不辨仙源何处寻。"]},{"id":"079","title":"蜀道难","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["噫吁戏，","危乎高哉！","蜀道之难难于上青天！","蚕丛及鱼凫，","开国何茫然！","尔来四万八千岁，","始与秦塞通人烟。","西当太白有鸟道，","可以横绝峨眉巅。","地崩山摧壮士死，","然后天梯石栈方钩连。","上有六龙回日之高标，","下有冲波逆折之回川。","黄鹤之飞尚不得，","猿猱欲度愁攀援。","青泥何盘盘，","百步九折萦岩峦。","扪参历井仰胁息，","以手抚膺坐长叹。","问君西游何时还？","畏途巉岩不可攀！","但见悲鸟号古木，","雄飞雌从绕林间。","又闻子规啼，","夜月愁空山。","蜀道之难难于上青天！","使人听此凋朱颜。","连峰去天不盈尺，","枯松倒挂倚绝壁。","飞湍瀑流争喧豗，","冰崖转石万壑雷。","其险也如此！","嗟尔远道之人，","胡为乎来哉？","剑阁峥嵘而崔嵬。","一夫当关，","万夫莫开。","所守或匪亲，","化为狼与豺。","朝避猛虎，","夕避长蛇。","磨牙吮血，","杀人如麻。","锦城虽云乐，","不如早还家。","蜀道之难难于上青天！","侧身西望常咨嗟！"]},{"id":"080","title":"长相思·其一","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["长相思，","在长安。","络纬秋啼金井阑，","微霜凄凄簟色寒。","孤灯不明思欲绝，","卷帷望月空长叹。","美人如花隔云端。","上有青冥之长天，","下有渌水之波澜。","天长路远魂飞苦，","梦魂不到关山难。","长相思，","摧心肝！"]},{"id":"081","title":"长相思·其二","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["日色已尽花含烟，","月明欲素愁不眠。","赵瑟初停凤凰柱，","蜀琴欲奏鸳鸯弦。","此曲有意无人传，","愿随春风寄燕然。","忆君迢迢隔青天。","昔日横波目，","今成流泪泉。","不信妾肠断，","归来看取明镜前。"]},{"id":"082","title":"行路难·其一","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["金樽清酒斗十千，","玉盘珍羞值万钱。","停杯投箸不能食，","拔剑四顾心茫然。","欲渡黄河冰塞川，","将登太行雪满山。","闲来垂钓碧溪上，","忽复乘舟梦日边。","行路难，","行路难！","多歧路，","今安在？","长风破浪会有时，","直挂云帆济沧海。"]},{"id":"083","title":"行路难·其二","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["大道如青天，","我独不得出。","羞逐长安社中儿，","赤鸡白狗赌梨栗。","弹剑作歌奏苦声，","曳裾王门不称情。","淮阴市井笑韩信，","汉朝公卿忌贾生。","君不见，","昔时燕家重郭隗，","拥彗折节无嫌猜。","剧辛乐毅感恩分，","输肝剖胆效英才。","昭王白骨萦蔓草，","谁人更扫黄金台？","行路难，","归去来！"]},{"id":"084","title":"行路难·其三","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["有耳莫洗颍川水，","有口莫食首阳蕨。","含光混世贵无名，","何用孤高比云月？","吾观自古贤达人，","功成不退皆殒身。","子胥既弃吴江上，","屈原终投湘水滨。","陆机雄才岂自保？","李斯税驾苦不早。","华亭鹤唳讵可闻，","上蔡苍鹰何足道！","君不见，","吴中张翰称达生，","秋风忽忆江东行。","且乐生前一杯酒，","何须身后千载名！"]},{"id":"085","title":"将进酒","author":"李白","genre":"七言古诗","yuefu":true,"paragraphs":["君不见，","黄河之水天上来，","奔流到海不复回。","君不见，","高堂明镜悲白发，","朝如青丝暮成雪。","人生得意须尽欢，","莫使金樽空对月！","天生我材必有用，","千金散尽还复来。","烹羊宰牛且为乐，","会须一饮三百杯！","岑夫子，","丹丘生，","将进酒，","君莫停！","与君歌一曲，","请君为我侧耳听！","钟鼓馔玉不足贵，","但愿长醉不愿醒！","古来圣贤皆寂寞，","惟有饮者留其名！","陈王昔时宴平乐，","斗酒十千恣欢谑。","主人何为言少钱？","径须沽取对君酌。","五花马，","千金裘，","呼儿将出换美酒，","与尔同消万古愁！"]},{"id":"086","title":"兵车行","author":"杜甫","genre":"七言古诗","yuefu":true,"paragraphs":["车辚辚，","马萧萧，","行人弓箭各在腰。","耶娘妻子走相送，","尘埃不见咸阳桥。","牵衣顿足拦道哭，","哭声直上干云霄！","道旁过者问行人，","行人但云点行频。","或从十五北防河，","便至四十西营田。","去时里正与裹头，","归来头白还戍边！","边亭流血成海水，","武皇开边意未已。","君不闻，","汉家山东二百州，","千村万落生荆杞！","纵有健妇把锄犁，","禾生陇亩无东西。","况复秦兵耐苦战，","被驱不异犬与鸡。","长者虽有问，","役夫敢申恨？","且如今年冬，","未休关西卒。","县官急索租，","租税从何出？","信知生男恶，","反是生女好。","生女犹得嫁比邻，","生男埋没随百草！","君不见，","青海头，","古来白骨无人收。","新鬼烦冤旧鬼哭，","天阴雨湿声啾啾！"]},{"id":"087","title":"丽人行","author":"杜甫","genre":"七言古诗","yuefu":true,"paragraphs":["三月三日天气新，","长安水边多丽人。","态浓意远淑且真，","肌理细腻骨肉匀。","绣罗衣裳照暮春，","蹙金孔雀银麒麟。","头上何所有？","翠微盍叶垂鬓唇。","背后何所见？","珠压腰衱稳称身。","就中云幕椒房亲，","赐名大国虢与秦。","紫驼之峰出翠釜，","水精之盘行素鳞。","犀箸餍饫久未下，","鸾刀缕切空纷纶。","黄门飞鞚不动尘，","御厨络绎送八珍。","箫鼓哀吟感鬼神，","宾从杂沓实要津。","后来鞍马何逡巡，","当轩下马入锦茵。","杨花雪落覆白苹，","青鸟飞去衔红巾。","炙手可热势绝伦，","慎莫近前丞相嗔！"]},{"id":"088","title":"哀江头","author":"杜甫","genre":"七言古诗","yuefu":true,"paragraphs":["少陵野老吞声哭，","春日潜行曲江曲。","江头宫殿锁千门，","细柳新蒲为谁绿？","忆昔霓旌下南苑，","苑中景物生颜色。","昭阳殿里第一人，","同辇随君侍君侧。","辇前才人带弓箭，","白马嚼啮黄金勒。","翻身向天仰射云，","一箭正坠双飞翼。","明眸皓齿今何在？","血污游魂归不得！","清渭东流剑阁深，","去住彼此无消息。","人生有情泪沾臆，","江水江花岂终极？","黄昏胡骑尘满城，","欲往城南望城北。"]},{"id":"089","title":"哀王孙","author":"杜甫","genre":"七言古诗","yuefu":true,"paragraphs":["长安城头头白乌，","夜飞延秋门上呼。","又向人家啄大屋，","屋底达官走避胡。","金鞭断折九马死，","骨肉不待同驰驱。","腰下宝玦青珊瑚，","可怜王孙泣路隅！","问之不肯道姓名，","但道困苦乞为奴。","已经百日窜荆棘，","身上无有完肌肤。","高帝子孙尽隆准，","龙种自与常人殊。","豺狼在邑龙在野，","王孙善保千金躯。","不敢长语临交衢，","且为王孙立斯须。","昨夜东风吹血腥，","东来橐驼满旧都。","朔方健儿好身手，","昔何勇锐今何愚！","窃闻天子已传位，","圣德北服南单于。","花门剺面请雪耻，","慎勿出口他人狙！","哀哉王孙慎勿疏，","五陵佳气无时无。"]},{"id":"090","title":"经邹鲁祭孔子而叹之","author":"唐玄宗","genre":"五言律诗","yuefu":false,"paragraphs":["夫子何为者，","栖栖一代中。","地犹鄹氏邑，","宅即鲁王宫。","叹凤嗟身否？","伤麟怨道穷。","今看两楹奠，","当与梦时同。"]},{"id":"091","title":"望月怀远","author":"张九龄","genre":"五言律诗","yuefu":false,"paragraphs":["海上生明月，","天涯共此时。","情人怨遥夜，","竟夕起相思！","灭烛怜光满，","披衣觉露滋。","不堪盈手赠，","还寝梦佳期。"]},{"id":"092","title":"送杜少府之任蜀州","author":"王勃","genre":"五言律诗","yuefu":false,"paragraphs":["城阙辅三秦，","风烟望五津。","与君离别意，","同是宦游人。","海内存知己，","天涯若比邻。","无为在歧路，","儿女共沾巾。"]},{"id":"093","title":"在狱咏蝉","author":"骆宾王","genre":"五言律诗","yuefu":false,"paragraphs":["西路蝉声唱，","南冠客思侵。","那堪玄鬓影，","来对白头吟！","露重飞难进，","风多响易沉。","无人信高洁，","谁为表予心？"],"prelude":"余禁所禁垣西，是法厅事也。有古槐数株焉，虽生意可知，同殷仲文之古树，而听讼斯在，即周召伯之甘棠。每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻；岂人心异於曩时，将虫响悲於前听？嗟乎！声以动容，德以象贤，故洁其身也，禀君子达人之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其真。吟乔树之微风，韵资天纵；饮高秋之坠露，清畏人知。仆失路艰虞，遭时徽徽，不哀伤而自怨，未摇落而先衰。闻蟪蛄之流声，悟平反之已奏；见螳螂之抱影，怯危机之未安。感而缀诗，贻诸知己。庶情沿物应，哀弱羽之飘零；道寄人知，悯馀声之寂寞。非谓文墨，取代幽忧云尔。"},{"id":"094","title":"和晋陵陆丞早春游望","author":"杜审言","genre":"五言律诗","yuefu":false,"paragraphs":["独有宦游人，","偏惊物候新。","云霞出海曙，","梅柳渡江春。","淑气催黄鸟，","晴光转绿苹。","忽闻歌古调，","归思欲沾巾。"]},{"id":"095","title":"杂诗·其三","author":"沈佺期","genre":"五言律诗","yuefu":false,"paragraphs":["闻道黄龙戍，","频年不解兵。","可怜闺里月，","长在汉家营。","少妇今春意，","良人昨夜情。","谁能将旗鼓，","一为取龙城？"]},{"id":"096","title":"题大庾岭北驿","author":"宋之问","genre":"五言律诗","yuefu":false,"paragraphs":["阳月南飞雁，","传闻至此回。","我行殊未已，","何日复归来？","江静潮初落，","林昏瘴不开。","明朝望乡处，","应见陇头梅。"]},{"id":"097","title":"次北固山下","author":"王湾","genre":"五言律诗","yuefu":false,"paragraphs":["客路青山外，","行舟绿水前。","潮平两岸阔，","风正一帆悬。","海日生残夜，","江春入旧年。","乡书何处达？","归雁洛阳边。"]},{"id":"098","title":"题破山寺后禅院","author":"常建","genre":"五言律诗","yuefu":false,"paragraphs":["清晨入古寺，","初日照高林。","曲径通幽处，","禅房花木深。","山光悦鸟性，","潭影空人心。","万籁此俱寂，","惟馀钟磬音。"]},{"id":"099","title":"寄左省杜拾遗","author":"岑参","genre":"五言律诗","yuefu":false,"paragraphs":["联步趋丹陛，","分曹限紫微。","晓随天仗入，","暮惹御香归。","白发悲花落，","青云羡鸟飞。","圣朝无阙事，","自觉谏书稀。"]},{"id":"100","title":"赠孟浩然","author":"李白","genre":"五言律诗","yuefu":false,"paragraphs":["吾爱孟夫子，","风流天下闻。","红颜弃轩冕，","白首卧松云。","醉月频中圣，","迷花不事君。","高山安可仰，","徒此挹清芬。"]},{"id":"101","title":"渡荆门送别","author":"李白","genre":"五言律诗","yuefu":false,"paragraphs":["渡远荆门外，","来从楚国游。","山随平野尽，","江入大荒流。","月下飞天镜，","云生结海楼。","仍怜故乡水，","万里送行舟。"]},{"id":"102","title":"送友人","author":"李白","genre":"五言律诗","yuefu":false,"paragraphs":["青山横北郭，","白水绕东城。","此地一为别，","孤蓬万里征。","浮云游子意，","落日故人情。","挥手自兹去，","萧萧班马鸣。"]},{"id":"103","title":"听蜀僧濬弹琴","author":"李白","genre":"五言律诗","yuefu":false,"paragraphs":["蜀僧抱绿绮，","西下峨眉峰。","为我一挥手，","如听万壑松。","客心洗流水，","馀响入霜钟。","不觉碧山暮，","秋云暗几重。"]},{"id":"104","title":"夜泊牛渚怀古","author":"李白","genre":"五言律诗","yuefu":false,"paragraphs":["牛渚西江夜，","青天无片云。","登舟望秋月，","空忆谢将军。","余亦能高咏，","斯人不可闻。","明朝挂帆席，","枫叶落纷纷。"]},{"id":"105","title":"月夜","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["今夜鄜州月，","闺中只独看。","遥怜小儿女，","未解忆长安。","香雾云鬟湿，","清辉玉臂寒。","何时倚虚幌，","双照泪痕干？"]},{"id":"106","title":"春望","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["国破山河在，","城春草木深。","感时花溅泪，","恨别鸟惊心。","烽火连三月，","家书抵万金。","白头搔更短，","浑欲不胜簪。"]},{"id":"107","title":"春宿左省","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["花隐掖垣暮，","啾啾栖鸟过。","星临万户动，","月傍九霄多。","不寝听金钥，","因风想玉珂。","明朝有封事，","数问夜如何？"]},{"id":"108","title":"至德二载甫自京金光门出","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["此道昔归顺，","西郊胡正繁。","至今残破胆，","应有未招魂。","近得归京邑，","移官岂至尊？","无才日衰老，","驻马望千门。"]},{"id":"109","title":"月夜忆舍弟","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["戍鼓断人行，","秋边一雁声。","露从今夜白，","月是故乡明。","有弟皆分散，","无家问死生。","寄书长不达，","况乃未休兵。"]},{"id":"110","title":"天末怀李白","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["凉风起天末，","君子意如何？","鸿雁几时到，","江湖秋水多。","文章憎命达，","魑魅喜人过。","应共冤魂语，","投诗赠汨罗。"]},{"id":"111","title":"奉济驿重送严公四韵","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["远送从此别，","青山空复情。","几时杯重把，","昨夜月同行。","列郡讴歌惜，","三朝出入荣。","将村独归处，","寂寞养残生。"]},{"id":"112","title":"别房太尉墓","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["他乡复行役，","驻马别孤坟。","近泪无干土，","低空有断云。","对棋陪谢傅，","把剑觅徐君。","唯见林花落，","莺啼送客闻。"]},{"id":"113","title":"旅夜书怀","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["细草微风岸，","危樯独夜舟。","星垂平野阔，","月涌大江流。","名岂文章著？","官应老病休。","飘飘何所似，","天地一沙鸥。"]},{"id":"114","title":"登岳阳楼","author":"杜甫","genre":"五言律诗","yuefu":false,"paragraphs":["昔闻洞庭水，","今上岳阳楼。","吴楚东南坼，","乾坤日夜浮。","亲朋无一字，","老病有孤舟。","戎马关山北，","凭轩涕泗流。"]},{"id":"115","title":"辋川闲居赠裴秀才迪","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["寒山转苍翠，","秋水日潺湲。","倚杖柴门外，","临风听暮蝉。","渡头馀落日，","墟里上孤烟。","复值接舆醉，","狂歌五柳前。"]},{"id":"116","title":"山居秋暝","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["空山新雨后，","天气晚来秋。","明月松间照，","清泉石上流。","竹喧归浣女，","莲动下渔舟。","随意春芳歇，","王孙自可留。"]},{"id":"117","title":"归嵩山作","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["清川带长薄，","车马去闲闲。","流水如有意，","暮禽相与还。","荒城临古渡，","落日满秋山。","迢递嵩高下，","归来且闭关。"]},{"id":"118","title":"终南山","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["太乙近天都，","连山接海隅。","白云回望合，","青霭入看无。","分野中峰变，","阴晴众壑殊。","欲投人处宿，","隔水问樵夫。"]},{"id":"119","title":"酬张少府","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["晚年惟好静，","万事不关心。","自顾无长策，","空知返旧林。","松风吹解带，","山月照弹琴。","君问穷通理，","渔歌入浦深。"]},{"id":"120","title":"过香积寺","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["不知香积寺，","数里入云峰。","古木无人径，","深山何处钟？","泉声咽危石，","日色冷青松。","薄暮空潭曲，","安禅制毒龙。"]},{"id":"121","title":"送梓州李使君","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["万壑树参天，","千山响杜鹃。","山中一夜雨，","树杪百重泉。","汉女输橦布，","巴人讼芋田。","文翁翻教授，","不敢倚先贤。"]},{"id":"122","title":"汉江临眺","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["楚塞三湘接，","荆门九派通。","江流天地外，","山色有无中。","郡邑浮前浦，","波澜动远空。","襄阳好风日，","留醉与山翁。"]},{"id":"123","title":"终南别业","author":"王维","genre":"五言律诗","yuefu":false,"paragraphs":["中岁颇好道，","晚家南山陲。","兴来美独往，","胜事空自知。","行到水穷处，","坐看云起时。","偶然值林叟，","谈笑无还期。"]},{"id":"124","title":"望洞庭湖赠张丞相","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["八月湖水平，","涵虚混太清。","气蒸云梦泽，","波撼岳阳城。","欲济无舟楫，","端居耻圣明。","坐观垂钓者，","空有羡鱼情。"]},{"id":"125","title":"与诸子登岘山","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["人事有代谢，","往来成古今。","江山留胜迹，","我辈复登临。","水落鱼梁浅，","天寒梦泽深。","羊公碑字在，","读罢泪沾襟。"]},{"id":"126","title":"宴梅道士山房","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["林卧愁春尽，","开轩览物华。","忽逢青鸟使，","邀入赤松家。","丹灶初开火，","仙桃正发花。","童颜若可驻，","何惜醉流霞！"]},{"id":"127","title":"岁暮归南山","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["北阙休上书，","南山归敝庐。","不才明主弃，","多病故人疏。","白发催年老，","青阳逼岁除。","永怀愁不寐，","松月夜窗墟。"]},{"id":"128","title":"过故人庄","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["故人具鸡黍，","邀我至田家。","绿树村边合，","青山郭外斜。","开轩面场圃，","把酒话桑麻。","待到重阳日，","还来就菊花。"]},{"id":"129","title":"秦中感秋寄远上人","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["一丘尝欲卧，","三径苦无资。","北土非吾愿，","东林怀我师。","黄金燃桂尽，","壮志逐年衰。","日夕凉风至，","闻蝉但益悲。"]},{"id":"130","title":"宿桐庐江寄广陵旧游","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["山暝听猿愁，","沧江急夜流。","风鸣两岸叶，","月照一孤舟。","建德非吾土，","维扬忆旧游。","还将两行泪，","遥寄海西头。"]},{"id":"131","title":"留别王维","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["寂寂竟何待，","朝朝空自归。","欲寻芳草去，","惜与故人违。","当路谁相假，","知音世所稀。","只应守寂寞，","还掩故园扉。"]},{"id":"132","title":"早寒江上有怀","author":"孟浩然","genre":"五言律诗","yuefu":false,"paragraphs":["木落雁南渡，","北风江上寒。","我家襄水曲，","遥隔楚云端。","乡泪客中尽，","孤帆天际看。","迷津欲有问，","平海夕漫漫。"]},{"id":"133","title":"秋日登吴公台上寺远眺","author":"刘长卿","genre":"五言律诗","yuefu":false,"paragraphs":["古台摇落后，","秋日望乡心。","野寺人来少，","云峰水隔深。","夕阳依旧垒，","寒磬满空林。","惆怅南朝事，","长江独至今。"]},{"id":"134","title":"送李中丞归汉阳别业","author":"刘长卿","genre":"五言律诗","yuefu":false,"paragraphs":["流落征南将，","曾驱十万师。","罢归无旧业，","老去恋明时。","独立三边静，","轻生一剑知。","茫茫江汉上，","日暮复何之。"]},{"id":"135","title":"饯别王十一南游","author":"刘长卿","genre":"五言律诗","yuefu":false,"paragraphs":["望君烟水阔，","挥手泪沾巾。","飞鸟没何处，","青山空向人。","长江一帆远，","落日五湖春。","谁见汀洲上，","相思愁白苹？"]},{"id":"136","title":"寻南溪常山道人隐居","author":"刘长卿","genre":"五言律诗","yuefu":false,"paragraphs":["一路经行处，","莓苔见履痕。","白云依静渚，","春草闭闲门。","过雨看松色，","随山到水源。","溪花与禅意，","相对亦忘言。"]},{"id":"137","title":"新年作","author":"刘长卿","genre":"五言律诗","yuefu":false,"paragraphs":["乡心新岁切，","天畔独潸然。","老至居人下，","春归在客先。","岭猿同旦暮，","江柳共风烟。","已似长沙傅，","从今又几年？"]},{"id":"138","title":"送僧归日本","author":"钱起","genre":"五言律诗","yuefu":false,"paragraphs":["上国随缘住，","来途若梦行。","浮天沧海远，","去世法舟轻。","水月通禅寂，","鱼龙听梵声。","惟怜一灯影，","万里眼中明。"]},{"id":"139","title":"谷口书斋寄杨补阙","author":"钱起","genre":"五言律诗","yuefu":false,"paragraphs":["泉壑带茅茨，","云霞生薜帷。","竹怜新雨后，","山爱夕阳时。","闲鹭栖常早，","秋花落更迟。","家童扫萝径，","昨与故人期。"]},{"id":"140","title":"淮上喜会梁川故人","author":"韦应物","genre":"五言律诗","yuefu":false,"paragraphs":["江汉曾为客，","相逢每醉还。","浮云一别后，","流水十年间。","欢笑情如旧，","萧疏鬓已斑。","何因北归去，","淮上对秋山。"]},{"id":"141","title":"赋得暮雨送李胄","author":"韦应物","genre":"五言律诗","yuefu":false,"paragraphs":["楚江微雨里，","建业暮钟时。","漠漠帆来重，","冥冥鸟去迟。","海门深不见，","浦树远含滋。","相送情无限，","沾襟比散丝。"]},{"id":"142","title":"酬程延秋夜即事见赠","author":"韩翃","genre":"五言律诗","yuefu":false,"paragraphs":["长簟迎风早，","空城澹月华。","星河秋一雁，","砧杵夜千家。","节候看应晚，","心期卧亦赊。","向来吟秀句，","不觉已鸣鸦。"]},{"id":"143","title":"阙题","author":"刘昚虚","genre":"五言律诗","yuefu":false,"paragraphs":["道由白云尽，","春与青溪长。","时有落花至，","远随流水香。","闲门向山路，","深柳读书堂。","幽映每白日，","清辉照衣裳。"]},{"id":"144","title":"江乡故人偶集客舍","author":"戴叔伦","genre":"五言律诗","yuefu":false,"paragraphs":["天秋月又满，","城阙夜千重。","还作江南会，","翻疑梦里逢。","风枝惊暗鹊，","露草覆寒虫。","羁旅长堪醉，","相留畏晓钟。"]},{"id":"145","title":"送李端","author":"卢纶","genre":"五言律诗","yuefu":false,"paragraphs":["故关衰草遍，","离别正堪悲！","路出寒云外，","人归暮雪时。","少孤为客早，","多难识君迟。","掩泪空相向，","风尘何处期？"]},{"id":"146","title":"喜见外弟又言别","author":"李益","genre":"五言律诗","yuefu":false,"paragraphs":["十年离乱后，","长大一相逢。","问姓惊初见，","称名忆旧容。","别来沧海事，","语罢暮天钟。","明日巴陵道，","秋山又几重。"]},{"id":"147","title":"云阳馆与韩绅宿别","author":"司空曙","genre":"五言律诗","yuefu":false,"paragraphs":["故人江海别，","几度隔山川。","乍见翻疑梦，","相悲各问年。","孤灯寒照雨，","深竹暗浮烟。","更有明朝恨，","离杯惜共传。"]},{"id":"148","title":"喜外弟卢纶见宿","author":"司空曙","genre":"五言律诗","yuefu":false,"paragraphs":["静夜四无邻，","荒居旧业贫。","雨中黄叶树，","灯下白头人。","以我独沉久，","愧君相访频。","平生自有分，","况是蔡家亲！"]},{"id":"149","title":"贼平后送人北归","author":"司空曙","genre":"五言律诗","yuefu":false,"paragraphs":["世乱同南去，","时清独北还。","他乡生白发，","旧国见青山。","晓月过残垒，","繁星宿故关。","寒禽与衰草，","处处伴愁颜。"]},{"id":"150","title":"蜀先主庙","author":"刘禹锡","genre":"五言律诗","yuefu":false,"paragraphs":["天地英雄气，","千秋尚凛然！","势分三足鼎，","业复五铢钱。","得相能开国，","生儿不象贤。","凄凉蜀故妓，","来舞魏宫前。"]},{"id":"151","title":"没蕃故人","author":"张籍","genre":"五言律诗","yuefu":false,"paragraphs":["前年伐月支，","城下没全师。","蕃汉断消息，","死生长别离。","无人收废帐，","归马识残旗。","欲祭疑君在，","天涯哭此时。"]},{"id":"152","title":"赋得古原草送别","author":"白居易","genre":"五言律诗","yuefu":false,"paragraphs":["离离原上草，","一岁一枯荣。","野火烧不尽，","春风吹又生。","远芳侵古道，","晴翠接荒城。","又送王孙去，","萋萋满别情。"]},{"id":"153","title":"旅宿","author":"杜牧","genre":"五言律诗","yuefu":false,"paragraphs":["旅馆无良伴，","凝情自悄然。","寒灯思旧事，","断雁警愁眠。","远梦归侵晓，","家书到隔年。","沧江好烟月，","门系钓鱼船。"]},{"id":"154","title":"秋日赴阙题潼关驿楼","author":"许浑","genre":"五言律诗","yuefu":false,"paragraphs":["红叶晚萧萧，","长亭酒一瓢。","残云归太华，","疏雨过中条。","树色随山迥，","河声入海遥。","帝乡明日到，","犹自梦渔樵。"]},{"id":"155","title":"早秋","author":"许浑","genre":"五言律诗","yuefu":false,"paragraphs":["遥夜泛清瑟，","西风生翠萝。","残萤栖玉露，","早雁拂银河。","高树晓还密，","远山晴更多。","淮南一叶下，","自觉老烟波。"]},{"id":"156","title":"蝉","author":"李商隐","genre":"五言律诗","yuefu":false,"paragraphs":["本以高难饱，","徒劳恨费声。","五更疏欲断，","一树碧无情。","薄宦梗犹泛，","故园芜已平。","烦君最相警，","我亦举家清。"]},{"id":"157","title":"风雨","author":"李商隐","genre":"五言律诗","yuefu":false,"paragraphs":["凄凉宝剑篇，","羁泊欲穷年。","黄叶仍风雨，","青楼自管弦。","新知遭薄俗，","旧好隔良缘。","心断新丰酒，","销愁斗几千。"]},{"id":"158","title":"落花","author":"李商隐","genre":"五言律诗","yuefu":false,"paragraphs":["高阁客竟去，","小园花乱飞。","参差连曲陌，","迢递送斜晖。","肠断未忍扫，","眼穿仍欲归。","芳心向春尽，","所得是沾衣。"]},{"id":"159","title":"凉思","author":"李商隐","genre":"五言律诗","yuefu":false,"paragraphs":["客去波平槛，","蝉休露满枝。","永怀当此节，","倚立自移时。","北斗兼春远，","南陵寓使迟。","天涯占梦数，","疑误有新知。"]},{"id":"160","title":"北青萝","author":"李商隐","genre":"五言律诗","yuefu":false,"paragraphs":["残阳西入崦，","茅屋访孤僧。","落叶人何在？","寒云路几层？","独敲初夜磬，","闲倚一枝藤。","世界微尘里，","吾宁爱与憎。"]},{"id":"161","title":"送人东游","author":"温庭筠","genre":"五言律诗","yuefu":false,"paragraphs":["荒戍落黄叶，","浩然离故关。","高风汉阳渡，","初日郢门山。","江上几人在？","天涯孤棹还。","何当重相见，","樽酒慰离颜？"]},{"id":"162","title":"灞上秋居","author":"马戴","genre":"五言律诗","yuefu":false,"paragraphs":["灞原风雨定，","晚见雁行频。","落叶他乡树，","寒灯独夜人。","空园白露滴，","孤壁野僧邻。","寄卧郊扉久，","何年致此身？"]},{"id":"163","title":"楚江怀古","author":"马戴","genre":"五言律诗","yuefu":false,"paragraphs":["露气寒光集，","微阳下楚丘。","猿啼洞庭树，","人在木兰舟。","广泽生明月，","苍山夹乱流。","云中君不见，","竟夕自悲秋。"]},{"id":"164","title":"书边事","author":"张乔","genre":"五言律诗","yuefu":false,"paragraphs":["调角断清秋，","征人倚戍楼。","春风对青冢，","白日落梁州。","大漠无兵阻，","穷边有客游。","蕃情似此水，","长愿向南流。"]},{"id":"165","title":"除夜有怀","author":"崔涂","genre":"五言律诗","yuefu":false,"paragraphs":["迢递三巴路，","羁危万里身。","乱山残雪夜，","孤独异乡春。","渐与骨肉远，","转於僮仆亲。","那堪正飘泊，","明日岁华新。"]},{"id":"166","title":"孤雁","author":"崔涂","genre":"五言律诗","yuefu":false,"paragraphs":["几行归塞尽，","片影独何之？","暮雨相呼失，","寒塘欲下迟。","渚云低暗渡，","关月冷相随。","未必逢矰缴，","孤飞自可疑。"]},{"id":"167","title":"春宫怨","author":"杜荀鹤","genre":"五言律诗","yuefu":false,"paragraphs":["早被婵娟误，","欲妆临镜慵。","承恩不在貌，","教妾若为容。","风暖鸟声碎，","日高花影重。","年年越溪女，","相忆采芙蓉。"]},{"id":"168","title":"章台夜思","author":"韦庄","genre":"五言律诗","yuefu":false,"paragraphs":["清瑟怨遥夜，","绕弦风雨哀。","孤灯闻楚角，","残月下章台。","芳草已云暮，","故人殊未来。","乡书不可寄，","秋雁又南回。"]},{"id":"169","title":"寻陆鸿渐不遇","author":"皎然","genre":"五言律诗","yuefu":false,"paragraphs":["移家虽带郭，","野径入桑麻。","近种篱边菊，","秋来未著花。","扣门无犬吠，","欲去问西家。","报到山中去，","归来每日斜。"]},{"id":"170","title":"黄鹤楼","author":"崔颢","genre":"七言律诗","yuefu":false,"paragraphs":["昔人已乘黄鹤去，","此地空馀黄鹤楼。","黄鹤一去不复返，","白云千载空悠悠。","晴川历历汉阳树，","芳草萋萋鹦鹉洲。","日暮乡关何处是，","烟波江上使人愁。"]},{"id":"171","title":"行经华阴","author":"崔颢","genre":"七言律诗","yuefu":false,"paragraphs":["岧峣太华俯咸京，","天外三峰削不成。","武帝祠前云欲散，","仙人掌上雨初晴。","河山北枕秦关险，","驿树西连汉畤平。","借问路傍名利客，","无如此处学长生。"]},{"id":"172","title":"望蓟门","author":"祖咏","genre":"七言律诗","yuefu":false,"paragraphs":["燕台一去客心惊，","箫鼓喧喧汉将营。","万里寒光生积雪，","三边曙色动危旌。","沙场烽火侵胡月，","海畔云山拥蓟城。","少小虽非投笔吏，","论功还欲请长缨。"]},{"id":"173","title":"送魏万之京","author":"李颀","genre":"七言律诗","yuefu":false,"paragraphs":["朝闻游子唱骊歌，","昨夜微霜初度河。","鸿雁不堪愁里听，","云山况是客中过。","关城树色催寒近，","御苑砧声向晚多。","莫见长安行乐处，","空令岁月易蹉跎。"]},{"id":"174","title":"九日登望仙台呈刘明府","author":"崔曙","genre":"七言律诗","yuefu":false,"paragraphs":["汉文皇帝有高台，","此日登临曙色开。","三晋云山皆北向，","二陵风雨自东来。","关门令尹谁能识？","河上仙翁去不回。","且欲竟寻彭泽宰，","陶然共醉菊花杯。"]},{"id":"175","title":"送李少府贬峡中王少府贬长沙","author":"高适","genre":"七言律诗","yuefu":false,"paragraphs":["嗟君此别意何如？","驻马衔杯问谪居。","巫峡啼猿数行泪，","衡阳归雁几封书。","青枫江上秋帆远，","白帝城边古木疏。","圣代即今多雨露，","暂时分手莫踌躇。"]},{"id":"176","title":"奉和中书舍人贾至早朝大明宫","author":"岑参","genre":"七言律诗","yuefu":false,"paragraphs":["鸡鸣紫陌曙光寒，","莺啭皇州春色阑。","金阙晓钟开万户，","玉阶仙仗拥千官。","花迎剑佩星初落，","柳拂旌旗露未干。","独有凤凰池上客，","阳春一曲和皆难。"]},{"id":"177","title":"和贾舍人早朝大明宫之作","author":"王维","genre":"七言律诗","yuefu":false,"paragraphs":["绛帻鸡人送晓筹，","尚衣方进翠云裘。","九天阊阖开宫殿，","万国衣冠拜冕旒。","日色才临仙掌动，","香烟欲傍衮龙浮。","朝罢须裁五色诏，","佩声归向凤池头。"]},{"id":"178","title":"奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制","author":"王维","genre":"七言律诗","yuefu":false,"paragraphs":["渭水自萦秦塞曲，","黄山旧绕汉宫斜。","銮舆迥出千门柳，","阁道回看上苑花。","云里帝城双凤阙，","雨中春树万人家。","为乘阳气行时令，","不是宸游玩物华。"]},{"id":"179","title":"积雨辋川庄作","author":"王维","genre":"七言律诗","yuefu":false,"paragraphs":["积雨空林烟火迟，","蒸藜炊黍饷东菑。","漠漠水田飞白鹭，","阴阴夏木啭黄鹂。","山中习静观朝槿，","松下清斋折露葵。","野老与人争席罢，","海鸥何事更相疑。"]},{"id":"180","title":"酬郭给事","author":"王维","genre":"七言律诗","yuefu":false,"paragraphs":["洞门高阁霭馀辉，","桃李阴阴柳絮飞。","禁里疏钟官舍晚，","省中啼鸟吏人稀。","晨摇玉佩趋金殿，","夕奉天书拜琐闱。","强欲从君无那老，","将因卧病解朝衣。"]},{"id":"181","title":"蜀相","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["丞相祠堂何处寻？","锦官城外柏森森。","映阶碧草自春色，","隔叶黄鹂空好音。","三顾频烦天下计，","两朝开济老臣心。","出师未捷身先死，","长使英雄泪满襟！"]},{"id":"182","title":"客至","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["舍南舍北皆春水，","但见群鸥日日来。","花径不曾缘客扫，","蓬门今始为君开。","盘飧市远无兼味，","樽酒家贫只旧醅。","肯与邻翁相对饮，","隔篱呼取尽馀杯！"]},{"id":"183","title":"野望","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["西山白雪三城戍，","南浦清江万里桥。","海内风尘诸弟隔，","天涯涕泪一身遥。","唯将迟暮供多病，","未有涓埃答圣朝。","跨马出郊时极目，","不堪人事日萧条！"]},{"id":"184","title":"闻官军收河南河北","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["剑外忽传收蓟北，","初闻涕泪满衣裳。","却看妻子愁何在，","漫卷诗书喜欲狂。","白日放歌须纵酒，","青春作伴好还乡！","即从巴峡穿巫峡，","便下襄阳向洛阳。"]},{"id":"185","title":"登高","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["风急天高猿啸哀，","渚清沙白鸟飞回。","无边落木萧萧下，","不尽长江滚滚来。","万里悲秋常作客，","百年多病独登台。","艰难苦恨繁霜鬓，","潦倒新停浊酒杯。"]},{"id":"186","title":"登楼","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["花近高楼伤客心，","万方多难此登临。","锦江春色来天地，","玉垒浮云变古今。","北极朝庭终不改，","西山寇盗莫相侵！","可怜后主还祠庙，","日暮聊为梁父吟。"]},{"id":"187","title":"宿府","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["清秋幕府井梧寒，","独宿江城蜡炬残。","永夜角声悲自语，","中天月色好谁看？","风尘荏苒音书绝，","关塞萧条行陆难。","已忍伶俜十年事，","强移栖息一枝安。"]},{"id":"188","title":"阁夜","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["岁暮阴阳催短景，","天涯霜雪霁寒霄。","五更鼓角声悲壮，","三峡星河影动摇。","野哭千家闻战伐，","夷歌数处起渔樵。","卧龙跃马终黄土，","人事音书漫寂寥。"]},{"id":"189","title":"咏怀古迹·其一","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["支离东北风尘际，","漂泊西南天地间。","三峡楼台淹日月，","五溪衣服共云山。","羯胡事主终无赖，","词客哀时且未还。","庾信平生最萧瑟，","暮年诗赋动江关。"]},{"id":"190","title":"咏怀古迹·其二","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["摇落深知宋玉悲，","风流儒雅亦吾师。","怅望千秋一洒泪，","萧条异代不同时。","江山故宅空文藻，","云雨荒台岂梦思！","最是楚宫俱泯灭，","舟人指点到今疑。"]},{"id":"191","title":"咏怀古迹·其三","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["群山万壑赴荆门，","生长明妃尚有村。","一去紫台连朔漠，","独留青冢向黄昏。","画图省识春风面，","环佩空归月下魂。","千载琵琶作胡语，","分明怨恨曲中论。"]},{"id":"192","title":"咏怀古迹·其四","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["蜀主征吴幸三峡，","崩年亦在永安宫。","翠华想像空山里，","玉殿虚无野寺中。","古庙杉松巢水鹤，","岁时伏腊走村翁。","武侯祠屋常邻近，","一体君臣祭祀同。"]},{"id":"193","title":"咏怀古迹·其五","author":"杜甫","genre":"七言律诗","yuefu":false,"paragraphs":["诸葛大名垂宇宙，","宗臣遗像肃清高。","三分割据纡筹策，","万古云霄一羽毛。","伯仲之间见伊吕，","指挥若定失萧曹。","运移汉祚终难复，","志决身歼军务劳。"]},{"id":"194","title":"江州重别薛六柳八二员外","author":"刘长卿","genre":"七言律诗","yuefu":false,"paragraphs":["生涯岂料承优诏？","世事空知学醉歌。","江上月明胡雁过，","淮南木落楚山多。","寄身且喜沧洲近，","顾影无如白发何！","今日龙钟人共老，","愧君犹遣慎风波。"]},{"id":"195","title":"长沙过贾谊宅","author":"刘长卿","genre":"七言律诗","yuefu":false,"paragraphs":["三年谪宦此栖迟，","万古惟留楚客悲。","秋草独寻人去后，","寒林空见日斜时。","汉文有道恩犹薄，","湘水无情吊岂知？","寂寂江山摇落处，","怜君何事到天涯！"]},{"id":"196","title":"自夏口至鹦鹉洲夕望岳阳寄源中丞","author":"刘长卿","genre":"七言律诗","yuefu":false,"paragraphs":["汀洲无浪复无烟，","楚客相思益渺然。","汉口夕阳斜渡鸟，","洞庭秋水远连天。","孤城背岭寒吹角，","独戍临江夜泊船。","贾谊上书忧汉室，","长沙谪去古今怜。"]},{"id":"197","title":"赠阙下裴舍人","author":"钱起","genre":"七言律诗","yuefu":false,"paragraphs":["二月黄鹂飞上林，","春城紫禁晓阴阴。","长乐钟声花外尽，","龙池柳色雨中深。","阳和不散穷途恨，","霄汉长怀捧日心。","献赋十年犹未遇，","羞将白发对华簪。"]},{"id":"198","title":"寄李儋元锡","author":"韦应物","genre":"七言律诗","yuefu":false,"paragraphs":["去年花里逢君别，","今日花开又一年。","世事茫茫难自料，","春愁黯黯独成眠。","身多疾病思田里，","邑有流亡愧俸钱。","闻道欲来相问讯，","西楼望月几回圆？"]},{"id":"199","title":"同题仙游观","author":"韩翃","genre":"七言律诗","yuefu":false,"paragraphs":["仙台初见五城楼，","风物凄凄宿雨收。","山色遥连秦树晚，","砧声近报汉宫秋。","疏松影落空坛静，","细草香闲小洞幽。","何用别寻方外去，","人间亦自有丹丘！"]},{"id":"200","title":"春思","author":"皇甫冉","genre":"七言律诗","yuefu":false,"paragraphs":["莺啼燕语报新年，","马邑龙堆路几千。","家住层城邻汉苑，","心随明月到胡天。","机中锦字论长恨，","楼上花枝笑独眠。","为问天戎窦车骑，","何时返旆勒燕然？"]},{"id":"201","title":"晚次鄂州","author":"卢纶","genre":"七言律诗","yuefu":false,"paragraphs":["云开远见汉阳城，","犹是孤帆一日程。","估客昼眠知浪静，","舟人夜语觉潮生。","三湘愁鬓逢秋色，","万里归心对月明。","旧业已随征战尽，","更堪江上鼓鼙声。"]},{"id":"202","title":"登柳州城楼寄漳汀封连四州","author":"柳宗元","genre":"七言律诗","yuefu":false,"paragraphs":["城上高楼接大荒，","海天愁思正茫茫。","惊风乱飐芙蓉水，","密雨斜侵薜荔墙。","岭树重遮千里目，","江流曲似九回肠。","共来百越文身地，","犹自音书滞一乡。"]},{"id":"203","title":"西塞山怀古","author":"刘禹锡","genre":"七言律诗","yuefu":false,"paragraphs":["王浚楼船下益州，","金陵王气黯然收。","千寻铁锁沈江底，","一片降幡出石头。","人世几回伤往事？","山形依旧枕寒流。","从今四海为家日，","故垒萧萧芦荻秋。"]},{"id":"204","title":"遣悲怀·其一","author":"元稹","genre":"七言律诗","yuefu":false,"paragraphs":["谢公最小偏怜女，","自嫁黔娄百事乖。","顾我无衣搜荩箧，","泥他沽酒拔金钗。","野蔬充膳甘长藿，","落叶添薪仰古槐。","今日俸钱过十万，","与君营奠复营斋。"]},{"id":"205","title":"遣悲怀·其二","author":"元稹","genre":"七言律诗","yuefu":false,"paragraphs":["昔日戏言身后事，","今朝都到眼前来。","衣裳已施行看尽，","针线犹存未忍开。","尚想旧情怜婢仆，","也曾因梦送钱财。","诚知此恨人人有，","贫贱夫妻百事哀。"]},{"id":"206","title":"遣悲怀·其三","author":"元稹","genre":"七言律诗","yuefu":false,"paragraphs":["闲坐悲君亦自悲，","百年都是几多时？","邓攸无子寻知命，","潘岳悼亡犹费词。","同穴冥何所望，","他生缘会更难期。","惟将终夜长开眼，","报答平生未展眉。"]},{"id":"207","title":"望月有感","author":"白居易","genre":"七言律诗","yuefu":false,"paragraphs":["时难年荒世业空，","弟兄羁旅各西东。","田园寥落干戈后，","骨肉流离道路中。","吊影分为千里雁，","辞根散作九秋蓬。","共看明月应垂泪，","一夜乡心五处同。"]},{"id":"208","title":"锦瑟","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["锦瑟无端五十弦，","一弦一柱思华年。","庄生晓梦迷蝴蝶，","望帝春心托杜鹃。","沧海月明珠有泪，","蓝田日暖玉生烟。","此情可待成追忆，","只是当时已惘然。"]},{"id":"209","title":"无题·其一","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["昨夜星辰昨夜风，","画楼西畔桂堂东。","身无彩凤双飞翼，","心有灵犀一点通。","隔座送钩春酒暖，","分曹射覆蜡灯红。","嗟余听鼓应官去，","走马兰台类转蓬。"]},{"id":"210","title":"隋宫","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["紫泉宫殿锁烟霞，","欲取芜城作帝家。","玉玺不缘归日角，","锦帆应是到天涯。","於今腐草无萤火，","终古垂杨有暮鸦。","地下若逢陈后主，","岂宜重问后庭花？"]},{"id":"211","title":"无题·其二","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["来是空言去绝踪，","月斜楼上五更钟。","梦为远别啼难唤，","书被催成墨未浓。","蜡照半笼金翡翠，","麝熏微度绣芙蓉。","刘郎已恨蓬山远，","更隔蓬山一万重。"]},{"id":"212","title":"无题·其三","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["飒飒东风细雨来，","芙蓉塘外有轻雷。","金蟾啮锁烧香入，","玉虎牵丝汲井回。","贾氏窥帘韩掾少，","宓妃留枕魏王才。","春心莫共花争发，","一寸相思一寸灰。"]},{"id":"213","title":"筹笔驿","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["猿鸟犹疑畏简书，","风云常为护储胥。","徒令上将挥神笔，","终见降王走传车。","管乐有才原不忝，","关张无命欲何如。","他年锦里经祠庙，","梁父吟成恨有馀。"]},{"id":"214","title":"无题·其四","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["相见时难别亦难，","东风无力百花残。","春蚕到死丝方尽，","蜡炬成灰泪始干。","晓镜但愁云鬓改，","夜吟应觉月光寒。","蓬莱此去无多路，","青鸟殷勤为探看。"]},{"id":"215","title":"春雨","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["怅卧新春白袷衣，","白门寥落意多违。","红楼隔雨相望冷，","珠箔飘灯独自归。","远路应悲春晼晚，","残宵犹得梦依稀。","玉珰缄札何由达？","万里云罗一雁飞。"]},{"id":"216","title":"无题·其五","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["凤尾香罗薄几重，","碧文圆顶夜深缝。","扇裁月魄羞难掩，","车走雷声语未通。","曾是寂寥金烬暗，","断无消息石榴红。","斑骓只系垂杨岸，","何处西南任好风？"]},{"id":"217","title":"无题·其六","author":"李商隐","genre":"七言律诗","yuefu":false,"paragraphs":["重帷深下莫愁堂，","卧后清宵细细长。","神女生涯原是梦，","小姑居处本无郎。","风波不信菱枝弱，","月露谁教桂叶香？","直道相思了无益，","未妨惆怅是清狂。"]},{"id":"218","title":"利州南渡","author":"温庭筠","genre":"七言律诗","yuefu":false,"paragraphs":["澹然空水对斜晖，","曲岛苍茫接翠微。","波上马嘶看棹去，","柳边人歇待船归。","数丛沙草群鸥散，","万顷江田一鹭飞。","谁解乘舟寻范蠡，","五湖烟水独忘机？"]},{"id":"219","title":"苏武庙","author":"温庭筠","genre":"七言律诗","yuefu":false,"paragraphs":["苏武魂销汉使前，","古祠高树两茫然。","云边雁断胡天月，","陇上羊归塞草烟。","回日楼台非甲帐，","去时冠剑是丁年。","茂陵不见封侯印，","空向秋波哭逝川。"]},{"id":"220","title":"宫词","author":"薛逢","genre":"七言律诗","yuefu":false,"paragraphs":["十二楼中尽晓妆，","望仙楼上望君王。","锁衔金兽连环冷，","水滴铜龙昼漏长。","云髻罢梳还对镜，","罗衣欲换更添香。","遥窥正殿帘开处，","袍裤宫人扫御床。"]},{"id":"221","title":"贫女","author":"秦韬玉","genre":"七言律诗","yuefu":false,"paragraphs":["蓬门未识绮罗香，","拟托良媒益自伤。","谁爱风流高格调？","共怜时世俭梳妆。","敢将十指夸针巧，","不把双眉斗画长。","苦恨年年压金线，","为他人作嫁衣裳。"]},{"id":"222","title":"独不见","author":"沈佺期","genre":"七言律诗","yuefu":false,"paragraphs":["卢家少妇郁金香，","海燕双栖玳瑁梁。","九月寒砧催木叶，","十年征戍忆辽阳。","白狼河北音书断，","丹凤城南秋夜长。","谁为含愁独不见，","更教明月照流黄？"]},{"id":"223","title":"鹿柴","author":"王维","genre":"五言绝句","yuefu":false,"paragraphs":["空山不见人，","但闻人语响。","返景入深林，","复照青苔上。"]},{"id":"224","title":"竹里馆","author":"王维","genre":"五言绝句","yuefu":false,"paragraphs":["独坐幽篁里，","弹琴复长啸。","深林人不知，","明月来相照。"]},{"id":"225","title":"山中送别","author":"王维","genre":"五言绝句","yuefu":false,"paragraphs":["山中相送罢，","日暮掩柴扉。","春草明年绿，","王孙归不归？"]},{"id":"226","title":"相思","author":"王维","genre":"五言绝句","yuefu":false,"paragraphs":["红豆生南国，","春来发几枝？","愿君多采撷，","此物最相思。"]},{"id":"227","title":"杂诗·其二","author":"王维","genre":"五言绝句","yuefu":false,"paragraphs":["君自故乡来，","应知故乡事。","来日绮窗前，","寒梅著花未？"]},{"id":"228","title":"送崔九","author":"裴迪","genre":"五言绝句","yuefu":false,"paragraphs":["归山深浅去，","须尽丘壑美。","莫学武陵人，","暂游桃源里。"]},{"id":"229","title":"终南望余雪","author":"祖咏","genre":"五言绝句","yuefu":false,"paragraphs":["终南阴岭秀，","积雪浮云端。","林表明霁色，","城中增暮寒。"]},{"id":"230","title":"宿建德江","author":"孟浩然","genre":"五言绝句","yuefu":false,"paragraphs":["移舟泊烟渚，","日暮客愁新。","野旷天低树，","江清月近人。"]},{"id":"231","title":"春晓","author":"孟浩然","genre":"五言绝句","yuefu":false,"paragraphs":["春眠不觉晓，","处处闻啼鸟。","夜来风雨声，","花落知多少？"]},{"id":"232","title":"静夜思","author":"李白","genre":"五言绝句","yuefu":false,"paragraphs":["床前明月光，","疑是地上霜。","举头望明月，","低头思故乡。"]},{"id":"233","title":"怨情","author":"李白","genre":"五言绝句","yuefu":false,"paragraphs":["美人卷珠帘，","深坐蹙蛾眉。","但见泪痕湿，","不知心恨谁？"]},{"id":"234","title":"八阵图","author":"杜甫","genre":"五言绝句","yuefu":false,"paragraphs":["功盖三分国，","名成八阵图。","江流石不转，","遗恨失吞吴。"]},{"id":"235","title":"登鹳雀楼","author":"王之涣","genre":"五言绝句","yuefu":false,"paragraphs":["白日依山尽，","黄河入海流。","欲穷千里目，","更上一层楼。"]},{"id":"236","title":"送灵澈","author":"刘长卿","genre":"五言绝句","yuefu":false,"paragraphs":["苍苍竹林寺，","杳杳钟声晚。","荷笠带斜阳，","青山独归远。"]},{"id":"237","title":"听弹琴","author":"刘长卿","genre":"五言绝句","yuefu":false,"paragraphs":["泠泠七弦上，","静听松风寒。","古调虽自爱，","今人多不弹。"]},{"id":"238","title":"送上人","author":"刘长卿","genre":"五言绝句","yuefu":false,"paragraphs":["孤云将野鹤，","岂向人间住！","莫买沃洲山，","时人已知处。"]},{"id":"239","title":"秋夜寄丘员外","author":"韦应物","genre":"五言绝句","yuefu":false,"paragraphs":["怀君属秋夜，","散步咏凉天。","空山松子落，","幽人应未眠。"]},{"id":"240","title":"听筝","author":"李端","genre":"五言绝句","yuefu":false,"paragraphs":["鸣筝金粟柱，","素手玉房前。","欲得周郎顾，","时时误拂弦。"]},{"id":"241","title":"新嫁娘词","author":"王建","genre":"五言绝句","yuefu":false,"paragraphs":["三日入厨下，","洗手作羹汤。","未谙姑食性，","先遣小姑尝。"]},{"id":"242","title":"玉台体","author":"权德舆","genre":"五言绝句","yuefu":false,"paragraphs":["昨夜裙带解，","今朝蟢子飞。","铅华不可弃，","莫是藁砧归。"]},{"id":"243","title":"江雪","author":"柳宗元","genre":"五言绝句","yuefu":false,"paragraphs":["千山鸟飞绝，","万径人踪灭。","孤舟蓑笠翁，","独钓寒江雪。"]},{"id":"244","title":"行宫","author":"元稹","genre":"五言绝句","yuefu":false,"paragraphs":["寥落古行宫，","宫花寂寞红。","白头宫女在，","闲坐说玄宗。"]},{"id":"245","title":"问刘十九","author":"白居易","genre":"五言绝句","yuefu":false,"paragraphs":["绿蚁新醅酒，","红泥小火炉。","晚来天欲雪，","能饮一杯无？"]},{"id":"246","title":"何满子","author":"张祜","genre":"五言绝句","yuefu":false,"paragraphs":["故国三千里，","深宫二十年。","一声何满子，","双泪落君前。"]},{"id":"247","title":"登乐游原","author":"李商隐","genre":"五言绝句","yuefu":false,"paragraphs":["向晚意不适，","驱车登古原。","夕阳无限好，","只是近黄昏。"]},{"id":"248","title":"寻隐者不遇","author":"贾岛","genre":"五言绝句","yuefu":false,"paragraphs":["松下问童子，","言师采药去。","只在此山中，","云深不知处。"]},{"id":"249","title":"渡汉江","author":"李频","genre":"五言绝句","yuefu":false,"paragraphs":["岭外音书绝，","经冬复立春。","近乡情更怯，","不敢问来人。"]},{"id":"250","title":"春怨","author":"金昌绪","genre":"五言绝句","yuefu":false,"paragraphs":["打起黄莺儿，","莫教枝上啼。","啼时惊妾梦，","不得到辽西。"]},{"id":"251","title":"哥舒歌","author":"西鄙人","genre":"五言绝句","yuefu":false,"paragraphs":["北斗七星高，","哥舒夜带刀。","至今窥牧马，","不敢过临洮。"]},{"id":"252","title":"长干行·其一","author":"崔颢","genre":"五言绝句","yuefu":true,"paragraphs":["君家何处住，","妾住在横塘。","停船暂借问，","或恐是同乡。"]},{"id":"253","title":"长干行·其二","author":"崔颢","genre":"五言绝句","yuefu":true,"paragraphs":["家临九江水，","来去九江侧。","同是长干人，","生小不相识。"]},{"id":"254","title":"玉阶怨","author":"李白","genre":"五言绝句","yuefu":true,"paragraphs":["玉阶生白露，","夜久侵罗袜。","却下水晶帘，","玲珑望秋月。"]},{"id":"255","title":"塞下曲·其一","author":"卢纶","genre":"五言绝句","yuefu":true,"paragraphs":["鹫翎金仆姑，","燕尾绣蝥弧。","独立扬新令，","千营共一呼。"]},{"id":"256","title":"塞下曲·其二","author":"卢纶","genre":"五言绝句","yuefu":true,"paragraphs":["林暗草惊风，","将军夜引弓。","平明寻白羽，","没在石棱中。"]},{"id":"257","title":"塞下曲·其三","author":"卢纶","genre":"五言绝句","yuefu":true,"paragraphs":["月黑雁飞高，","单于夜遁逃。","欲将轻骑逐，","大雪满弓刀。"]},{"id":"258","title":"塞下曲·其四","author":"卢纶","genre":"五言绝句","yuefu":true,"paragraphs":["野幕蔽琼筵，","羌戎贺劳旋。","醉和金甲舞，","雷鼓动山川。"]},{"id":"259","title":"江南曲","author":"李益","genre":"五言绝句","yuefu":true,"paragraphs":["嫁得瞿塘贾，","朝朝误妾期。","早知潮有信，","嫁与弄潮儿。"]},{"id":"260","title":"回乡偶书","author":"贺知章","genre":"七言绝句","yuefu":false,"paragraphs":["少小离家老大回，","乡音无改鬓毛衰。","儿童相见不相识，","笑问客从何处来？"]},{"id":"261","title":"桃花溪","author":"张旭","genre":"七言绝句","yuefu":false,"paragraphs":["隐隐飞桥隔野烟，","石矶西畔问渔船。","桃花尽日随流水，","洞在清溪何处边？"]},{"id":"262","title":"九月九日忆山东兄弟","author":"王维","genre":"七言绝句","yuefu":false,"paragraphs":["独在异乡为异客，","每逢佳节倍思亲。","遥知兄弟登高处，","遍插茱萸少一人。"]},{"id":"263","title":"芙蓉楼送辛渐","author":"王昌龄","genre":"七言绝句","yuefu":false,"paragraphs":["寒雨连江夜入吴，","平明送客楚山孤。","洛阳亲友如相问，","一片冰心在玉壶。"]},{"id":"264","title":"闺怨","author":"王昌龄","genre":"七言绝句","yuefu":false,"paragraphs":["闺中少妇不知愁，","春日凝妆上翠楼。","忽见陌头杨柳色，","悔教夫婿觅封侯。"]},{"id":"265","title":"春宫曲","author":"王昌龄","genre":"七言绝句","yuefu":false,"paragraphs":["昨夜风开露井桃，","未央前殿月轮高。","平阳歌舞新承宠，","帘外春寒赐锦袍。"]},{"id":"266","title":"黄鹤楼送孟浩然之广陵","author":"李白","genre":"七言绝句","yuefu":false,"paragraphs":["故人西辞黄鹤楼，","烟花三月下扬州。","孤帆远影碧空尽，","惟见长江天际流。"]},{"id":"267","title":"早发白帝城","author":"李白","genre":"七言绝句","yuefu":false,"paragraphs":["朝辞白帝彩云间，","千里江陵一日还。","两岸猿声啼不住，","轻舟已过万重山。"]},{"id":"268","title":"逢入京使","author":"岑参","genre":"七言绝句","yuefu":false,"paragraphs":["故园东望路漫漫，","双袖龙钟泪不干。","马上相逢无纸笔，","凭君传语报平安。"]},{"id":"269","title":"江南逢李龟年","author":"杜甫","genre":"七言绝句","yuefu":false,"paragraphs":["岐王宅里寻常见，","崔九堂前几度闻。","正是江南好风景，","落花时节又逢君。"]},{"id":"270","title":"滁州西涧","author":"韦应物","genre":"七言绝句","yuefu":false,"paragraphs":["独怜幽草涧边生，","上有黄鹂深树鸣。","春潮带雨晚来急，","野渡无人舟自横。"]},{"id":"271","title":"枫桥夜泊","author":"张继","genre":"七言绝句","yuefu":false,"paragraphs":["月落乌啼霜满天，","江枫渔火对愁眠。","姑苏城外寒山寺，","夜半钟声到客船。"]},{"id":"272","title":"寒食","author":"韩翃","genre":"七言绝句","yuefu":false,"paragraphs":["春城无处不飞花，","寒食东风御柳斜。","日暮汉宫传蜡烛，","轻烟散入五侯家。"]},{"id":"273","title":"月夜","author":"刘方平","genre":"七言绝句","yuefu":false,"paragraphs":["更深月色半人家，","北斗阑干南斗斜。","今夜偏知春气暖，","虫声新透绿窗纱。"]},{"id":"274","title":"春怨","author":"刘方平","genre":"七言绝句","yuefu":false,"paragraphs":["纱窗日落渐黄昏，","金屋无人见泪痕。","寂寞空庭春欲晚，","梨花满地不开门。"]},{"id":"275","title":"征人怨","author":"柳中庸","genre":"七言绝句","yuefu":false,"paragraphs":["岁岁金河复玉关，","朝朝马策与刀环。","三春白雪归青冢，","万里黄河绕黑山。"]},{"id":"276","title":"宫词","author":"顾况","genre":"七言绝句","yuefu":false,"paragraphs":["玉楼天半起笙歌，","风送宫嫔笑语和。","月殿影开闻夜漏，","水晶帘卷近秋河。"]},{"id":"277","title":"夜上受降城闻笛","author":"李益","genre":"七言绝句","yuefu":false,"paragraphs":["回乐峰前沙似雪，","受降城外月如霜。","不知何处吹芦管，","一夜征人尽望乡。"]},{"id":"278","title":"乌衣巷","author":"刘禹锡","genre":"七言绝句","yuefu":false,"paragraphs":["朱雀桥边野草花，","乌衣巷口夕阳斜。","旧时王谢堂前燕，","飞入寻常百姓家。"]},{"id":"279","title":"春词","author":"刘禹锡","genre":"七言绝句","yuefu":false,"paragraphs":["新妆宜面下朱楼，","深锁春光一院愁。","行到中庭数花朵，","蜻蜓飞上玉搔头。"]},{"id":"280","title":"后宫词","author":"白居易","genre":"七言绝句","yuefu":false,"paragraphs":["泪湿罗巾梦不成，","夜深前殿按歌声。","红颜未老恩先断，","斜倚薰笼坐到明。"]},{"id":"281","title":"赠内人","author":"张祜","genre":"七言绝句","yuefu":false,"paragraphs":["禁门宫树月痕过，","媚眼惟看宿鹭窠。","斜拔玉钗灯影畔，","剔开红焰救飞蛾。"]},{"id":"282","title":"集灵台·其一","author":"张祜","genre":"七言绝句","yuefu":false,"paragraphs":["日光斜照集灵台，","红树花迎晓露开。","昨夜上皇新授箓，","太真含笑入帘来。"]},{"id":"283","title":"集灵台·其二","author":"张祜","genre":"七言绝句","yuefu":false,"paragraphs":["虢国夫人承主恩，","平明骑马入宫门。","却嫌脂粉污颜色，","淡扫蛾眉朝至尊。"]},{"id":"284","title":"题金陵渡","author":"张祜","genre":"七言绝句","yuefu":false,"paragraphs":["金陵津渡小山楼，","一宿行人自可愁。","潮落夜江斜月里，","两三星火是瓜州。"]},{"id":"285","title":"宫词","author":"朱庆馀","genre":"七言绝句","yuefu":false,"paragraphs":["寂寂花时闭院门，","美人相并立琼轩。","含情欲说宫中事，","鹦鹉前头不敢言。"]},{"id":"286","title":"近试上张水部","author":"朱庆馀","genre":"七言绝句","yuefu":false,"paragraphs":["洞房昨夜停红烛，","待晓堂前拜舅姑。","妆罢低声问夫婿，","画眉深浅入时无？"]},{"id":"287","title":"将赴吴兴登乐游原一绝","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["清时有味是无能，","闲爱孤云静爱僧。","欲把一麾江海去，","乐游原上望昭陵。"]},{"id":"288","title":"赤壁","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["折戟沉沙铁未销，","自将磨洗认前朝。","东风不与周郎便，","铜雀春深锁二乔。"]},{"id":"289","title":"泊秦淮","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["烟笼寒水月笼沙，","夜泊秦淮近酒家。","商女不知亡国恨，","隔江犹唱《后庭花》。"]},{"id":"290","title":"寄扬州韩绰判官","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["青山隐隐水迢迢，","秋尽江南草未凋。","二十四桥明月夜，","玉人何处教吹箫？"]},{"id":"291","title":"遣怀","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["落魄江湖载酒行，","楚腰纤细掌中轻。","十年一觉扬州梦，","赢得青楼薄幸名。"]},{"id":"292","title":"秋夕","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["银烛秋光冷画屏，","轻罗小扇扑流萤。","天阶夜色凉如水，","坐看牵牛织女星。"]},{"id":"293","title":"赠别·其一","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["娉娉袅袅十三馀，","豆蔻梢头二月初。","春风十里扬州路，","卷上珠帘总不如。"]},{"id":"294","title":"赠别·其二","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["多情却似总无情，","唯觉樽前笑不成。","蜡烛有心还惜别，","替人垂泪到天明。"]},{"id":"295","title":"金谷园","author":"杜牧","genre":"七言绝句","yuefu":false,"paragraphs":["繁华事散逐香尘，","流水无情草自春。","日暮东风怨啼鸟，","落花犹似坠楼人。"]},{"id":"296","title":"夜雨寄北","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["君问归期未有期，","巴山夜雨涨秋池。","何当共剪西窗烛，","却话巴山夜雨时？"]},{"id":"297","title":"寄令狐郎中","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["嵩云秦树久离居，","双鲤迢迢一纸笔。","休问梁园旧宾客，","茂陵秋雨病相如。"]},{"id":"298","title":"为有","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["为有云屏无限娇，","凤城寒尽怕春宵。","无端嫁得金龟婿，","辜负香衾事早朝。"]},{"id":"299","title":"隋宫","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["乘兴南游不戒严，","九重谁省谏书函？","春风举国裁宫锦，","半作障泥半作帆。"]},{"id":"300","title":"瑶池","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["瑶池阿母绮窗开，","黄竹歌声动地哀。","八骏日行三万里，","穆王何事不重来？"]},{"id":"301","title":"嫦娥","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["云母屏风烛影深，","长河渐落晓星沈。","嫦娥应悔偷灵药，","碧海青天夜夜心。"]},{"id":"302","title":"贾生","author":"李商隐","genre":"七言绝句","yuefu":false,"paragraphs":["宣室求贤访逐臣，","贾生才调更无伦。","可怜夜半虚前席，","不问苍生问鬼神！"]},{"id":"303","title":"瑶瑟怨","author":"温庭筠","genre":"七言绝句","yuefu":false,"paragraphs":["冰簟银床梦不成，","碧天如水夜云轻。","雁声远过潇湘去，","十二楼中月自明。"]},{"id":"304","title":"马嵬坡","author":"郑畋","genre":"七言绝句","yuefu":false,"paragraphs":["玄宗回马杨妃死，","云雨难忘日月新。","终是圣明天子事，","景阳宫井又何人？"]},{"id":"305","title":"已凉","author":"韩偓","genre":"七言绝句","yuefu":false,"paragraphs":["碧阑干外绣帘垂，","猩色屏风画折枝。","八尺龙须方锦褥，","已凉天气未寒时。"]},{"id":"306","title":"台城","author":"韦庄","genre":"七言绝句","yuefu":false,"paragraphs":["江雨霏霏江草齐，","六朝如梦鸟空啼。","无情最是台城柳，","依旧烟笼十里堤。"]},{"id":"307","title":"陇西行","author":"陈陶","genre":"七言绝句","yuefu":false,"paragraphs":["誓扫匈奴不顾身，","五千貂锦丧胡尘。","可怜无定河边骨，","犹是深闺梦里人！"]},{"id":"308","title":"寄人","author":"张泌","genre":"七言绝句","yuefu":false,"paragraphs":["别梦依依到谢家，","小廊回合曲阑斜。","多情只有春庭月，","犹为离人照落花。"]},{"id":"309","title":"杂诗","author":"无名氏","genre":"七言绝句","yuefu":false,"paragraphs":["近寒食雨草萋萋，","著麦苗风柳映堤。","等是有家归未得，","杜鹃休向耳边啼。"]},{"id":"310","title":"凉州词","author":"王翰","genre":"七言绝句","yuefu":true,"paragraphs":["葡萄美酒夜光杯，","欲饮琵琶马上催。","醉卧沙场君莫笑，","古来征战几人回！"]},{"id":"311","title":"渭城曲","author":"王维","genre":"七言绝句","yuefu":true,"paragraphs":["渭城朝雨浥轻尘，","客舍青青柳色新。","劝君更尽一杯酒，","西出阳关无故人。"]},{"id":"312","title":"秋夜曲","author":"王维","genre":"七言绝句","yuefu":true,"paragraphs":["桂魄初生秋露微，","轻罗已薄未更衣。","银筝夜久殷勤弄，","心怯空房不忍归！"]},{"id":"313","title":"长信怨","author":"王昌龄","genre":"七言绝句","yuefu":true,"paragraphs":["奉帚平明金殿开，","且将团扇共徘徊。","玉颜不及寒鸦色，","犹带昭阳日影来。"]},{"id":"314","title":"出塞","author":"王昌龄","genre":"七言绝句","yuefu":true,"paragraphs":["秦时明月汉时关，","万里长征人未还。","但使龙城飞将在，","不教胡马渡阴山！"]},{"id":"315","title":"出塞","author":"王之涣","genre":"七言绝句","yuefu":true,"paragraphs":["黄河远上白云间，","一片孤城万仞山。","羌笛何须怨杨柳？","春风不度玉门关。"]},{"id":"316","title":"清平调·其一","author":"李白","genre":"七言绝句","yuefu":true,"paragraphs":["云想衣裳花想容，","春风拂槛露华浓。","若非群玉山头见，","会向瑶台月下逢。"]},{"id":"317","title":"清平调·其二","author":"李白","genre":"七言绝句","yuefu":true,"paragraphs":["一枝红艳露凝香，","云雨巫山枉断肠。","借问汉宫谁得似？","可怜飞燕倚新妆。"]},{"id":"318","title":"清平调·其三","author":"李白","genre":"七言绝句","yuefu":true,"paragraphs":["名花倾国两相欢，","常得君王带笑看。","解释春风无限恨，","沈香亭北倚阑干。"]},{"id":"319","title":"金缕衣","author":"杜秋娘","genre":"七言绝句","yuefu":true,"paragraphs":["劝君莫惜金缕衣，","劝君惜取少年时。","花开堪折直须折，","莫待无花空折枝！"]}],"ann":{"100":{"ti":"李白赠孟浩然。爱其风流——红颜弃轩冕、白首卧松云，以高山仰止作结，敬慕之情极其真挚。","zhu":[{"w":"孟夫子","v":"孟浩然，长李白十二岁。"},{"w":"红颜","v":"少壮之年。"},{"w":"轩冕","v":"轩车与冠冕，代指官位爵禄。"},{"w":"卧松云","v":"隐居山林。"},{"w":"中圣","v":"醉酒。古人称清酒为圣人、浊酒为贤人。"},{"w":"迷花","v":"迷恋花草，指隐居。"},{"w":"高山安可仰","v":"《诗经》「高山仰止，景行行止」，喻德高难及。"},{"w":"挹清芬","v":"汲取其清芬之气，谓景仰。"}],"yi":"我爱孟夫子，风流天下闻名。少年时就弃绝轩冕，到白首还高卧松云。醉月之下频频中酒，迷花之间不肯事君。高山哪能仰到尽头？只能在此汲取你的清芬。","shang":"「红颜弃轩冕，白首卧松云」十字写尽一生高致，为孟浩然定评。通篇以一「爱」字领起，一「仰」字收束，直呼直赞而不觉其谀，是赠答诗中最坦荡者。"},"101":{"ti":"李白出蜀途中渡荆门而作。山随平野尽、江入大荒流，是蜀中少年初见中原的开阔；结怜故乡水，情意无限。","zhu":[{"w":"荆门","v":"荆门山，在今湖北宜都，长江出峡处。"},{"w":"楚国","v":"今湖北一带，古楚地。"},{"w":"平野","v":"平坦原野。"},{"w":"大荒","v":"广阔无际的原野。"},{"w":"海楼","v":"海市蜃楼，云霞幻成楼台。"},{"w":"故乡水","v":"长江上游流经蜀地，故称。"},{"w":"怜","v":"爱。"}],"yi":"远渡荆门之外，来到古楚国遨游。山峦随着平原展尽，江水奔入大荒流淌。月影如天上飞来的明镜，云霞结成海市楼台。仍然怜爱这故乡的水，不远万里送我行舟。","shang":"「山随平野尽，江入大荒流」十字写尽出峡之境，与「月下飞天镜，云生结海楼」同为壮阔名句。结以故乡水相送，把长江写活了，乡情在「怜」字中婉转不尽。"},"102":{"ti":"李白送别友人而作。青山白水起兴，浮云落日为喻，「萧萧班马鸣」以马声收束，情在景中。","zhu":[{"w":"郭","v":"外城。"},{"w":"孤蓬","v":"随风飘转的蓬草，喻远行之人。"},{"w":"浮云","v":"飘忽无定，喻游子。"},{"w":"落日","v":"徐徐而下，喻依依不舍。"},{"w":"自兹去","v":"从此分别。"},{"w":"班马","v":"离群之马。"}],"yi":"青山横亘北郭之外，白水绕过东城。此地一经分别，你便如孤蓬万里远征。浮云是游子的心意，落日是故人的深情。挥手从此离去，萧萧声中连离群的马也不忍嘶鸣。","shang":"以「浮云游子意，落日故人情」把难状之情托于眼前之景，工丽天成。结句不写人而写马，班马犹恋，则人何以堪，余音全在萧萧声外。"},"103":{"ti":"李白听蜀僧濬弹琴而作。绿绮、峨眉、万壑松，写琴声之清越与知音之遇，不觉暮色已深。","zhu":[{"w":"濬","v":"僧人名，一作「浚」。"},{"w":"绿绮","v":"司马相如的琴名，代指名琴。"},{"w":"一挥手","v":"指弹琴的动作，极言其洒脱。"},{"w":"万壑松","v":"千山万谷的松涛声，喻琴声宏大清越。"},{"w":"客心","v":"客居者的心。"},{"w":"流水","v":"《列子》伯牙鼓琴、锺子期知音事，喻心被琴声涤净。"},{"w":"霜钟","v":"《山海经》丰山九钟「霜降则钟鸣」，此指暮色中寺钟。"}],"yi":"蜀地僧人抱着绿绮琴，从峨眉峰西边下来。为我挥手一弹，如听万壑松涛。客居的心被流水般的琴声洗净，余响融入霜降的暮钟。不觉碧山已暮，秋云暗了几重。","shang":"「为我一挥手，如听万壑松」以自然之声写琴声，气魄之大非寻常听琴诗所有。结以「不觉碧山暮」，写琴声移人至忘时之境，戛然而止而余韵无穷。"},"104":{"ti":"李白夜泊牛渚，忆东晋袁宏牛渚咏诗、谢尚月下知音事。怀古而叹知音难再，全篇不用一典外之事，一气旋折。","zhu":[{"w":"牛渚","v":"山名，在今安徽当涂，临长江。"},{"w":"西江","v":"古称长江自南京至江西段为西江。"},{"w":"谢将军","v":"东晋谢尚，镇守牛渚时，秋夜泛江闻袁宏咏诗，遂引与交谈，宏由是知名。"},{"w":"高咏","v":"善于吟诗。"},{"w":"斯人","v":"指谢尚那样识才之人。"},{"w":"挂帆席","v":"扬起船帆。"}],"yi":"牛渚山西江的夜里，青天没有一丝云。登上船头望秋月，空自忆念谢将军。我也能登高长咏，可再没有斯人可闻。明朝挂起帆席离去，枫叶正落得纷纷。","shang":"此诗五律而全篇不对仗，行若流水，是李白以气行文、不拘绳墨的名例。「空忆」「不可闻」，古之知音已渺，今之赏音无人，一「空」字贯全篇。结以枫叶纷纷，情与景俱萧瑟。"},"105":{"ti":"杜甫陷长安时望月思妻。不说自己看月，反写妻子独看，小儿女未解忆长安，愈见其孤。老杜五律深挚之作。","zhu":[{"w":"鄜州","v":"今陕西富县，杜甫家小寄居处。"},{"w":"闺中","v":"指妻子。"},{"w":"未解忆","v":"还不懂得想念在长安的父亲。"},{"w":"香雾","v":"夜雾沾染发香。"},{"w":"云鬟","v":"如云的发髻。"},{"w":"清辉","v":"月光。"},{"w":"虚幌","v":"轻薄透明的帷幔。"},{"w":"双照","v":"月光同照两人。"}],"yi":"今夜鄜州的月，闺中只有你独自看。遥怜幼小的儿女，还不懂得思念在长安的父亲。夜雾沾湿了你的云鬟，月光冷着你的玉臂。何时共倚薄帷，让月色照干两个人的泪痕？","shang":"全篇从对面着想，无一字言己之苦而苦楚倍深。「香雾云鬟湿，清辉玉臂寒」想象妻子久立月下，痴极而生怜。结以「双照泪痕干」，以未来之团圆反照眼前之离散，笔法曲折至此。"},"106":{"ti":"杜甫至德二载陷贼中望春而作。国破山河在，一开篇便字字千钧；家书抵万金，写尽乱离人心。","zhu":[{"w":"国破","v":"指长安沦陷。"},{"w":"感时","v":"感伤时局。"},{"w":"花溅泪","v":"见花而泪落，一说花亦溅泪。"},{"w":"恨别","v":"怅恨离别。"},{"w":"鸟惊心","v":"闻鸟鸣而心惊。"},{"w":"烽火连三月","v":"战火连续到三月（一说连逢三月，言战事之久）。"},{"w":"浑欲","v":"简直要。"},{"w":"不胜簪","v":"插不住簪子。古男子束发戴冠用簪。"}],"yi":"国都残破，山河犹在；春天又到，城中草木深深。感伤时局，见花开也溅泪；怅恨离别，闻鸟鸣也惊心。战火连着三个月不断，家书一封抵得万金。白发越搔越短，简直要插不住簪子。","shang":"「国破山河在」一开篇便是沉痛至极的对举——破者在国、在者在山河，人事全非而天地依然。颈联「家书抵万金」道尽战乱人心，遂成千古共语。全篇沉郁顿挫，五律至此，字字有鼎。"},"107":{"ti":"杜甫任左拾遗时夜宿门下省。星临万户、月傍九霄，写宫禁气象；因明日有封事，数问夜如何，忠谨之情见于细节。","zhu":[{"w":"左省","v":"门下省，杜甫时任左拾遗。"},{"w":"掖垣","v":"宫墙旁侧的官署，此指门下省。"},{"w":"万户","v":"宫中千门万户。"},{"w":"九霄","v":"天之极高处。"},{"w":"金钥","v":"宫门锁钥之声。"},{"w":"玉珂","v":"马勒上的玉饰，百官早朝马以玉珂相鸣。"},{"w":"封事","v":"密封的奏章。"}],"yi":"暮色里花影隐入宫墙，栖鸟啾啾飞过。星光下临，千门万户似在浮动；明月傍着九霄，得月独多。睡不着听宫门锁钥，因风起疑是玉珂鸣响。明朝有封事要上，几次问夜到了几更？","shang":"「星临万户动，月傍九霄多」一「动」一「多」，宫殿如在目前，气象壮丽。后四句写不寝待旦，「数问夜如何」五字，把一个小小谏官的忠勤写得神采奕奕。"},"108":{"ti":"杜甫至德二载收复长安后，因疏救房琯被贬华州，出金光门而作。题序甚长。驻马望千门，眷恋君国之情极深。","zhu":[{"w":"金光门","v":"长安西面中门。"},{"w":"归顺","v":"投奔肃宗行在。"},{"w":"胡正繁","v":"胡兵正当猖獗。"},{"w":"残破胆","v":"心胆犹存惊惧。"},{"w":"未招魂","v":"惊魂未定，如尚未招回。"},{"w":"移官","v":"被贬华州司功参军。"},{"w":"岂至尊","v":"难道出于皇帝本意？谓出自贺兰进明等排挤。"},{"w":"千门","v":"宫门，代指朝廷。"}],"yi":"当年投奔行在走的正是此道，西郊胡兵正猖獗。至今想起来心胆犹碎，惊魂怕是还未招回。近来得以回到京邑，改官外任岂是皇帝本意？无才之人日见衰老，驻马回望宫门千重。","shang":"全篇自省而不敢怨君，「移官岂至尊」五字回护婉转，忠厚至极。结句「驻马望千门」，一望之间，去国之痛与恋阙之情尽在其中。杜诗之温柔敦厚，此篇最可玩味。"},"109":{"ti":"杜甫乾元二年秋在秦州，忆战乱中离散诸弟。露从今夜白、月是故乡明，一联白话而有至情。","zhu":[{"w":"舍弟","v":"对人称自己的弟弟。"},{"w":"戍鼓","v":"戍楼的更鼓。"},{"w":"断人行","v":"宵禁后断绝行人。"},{"w":"秋边","v":"秋天的边地，一作「边秋」。"},{"w":"露从今夜白","v":"是夜适逢白露节气。"},{"w":"无家","v":"战乱中家业荡然，无处存问。"},{"w":"寄书","v":"寄信。"},{"w":"况乃","v":"何况。"}],"yi":"戍楼鼓响路上断绝行人，秋夜边地一只孤雁哀鸣。露水从今夜起更白了，月亮还是故乡的明。兄弟们各自离散，没有家可问他们的死生。寄出的信常常不能送达，何况战事还没有停息。","shang":"「露从今夜白，月是故乡明」明明是同一轮月、同一种露，偏说故乡的明，无理而妙至情，遂成千古名句。「无家问死生」五字沉痛之极。全篇从雁声月色写至兵戈，层次井然。"},"110":{"ti":"杜甫闻李白流放夜郎，天末怀人而作。文章憎命达、魑魅喜人过，同情与不平并见，末欲投诗汨罗，哀之至也。","zhu":[{"w":"天末","v":"天的尽头，指秦州边地。"},{"w":"君子","v":"指李白。"},{"w":"鸿雁","v":"喻音信。"},{"w":"江湖秋水多","v":"江湖风波险恶，喻世路艰危。"},{"w":"文章憎命达","v":"好文章总与困厄的命运相伴随。"},{"w":"魑魅","v":"山林精怪，喻奸邪之人。"},{"w":"冤魂","v":"指屈原。"},{"w":"汨罗","v":"屈原自沉之江，在今湖南。"}],"yi":"凉风从天边吹起，你如今心情如何？鸿雁几时才能捎信来，江湖上秋水正多风波。文章偏偏憎恶命运通达，魑魅之属最喜人经过。你应共屈原冤魂共语，投诗赠与汨罗江水。","shang":"「文章憎命达，魑魅喜人过」十字，是替天下才人发的牢骚，亦是对造化不公的抗议，故成千古名论。结以投诗汨罗，以屈子拟李白，哀痛之情可以想见。"},"111":{"ti":"杜甫送别严武再镇蜀，至奉济驿重送而作。严武一去，蜀中又乱，诗人在「寂寞养残生」的预感中作别。","zhu":[{"w":"严公","v":"严武，剑南节度使，杜甫好友兼靠山。"},{"w":"四韵","v":"八句律诗。"},{"w":"空复情","v":"枉自多情，谓青山相送亦是徒然。"},{"w":"几时杯重把","v":"何时再能举杯相聚。"},{"w":"列郡","v":"剑南所属各郡。"},{"w":"讴歌惜","v":"歌颂而惋惜其离任。"},{"w":"三朝","v":"玄宗、肃宗、代宗三朝。"},{"w":"将村","v":"浣花溪畔杜甫草堂所在地（一作梓州）。"}],"yi":"远送你从此分别，青山空自多情。何时能再举杯共饮？昨夜我们还月下同行。各郡百姓讴歌、惋惜你的离任，你三朝出入、历仕荣显。而我独归将村草堂，寂寞地养此残生。","shang":"「几时杯重把，昨夜月同行」流水对写离合，最见亲切。末二句由严公之荣反照己之寂寞，一荣一枯，全篇之意归于「寂寞养残生」五字，怅惘欲绝。"},"112":{"ti":"杜甫经阆州房琯墓而作。房琯于杜甫有知遇之恩，因救琯而贬，故诗极沉痛。近泪无干土，一联至情。","zhu":[{"w":"房太尉","v":"房琯，玄宗朝宰相，肃宗时罢相，杜甫因上疏救之遭贬。"},{"w":"行役","v":"因公务跋涉。"},{"w":"对棋陪谢傅","v":"晋谢安（谢太傅）嗜围棋，房琯喜谈兵下棋，以谢安拟之。"},{"w":"把剑觅徐君","v":"吴季札挂剑于徐君墓树以偿心诺，喻生死之交。"},{"w":"断云","v":"孤云。"}],"yi":"在他乡又一次奔波行役，驻马拜别这座孤坟。泪水近处没有干土，低空飘着片片断云。当年对弈，我曾陪侍如谢傅之客；今日把剑，如季札寻访徐君。只见林花纷纷落尽，黄莺的啼声送着来客。","shang":"「近泪无干土，低空有断云」以极真之语写极痛之情，是哭友名句。连用谢傅、徐君二典，一忆生前之交、一证死后之诺。结以莺啼花落，物犹有情，人何以堪。"},"113":{"ti":"杜甫代宗永泰元年离蜀东下，舟中夜泊而作。星垂平野阔、月涌大江流，写景壮阔；天地一沙鸥，自伤身世至极。","zhu":[{"w":"细草微风岸","v":"岸上细草，微风轻拂。"},{"w":"危樯","v":"高高的桅杆。"},{"w":"独夜舟","v":"孤舟夜泊。"},{"w":"星垂","v":"星光低垂。"},{"w":"月涌","v":"月影随波涌动。"},{"w":"名岂文章著","v":"名声岂是因文章而显著（自嘲抱负不在文章）。"},{"w":"官应老病休","v":"官职应因老病而休退（实为排挤所致）。"},{"w":"沙鸥","v":"水鸟，喻漂泊无依。"}],"yi":"细草在微风中摇曳的岸边，高桅下泊着我孤零零的夜舟。星光低垂，平野显得辽阔；月影涌动，大江滚滚奔流。名声岂是靠文章而显？官位应因老病而休。飘飘荡荡像什么？像天地间一只沙鸥。","shang":"「星垂平野阔，月涌大江流」境界之大，与「山随平野尽」并为唐人写江夜双璧。后四句自嘲自伤，「名岂」「官应」两问，愤懑全在字缝里；结以天地沙鸥，渺小与广大相形，孤绝之感千古无两。"},"114":{"ti":"杜甫晚年登岳阳楼而作。吴楚坼、乾坤浮，写洞庭之壮阔已极；亲朋无一字、老病有孤舟，写身世之孤绝亦极，遂成杜律第一。","zhu":[{"w":"岳阳楼","v":"今湖南岳阳西门城楼，下临洞庭。"},{"w":"吴楚","v":"春秋吴楚之地，洞庭湖东为吴、南为楚。"},{"w":"坼","v":"分裂。"},{"w":"乾坤","v":"天地，此指日月星辰。"},{"w":"日夜浮","v":"日夜浮于湖面（湖水浩阔，日月似浮其间）。"},{"w":"无一字","v":"音信全无。"},{"w":"戎马","v":"战事。时吐蕃犯边。"},{"w":"凭轩","v":"倚着栏杆。"},{"w":"涕泗","v":"眼泪鼻涕。"}],"yi":"昔日听闻洞庭水阔，今天登上岳阳楼。吴楚之地被湖分割东南，日月星辰日夜浮沉其间。亲朋故旧无一字音信，年老多病只有一叶孤舟。北面关山战事未息，凭栏远望，涕泪横流。","shang":"前四句写景，气吞湖海；后四句写身世，孤舟老病——大与小的强烈反差，正是此诗动人的力量。结以「凭轩涕泗流」，由一身之孤推及天下之乱，杜诗「沉郁」至此为极。宋人推为登楼诗第一。"},"115":{"ti":"王维隐居辋川，赠裴迪。寒山秋水、渡头落日、墟里孤烟，与醉后狂歌的接舆（裴迪）相映，闲适之至。","zhu":[{"w":"辋川","v":"王维别业所在，在今陕西蓝田。"},{"w":"潺湲","v":"水流声。"},{"w":"渡头","v":"渡口。"},{"w":"墟里","v":"村落。"},{"w":"孤烟","v":"炊烟。"},{"w":"接舆","v":"春秋楚狂人陆通，此借指裴迪。"},{"w":"五柳","v":"陶渊明五柳先生，王维自比。"}],"yi":"寒山渐渐转为苍翠，秋水一天天潺潺流淌。倚着柴门立在门外，临风听暮蝉声声。渡口留着一轮落日，村落升起一缕孤烟。又碰到你像接舆那样喝醉，在我这五柳堂前狂歌。","shang":"「渡头馀落日，墟里上孤烟」十字如画，一「馀」一「上」最见功夫——落日是余晖之静，孤烟是上升之动，静动相生。结以接舆、五柳两个典故把裴迪与自己写入画中，淡而有味。"},"116":{"ti":"王维居辋川，秋暝山居而作。明月清泉、竹喧莲动，声色俱清，是王维山水诗的代表作，「诗中有画」之最佳注脚。","zhu":[{"w":"暝","v":"日暮。"},{"w":"空山","v":"幽静少人的山。"},{"w":"浣女","v":"洗衣服的女子。"},{"w":"春芳歇","v":"春天的芳华消歇。"},{"w":"王孙","v":"贵族子弟，此诗人自指。反用《楚辞》「王孙兮归来，山中兮不可久留」。"}],"yi":"空山刚下过一场新雨，天气带来晚来的秋意。明月照进松林，清泉流过山石。竹林喧响，是浣衣女子归来；莲叶摇动，是渔舟顺流而下。任凭春天的芳菲消歇吧，王孙自可留在山中。","shang":"「明月松间照，清泉石上流」一静照、一动流，为山水诗极则；「竹喧」「莲动」先闻声而后见人，倒装得趣。尾联反用楚辞，宣言留居山中——秋景胜于春芳，是王维的隐逸宣言。"},"117":{"ti":"王维归嵩山时作。清川长薄、暮禽相还，一路写景俱是归意，结以「归来且闭关」，万念俱收。","zhu":[{"w":"嵩山","v":"五岳之中岳，在今河南登封。"},{"w":"清川","v":"清澈的河川。"},{"w":"长薄","v":"绵延的草木丛。"},{"w":"闲闲","v":"从容自得的样子。"},{"w":"暮禽","v":"傍晚归巢的鸟。"},{"w":"迢递","v":"遥远的样子。"},{"w":"闭关","v":"闭门谢客。"}],"yi":"清川带着绵延的草木，车马从容地归去。流水像是有意相送，暮禽与我相偕还山。荒城临着古渡，落日洒满秋山。迢迢嵩山之下，归来暂且闭门谢客。","shang":"「流水如有意，暮禽相与还」以物之有情写己之归心，与陶诗「山气日夕佳，飞鸟相与还」同一机杼。结句「且闭关」之「且」字，见归隐是权宜、其心未灰，微妙之至。"},"118":{"ti":"王维游终南山而作。白云青霭、阴晴众壑，写尽山之大；「隔水问樵夫」以一问收千仞之高。","zhu":[{"w":"太乙","v":"终南山主峰，亦代指终南山。"},{"w":"天都","v":"天帝之都。"},{"w":"海隅","v":"海边。"},{"w":"青霭","v":"山间青色云气。"},{"w":"入看无","v":"走近了反而看不见。"},{"w":"分野","v":"古人以星宿划分地上区域。"},{"w":"中峰","v":"太乙主峰。"},{"w":"人处","v":"有人烟处。"}],"yi":"太乙峰接近天帝之都，山脉连绵直到海边。白云回望时又合成一片，青霭走近了反而无痕。中峰变了分野，众壑阴晴各殊。想找人家投宿，隔着溪水问那樵夫。","shang":"「白云回望合，青霭入看无」写山之烟云最妙——远望有、近看无，正是山间真境。「隔水问樵夫」收束奇绝：山高人小，以一人之声衬千岩之静，画意与诗心俱绝。"},"119":{"ti":"王维晚年酬张少府。晚年好静、万事不关心，松风山月之间，以「渔歌入浦深」答穷通之问，禅意最深。","zhu":[{"w":"张少府","v":"名不详，任县尉。"},{"w":"长策","v":"良策。"},{"w":"旧林","v":"旧日山林，喻归隐之所。语本《庄子》。「君其涉于江而浮于海」。」"},{"w":"穷通","v":"困厄与显达。"},{"w":"渔歌入浦深","v":"隐者之歌渐入水浦深处，谓不答之答。"}],"yi":"晚年只爱好清静，万事都不再关心。自顾没有经世长策，只知道返回旧日山林。松风吹开衣带，山月照我弹琴。你问穷通之理？听那渔歌渐渐唱入水浦深处。","shang":"「君问穷通理，渔歌入浦深」以不答为答，是全诗之眼——穷通之理本不可言，惟有付与渔歌。首联「万事不关心」看似枯淡，正因「自顾无长策」之痛。王维晚年禅诗，此为最冲淡者。"},"120":{"ti":"王维寻访香积寺，数里入云峰而始闻钟声。泉咽危石、日冷青松，写深山之幽，结以「安禅制毒龙」，禅理入化。","zhu":[{"w":"香积寺","v":"在长安终南山子午谷，一说不必寻路而遇，故云不知。"},{"w":"云峰","v":"高入云中的山峰。"},{"w":"咽","v":"呜咽。泉流受阻声如哽咽。"},{"w":"危石","v":"高耸的岩石。"},{"w":"冷青松","v":"日光穿松，色淡生寒。"},{"w":"空潭曲","v":"潭水澄静的湾曲处。"},{"w":"安禅","v":"安然入于禅定。"},{"w":"毒龙","v":"佛家喻妄念欲火。《涅槃经》：「但我住处有一毒龙，其性暴急，恐相危害」。"}],"yi":"不知道香积寺在哪里，走了数里已入云中峰峦。古木之间没有人的小径，深山何处传来钟声？泉水在危石间呜咽，日色在青松上生寒。薄暮时分，空潭湾曲澄澈——安禅入定，制伏心中毒龙。","shang":"「泉声咽危石，日色冷青松」一「咽」一「冷」，声音与光色皆着幽寒之色，为炼字名例。全篇由「不知」起、以「制毒龙」结，寻寺之旅即是入禅之旅，物境心境浑然一体。"},"121":{"ti":"王维送友人李使君赴梓州刺史任。写蜀中万壑千山、一夜雨后百重泉，勉其兴学教化，如文翁之化蜀。","zhu":[{"w":"梓州","v":"今四川三台，唐属东川。"},{"w":"使君","v":"对州郡长官的尊称。"},{"w":"树杪","v":"树梢。"},{"w":"橦布","v":"橦木花织成的布，蜀地特产。"},{"w":"输","v":"缴纳。"},{"w":"巴人","v":"巴地之民，蜀人称巴。"},{"w":"讼芋田","v":"为芋田的争讼，谓民务农事而有田讼。"},{"w":"文翁","v":"汉景帝时蜀郡太守，兴办学校，教化蜀人。"},{"w":"翻教授","v":"翻然改变风气、推行教化。"}],"yi":"万壑之间树木参天，千山之中响遍杜鹃。山里下了一夜雨，树梢上泻下百重飞泉。汉家女子缴纳橦布，巴人常常为芋田兴讼。要像文翁那样翻新教化，不敢倚仗前贤而不作为。","shang":"「山中一夜雨，树杪百重泉」以奇想写雨后山泉，为唐人写蜀中山水第一名句。前四句写景即蜀中山川之险远，后四句用文翁典以勉其教化，送刺史之诗不作寒暄语，格局自高。"},"122":{"ti":"王维临眺汉江而作。江流天地外、山色有无中，写大水茫茫之境为千古绝调；结以襄阳风日，愿与山翁共醉。","zhu":[{"w":"汉江","v":"即汉水。"},{"w":"临眺","v":"登高远望。"},{"w":"楚塞","v":"古楚国的边界。"},{"w":"三湘","v":"潇湘、蒸湘、沅湘，泛指洞庭南北。"},{"w":"荆门","v":"荆门山，楚地西境。"},{"w":"九派","v":"长江至浔阳分为九支。"},{"w":"前浦","v":"眼前水滨。"},{"w":"山翁","v":"晋山简，镇襄阳，好酒，此借指当地友人。"}],"yi":"楚塞连着三湘水，荆门通九派长江。江水流到天地之外，山色若有若无之间。城郭仿佛浮在前面水滨，波澜摇动着远处的天空。襄阳的风日如此美好，愿留在山翁处一同醉倒。","shang":"「江流天地外，山色有无中」把汉江写成天地间的浩渺之气，王世贞推为「唐诗中的画」。郡邑「浮」、波澜「动」，一派水气氤氲。结句以醉入景，是王维少见的纵情之笔。"},"123":{"ti":"王维晚年隐居辋川自述。行到水穷处，坐看云起时——随缘任运，是唐诗中最见禅境的一联。","zhu":[{"w":"中岁","v":"中年。"},{"w":"好道","v":"信奉佛理。"},{"w":"南山陲","v":"终南山边，指辋川。"},{"w":"胜事","v":"美好的事。"},{"w":"空自知","v":"只有自己心领，无人分享。"},{"w":"水穷处","v":"水流尽头。"},{"w":"值","v":"遇到。"},{"w":"林叟","v":"山林老人。"},{"w":"无还期","v":"忘了回去的时间。"}],"yi":"中年以后颇好佛道，晚年安家在终南山边。兴致来了独自前往，美好之事只有自己知道。行到水的尽头，就坐下来看云起云落。偶然遇见林中老翁，谈笑之间忘了归期。","shang":"「行到水穷处，坐看云起时」上句写已尽之境，下句写方生之机——路穷而云起，禅家的随缘自适全在此十字之中，故为千古禅诗第一名联。通篇如话家常，「空自知」「无还期」皆不作意而意远。"},"124":{"ti":"孟浩然望洞庭湖上书干张九龄。气蒸云梦泽、波撼岳阳城，写湖之壮阔前无古人；欲济无舟楫，望荐之情见于言外。","zhu":[{"w":"张丞相","v":"张九龄，时为宰相。"},{"w":"涵虚","v":"水汽迷茫的湖面。涵，包含；虚，天空。"},{"w":"太清","v":"天空。"},{"w":"云梦泽","v":"古大泽，跨今两湖之地。"},{"w":"岳阳城","v":"今湖南岳阳，滨洞庭。"},{"w":"济","v":"渡。"},{"w":"舟楫","v":"船和桨，喻引荐。"},{"w":"端居","v":"平居闲处。"},{"w":"羡鱼情","v":"《汉书》「临渊羡鱼，不如退而结网」，此喻空有出仕之愿。"}],"yi":"八月洞庭湖水盛涨，与天相接浑然一体。水气蒸腾着云梦大泽，波涛撼动了岳阳古城。想渡湖却无舟楫，闲居圣明之世实在有愧。坐着看那垂钓的人，空有一片羡鱼之情。","shang":"「气蒸云梦泽，波撼岳阳城」以一「蒸」一「撼」写尽洞庭的吞吐气象，为咏洞庭第一名句。前四句壮阔之极，后四句转出「欲济无舟楫」，干谒之意全用比兴，不露寒乞，是干谒诗的体面之作。"},"125":{"ti":"孟浩然与友人登岘山怀羊祜而作。人事有代谢，往来成古今——开篇即是大感慨；读羊公碑而泪下，人生之暂与山水之常两相对照。","zhu":[{"w":"岘山","v":"在今湖北襄阳，晋羊祜镇襄阳时常登临。"},{"w":"代谢","v":"更替变化。"},{"w":"胜迹","v":"名胜古迹。"},{"w":"鱼梁","v":"汉水中的沙洲，庞德公隐居处。"},{"w":"梦泽","v":"云梦泽。"},{"w":"羊公碑","v":"羊祜有德于襄阳，百姓立碑，望其碑者皆流涕，杜预因名「堕泪碑」。"}],"yi":"人间之事有更替变化，来来往往便成了古今。江山留着胜迹，我们这辈人又来登临。水落了鱼梁洲浅露，天寒了云梦泽幽深。羊公的碑字还在，读罢泪已沾襟。","shang":"开篇十字不着一景而千古兴亡俱在其中，气象极老。中二联以水落天寒写登临之景，暗含岁月之肃杀。结以羊公碑，羊祜当年「自有宇宙，便有此山」之叹与此诗同一感慨，故读罢泪下。"},"126":{"ti":"孟浩然赴梅道士山房宴饮。青鸟使邀、赤松家饮，仙家气象；末言若得驻童颜，何惜一醉流霞，放达中见超逸。","zhu":[{"w":"梅道士","v":"孟浩然友人，隐居修道者。"},{"w":"林卧","v":"高卧林下。"},{"w":"物华","v":"美好的景物。"},{"w":"青鸟使","v":"神话中西王母传信之鸟，此指梅道士的使者。"},{"w":"赤松","v":"仙人赤松子，此借指梅道士。"},{"w":"丹灶","v":"炼丹的炉灶。"},{"w":"流霞","v":"传说仙酒名，饮之不饥。"}],"yi":"高卧林间愁春将尽，推窗一揽满眼物华。忽然遇见青鸟使者，邀我进入赤松之家。丹灶刚生起火，仙桃正开着花。童颜若是可以留住，何惜一醉流霞仙酒！","shang":"通篇以仙家语写寻常宴饮，青鸟、赤松、丹灶、仙桃、流霞，错落成趣。「童颜若可驻，何惜醉流霞」以半戏之语作结，见出诗人豁达的名士气。"},"127":{"ti":"孟浩然岁暮自长安归南山而作。「不才明主弃，多病故人疏」，据《新唐书》，玄宗闻此二句而叹「卿不求仕，而朕未尝弃卿」，遂放归。","zhu":[{"w":"南山","v":"襄阳岘山之南，孟浩然家园所在。"},{"w":"北阙","v":"宫禁北面的门楼，大臣上书奏事之所。"},{"w":"敝庐","v":"破旧的居所。"},{"w":"不才","v":"没有才能（自谦兼自嘲）。"},{"w":"青阳","v":"春天。"},{"w":"岁除","v":"年终。"},{"w":"松月夜窗墟","v":"松间月色照着夜窗虚室（墟，一作虚）。"}],"yi":"不必再向宫门上书了，回到南山我的旧居。没有才干被明主弃置，体弱多病连故人也疏远。白发催着人老去，春天逼走了残年。长怀愁绪夜不能寐，松间月色照着空窗。","shang":"「不才明主弃，多病故人疏」十字自嘲，怨在有无之间——「明主」反语最见分寸，故玄宗读之亦无可责。结以松月空窗，以景结情，落寞之境如在眼前。"},"128":{"ti":"孟浩然应邀过访田家。鸡黍之约、绿树青山，把酒话桑麻，一片田家真味，为田园诗的极平实之作。","zhu":[{"w":"具鸡黍","v":"备办鸡和黄米饭，指农家待客的饭食。"},{"w":"合","v":"环绕。"},{"w":"郭","v":"外城。"},{"w":"开轩","v":"打开窗户。"},{"w":"场圃","v":"打谷场与菜园。"},{"w":"话桑麻","v":"谈论农事。桑麻代指庄稼。"},{"w":"就菊花","v":"来赏菊共饮。重阳有菊酒之约。"}],"yi":"老朋友备好鸡黍饭菜，邀请我到他田家。绿树把村边合围，青山在郭外斜横。推开窗对着场圃，把酒闲话桑麻。等到九月重阳那天，还要来此赏菊。","shang":"全篇如话家常，毫无奇字奥句，而恬淡之味自足——「话桑麻」三字最见田家风神。结以重阳之约，不作离恨语而情味更长。陶渊明之后，田园诗至此又一极。"},"129":{"ti":"孟浩然在长安（秦中）感秋寄诗僧上人。黄金燃桂尽、壮志逐年衰，写干谒落空的穷愁，闻蝉益悲。","zhu":[{"w":"秦中","v":"关中，指长安。"},{"w":"远上人","v":"名远的僧人。上人，对僧人的尊称。"},{"w":"一丘","v":"一丘一壑，指隐居。"},{"w":"三径","v":"汉蒋诩隐居开三径，指隐者家园。"},{"w":"北土","v":"指长安。"},{"w":"东林","v":"晋慧远居庐山东林寺，代指佛寺，指上人处。"},{"w":"燃桂","v":"长安柴米昂贵，如烧桂煮玉。"}],"yi":"本想归卧一丘山林，苦于营建三径没有资财。北土非我所愿，东林里怀念我的师父。黄金像烧桂一样耗尽，壮志逐年衰减。傍晚凉风吹来，听见蝉声只有更悲。","shang":"「黄金燃桂尽，壮志逐年衰」写长安居之不易与志气之消磨，俱见沉痛。结以凉风蝉声，秋气袭人，客愁与蝉声相和而益悲。孟浩然长安失意诸作，此篇最见穷愁之态。"},"130":{"ti":"孟浩然夜泊桐庐江，寄扬州（广陵）旧友。山暝猿愁、沧江夜流，月照孤舟，还把两行泪遥寄海西头。","zhu":[{"w":"桐庐江","v":"富春江上游，在今浙江桐庐。"},{"w":"广陵","v":"今江苏扬州。"},{"w":"山暝","v":"山中昏暗。"},{"w":"沧江","v":"江水青苍之色。"},{"w":"建德","v":"桐庐邻县，作者泛指其地。"},{"w":"非吾土","v":"不是我的故乡。用王粲《登楼赋》「虽信美而非吾土兮」。"},{"w":"维扬","v":"扬州。"},{"w":"海西头","v":"扬州古称海西头（隋炀帝诗）。"}],"yi":"山中昏暗听猿声生愁，沧江湍急连夜奔流。风摇两岸的树叶，月光照着一只孤舟。建德虽好终非吾土，遥忆扬州的旧日交游。且把这两行热泪，遥遥寄到海西头。","shang":"「风鸣两岸叶，月照一孤舟」以动写静、以阔写孤，羁旅之境如画。「还将两行泪，遥寄海西头」，泪可寄远，痴语至情，孟诗之真挚如此。"},"131":{"ti":"孟浩然长安干谒落空，留别王维。当路谁相假、知音世所稀，愤懑与孤高并见，遂「还掩故园扉」。","zhu":[{"w":"寂寂","v":"落寞无闻。"},{"w":"寻芳草","v":"归隐寻芳草之泽。"},{"w":"违","v":"离别。"},{"w":"当路","v":"当权者。"},{"w":"相假","v":"相助提携。"},{"w":"知音","v":"知己。"}],"yi":"这样落寂还能等什么？天天白白地空手而归。想寻芳草归隐去，又舍不得与故人分离。当权者有谁来相假？知音在这世上本就稀少。只应守着这寂寞，再掩上故园的门扉。","shang":"「当路谁相假，知音世所稀」一问一叹，把干谒之辱与世无知音之痛说尽。结句「还掩故园扉」动作轻微而决绝极深。此诗与《岁暮归南山》同为孟浩然失意长安之作，愤语最直。"},"132":{"ti":"孟浩然秋江早寒怀乡。木落雁南渡、北风江上寒，起句萧瑟已极；乡泪客中尽，迷津欲有问，归思与迷惘交织。","zhu":[{"w":"木落","v":"树叶飘落。"},{"w":"襄水曲","v":"襄水弯曲处，指襄阳故乡。"},{"w":"楚云端","v":"楚地的天边。"},{"w":"迷津","v":"迷失渡口。《论语》使子路问津事。"},{"w":"平海","v":"江水入海处水面平阔。"}],"yi":"树叶落了雁往南飞，北风吹得江上一片寒。我家在襄水弯曲处，遥隔在楚地云端。思乡的泪在客中流尽，望着天际的孤帆。想问一问迷津何处，只见入海的江面夕照漫漫。","shang":"「木落雁南渡，北风江上寒」十字写尽深秋江天，为发端名句。结「迷津欲有问」用孔子使子路问津典，仕隐茫然，与平海漫漫之景相接，遂成浩渺不尽之势。"},"133":{"ti":"刘长卿登吴公台吊古。夕阳旧垒、寒磬空林，南朝旧事已随江水，惟长江独至今，兴亡之慨深沉。","zhu":[{"w":"吴公台","v":"在今扬州，陈将吴明彻所筑弩台。"},{"w":"摇落","v":"草木凋零。宋玉「悲哉秋之为气也，萧瑟兮草木摇落而变衰」。"},{"w":"旧垒","v":"旧时的营垒。"},{"w":"寒磬","v":"清冷的磬声。"},{"w":"南朝","v":"宋齐梁陈，据江南的四个朝代。"}],"yi":"古台草木摇落之后，秋日里起了望乡之心。野寺来人稀少，云峰隔着深水。夕阳照着旧时营垒，寒磬声满空林。惆怅那南朝旧事，唯有长江独自流到今天。","shang":"「夕阳依旧垒，寒磬满空林」十字苍凉入骨，为刘长卿五律之最。结以「长江独至今」——人事有尽而江水无穷，吊古之意与《登幽州台歌》同一浩叹而语更收敛。"},"134":{"ti":"刘长卿送罢归的老将归汉阳别业。独立三边静、轻生一剑知，写其功高身世之悲，日暮江汉，何所归往？","zhu":[{"w":"李中丞","v":"李姓殿中侍御史衔的将军，名不详。"},{"w":"汉阳别业","v":"汉阳的旧宅。别业，本宅之外的产业。"},{"w":"旧业","v":"祖上的产业。"},{"w":"明时","v":"政治清明的时代。"},{"w":"三边","v":"幽、并、凉三州，泛指边疆。"},{"w":"轻生","v":"不惜生命。"},{"w":"一剑知","v":"只有佩剑知道其轻生报国之心。"},{"w":"江汉","v":"汉水。"}],"yi":"流落无归的征南老将，当年统率过十万雄师。罢归之后没有旧业，人到老来还眷恋着明时。独立阵前，三边为之寂静；轻生报国，只有一剑相知。茫茫江汉水上，日暮又往哪里去？","shang":"「独立三边静，轻生一剑知」写老将，字字有金石声；与「罢归无旧业」对照，功高而无所归，悲慨极深。结句「日暮复何之」一问，天涯何处可为家，全诗之意尽收于此。"},"135":{"ti":"刘长卿饯别王十一南游。望君烟水阔、挥手泪沾巾，长江一帆远、落日五湖春，送别全从「望」字写出。","zhu":[{"w":"王十一","v":"王姓排行十一者，名字不详。"},{"w":"飞鸟","v":"喻远行之人。"},{"w":"青山空向人","v":"青山徒然对着留者。"},{"w":"五湖","v":"太湖一带，指友人游处。"},{"w":"汀洲","v":"水中小洲。"},{"w":"白苹","v":"水草，花白色。古诗采苹江南以赠所思。"}],"yi":"望着你走向烟水迷茫的远处，挥手之间泪已沾巾。飞鸟不知没入何处，青山空自对着我这留者。长江上一帆远去，落日里五湖春深。有谁看见汀洲之上，相思的人对着白苹发愁？","shang":"全篇无一语写饮宴话别，只写「望」中景象：帆远、日斜、鸟没、山空——人去愈远而望者之情愈深。「长江一帆远，落日五湖春」以阔大之景写怅惘之情，别情尽在不言中。"},"136":{"ti":"刘长卿寻隐者不遇，却得溪花禅意。白云静渚、春草闲门，结以「相对亦忘言」，访人不遇反成妙悟。","zhu":[{"w":"常山道人","v":"姓常的山中道士，一说「常山道」之隐者。"},{"w":"莓苔","v":"青苔。"},{"w":"渚","v":"水中小洲。"},{"w":"禅意","v":"禅理妙悟。"},{"w":"忘言","v":"心领神会而不需言语。《庄子》「得意而忘言」。"}],"yi":"一路经过的地方，莓苔上看得见鞋痕。白云依着安静的洲渚，春草掩闭着闲静的门。过雨之后看松色更青，随着山势走到水源。溪花与禅意相对，彼此相忘于言语之外。","shang":"「白云依静渚，春草闭闲门」写隐者之居，「闭」字有味——门虽闭而境自幽。结句「相对亦忘言」化用陶潜「欲辨已忘言」与庄子「得意忘言」，人与花相对两忘，禅意自足，是寻隐诗的神来之笔。"},"137":{"ti":"刘长卿贬南巴尉后新年感怀。老至居人下、春归在客先，新岁之中，天涯逐臣的辛酸尽出。","zhu":[{"w":"天畔","v":"天边，指岭南贬所。"},{"w":"潸然","v":"流泪的样子。"},{"w":"居人下","v":"居于下属之位。"},{"w":"春归在客先","v":"春天已回到人间，而游子尚滞留未归。"},{"w":"岭猿","v":"岭南的猿猴。"},{"w":"长沙傅","v":"贾谊贬为长沙王太傅。"}],"yi":"新年的乡心格外急切，独自在天边潸然泪下。老来了还居人之下，春天已归去而客还未归。岭上的猿与我共度早晚，江边的柳与我同受风烟。已像那长沙太傅贾谊，从今还要这样过几年？","shang":"「老至居人下，春归在客先」两两相形——人之困顿不如物之自由，全用口语而沉痛至深。结以贾谊自比，自伤再贬尚无归期，与《新年作》题相发，刘长卿「五言长城」的哀婉本色。"},"138":{"ti":"钱起送日本僧人归国。浮天沧海远、去世法舟轻，以禅意写万里归航；惟怜一灯影，万里眼中明。","zhu":[{"w":"上国","v":"中国（唐）的尊称。"},{"w":"随缘住","v":"随因缘而居留。"},{"w":"法舟","v":"佛法庇护之舟，指僧人所乘。"},{"w":"水月","v":"水中之月，佛家喻万法皆空。"},{"w":"禅寂","v":"禅定寂静。"},{"w":"梵声","v":"诵经之声。"},{"w":"一灯","v":"禅家喻佛法如灯，能破暗。"}],"yi":"您随缘住在中华，来时的路如梦中一行。浮天沧海那样遥远，离世归去，法舟何等轻扬。水月通于禅寂，鱼龙也在谛听梵声。只是怜爱那一盏禅灯，万里航程在眼中长明。","shang":"「水月通禅寂，鱼龙听梵声」写海夜行舟，法音与天地相通，禅意与诗意合一。结「惟怜一灯影，万里眼中明」——一灯之微而照万里之遥，佛法之光明尽在其中。送僧诗至此，不着一字愁苦，纯是庄严。"},"139":{"ti":"钱起在谷口书斋寄约杨补阙来游。竹怜新雨后、山爱夕阳时，闲鹭秋花俱可爱，家童已扫萝径待故人。","zhu":[{"w":"谷口","v":"在今陕西泾阳，汉代郑朴（子真）隐居处。"},{"w":"补阙","v":"谏官名，掌供奉讽谏。"},{"w":"泉壑","v":"泉水山谷。"},{"w":"茅茨","v":"茅屋。"},{"w":"薜帷","v":"薜荔绕成的帘帷。《楚辞》「网薜荔兮为帷」。"},{"w":"萝径","v":"藤萝掩映的小路。"},{"w":"期","v":"约定。"}],"yi":"泉水山川环绕着茅屋，云霞从薜荔帷上生起。竹子可爱是在新雨之后，山色最喜是夕阳西时。闲鹭栖息一向来得早，秋花凋落总更迟些。家童已把萝径扫净，昨天与你约了今日之期。","shang":"「竹怜新雨后，山爱夕阳时」一「怜」一「爱」，把山水写得可亲可恋，是邀友书斋的最美说辞。末二句家童扫径、故人有期，殷勤之情见于细微，是邀约诗的雅致典型。"},"140":{"ti":"韦应物淮上重逢梁川故人。浮云一别后，流水十年间——十字写尽聚散，重逢之喜与迟暮之感交并。","zhu":[{"w":"淮上","v":"淮水边，今江苏淮阴一带。"},{"w":"梁川","v":"一作梁州（今陕西汉中）。"},{"w":"江汉","v":"长江汉水之间。"},{"w":"萧疏","v":"稀疏斑白。"},{"w":"何因","v":"因为什么（不能一同北归）。"}],"yi":"当年我们同客江汉，相逢总要醉后方归。自那一别如浮云飘散，转眼流水已过十年。今日重逢欢笑依旧，鬓边却已萧疏斑白。何因此时不一同北归？就在淮上对着秋山。","shang":"「浮云一别后，流水十年间」以浮云流水写十年聚散，语极平淡而感慨极深，为唐人重逢诗第一名联。「欢笑情如旧，萧疏鬓已斑」喜中带老，结以对秋山，不尽之意在山水之间。"},"141":{"ti":"韦应物赋得暮雨送李胄。楚江微雨、建业暮钟，帆重鸟迟、浦树含滋，全篇以雨湿之景写沾襟之别。","zhu":[{"w":"赋得","v":"凡依指定题目作诗称赋得。"},{"w":"李胄","v":"一作李曹，事迹不详。"},{"w":"楚江","v":"长江流经楚地的一段。"},{"w":"建业","v":"今南京。"},{"w":"漠漠","v":"水气密布的样子。"},{"w":"海门","v":"长江入海处。"},{"w":"含滋","v":"含着水气。"},{"w":"散丝","v":"细密的雨丝。"}],"yi":"楚江笼在微雨里，建业正是暮钟时分。水气漠漠，帆影来时沉重；暮色冥冥，鸟儿飞去也迟。海门幽深望不见，浦树远远含着水气。相送之情无限，泪沾衣襟如同这细密的雨丝。","shang":"全篇字字是雨：帆「重」、鸟「迟」、树「含滋」，雨意浸透一切；末句「沾襟比散丝」，人泪与雨丝合一，题意（暮雨送别）与诗情完全相扣，是「赋得体」最工稳的名作。"},"142":{"ti":"韩翃酬答程延秋夜诗。星河秋一雁、砧杵夜千家，秋夜声色绝美；吟君秀句不觉鸦鸣，知音之感深挚。","zhu":[{"w":"程延","v":"一作程近，诗人，事迹不详。"},{"w":"即事","v":"就眼前之景而作。"},{"w":"长簟","v":"细长的竹子。"},{"w":"澹","v":"荡漾。"},{"w":"月华","v":"月光。"},{"w":"砧杵","v":"捣衣石与棒槌，秋夜捣衣之声。"},{"w":"心期","v":"心中所期约的相知。"},{"w":"赊","v":"远，迟。"},{"w":"秀句","v":"指程延赠诗中的佳句。"},{"w":"鸣鸦","v":"鸦鸣，天明之候。"}],"yi":"长竹早早地迎着秋风，空城上月光荡漾。星河之间秋雁一声，砧杵声里夜捣千家。看节候已是深晚，心期相知却还疏远。一向吟诵你的秀句，不觉已到晨鸦啼鸣。","shang":"「星河秋一雁，砧杵夜千家」一雁一声对千家砧杵，秋夜之寥廓与人间之繁音并出，为韩翃五律名句。结以「不觉已鸣鸦」，吟人之句而至忘时，知音之感自在其中。"},"143":{"ti":"刘昚虚阙题（原题已佚）。道由白云、春随青溪，落花流水、深柳书堂，写隐居读书之境幽绝。","zhu":[{"w":"阙题","v":"原题缺失，后人以「阙题」名之。"},{"w":"春与青溪长","v":"春色随着青溪一样绵长。"},{"w":"落花至","v":"时有落花随水而至。"},{"w":"远随流水香","v":"花香远远随着流水传来。"},{"w":"闲门","v":"清闲的门庭。"},{"w":"幽映","v":"幽深的树影映照。"},{"w":"清辉","v":"清幽的光。"}],"yi":"道路在白云深处到了尽头，春色与青溪一样绵长。时时有落花漂到眼前，远远随流水送来花香。闲静的门向着山路，深柳之间是读书的堂。日光透过幽幽的树影，清辉照着我的衣裳。","shang":"「时有落花至，远随流水香」十字有花有水有香，动之极而静之极，为写溪居第一名句。「深柳读书堂」五字，后世书斋题额多取之，可见其境之胜。全篇无一生字，幽意自然流出。"},"144":{"ti":"戴叔伦与江南故人客舍偶聚。翻疑梦里逢，写乱后重逢如梦；相留畏晓钟，畏的竟是别期将至。","zhu":[{"w":"偶集","v":"偶然相聚。"},{"w":"城阙","v":"都城，此指长安。"},{"w":"千重","v":"层层深锁。"},{"w":"翻疑","v":"反而怀疑。"},{"w":"风枝惊暗鹊","v":"用曹操「月明星稀，乌鹊南飞」及「绕树三匝，何枝可依」意，写客居不安。"},{"w":"寒虫","v":"秋虫。"},{"w":"羁旅","v":"客居他乡。"},{"w":"晓钟","v":"报晓的钟声，指别期。"}],"yi":"秋天到了，月亮又圆，都城的夜里千重深锁。还能作江南故人之会，反而疑心是梦里相逢。风吹树枝惊起暗处的鹊，露湿秋草盖着寒虫。客居本就该长醉，相留时只怕听那报晓的钟。","shang":"「还作江南会，翻疑梦里逢」与司空曙「乍见翻疑梦」同一机杼，乱后重逢之神情如画。结句「相留畏晓钟」最痴——留客而畏钟，钟催别期也。以畏字写惜，情味最深。"},"145":{"ti":"卢纶送李端于乱后。故关衰草、寒云暮雪，一路皆悲；「少孤为客早，多难识君迟」写尽人生际遇之痛。","zhu":[{"w":"故关","v":"故乡的关塞。"},{"w":"衰草","v":"枯草。"},{"w":"少孤","v":"幼年丧父。"},{"w":"为客早","v":"很早就流离为客。"},{"w":"多难","v":"时世多难。"},{"w":"识君迟","v":"与你相识太晚。"},{"w":"掩泪","v":"掩面拭泪。"},{"w":"风尘","v":"乱世奔波。"}],"yi":"故乡的关塞枯草遍野，离别正在这时，怎么不悲！路伸向寒云之外，人归在暮雪之时。少年失父、为客又早，多难的岁月才识君又迟。掩泪空自相向，风尘之中何处再会？","shang":"「少孤为客早，多难识君迟」十字把半生身世说尽，故被推为大历十才子第一联。通篇衰草、寒云、暮雪，一片悲凉底色。结句「风尘何处期」，乱世之中连后会之期也不敢许。"},"146":{"ti":"李益乱后见表弟又即言别。问姓惊初见、称名忆旧容，把久别乍逢的一瞬写得神情毕肖。","zhu":[{"w":"外弟","v":"表弟。"},{"w":"离乱","v":"遭安史之乱流离。"},{"w":"问姓惊初见","v":"初见问姓还惊为路人。"},{"w":"称名忆旧容","v":"报名之后才忆起旧日容貌。"},{"w":"沧海事","v":"沧海桑田，喻十年间人事巨变。"},{"w":"暮天钟","v":"黄昏寺钟，谓语罢已晚。"},{"w":"巴陵","v":"今湖南岳阳，李益将赴之地。"}],"yi":"十年离乱之后，你长大了我才与你相逢。问姓时惊于初见，称名后忆起旧容。说起别来沧海桑田的变化，话语说罢已是暮天钟响。明日你走上巴陵道，秋山又隔几重？","shang":"「问姓惊初见，称名忆旧容」由陌生到相识的心理过程，十个字全写尽了，是重逢诗的绝唱。末二句「明日巴陵道，秋山又几重」——重逢方半日，又问别后之程，悲喜翻覆，最见乱世人情。"},"147":{"ti":"司空曙与韩绅宿别。乍见翻疑梦、相悲各问年，乱后重逢之惊疑与辛酸，全在细节之中。","zhu":[{"w":"云阳馆","v":"云阳（今陕西泾阳）的驿馆。"},{"w":"韩绅","v":"一作韩升卿，韩愈四叔。"},{"w":"宿别","v":"同宿后又分别。"},{"w":"乍见","v":"突然相见。"},{"w":"翻疑梦","v":"反而疑心是梦。"},{"w":"问年","v":"互问年岁。"},{"w":"离杯","v":"离别之酒。"}],"yi":"故人江海一别，几度隔着山川。突然相见反而疑是梦，相悲之余各自问年。孤灯寒光照着夜雨，深竹暗浮着雾烟。更有明朝离恨，惜别之酒共传相劝。","shang":"「乍见翻疑梦，相悲各问年」十字，与卢纶「多难识君迟」并称大历重逢诗双璧。颈联「孤灯寒照雨，深竹暗浮烟」以景写夜话之凄迷。结句「离杯惜共传」——明知明朝有恨，此杯更要珍惜。"},"148":{"ti":"司空曙喜表弟卢纶夜来留宿。雨中黄叶树、灯下白头人，一联双影，为写贫老相逢第一名句。","zhu":[{"w":"见宿","v":"光临留宿。"},{"w":"旧业","v":"家产。"},{"w":"沉","v":"沉沦。"},{"w":"蔡家亲","v":"晋蔡邕与羊祜为表亲，羊祜以名表报蔡，此借指表亲。"}],"yi":"静夜四周没有邻居，荒居里旧业清贫。雨中的黄叶树，灯下的白头人。以我这独沉之久，愧你相访之频。平生自有缘分相系，何况还是蔡家之亲！","shang":"「雨中黄叶树，灯下白头人」树与人、雨与灯，两两相叠，不言衰而衰景自现，前人谓胜过「树犹如此」之叹。结以「蔡家亲」，困顿中的一点温热，故题为「喜」。"},"149":{"ti":"司空曙送人于乱平之后北归。同去独还，他乡白发、旧国青山，送别之中自寓身世。","zhu":[{"w":"贼平","v":"安史之乱平定。"},{"w":"时清","v":"时局清平。"},{"w":"旧国","v":"故乡。"},{"w":"残垒","v":"战争残余的营垒。"},{"w":"故关","v":"旧时的关塞。"},{"w":"寒禽","v":"寒天的鸟。"}],"yi":"乱世同你一起南来，时清你却独自北还。他乡生出了白发，故乡只怕只见青山。晓月下经过残破营垒，繁星下宿在旧日关塞。寒禽与衰草，处处伴着你的愁颜。","shang":"「他乡生白发，旧国见青山」十字沉痛——去时黑发、归时白头，故乡恐怕只剩青山如故。颈联晓月繁星写归程之艰。结以寒禽衰草伴愁颜，北归不是喜而是另一段漂泊，乱后余痛至深。"},"150":{"ti":"刘禹锡过成都先主庙而作。天地英雄气、千秋尚凛然，起句千钧；「得相能开国，生儿不象贤」，一句褒、一句贬，咏史之笔力极健。","zhu":[{"w":"蜀先主","v":"刘备。"},{"w":"英雄气","v":"曹操语「今天下英雄，唯使君与操耳」。"},{"w":"三足鼎","v":"魏蜀吴三分天下。"},{"w":"五铢钱","v":"汉钱币，刘备铸直百五铢，喻复汉之业。"},{"w":"得相","v":"得诸葛亮为相。"},{"w":"生儿不象贤","v":"后主刘禅不能效法先贤。"},{"w":"蜀故妓","v":"蜀宫旧日歌舞伎。"},{"w":"来舞魏宫前","v":"蜀亡后刘禅降魏，旧伎在魏宫歌舞，《汉晋春秋》记「此间乐，不思蜀」事。"}],"yi":"天地间长存英雄之气，千秋之下还那样凛然！势分三足之鼎，业复五铢之钱。得贤相便能开国，生儿子却不像先贤。最凄凉那蜀宫的旧妓，如今来在魏宫前歌舞。","shang":"五十字之内，从开国写到亡国，从英雄写到儿不象贤——「凄凉蜀故妓，来舞魏宫前」以一幕场景收束全局，不置一字讥评而兴亡之痛彻骨。刘禹锡咏史五律，此为压卷。"},"151":{"ti":"张籍怀念陷没蕃中的故人。欲祭疑君在，生死未卜之间，祭也不是、不祭也不是，此五字写尽悬望之痛。","zhu":[{"w":"没","v":"陷没，覆没。"},{"w":"月支","v":"古西域国名，此借指唐与吐蕃交战之地。"},{"w":"没全师","v":"全军覆没。"},{"w":"蕃汉","v":"吐蕃与唐。"},{"w":"废帐","v":"遗弃的军帐。"},{"w":"归马识残旗","v":"逃归的战马还认得残破的军旗。"}],"yi":"前年征伐月支，城下全军覆没。蕃汉之间断了消息，是死是生长久别离。没有人收拾废帐，逃归的马还认得残旗。想祭奠你又疑你还在，天涯痛哭，就在此时。","shang":"「欲祭疑君在」五字，写尽生死茫茫之际的痴望——盼其生，故不忍祭；恐其死，故思一恸。结「天涯哭此时」，终于放声，压抑愈久则悲愈深。中唐边塞之痛，此篇最切。"},"152":{"ti":"白居易十六岁应考习作。离离原上草一岁一枯荣，野火春风一联，写物之不屈，兼寓送别之不尽。","zhu":[{"w":"赋得","v":"按指定题目作诗。"},{"w":"离离","v":"茂盛纷披的样子。"},{"w":"枯荣","v":"枯萎与繁茂。"},{"w":"远芳","v":"远处的芳草。"},{"w":"侵","v":"蔓延。"},{"w":"晴翠","v":"阳光下草色明翠。"},{"w":"王孙","v":"游子。《楚辞》「王孙游兮不归，春草生兮萋萋」。"},{"w":"萋萋","v":"草茂盛的样子。"}],"yi":"原上茂密的青草，一年一度枯了又荣。野火烧不尽它，春风吹拂又重生。远处的芳草侵上古道，晴日的翠色连接荒城。又要送走远行的人，萋萋芳草满是别情。","shang":"「野火烧不尽，春风吹又生」十字写尽生生不息之理，顾况见之叹「道得个语，居即易矣」，遂有「长安米贵、居大不易」的佳话。以草之荣枯写别情之不断，结「萋萋满别情」，咏物与送别融为一体。"},"153":{"ti":"杜牧旅宿怀乡。远梦归侵晓、家书到隔年，写乡路之遥至极；结以沧江烟月、钓船门系，景愈美而愁愈深。","zhu":[{"w":"凝情","v":"情思专注。"},{"w":"悄然","v":"忧愁的样子。"},{"w":"断雁","v":"失群之雁。"},{"w":"警","v":"惊醒。"},{"w":"远梦归侵晓","v":"梦魂归乡，天将亮才到达，极言其远。"},{"w":"隔年","v":"一年之后才到。"},{"w":"沧江","v":"江水清苍。"}],"yi":"旅店里没有好伴侣，凝着情思独自悄然。寒灯之下想旧日之事，失群的雁声惊断愁眠。梦魂归乡要到天将亮，家书寄到要隔上一年。沧江的烟月这样好，门外系着一条钓鱼船。","shang":"「远梦归侵晓，家书到隔年」归梦、家书皆以「远」字写极，梦短书迟，客愁至深。结句忽然放下愁笔，写沧江烟月之美、钓船之闲——可望而不可即之乐，正是旅人最痛处。"},"154":{"ti":"许浑赴长安途中题潼关驿楼。残云太华、疏雨中条，写关河之胜；帝乡明日到，犹自梦渔樵，宦情与隐意交战。","zhu":[{"w":"赴阙","v":"前往朝廷。"},{"w":"潼关","v":"在今陕西潼关，扼关中东门。"},{"w":"驿楼","v":"驿站的楼。"},{"w":"太华","v":"华山。"},{"w":"中条","v":"中条山，在今山西。"},{"w":"迥","v":"远。"},{"w":"帝乡","v":"京城。"},{"w":"渔樵","v":"打鱼砍柴，指隐居生活。"}],"yi":"红叶在晚风中萧萧作响，长亭里喝下一瓢酒。残云归向太华山，疏雨掠过中条山。树色随着山势愈远，河声奔向大海愈遥。京城明天就要到了，我还在梦里打渔砍樵。","shang":"「残云归太华，疏雨过中条」写潼关形胜，山川尽入两句之中。结句「犹自梦渔樵」妙在将进未进之际——帝乡在望而心在江湖，宦隐两难的真心境，尽在一「犹」字。"},"155":{"ti":"许浑咏早秋。残萤玉露、早雁银河，一叶落而知岁暮，自觉老于烟波，秋气与之俱来。","zhu":[{"w":"遥夜","v":"长夜。"},{"w":"泛清瑟","v":"弹奏清瑟。"},{"w":"翠萝","v":"青绿的藤萝。"},{"w":"玉露","v":"白露的美称。"},{"w":"拂","v":"掠过。"},{"w":"淮南一叶下","v":"《淮南子》「见一叶落而知岁之将暮」。"},{"w":"烟波","v":"水上的雾霭波光，指江湖。"}],"yi":"长夜里弹一曲清瑟，西风从翠萝间生起。残萤栖在玉露上，早雁掠过银河。高树到晓还显得浓密，远山在晴天更加清晰。淮南落下一片叶子，自觉已在烟波中老去。","shang":"「残萤栖玉露，早雁拂银河」残萤对早雁、玉露对银河，早秋之象无一字不精。结用「一叶知秋」典而翻出「老」字——叶落是秋，人老也是秋，双关至妙。"},"156":{"ti":"李商隐咏蝉自况。本以高难饱、徒劳恨费声，以蝉之高洁饮露写寒士之清贫，五更疏欲断、一树碧无情，物我两绝。","zhu":[{"w":"高难饱","v":"栖于高处、只饮清露，故难果腹。"},{"w":"恨费声","v":"鸣声再多也是徒劳。"},{"w":"五更疏欲断","v":"天快亮时蝉声稀疏将绝。"},{"w":"一树碧无情","v":"满树依旧碧绿，全不管蝉声之哀。"},{"w":"薄宦","v":"卑微的官职。"},{"w":"梗犹泛","v":"如桃木偶人随水漂流。《战国策》土偶与桃梗对话。"},{"w":"芜已平","v":"故园荒草已齐平。"},{"w":"举家清","v":"全家清贫。"}],"yi":"本来就因栖高而难饱，白白地费尽了这怨恨的鸣声。五更时声音稀疏将断，一树碧绿全然无情。卑微的官职如桃梗漂泊，故园的荒草已经齐平。烦劳你来警戒我，我也是举家清贫。","shang":"「一树碧无情」五字，把世态的冷漠写成一片无情之碧，故纪昀叹为「字字奇绝」。蝉之高难饱与人之举家清相照，咏物至此，物我不分。义山咏物三绝（蝉、柳、泪）之首。"},"157":{"ti":"李商隐自伤羁泊。凄凉宝剑篇，以郭震（元振）《宝剑篇》见赏于武后之遇，反照自己怀才不遇；心断新丰酒，用马周逆旅主人不之顾事。","zhu":[{"w":"宝剑篇","v":"唐郭震（元振）所作，武后览之称赏，遂得重用。"},{"w":"羁泊","v":"羁旅漂泊。"},{"w":"穷年","v":"终年，到老。"},{"w":"青楼","v":"富家高楼。"},{"w":"新知","v":"新交的朋友。"},{"w":"薄俗","v":"浇薄的风俗。"},{"w":"旧好","v":"旧日知交。"},{"w":"新丰酒","v":"唐马周落魄新丰，逆旅主人不之顾，周沽酒独酌。"},{"w":"斗几千","v":"一斗酒几千钱。"}],"yi":"《宝剑篇》那样的才华，落得凄凉，羁旅漂泊欲至穷年。黄叶仍在风雨之中，青楼里自演管弦。新交的朋友遭着薄俗，旧日的知音又隔了良缘。心已断绝，只有新丰之酒——销这千愁，一斗几千。","shang":"「黄叶仍风雨，青楼自管弦」一「仍」一「自」，世态之炎凉写至骨中。连用郭震、马周二典，皆是才士得遇的先例，正反照自己之不遇。义山飘零身世，此篇最见愤郁。"},"158":{"ti":"李商隐咏落花。客去花飞、斜晖曲陌，肠断未忍扫，眼穿仍欲归——花与人同此飘零，所得只有沾衣。","zhu":[{"w":"竟","v":"终于，终于离去。"},{"w":"参差","v":"花影高低错落。"},{"w":"曲陌","v":"曲折的小路。"},{"w":"迢递","v":"遥远。"},{"w":"眼穿","v":"望眼欲穿。"},{"w":"芳心","v":"花心，亦自喻怀抱。"},{"w":"沾衣","v":"落花沾衣（一解泪水沾衣）。"}],"yi":"高阁上的客人终于离去，小园里落花乱飞。高低错落连着曲折小路，远远飘送着西斜的余晖。愁肠寸断不忍扫去，望眼欲穿它仍想归来。芳心随着春天耗尽，所得不过是沾湿了衣襟。","shang":"「芳心向春尽，所得是沾衣」——以花之一生总括人之怀抱：尽付春光、所得几何？问得沉痛。中二联写花飞之状、斜晖之送，有情之物陪着无情之天。义山身世之感，多托于落花。"},"159":{"ti":"李商隐秋日怀友。永怀当此节、倚立自移时，写怀人之痴；疑误有新知，猜疑之中见交情之深。","zhu":[{"w":"波平槛","v":"水波与栏杆齐平，言秋水涨满。"},{"w":"蝉休","v":"蝉声停了，秋深之候。"},{"w":"移时","v":"历时良久。"},{"w":"北斗兼春远","v":"友人所在之北斗城（长安）与经历之春，都已遥远。"},{"w":"南陵","v":"今安徽南陵，友人寓居之地。"},{"w":"寓使","v":"捎信的使者。"},{"w":"占梦数","v":"多次占卜梦境。"},{"w":"新知","v":"新的知交，疑友人另结新欢而疏己。"}],"yi":"客人去了，水波与栏杆齐平，蝉声停了，露水挂满枝头。永远怀念正是这个时节，倚栏站立自是不知多久。北斗般的京城与逝去的春天一样遥远，南陵的音信迟迟不至。在天涯屡屡占问梦境，莫不是疑我有新交、误了音书？","shang":"全篇不作一句艳语，而「疑误有新知」的患得患失，把友谊写到与爱情一样细腻。倚立「移时」之久、占梦「数」次之多，皆以痴态见深情。义山诗之「凉」，是温情之凉。"},"160":{"ti":"李商隐日暮访孤僧而作。落叶寒云、独磬藤枝，结以「世界微尘里，吾宁爱与憎」，万象俱寂，一悟至道。","zhu":[{"w":"崦","v":"崦嵫山，日入之处。《离骚》「望崦嵫而勿迫」。"},{"w":"孤僧","v":"独居的僧人。"},{"w":"初夜","v":"黄昏时分。"},{"w":"磬","v":"僧寺中的法器。"},{"w":"一枝藤","v":"藤制的手杖。"},{"w":"微尘","v":"佛家谓世界微尘，极言其小。"},{"w":"宁","v":"岂、何须。"},{"w":"爱与憎","v":"爱憎之情。"}],"yi":"残阳西落入崦嵫，茅屋里去访那孤僧。落叶之下人在何处？寒云遮路上有几层？独自敲响初夜的磬，闲闲倚着一枝藤杖。在这世界微尘之中，我何须再分什么爱与憎？","shang":"「独敲初夜磬，闲倚一枝藤」十字写尽孤僧风神。「世界微尘里，吾宁爱与憎」以《法华经》微尘世界义作结——既知世界不过微尘，爱憎更何足道。义山诗多沉郁，此篇独见澄澈。"},"161":{"ti":"温庭筠送人东游。高风汉阳渡、初日郢门山，以大笔写送别之远；何当重相见，樽酒慰离颜，旷达而不失深挚。","zhu":[{"w":"荒戍","v":"荒废的营垒。"},{"w":"浩然","v":"志向高远貌。《孟子》「予然后浩然有归志」。"},{"w":"故关","v":"旧时的关塞。"},{"w":"汉阳渡","v":"今武汉汉阳的长江渡口。"},{"w":"郢门山","v":"荆门山，古属郢地。"},{"w":"孤棹","v":"孤舟。"},{"w":"何当","v":"何时能够。"}],"yi":"荒废的戍楼落下黄叶，你浩然辞别旧时的关塞。高风中通过汉阳渡，初日下直指郢门山。江上还剩几个人在？天涯路上孤棹归还。何时能重新相见？一杯樽酒慰这离别的容颜。","shang":"「高风汉阳渡，初日郢门山」写行舟之远，气象宏阔，无一字悲戚而有豪气。「江上几人在？」一问苍凉，含兵乱后存殁之感。结以樽酒之约，离情托于后会，温词中此为上乘。"},"162":{"ti":"马戴落第寄居灞上而作。落叶他乡树、寒灯独夜人，十字写尽客愁，为唐人五律名联。","zhu":[{"w":"灞上","v":"灞水高原，在长安东，作者寓居处。"},{"w":"雁行频","v":"雁阵频频南飞，秋深之候。"},{"w":"独夜","v":"孤夜。"},{"w":"白露滴","v":"夜静得听得见白露滴落。"},{"w":"孤壁","v":"孤零零的墙壁，指居处孤寂。"},{"w":"野僧邻","v":"与野僧为邻。"},{"w":"郊扉","v":"郊外的门户，指寓所。"},{"w":"致此身","v":"出仕报国。《论语》「事君能致其身」。"}],"yi":"灞原上风雨刚停，傍晚看雁阵频频南飞。落叶是他乡的树，寒灯下是独夜的人。空园里静得听见白露滴落，孤壁之外与野僧为邻。寄居郊外已经很久，哪一年才能报效此身？","shang":"「落叶他乡树，寒灯独夜人」他乡、独夜，一景一人，十字之内客愁至极，故传诵千古。「空园白露滴」以声写静，静极矣。结句「何年致此身」，落第之愤化为长叹，全篇因此有着落。"},"163":{"ti":"马戴泛舟楚江怀古。猿啼洞庭树、人在木兰舟，广泽明月、苍山乱流，写景空阔；云中君不见，怀屈子之思遂成悲秋。","zhu":[{"w":"楚江","v":"此指洞庭湖水系。"},{"w":"微阳","v":"斜阳。"},{"w":"楚丘","v":"楚地山丘。"},{"w":"木兰舟","v":"木兰树所造之船，言其精美。"},{"w":"广泽","v":"广阔的湖泽。"},{"w":"云中君","v":"《楚辞·九歌》篇名，祀云神。"},{"w":"竟夕","v":"整夜。"}],"yi":"露气与寒光凝聚，斜阳落向楚地山丘。猿在洞庭树上啼，人在木兰舟中游。广泽上升起明月，苍山间夹着乱流。云中君却望不见，整夜自在此悲秋。","shang":"「广泽生明月，苍山夹乱流」写洞庭月夜，浩阔中见苍莽，为晚唐五律名句。结以「云中君不见」——求古之灵而灵不可见，遂与屈子同悲。怀古与悲秋相合，故沈德潜称其「幽奇」。"},"164":{"ti":"张乔题咏边地清秋。调角断清秋、征人倚戍楼，写罢战之边地难得的安宁，末愿蕃情如水长向南流。","zhu":[{"w":"调角","v":"吹奏号角。"},{"w":"断","v":"占尽、响遍。"},{"w":"青冢","v":"王昭君墓，在今呼和浩特。"},{"w":"梁州","v":"今陕西汉中一带，唐边地。"},{"w":"穷边","v":"极远的边地。"},{"w":"蕃情","v":"蕃人（吐蕃）之情。"},{"w":"向南流","v":"边地之水南流，喻蕃人向往唐之教化。"}],"yi":"号角声占尽清秋，征人倚着戍楼。春风对着昭君青冢，白日落向梁州。大漠上没有兵阻，穷远的边地也有客游。蕃人的情意就像这水，但愿长年向南流。","shang":"「春风对青冢，白日落梁州」以青冢之春对梁州之日，边地顿时开阔明丽——全因「大漠无兵阻」。结句以水喻情，愿化干戈为向往，是唐人边塞诗中最和平的一首，立意别开生面。"},"165":{"ti":"崔涂除夕客居巴蜀怀乡。乱山残雪夜，孤独异乡春——十字把除夕之孤写到极处；明日岁华新，新岁又是漂泊。","zhu":[{"w":"迢递","v":"遥远。"},{"w":"三巴","v":"巴郡、巴东、巴西，泛指今川东。"},{"w":"羁危","v":"羁旅艰危。"},{"w":"孤独异乡春","v":"一作「独凄异乡人」。"},{"w":"转於","v":"反而与。於，同「与」。"},{"w":"岁华新","v":"新年。"}],"yi":"三巴的路那样遥远，万里之外羁旅艰危之身。乱山里残雪之夜，孤零零过着异乡之春。渐渐与骨肉疏远，反而同僮仆亲近。哪堪正在漂泊之中，明日又是新年。","shang":"「乱山残雪夜，孤独异乡春」十个字有山、雪、夜、客、节令五重愁绪，故为除夜诗名句。「转於僮仆亲」五字最痛——亲骨肉反不如僮仆，漂泊之状写得入骨。结句明日岁华新，新岁新愁而已。"},"166":{"ti":"崔涂咏孤雁自况。暮雨相呼失、寒塘欲下迟，写孤雁之彷徨无依；未必逢矰缴，孤飞自可疑——惊惧之情写出世乱人心。","zhu":[{"w":"归塞尽","v":"北归塞外的雁都飞尽了。"},{"w":"片影","v":"孤雁的独影。"},{"w":"何之","v":"到哪儿去。"},{"w":"相呼失","v":"呼唤而失其群。"},{"w":"欲下迟","v":"想落下而迟疑。"},{"w":"渚云","v":"洲渚上的云。"},{"w":"矰缴","v":"系丝绳的射鸟短箭。"},{"w":"可疑","v":"犹疑不安。"}],"yi":"几行北归塞外的大雁都飞尽了，一片孤影独自投向何处？暮雨里呼唤而失群，寒塘边想落又迟疑。低低穿过渚上的暗云，冷冷随着关山的月色。未必就遇上矰缴暗箭，可这孤飞总叫人自疑不安。","shang":"「暮雨相呼失，寒塘欲下迟」写雁如写人，彷徨顾盼之情全出。结联翻进一层——不必真有箭，孤飞者自生疑惧，乱离人共此心境，故纪昀评为「如此咏物，便是咏怀」。"},"167":{"ti":"杜荀鹤拟宫怨。承恩不在貌，教妾若为容——道破宫怨之实；年年越溪女，相忆采芙蓉，结忆旧伴，哀婉至极。","zhu":[{"w":"婵娟","v":"姿容美好。"},{"w":"误","v":"误了终身。"},{"w":"慵","v":"懒。"},{"w":"若为容","v":"如何修饰。若为，怎样。"},{"w":"碎","v":"细碎繁密。"},{"w":"越溪女","v":"指西施浣纱时的女伴（一说泛指越地女伴）。"},{"w":"采芙蓉","v":"采莲。"}],"yi":"早就被这美貌耽误，想对镜梳妆也提不起劲。承恩的原来不在容貌，教我拿什么去修饰容形？风暖了鸟声细碎，日高了花影重重。年年想起越溪的旧伴，想那时一同采芙蓉。","shang":"「承恩不在貌」一句，把一切以色事人的幻梦说破，故前有「欲妆临镜慵」之懒，后有「相忆采芙蓉」之思——宫怨至此已成人之大惑。中二联风暖日高、鸟碎花重，景愈明媚而情愈幽怨。"},"168":{"ti":"韦庄夜宿章台怀远。清瑟怨遥夜、孤灯闻楚角，一路声色皆哀；芳草已暮、故人未来，乡书难寄、秋雁南回。","zhu":[{"w":"章台","v":"章华台，楚灵王所筑，在今湖北监利。"},{"w":"清瑟","v":"凄清的瑟声。"},{"w":"楚角","v":"楚地（湖北）的号角声。"},{"w":"芳草已云暮","v":"芳草已到迟暮，喻岁将晚、人未归。"},{"w":"殊","v":"竟、还。"},{"w":"乡书","v":"家信。"}],"yi":"凄清的瑟声怨着长夜，绕弦的风雨也在悲鸣。孤灯里听得楚地角声，残月落下章台。芳草已经迟暮，故人终究未来。家书已是无法寄出，秋雁又向南飞回。","shang":"「孤灯闻楚角，残月下章台」以声与光写夜之残，客愁俱在其中。结联层层收束——芳草暮、故人迟、乡书断、秋雁回，一层紧似一层，竟无一字安慰，晚唐乱世的寒意透纸而出。"},"169":{"ti":"皎然访茶圣陆羽（陆鸿渐）不遇。野径桑麻、篱边新菊，扣门无犬吠，欲去问西家——不遇之趣，萧散如画。","zhu":[{"w":"陆鸿渐","v":"陆羽，字鸿渐，著《茶经》，世称茶圣，皎然挚友。"},{"w":"带郭","v":"靠近外城。"},{"w":"野径","v":"田野小路。"},{"w":"著花","v":"开花。"},{"w":"扣门","v":"敲门。扣，同「叩」。"},{"w":"西家","v":"西边邻家。"}],"yi":"新搬的家虽靠近城郭，野径一直通入桑麻。近年在篱边种了菊花，秋来还没有开花。敲门没有犬吠声，想离去时向那西邻打听。回答说进山里去了，回来总是每天日头西斜。","shang":"全篇八句纯用白描，如一则清谈小品：无犬吠、未著花、问西家、日日斜——访人不遇而满纸闲适。「扣门无犬吠」妙在静中有声，隐者之居、隐者之趣，不待言而自见。"},"170":{"ti":"崔颢登武昌黄鹤楼而作。相传李白登楼见之曰「眼前有景道不得，崔颢题诗在上头」，遂为唐人七律第一。","zhu":[{"w":"昔人","v":"传说中的仙人。一说费祎，一说王子安，骑鹤于此。"},{"w":"黄鹤楼","v":"故址在今武昌蛇山黄鹤矶，下临长江。"},{"w":"悠悠","v":"白云飘荡的样子。"},{"w":"历历","v":"分明可数。"},{"w":"汉阳","v":"今武汉汉阳，与黄鹤楼隔江相望。"},{"w":"萋萋","v":"草茂盛的样子。"},{"w":"鹦鹉洲","v":"长江中沙洲，在黄鹤楼西北，东汉祢衡作《鹦鹉赋》处。"},{"w":"乡关","v":"故乡。"}],"yi":"昔日的仙人已乘黄鹤离去，这里只空留一座黄鹤楼。黄鹤一去不再回返，白云千载空自悠悠。晴川里汉阳的树历历分明，芳草萋萋长满鹦鹉洲。日暮时乡关在何处？烟波浩渺的江上使人发愁。","shang":"前四句一气旋转，连用三个「黄鹤」，全不避律而大气包举，严羽谓「唐人七律，当以此为第一」。后四句忽归整饬，楼头日暮、烟波乡愁，由怀古折入怀乡。不拘绳墨而自成绝唱，此其所以不可及。"},"171":{"ti":"崔颢行经华阴，望太华山之奇秀。借问路傍名利客：无如此处学长生——对奔竞尘世的一声棒喝。","zhu":[{"w":"岧峣","v":"高峻的样子。"},{"w":"太华","v":"华山。"},{"w":"咸京","v":"咸阳，指唐都长安。"},{"w":"三峰","v":"华山莲花、玉女、明星三峰。"},{"w":"削不成","v":"非人力所能削成。"},{"w":"武帝祠","v":"汉武帝所建巨灵祠，在华山东。"},{"w":"仙人掌","v":"华山东峰石壁如掌，传为河神巨灵劈山所留。"},{"w":"驿树","v":"驿路两旁的树。"},{"w":"畤","v":"古代祭天地五帝的处所。"},{"w":"长生","v":"道家养生求仙之道。"}],"yi":"高峻的太华山俯瞰着咸京，天外三峰非人力所能削成。武帝祠前云气将散，仙人掌上雨过初晴。河山北枕秦关何等险固，驿路西连汉畤一派平坦。借问路旁追名逐利的客人，何不在此学长生？","shang":"「天外三峰削不成」一句见山之神秀；中二联云散雨晴、枕秦连汉，气象宏阔如画。结句忽转向路人，以「学长生」反照「名利客」，讽意与羡山之意并出，崔颢七律的俊爽本色。"},"172":{"ti":"祖咏登蓟门（居庸关）望边营而作。万里寒光生积雪、三边曙色动危旌，写边塞气象凛然；结以请长缨之志，壮怀激烈。","zhu":[{"w":"蓟门","v":"居庸关一带，唐边防要地。"},{"w":"燕台","v":"黄金台，燕昭王招贤所筑。"},{"w":"汉将营","v":"以汉拟唐，指唐军营。"},{"w":"三边","v":"泛指东北、北、西北三方边地。"},{"w":"危旌","v":"高扬的军旗。"},{"w":"投笔吏","v":"汉班超投笔从戎事。"},{"w":"请长缨","v":"汉终军请以长缨缚南越王事。"}],"yi":"一到燕台，客心为之惊动——箫鼓喧喧，是汉家将营。万里寒光生于积雪，三边曙色映动危旌。沙场烽火直侵胡月，海畔云山环拥蓟城。少小虽非投笔之吏，论功还欲请一条长缨！","shang":"「万里寒光生积雪，三边曙色动危旌」十字写尽北疆的凛冽与军容之盛，「生」「动」二字最见精神。结以班超、终军二典自励，客心之「惊」遂由惊其气象而惊其壮志，一气贯注。"},"173":{"ti":"李颀送魏万赴长安。昨夜微霜初度河，时令与离情并起；鸿雁不堪愁里听，云山况是客中过，句句体贴入微。","zhu":[{"w":"魏万","v":"名颢，天宝间曾求仙访道，后为李白所称。"},{"w":"骊歌","v":"告别之歌。骊，黑马。"},{"w":"度河","v":"渡过黄河。"},{"w":"关城","v":"潼关。"},{"w":"御苑","v":"皇家宫苑，指长安。"},{"w":"砧声","v":"捣衣声。"},{"w":"蹉跎","v":"虚度光阴。"}],"yi":"早晨听你唱起骊歌，昨夜微霜才渡过黄河。鸿雁不堪在愁里听，云山何况又在客中经过。关城树色催着寒气将近，御苑砧声到晚愈多。莫要只见长安是行乐之处，白白让岁月轻易蹉跎。","shang":"「鸿雁不堪愁里听，云山况是客中过」体贴游子之心至深，为送行名句。末二句忽然叮咛——长安行乐之地，莫令岁月蹉跎：以长辈口吻作结，殷切之情全出，正是李颀送别诗的厚道处。"},"174":{"ti":"崔曙九日登望仙台呈刘明府。三晋云山北向、二陵风雨东来，写台之高旷；结欲共醉菊花杯，节候与怀抱相合。","zhu":[{"w":"望仙台","v":"汉文帝为河上公所筑，在陕州。"},{"w":"九日","v":"重阳节。"},{"w":"明府","v":"唐对县令的尊称。"},{"w":"高台","v":"即望仙台。"},{"w":"三晋","v":"韩赵魏三分晋地，指今山西一带。"},{"w":"二陵","v":"崤山南北二陵，在今河南洛宁。"},{"w":"关门令尹","v":"函谷关令尹喜，识老子于关。"},{"w":"河上仙翁","v":"河上公，授文帝《老子》而去。"},{"w":"彭泽宰","v":"陶渊明，曾为彭泽令。"}],"yi":"汉文皇帝筑起高台，今日登临，曙色顿开。三晋的云山都向北去，二陵的风雨自东面来。关门那位识老子的令尹谁能遇到？河上的仙翁一去不回。且去寻访彭泽县宰那样的高人，陶然共醉菊花之杯。","shang":"「三晋云山皆北向，二陵风雨自东来」写高台所望，山河尽入胸中，气象为一篇之骨。中引令尹、仙翁二典，皆求仙而不可得，遂归陶令之菊花——由仙入隐，是九日诗的高格。"},"175":{"ti":"高适送两位贬官友人：一贬峡中、一贬长沙。巫峡啼猿、衡阳归雁，皆切两人贬地；结以「圣代即今多雨露」，宽慰至深。","zhu":[{"w":"少府","v":"县尉的别称。"},{"w":"峡中","v":"巫峡一带，今川东鄂西。"},{"w":"衔杯","v":"饮酒。"},{"w":"谪居","v":"贬谪所居。"},{"w":"巫峡啼猿","v":"《水经注》引渔者歌「巴东三峡巫峡长，猿鸣三声泪沾裳」。"},{"w":"衡阳归雁","v":"衡阳有回雁峰，雁至此而北回，可传书信。"},{"w":"青枫江","v":"长沙湘江一带，古多青枫。"},{"w":"白帝城","v":"在夔州，峡中之地。"},{"w":"雨露","v":"喻朝廷恩泽。"},{"w":"踌躇","v":"忧愁不决。"}],"yi":"可叹你们此番分别心意如何？我驻马举杯，问一声谪居的情形。巫峡的啼猿使人落泪，衡阳的归雁能捎几封书信？青枫江上秋帆正远，白帝城边古木疏疏。圣明之代如今多有雨露，暂时分手，不必踌躇。","shang":"「巫峡啼猿数行泪，衡阳归雁几封书」分切二友贬地，一写泪、一写书，工绝而情深。结以「暂时分手莫踌躇」——相信圣代雨露终会降临，不作一语愁苦，正是高适的雄浑本色。"},"176":{"ti":"岑参和中书舍人贾至《早朝大明宫》之作。鸡鸣曙光、金阙晓钟，写大明宫早朝之盛，结以「阳春一曲和皆难」，恭维贾诗之高。","zhu":[{"w":"贾至","v":"时任中书舍人，作早朝诗，王维、岑参、杜甫皆和。"},{"w":"紫陌","v":"京城的道路。"},{"w":"皇州","v":"帝都。"},{"w":"春色阑","v":"春将尽。"},{"w":"金阙","v":"宫门阙。"},{"w":"仙仗","v":"皇帝的仪仗。"},{"w":"剑佩","v":"佩剑与玉佩，百官服饰。"},{"w":"凤凰池","v":"中书省。"},{"w":"阳春","v":"曲高和寡的《阳春白雪》，赞贾至原作。"}],"yi":"鸡鸣时紫陌上曙光犹寒，莺啼声里皇州春色将阑。金阙晓钟声中开了万户，玉阶仙仗拥着千官。花迎剑佩，晨星初落；柳拂旌旗，朝露未干。独有凤凰池上的客人，一曲《阳春》相和最是困难。","shang":"「花迎剑佩星初落，柳拂旌旗露未干」写早朝，花柳星露、剑佩旌旗错落成章，典丽如画。全篇铺陈宫阙气象，结以「和皆难」点出唱和本意——既颂朝仪，又赞原作，是应制和诗的体面之作。"},"177":{"ti":"王维和贾至早朝诗。九天阊阖开宫殿，万国衣冠拜冕旒——写盛唐气象，此十字遂为千古绝唱。","zhu":[{"w":"绛帻鸡人","v":"头裹红巾报时的宫人，如鸡司晨。"},{"w":"尚衣","v":"掌管帝王衣服的官署。"},{"w":"翠云裘","v":"翠羽织成的裘。"},{"w":"阊阖","v":"天门，此指宫门。"},{"w":"万国衣冠","v":"各国使臣与百官。"},{"w":"冕旒","v":"天子之冠，代指皇帝。"},{"w":"仙掌","v":"宫中障日之扇（或指金铜仙人掌）。"},{"w":"衮龙","v":"龙袍。"},{"w":"五色诏","v":"五色纸写的诏书。"},{"w":"凤池头","v":"中书省。"}],"yi":"裹着绛帻的鸡人送来晓筹，尚衣局才进上翠云裘。九天阊阖豁然打开宫殿，万国衣冠拜伏于冕旒之下。日色才照临，仙掌扇微动；香烟欲傍着，衮龙袍上浮。朝罢须裁五色之诏，佩声归向凤凰池头。","shang":"「九天阊阖开宫殿，万国衣冠拜冕旒」——殿门如天门之开，万国如潮之拜，盛唐的威仪与气象被这十个字定住了，后世再写早朝无能出其右。结以五色诏、凤池头，切贾至中书舍人之职，收得雅驯。"},"178":{"ti":"王维应制和玄宗春望诗。云里帝城双凤阙，雨中春树万人家，一联写尽帝京气象与人间烟火。","zhu":[{"w":"应制","v":"奉皇帝之命作诗。"},{"w":"渭水","v":"关中黄河支流。"},{"w":"秦塞","v":"秦地关塞。"},{"w":"銮舆","v":"皇帝车驾。"},{"w":"上苑","v":"皇家园林。"},{"w":"双凤阙","v":"大明宫含元殿前栖凤翔鸾二阙。"},{"w":"阳气","v":"春天生发之气。"},{"w":"行时令","v":"顺应时令施行政教。"},{"w":"宸游","v":"皇帝出游。"},{"w":"物华","v":"景物。"}],"yi":"渭水自萦绕着秦塞曲流，黄山旧时绕着汉宫倾斜。銮舆远远驶出千门杨柳，阁道回望上苑一片春花。云里帝城耸立双凤之阙，雨中春树掩着万户人家。正是乘着阳气推行时令，并非宸游只玩赏物华。","shang":"「云里帝城双凤阙，雨中春树万人家」上句天家之尊、下句人间之庶，一联之内气象与温情兼得，为应制诗中难得的佳句。结句「不是宸游玩物华」为帝王回护，应制体例使然，而中二联已足千古。"},"179":{"ti":"王维积雨中的辋川庄。漠漠水田飞白鹭，阴阴夏木啭黄鹂——一联水田夏木，为唐诗写景之极；末以野老海鸥自任，物我无猜。","zhu":[{"w":"藜","v":"野菜，嫩叶可食。"},{"w":"黍","v":"黄米。"},{"w":"饷东菑","v":"送到东边田头给耕作者吃。菑，初耕的田地。"},{"w":"漠漠","v":"水气迷蒙。"},{"w":"阴阴","v":"树荫幽深。"},{"w":"朝槿","v":"木槿，朝开暮落。"},{"w":"露葵","v":"带露的葵菜。"},{"w":"争席","v":"争坐席，典出《庄子》杨朱见老子后忘机，人可与争席。"},{"w":"海鸥","v":"《列子》：海上之人无机心则鸥鸟亲近，机心一起鸥鸟不肯下。"}],"yi":"积雨的空林里炊烟迟缓，蒸藜炊黍，送往东边田头。漠漠水田上飞着白鹭，阴阴夏木里黄鹂啼啭。山中习静，看朝开暮落的木槿；松下清斋，折带露的葵菜。野老与人争席的日子早已过去，海鸥为何还来相疑？","shang":"「漠漠水田飞白鹭，阴阴夏木啭黄鹂」两组叠字、四重色彩，画笔不能到，故李肇以为得之李嘉祐句而气象自别。结以争席、鸥鹭二典——我已无机心，谁还疑我？禅意与田家气浑然一体，为辋川七律之冠。"},"180":{"ti":"王维酬答郭给事。洞门高阁、桃李阴阴，写禁中清景；「强欲从君无那老，将因卧病解朝衣」，倦于仕途，溢于言表。","zhu":[{"w":"郭给事","v":"郭承嘏（一说郭元振孙），任门下省给事中。"},{"w":"洞门","v":"重重相通的宫门。"},{"w":"霭","v":"凝聚。"},{"w":"禁里","v":"宫中。"},{"w":"省中","v":"门下省。"},{"w":"天书","v":"皇帝的诏令。"},{"w":"琐闱","v":"宫门，刻连琐图案。"},{"w":"无那","v":"无奈。"},{"w":"解朝衣","v":"辞官。"}],"yi":"重重洞门高阁里凝聚着余辉，桃李荫下柳絮纷飞。宫里疏钟响过官舍已晚，省中鸟啼、吏人稀少。清晨摇着玉佩趋步金殿，傍晚捧着天书拜别琐闱。强想随君共事，无奈人已老；将因卧病，解下朝衣。","shang":"「禁里疏钟官舍晚，省中啼鸟吏人稀」写省中清寂，鸟啼吏稀，正是太平闲暇气象，亦见此公心迹。结以「强欲从君」四字一层、「无那老」再一层、「卧病解朝衣」三层，倦勤之意婉转道出，是酬答诗中见性情者。"},"181":{"ti":"杜甫初至成都谒武侯祠而作。三顾频烦天下计，两朝开济老臣心——十四字定尽诸葛一生，结以出师未捷，千古同悲。","zhu":[{"w":"蜀相","v":"诸葛亮。"},{"w":"锦官城","v":"成都。"},{"w":"柏森森","v":"祠前古柏茂密。"},{"w":"自春色","v":"自为春色，无人赏看。"},{"w":"空好音","v":"空作好音，无人倾听。"},{"w":"三顾","v":"刘备三顾茅庐。"},{"w":"频烦","v":"屡次烦劳。"},{"w":"两朝","v":"刘备、刘禅两朝。"},{"w":"开济","v":"开创与匡济。"}],"yi":"丞相的祠堂到哪里去寻？锦官城外柏树森森。映阶的碧草自锁春色，隔叶的黄鹂空作好音。三顾茅庐频烦天下大计，两朝开济一片老臣之心。出师尚未成功身已先死，长使英雄泪满衣襟！","shang":"「自春色」「空好音」两个虚字，祠堂之寂寞、英雄之不遇全在其中，故前人谓「一「自」一「空」，最见情致」。颈联十四字概括诸葛亮一生功业与心迹，无一字虚设；结句一恸，千载之下读之犹使英雄气短。七律怀古，此为极笔。"},"182":{"ti":"杜甫成都草堂迎客。花径缘客扫、蓬门为君开，市远盘飧、家贫旧醅，一餐家常饭写尽真淳，结以隔篱呼取邻翁，趣极。","zhu":[{"w":"舍","v":"草堂。"},{"w":"群鸥","v":"水鸟，古人以鸥鹭无机心为友。"},{"w":"缘客扫","v":"为客而扫。缘，因。"},{"w":"蓬门","v":"柴门。"},{"w":"盘飧","v":"盘中熟食。"},{"w":"兼味","v":"多种菜肴。"},{"w":"旧醅","v":"隔年的浊酒，未滤清。"},{"w":"呼取","v":"呼唤。"}],"yi":"舍南舍北都是春水，只见群鸥日日飞来。花径不曾为客扫过，柴门今天才为您打开。盘飧离市远没有兼味，家贫的樽酒只有旧醅。肯与邻家老翁对饮么？隔着篱笆喊他来干尽余杯！","shang":"「花径不曾缘客扫，蓬门今始为君开」主客之情以门户写之，殷勤之意扑面而来。「肯与邻翁相对饮，隔篱呼取尽余杯」把一席酒饮成了村社的欢聚，真气弥漫。杜诗沉郁之外，别有此天真一路。"},"183":{"ti":"杜甫居成都草堂时出郊野望。西山白雪三城戍、南浦清江万里桥，起笔便见西陲之警与蜀中之乱；「唯将迟暮供多病」，自伤极矣。","zhu":[{"w":"三城","v":"松、维、保三州，唐西陲要地。"},{"w":"南浦","v":"成都南郊水滨。"},{"w":"清江","v":"锦江。"},{"w":"万里桥","v":"成都城南，费祎使吴登舟处曰「万里之行始于此」。"},{"w":"风尘","v":"战乱。"},{"w":"迟暮","v":"晚年。"},{"w":"涓埃","v":"细流与微尘，喻微末贡献。"},{"w":"萧条","v":"冷落衰败。"}],"yi":"西山白雪下三城戍守，南浦清江边万里桥横。海内风尘中诸弟阻隔，天涯涕泪里一身孤遥。唯将迟暮之年供于多病，未有一涓一埃答谢圣朝。跨马出郊时纵目远望，不堪人事一天天萧条！","shang":"首联一雪一江、一戍一桥，家国之忧尽在山川之间。颈联「唯将」「未有」两两对照，迟暮多病之身竟无以报国，自责之深令人心酸。结句「人事日萧条」，个人之孤推及天下之乱，是杜律的老境与血诚。"},"184":{"ti":"杜甫代宗广德元年春，闻官军收复失地，狂喜而作，为平生第一快诗。八句如骏马注坡，一气奔放。","zhu":[{"w":"剑外","v":"剑门以南，指蜀地。"},{"w":"蓟北","v":"今河北北部，安史叛军老巢。"},{"w":"","v":"回头看。"},{"w":"妻子","v":"妻子儿女。"},{"w":"漫卷","v":"胡乱卷起。"},{"w":"青春","v":"春天，谓春光作伴。"},{"w":"巴峡","v":"巴县一带江峡。"},{"w":"巫峡","v":"长江三峡之一。"}],"yi":"剑门之外忽然传来收复蓟北的消息，初闻时涕泪洒满衣裳。回头看妻子儿女的愁容何在？胡乱卷起诗书，欢喜得要发狂。白日放歌须纵酒，青春正好作伴还乡！即从巴峡穿过巫峡，便下襄阳直向洛阳。","shang":"「初闻涕泪满衣裳」是喜极之哭，「漫卷诗书喜欲狂」是喜极之态；结二句以四个地名一路飞下，归心之疾如舟脱缆。浦起龙评为「老杜生平第一首快诗」。沉郁一生的杜甫，偶一流露的狂喜，弥足珍贵。"},"185":{"ti":"杜甫大历二年重阳登夔州白帝城外高台而作。一篇之中句句皆对、字字皆愁，被推为古今七律第一。","zhu":[{"w":"猿啸哀","v":"巫峡多猿，鸣声甚哀。"},{"w":"渚","v":"水中小洲。"},{"w":"鸟飞回","v":"鸟在急风中盘旋。"},{"w":"落木","v":"落叶。"},{"w":"萧萧","v":"落叶声。"},{"w":"常作客","v":"长年漂泊作客。"},{"w":"百年","v":"一生，此指晚年。"},{"w":"繁霜鬓","v":"白发日多。"},{"w":"潦倒","v":"衰颓。"},{"w":"新停","v":"刚刚戒酒（因病）。"}],"yi":"风急天高，猿啸声声悲哀；渚清沙白，鸟儿盘旋来回。无边的落叶萧萧而下，不尽的长江滚滚而来。万里悲秋，常是客中之人；百年多病，独自登上这台。艰难苦恨，霜鬓日繁；潦倒之际，新近又停了浊酒之杯。","shang":"前四句写景，一联回环之中山川之哀已极；「无边落木」「不尽长江」以无穷之景写无穷之愁。后四句层层递进——作客、悲秋、多病、独登、断酒，八重愁意凝于十四字。胡应麟推为「古今七言律第一」，沉郁顿挫至此为极。"},"186":{"ti":"杜甫寓成都登楼而作。时吐蕃陷京畿，万方多难登临，锦江春色、玉垒浮云间，是家国的大忧愤。","zhu":[{"w":"万方多难","v":"时吐蕃陷长安，代宗奔陕，四方多事。"},{"w":"锦江","v":"岷江支流，流经成都。"},{"w":"玉垒","v":"山名，在成都西北。"},{"w":"北极","v":"北极星，喻朝廷。"},{"w":"西山寇盗","v":"吐蕃。"},{"w":"后主","v":"蜀汉刘禅，宠信黄皓而亡国。"},{"w":"祠庙","v":"成都先主庙侧有后主祠。"},{"w":"梁父吟","v":"乐府曲名，诸葛亮好为此曲。"}],"yi":"花开近高楼，反伤客子之心；万方多难之际，我登上了此楼。锦江的春色来自天地，玉垒的浮云变幻古今。北极朝廷终不会改易，西山的寇盗莫要相侵！可怜那后主还立着祠庙，日暮聊且吟一曲《梁父吟》。","shang":"「锦江春色来天地，玉垒浮云变古今」以天地古今写眼前一景，气吞一世。「北极朝廷终不改」是信念，「西山寇盗莫相侵」是斥责；结以「日暮聊为梁父吟」——以武侯之志自任，忧愤至深。沉雄之至，为杜七律骨干。"},"187":{"ti":"杜甫在严武幕府夜宿而作。永夜角声、中天月色，问「好谁看」者，孤宿无人共赏；强移一枝，幕府生活的委屈毕现。","zhu":[{"w":"幕府","v":"严武节度使府署。"},{"w":"井梧","v":"井边梧桐。"},{"w":"蜡炬残","v":"蜡烛将尽，夜已深。"},{"w":"永夜","v":"长夜。"},{"w":"角声","v":"军中号角。"},{"w":"荏苒","v":"时光推移。"},{"w":"伶俜","v":"孤独无依。"},{"w":"一枝安","v":"《庄子》鹪鹩巢于深林，不过一枝；喻勉强栖身。"}],"yi":"清秋的幕府井梧生寒，独宿江城蜡炬将残。长夜里角声悲怆如自语，中天的月色好了给谁看？风尘荏苒音书断绝，关塞萧条行路艰难。已忍了十年的伶仃孤苦，强移栖息，且求一枝之安。","shang":"「永夜角声悲自语，中天月色好谁看」上句自问自答、下句问而无答，孤绝之情全在语法的错落中。结以鹪鹩一枝自嘲栖幕——「强移」二字，对幕府生活的勉强与无聊写得极真。"},"188":{"ti":"杜甫寓夔州西阁夜作。五更鼓角、三峡星河，写夔府夜色之壮；卧龙跃马终归黄土，人事音书都付寂寥。","zhu":[{"w":"阴阳","v":"日月。"},{"w":"短景","v":"冬日短促的日影。景，日光。"},{"w":"霁","v":"雪止天晴。"},{"w":"鼓角","v":"军中报时的鼓与号角。"},{"w":"野哭","v":"郊野的哭声。"},{"w":"战伐","v":"时崔旰等蜀中军阀混战。"},{"w":"夷歌","v":"巴蜀少数民族的歌。"},{"w":"卧龙","v":"诸葛亮。"},{"w":"跃马","v":"公孙述，西汉末据蜀称帝。"},{"w":"漫","v":"任随。"}],"yi":"岁暮的日月催着短景，天涯霜雪初霁、寒夜放晴。五更鼓角声声悲壮，三峡里星河倒影动摇。野哭千家，听得出战伐；夷歌数处，起自渔樵。卧龙、跃马终归黄土——人事音书，都付与寂寥吧。","shang":"「五更鼓角声悲壮，三峡星河影动摇」声在耳、影在目，壮丽与悲凉一体，为杜七律写夜景第一。结以「人事音书漫寂寥」——英雄成败同归黄土，与世推移的旷达里是无可奈何的大悲凉。"},"189":{"ti":"杜甫咏怀古迹五首其一。支离东北、漂泊西南，以庾信自比——皆哀时而未还，暮年诗赋动江关。","zhu":[{"w":"支离","v":"流离。"},{"w":"风尘际","v":"战乱之中。"},{"w":"三峡楼台","v":"夔州依山而居。"},{"w":"淹日月","v":"滞留多时。"},{"w":"五溪衣服","v":"五溪（今湘黔边境）蛮人服饰，指与共居的边地之人。"},{"w":"羯胡","v":"指安禄山（兼喻侯景）。"},{"w":"无赖","v":"狡诈反复。"},{"w":"词客","v":"诗人，庾信自谓，兼指杜甫。"},{"w":"江关","v":"荆州一带，庾信暮年留北而名动江关。"}],"yi":"流离在东北的风尘之际，漂泊于西南的天地之间。三峡的楼台淹留日月，与五溪的衣服共此云山。羯胡事主终归无赖，词客哀时且未能还。庾信平生最为萧瑟，暮年的诗赋却震动江关。","shang":"首联「支离」「漂泊」四字总领五首，写尽身世。以庾信拟己：侯景之乱与安史之乱、羁北与滞蜀，两两相照。结句「暮年诗赋动江关」，是慰藉亦是自许——身世尽可萧瑟，文章自有千秋。"},"190":{"ti":"杜甫咏怀古迹其二，咏宋玉。摇落深知宋玉悲——读其文而知其心，异代知音一洒泪。","zhu":[{"w":"宋玉","v":"战国楚辞赋家，《九辩》有「悲哉秋之为气也，萧瑟兮草木摇落而变衰」。"},{"w":"摇落","v":"草木凋零，亦指身世之感。"},{"w":"风流儒雅","v":"指宋玉的文采与品格。"},{"w":"异代不同时","v":"隔代而不同时。"},{"w":"故宅","v":"归州、江陵皆有宋玉宅。"},{"w":"云雨荒台","v":"宋玉《高唐赋》记楚王梦神女事，巫山云雨。"},{"w":"岂梦思","v":"岂止说梦，寓讽谏之旨。"},{"w":"楚宫","v":"楚王宫遗址。"}],"yi":"从草木摇落里深深懂得宋玉的悲慨，风流儒雅，也是我的老师。怅望千秋，为此一洒泪；萧条异代，偏不同时。江山的故宅空留文藻，云雨荒台岂止是说梦！最可惜那楚宫都已泯灭，船夫指点着、至今存疑。","shang":"「怅望千秋一洒泪，萧条异代不同时」——知音之泪为隔代之人而落，故为千古文人同感。为宋玉辩「云雨岂梦思」，见杜甫识其讽谏之志；结叹楚宫泯灭而故宅空存文藻，文人身后之名，系于文字而已。"},"191":{"ti":"杜甫咏怀古迹其三，咏王昭君。群山万壑赴荆门——一「赴」字写尽山川奔赴之势，为明妃村起出无上气象。","zhu":[{"w":"明妃","v":"王嫱，字昭君，晋人避司马昭讳称明妃。"},{"w":"荆门","v":"山名，昭君村在荆门山附近。"},{"w":"紫台","v":"紫宫，汉宫，指汉廷。"},{"w":"朔漠","v":"北方沙漠，匈奴地。"},{"w":"青冢","v":"昭君墓，在今呼和浩特，传说草色常青。"},{"w":"画图省识","v":"汉元帝按画图召幸宫人；省识，略识。"},{"w":"春风面","v":"美丽的容颜。"},{"w":"环佩","v":"女子饰物，指昭君魂。"},{"w":"琵琶","v":"昭君出塞马上弹琵琶，后世传为怨曲。胡语，塞外之音。"}],"yi":"群山万壑奔赴荆门，生长明妃的村庄还在。一去紫台连着朔漠，独留青冢向着黄昏。画图上省识春风之面，环佩空归月下之魂。千载琵琶弹着胡语，分明是怨恨在曲中诉说。","shang":"「一去紫台连朔漠，独留青冢向黄昏」一「连」一「向」，生离与死别，被两个动词写尽，朱彝尊叹为「咏昭君之绝唱」。「画图省识」怨君王之昏，「环佩空归」写魂魄之痴；结以千载琵琶，怨无终极。山川之雄与儿女之怨相激，此其所以为大。"},"192":{"ti":"杜甫咏怀古迹其四，咏刘备永安宫。玉殿虚无野寺中——盛时翠华、殁后虚无，惟武侯祠屋常邻近，一体君臣祭祀同。","zhu":[{"w":"蜀主","v":"刘备。"},{"w":"征吴","v":"伐吴为关羽复仇。"},{"w":"幸","v":"驾临。"},{"w":"永安宫","v":"在夔州，刘备猇亭败后崩于此。"},{"w":"翠华","v":"翠羽旗，仪仗。"},{"w":"野寺","v":"永安宫故址后为寺。"},{"w":"巢水鹤","v":"水鹤（鹭）在古庙杉松上筑巢。"},{"w":"岁时伏腊","v":"逢年过节。伏，伏日；腊，腊日。"},{"w":"武侯祠屋","v":"夔州诸葛亮祠与先主庙相近。"},{"w":"一体君臣","v":"君臣合祀。"}],"yi":"蜀主征吴驾临三峡，崩逝之年也在永安宫。翠华的仪仗只在空山想像，玉殿早已虚无、只在野寺之中。古庙的杉松上水鹤筑巢，逢年过节村翁走来祭祀。武侯的祠屋常相邻近——一体君臣，祭祀相同。","shang":"「翠华想像空山里，玉殿虚无野寺中」十字写尽帝王身后之寂寞，与前篇「武侯祠屋常邻近」相映——君臣一体而同受村翁之祭，是杜甫少有的温厚收束。以议论之笔入咏史而情韵不减。"},"193":{"ti":"杜甫咏怀古迹其五，咏诸葛亮。万古云霄一羽毛——以一羽之轻写千钧之重，推武侯为伊吕之俦。","zhu":[{"w":"宗臣","v":"为后世所宗仰的大臣。"},{"w":"肃清高","v":"遗像令人肃然，见其清高。"},{"w":"纡筹策","v":"曲折周密地筹划。纡，屈曲。"},{"w":"云霄一羽毛","v":"如鸾凤高翔于云霄之上。"},{"w":"伯仲之间","v":"不相上下。"},{"w":"伊吕","v":"商汤之相伊尹、周武王之相吕尚。"},{"w":"萧曹","v":"萧何、曹参，汉初名相。"},{"w":"汉祚","v":"汉朝的国运。祚，帝位国统。"},{"w":"身歼","v":"身死。"}],"yi":"诸葛大名垂于宇宙，宗臣的遗像肃然清高。三分割据，纡回筹划；万古云霄，一羽独高。与伊尹吕尚在伯仲之间，指挥若定使萧曹失色。汉祚转移终难恢复，志决身歼，军务成劳。","shang":"「万古云霄一羽毛」五个字，把诸葛的人格悬到云霄之上——万古之时间与一羽之形象相乘，奇绝而妥帖。「伯仲之间见伊吕」直接置之于伊吕之列，是杜甫对武侯的至高评价；结以「志决身歼」，惋惜与崇敬并至。"},"194":{"ti":"刘长卿再贬南巴，别薛六柳八。江上月明胡雁过、淮南木落楚山多，写贬途秋色；愧君犹遣慎风波，患难之交尤可感。","zhu":[{"w":"江州","v":"今江西九江。"},{"w":"薛六柳八","v":"薛、柳二位友人，排行六、八。"},{"w":"员外","v":"员外郎的省称。"},{"w":"优诏","v":"褒美之诏（实为贬官，故曰岂料）。"},{"w":"胡雁","v":"北方飞来的雁。"},{"w":"淮南木落","v":"《楚辞》「洞庭波兮木叶下」，淮南木落而山愈显。"},{"w":"沧洲","v":"滨水之地，指贬所近水。"},{"w":"无如","v":"无奈。"},{"w":"龙钟","v":"衰惫之态。"},{"w":"遣","v":"叮嘱。"}],"yi":"一生行止岂料到承受这般「优诏」？世事难知，空知学人醉歌。江上月明，胡雁飞过；淮南木落，楚山更多。寄身此地且喜沧洲相近，顾影自怜——无奈白发又添几何！今日龙钟，与你共老，愧对你们还叮嘱我路上慎风波。","shang":"「生涯岂料承优诏」以「优诏」二字冷嘲贬谪，怨而不怒；「淮南木落楚山多」以山之多写行之远，景语皆情语。结句「愧君犹遣慎风波」——自顾不暇犹蒙挂念，患难友情，愈见其真。"},"195":{"ti":"刘长卿贬途中过长沙贾谊故宅。汉文有道恩犹薄——为贾谊鸣，亦为己鸣；怜君何事到天涯，一问千古同悲。","zhu":[{"w":"贾谊宅","v":"贾谊贬长沙王太傅时所居，在长沙。"},{"w":"三年谪宦","v":"贾谊谪居长沙三年。"},{"w":"栖迟","v":"淹留。"},{"w":"楚客","v":"客居楚地之人，指贾谊兼自指。"},{"w":"日斜时","v":"贾谊《鵩鸟赋》「庚子日斜兮，鵩集予舍」。"},{"w":"汉文","v":"汉文帝。"},{"w":"湘水无情吊岂知","v":"贾谊渡湘水吊屈原，屈原岂知？喻古今吊古之隔。"},{"w":"摇落","v":"草木凋零。"}],"yi":"三年谪宦在此栖迟，万古只留下一片楚客的悲慨。秋草里独寻人去之后，寒林中空见日斜之时。汉文有道而恩犹嫌薄，湘水无情凭吊岂能知？寂寞的江山摇落之处，怜你何事竟到了天涯！","shang":"「秋草独寻人去后，寒林空见日斜时」暗用《鵩鸟赋》「日斜」语，寻、空二字，人宅两空之慨尽出。「汉文有道恩犹薄」论史最沉痛——明主尚且如此，况昏主乎？结句一问，怜贾谊即自怜，遂成吊古第一名篇。"},"196":{"ti":"刘长卿贬南巴途中，自夏口至鹦鹉洲夕望岳阳寄源中丞。汉口夕阳斜渡鸟、洞庭秋水远连天，写江天浩渺中一行人之孤。","zhu":[{"w":"夏口","v":"今武汉武昌。"},{"w":"鹦鹉洲","v":"长江中沙洲。"},{"w":"源中丞","v":"御史中丞源某，亦遭贬者。"},{"w":"汀洲","v":"鹦鹉洲。"},{"w":"渺然","v":"悠远无尽。"},{"w":"斜渡鸟","v":"一作「飞鸟没」。"},{"w":"孤城","v":"指汉阳城。"},{"w":"独戍","v":"孤立的哨所。"},{"w":"贾谊上书","v":"贾谊屡上疏论时政，谪长沙；源中丞亦以直言遭贬，故引以相拟。"}],"yi":"汀洲上无浪也无烟，楚客的相思更加渺然。汉口的夕阳斜照渡鸟，洞庭的秋水远接连天。孤城背岭，寒风中吹角；独戍临江，夜里泊着船。贾谊上书忧虑汉室，长沙谪去，古今同怜。","shang":"「汉口夕阳斜渡鸟，洞庭秋水远连天」写江汉洞庭间的大景，浩渺无际，愈见「孤城」「独戍」之小。结以贾谊拟源中丞，同贬同怜——刘长卿一生两遭迁谪，笔笔皆是身世。"},"197":{"ti":"钱起献赋未遇，赠阙下裴舍人求引荐。长乐钟声花外尽，龙池柳色雨中深——通首以写景代陈情，为干谒诗最含蓄者。","zhu":[{"w":"阙下","v":"宫阙之下，指朝廷。"},{"w":"舍人","v":"中书舍人。"},{"w":"紫禁","v":"皇宫。"},{"w":"花外尽","v":"钟声在花树外渐渐消尽。"},{"w":"龙池","v":"兴庆宫池名。"},{"w":"阳和","v":"春天的暖气。"},{"w":"霄汉","v":"云霄银河，指朝廷。"},{"w":"捧日心","v":"效忠之心。"},{"w":"献赋","v":"向皇帝献赋以求进用。"},{"w":"华簪","v":"贵人冠饰，代指显贵。"}],"yi":"二月黄鹂飞上林苑，春城紫禁晓色阴阴。长乐宫钟声在花外消尽，龙池柳色在雨中更深。阳和之气驱不散穷途之恨，霄汉之上长怀捧日之心。献赋十年犹未遇合，羞将白发对着华簪。","shang":"「长乐钟声花外尽，龙池柳色雨中深」不写人而宫苑景色俱出，暗点裴舍人之近侍，格高语秀。后四句才自陈穷途——「阳和不散」反衬「捧日」之诚，末句「羞将白发对华簪」，干谒而能自处如此，故为唐代干谒诗之冠。"},"198":{"ti":"韦应物寄李儋元锡。身多疾病思田里，邑有流亡愧俸钱——十字仁者之怀，宋人叹为「仁者之言」。","zhu":[{"w":"李儋","v":"武威人，韦应物诗友。"},{"w":"元锡","v":"字君贶，亦韦之友。"},{"w":"黯黯","v":"心神黯淡低沉。"},{"w":"思田里","v":"想归隐田园。"},{"w":"邑","v":"所辖之县。"},{"w":"流亡","v":"逃荒的百姓。"},{"w":"愧俸钱","v":"愧对所领的俸禄。"},{"w":"问讯","v":"探望。"},{"w":"西楼","v":"滁州西楼。"}],"yi":"去年花开时节与你分别，今日花开又是一年。世事茫茫难以自料，春愁黯黯独自成眠。身多疾病想归田里，邑中尚有流亡之民，愧对这俸禄。听说你要来相问讯，西楼的月已几回圆？","shang":"「邑有流亡愧俸钱」——身为一郡之守，见民之流亡而愧其禄，此一「愧」字是全唐诗人中最重的良心。范仲淹读之称「仁者之言」。结以「西楼望月几回圆」，盼友与念乱并举，温厚之至。"},"199":{"ti":"韩翃与友人同题仙游观。疏松影落空坛静，细草香闲小洞幽——一道观幽境；结言人间自有丹丘，不必方外别寻。","zhu":[{"w":"仙游观","v":"道士潘师正所建道观，在嵩山（一说在洛阳附近）。"},{"w":"五城楼","v":"传说仙人五城十二楼，喻道观楼观。"},{"w":"宿雨","v":"隔夜的雨。"},{"w":"秦树","v":"秦地（长安）的树。"},{"w":"砧声","v":"捣衣声，报秋。"},{"w":"空坛","v":"修道之坛。"},{"w":"小洞","v":"道观洞穴。"},{"w":"方外","v":"世俗之外。"},{"w":"丹丘","v":"传说昼夜长明之地，神仙所居。"}],"yi":"仙台上初见五城楼观，风物凄清、宿雨方收。山色遥连着秦地的晚树，砧声近报汉宫的秋意。疏松的影子落在空坛，一片静谧；细草的香气闲闲浮起，小洞幽幽。何须再向方外去别寻仙境？人间自有这丹丘！","shang":"「疏松影落空坛静，细草香闲小洞幽」写道观之静之幽，声色香俱全而不着一仙字。结句翻出一层——仙境不在方外而在眼前，与「山色有无中」同一机杼，唐人题观诗之最旷达者。"},"200":{"ti":"皇甫冉拟闺情。家住层城邻汉苑，心随明月到胡天——闺中锦字与塞外征人两地相照，末问「何时返旆勒燕然」。","zhu":[{"w":"马邑","v":"在今山西朔县，汉与匈奴争战之地。"},{"w":"龙堆","v":"白龙堆沙漠，在今新疆。"},{"w":"层城","v":"古代传说昆仑山最高处，此指京城。"},{"w":"汉苑","v":"皇宫苑囿。"},{"w":"胡天","v":"塞外。"},{"w":"锦字","v":"前秦苏蕙织锦为回文诗寄窦滔，喻妻子寄夫的书信。"},{"w":"天戎","v":"一作「为问元戎」。"},{"w":"窦车骑","v":"东汉窦宪，破匈奴，登燕然山刻石记功。"},{"w":"返旆","v":"班师。旆，军旗。"},{"w":"勒燕然","v":"刻石燕然山。"}],"yi":"莺啼燕语报着新年，马邑龙堆路隔几千。家住层城、毗邻汉苑，心却随明月到了胡天。机上锦字织论长恨，楼上花枝笑她独眠。为问那出征的窦车骑：何时返旆、勒石燕然？","shang":"「家住层城邻汉苑，心随明月到胡天」身在长安而心在塞外，一联之内千里万里。机中锦字、楼上花枝皆拟人有意——花枝「笑独眠」三字怨入骨髓。结以勒燕然之问，闺怨之外更有望捷之切。"},"201":{"ti":"卢纶晚泊鄂州。云开远见汉阳城，犹是孤帆一日程——可见而未可即，乱世行舟之叹尽在此十字。","zhu":[{"w":"鄂州","v":"今武汉武昌。"},{"w":"次","v":"停泊。"},{"w":"汉阳城","v":"今武汉汉阳。"},{"w":"估客","v":"商人。"},{"w":"舟人","v":"船夫。"},{"w":"三湘","v":"泛指洞庭湘江流域。"},{"w":"旧业","v":"家业。"},{"w":"鼓鼙","v":"战鼓，指战事。"}],"yi":"云开处远远望见汉阳城，还是孤帆一日的路程。估客昼眠，知是浪静；舟人夜语，觉出潮生。三湘的愁鬓逢着秋色，万里的归心对着月明。旧业已随征战而尽，更哪堪江上又起鼓鼙之声！","shang":"「估客昼眠知浪静，舟人夜语觉潮生」以人写水，细微入神，故为卢纶名句。「旧业已随征战尽」七字，安史乱后流民之痛尽在；结「更堪」二字，闻鼓而心惊，与首句「云开」之望恰成对照。"},"202":{"ti":"柳宗元贬柳州，寄漳汀封连四州刺史。惊风乱飐芙蓉水，密雨斜侵薜荔墙——风雨摧花，寓意逐臣处境，为唐律写景寓愤之极。","zhu":[{"w":"漳汀封连四州","v":"韩泰（漳州）、韩晔（汀州）、陈谏（封州）、刘禹锡（连州）。"},{"w":"大荒","v":"极远的荒地。"},{"w":"海天愁思","v":"愁思如海天浩茫。"},{"w":"惊风","v":"狂风。"},{"w":"飐","v":"吹动。"},{"w":"芙蓉水","v":"长满荷花的池塘。"},{"w":"薜荔","v":"香草，缘墙而生，喻君子自守。"},{"w":"九回肠","v":"愁肠百转。司马迁「肠一日而九回」。"},{"w":"百越文身地","v":"岭南越人文身之地。"},{"w":"滞一乡","v":"音书阻隔，各滞一乡。"}],"yi":"城上高楼接着大荒，海天般的愁思正茫茫。惊风乱飐芙蓉之水，密雨斜侵薜荔之墙。岭树重重遮断千里之目，江流曲折似九回之肠。同来这百越文身之地，犹自音书阻隔、各滞一乡。","shang":"「惊风乱飐芙蓉水，密雨斜侵薜荔墙」风狂雨密，荷与薜荔皆君子之象，摧折之意在字外，为柳诗七律之骨。结以「音书滞一乡」——同谪尚且难通，人间阻隔至此。苏轼谓柳诗「发纤秾于简古」，此篇当之。"},"203":{"ti":"刘禹锡自和州返洛阳，经西塞山怀古。王浚楼船下益州，一片降幡出石头——四句写尽一个王朝的覆灭。","zhu":[{"w":"西塞山","v":"在今湖北大冶东，长江要塞，为吴国西大门。"},{"w":"王浚","v":"西晋益州刺史，造楼船伐吴。"},{"w":"金陵王气","v":"相传金陵有天子气。"},{"w":"黯然收","v":"黯然消散。"},{"w":"千寻铁锁","v":"吴人在江中置铁锁拦晋船。寻，八尺。"},{"w":"降幡","v":"投降的旗。"},{"w":"石头","v":"石头城，金陵。"},{"w":"枕寒流","v":"山形依旧枕着寒冷的江流。"},{"w":"四海为家","v":"天下统一。"},{"w":"故垒","v":"旧时营垒。"}],"yi":"王浚的楼船顺流下了益州，金陵的王气黯然收。千寻铁锁沉入江底，一片降幡出了石头。人世几回伤悼往事？山形依旧枕着寒流。从今四海为家的日子，故垒萧萧，芦荻正秋。","shang":"「千寻铁锁沈江底，一片降幡出石头」——防线之长与降旗之孤，兴亡只在一瞬，全用形象说话，不着一字议论。「人世几回伤往事？山形依旧枕寒流」一问一答，山河无情、人事有尽。结以故垒芦荻，归到眼前。唐人咏史，此为绝唱。"},"204":{"ti":"元稹悼亡妻韦丛三首其一。忆韦氏出身名门而下嫁寒士、拔钗沽酒、拔薪槐下；今日俸钱过十万，惟以营奠营斋报之。","zhu":[{"w":"谢公","v":"东晋谢奕，其幼女谢道韫最受怜爱，比韦丛为韦夏卿幼女。"},{"w":"偏怜女","v":"最疼爱的女儿。"},{"w":"黔娄","v":"战国贫士，元稹自比。"},{"w":"百事乖","v":"诸事不顺。"},{"w":"荩箧","v":"草编的箱子。"},{"w":"泥他","v":"软缠她。泥，软求。"},{"w":"沽酒","v":"买酒。"},{"w":"长藿","v":"长长的豆叶，粗食。"},{"w":"营奠","v":"操办祭奠。"},{"w":"营斋","v":"延僧施食超度。"}],"yi":"你是谢公最小偏怜的女儿，自嫁我这黔娄般的穷汉，百事乖违。见我无衣，翻箱搜检；软缠着你买酒，你便拔下金钗。野蔬充膳，你吃得甘甜；落叶作柴，全靠古槐。今日俸钱过了十万，也只能为你营奠又营斋。","shang":"「顾我无衣搜荩箧，泥他沽酒拔金钗」——贫贱夫妻的两个细节，写尽韦丛之贤；「落叶添薪仰古槐」之「仰」字，家贫如见。结句沉痛：俸钱十万，所报者唯祭奠斋醮而已，人琴之痛至此。"},"205":{"ti":"元稹悼亡其二。昔日戏言身后事，今朝都到眼前来——旧情入梦、睹物伤神，结以「贫贱夫妻百事哀」，为千古悼亡定评。","zhu":[{"w":"戏言","v":"开玩笑的话。"},{"w":"身后事","v":"死后的打算。"},{"w":"施行看尽","v":"眼看就要施舍送完。"},{"w":"针线","v":"亡妻的针线活计。"},{"w":"送钱财","v":"梦见贫妻送钱，醒而焚纸以慰。"},{"w":"诚知","v":"确实知道。"}],"yi":"昔日玩笑说及身后之事，今朝都一一到眼前来。衣裳眼看就要施舍送尽，针线犹存、未忍打开。尚念旧情，连婢仆也格外怜惜；也曾因梦送钱，醒来焚纸。诚知这生死之恨人人都有——贫贱夫妻，是百事都哀。","shang":"「贫贱夫妻百事哀」七字，道尽共患难者死别之痛，遂成悼亡第一语。施衣、开箱、怜婢、焚纸，桩桩是小事，桩桩是旧情——悼亡诗之动人不在辞而在物。元稹情深至此，无怪身后聚讼而此诗独传。"},"206":{"ti":"元稹悼亡其三。惟将终夜长开眼，报答平生未展眉——以不眠报未展之眉，情之痴绝至此。","zhu":[{"w":"邓攸无子","v":"晋邓攸避乱弃子保侄，终无子。时元稹无子。"},{"w":"寻知命","v":"将到知命之年（五十）。"},{"w":"潘岳悼亡","v":"晋潘岳丧妻作《悼亡诗》，词虽工而妻不能复生，犹费词。"},{"w":"同穴","v":"夫妻合葬。"},{"w":"冥何所望","v":"一作「窅冥何所望」，渺茫无望。"},{"w":"他生缘会","v":"来生再结夫妇之缘。"},{"w":"长开眼","v":"彻夜不眠。一说用鳏鱼常睁眼典，自伤将鳏居。"},{"w":"未展眉","v":"妻生前为贫而愁，未曾舒眉。"}],"yi":"闲坐悲你也悲我自己，百年人生又有几多时？邓攸无子，眼看到了知命；潘岳悼亡，词也是白费。同穴已是渺茫无望，他生的缘会也难预期。只能把终夜长睁的眼，报答你平生未展的眉。","shang":"「惟将终夜长开眼，报答平生未展眉」——生前的亏欠以死后的不眠来偿，痴语至极亦情至极。三首《遣悲怀》至此收束，从忆贤、念旧到自悲，层层进逼，悼亡诗至此格局始大。"},"207":{"ti":"白居易河南经乱后，望月有感，寄符离、下邽弟兄。吊影分为千里雁，辞根散作九秋蓬——雁与蓬，写尽离散。","zhu":[{"w":"时难年荒","v":"建中、贞元间藩镇战乱、河南饥荒。"},{"w":"世业","v":"祖传家业。"},{"w":"羁旅","v":"客居漂泊。"},{"w":"寥落","v":"荒废冷落。"},{"w":"干戈","v":"战乱。"},{"w":"吊影","v":"形影相吊，只有影子相伴。"},{"w":"千里雁","v":"雁行失群，喻兄弟分散。"},{"w":"九秋蓬","v":"深秋随风飘转的蓬草。"},{"w":"五处同","v":"弟兄分处五地（符离、下邽、洛阳、荥阳、长安）。"}],"yi":"时难年荒，祖业荡然，弟兄们羁旅各奔西东。田园在干戈之后寥落，骨肉在道路之中流离。顾影自怜，分作千里的孤雁；离根而去，散成九秋的飞蓬。共看这一轮明月应都垂泪——一夜乡心，五处相同。","shang":"「吊影分为千里雁，辞根散作九秋蓬」雁、蓬二象，把「骨肉流离道路中」具象化了。结句「一夜乡心五处同」——五处之人共此月色共此泪，以「同」字收「散」字，白诗平易而深挚，此篇当之。"},"208":{"ti":"李商隐锦瑟自伤。五十六字之中，庄生梦蝶、望帝啼鹃、沧海珠泪、蓝田玉烟——一联一境，千古解人无穷。","zhu":[{"w":"无端","v":"没来由。"},{"w":"五十弦","v":"古瑟五十弦，后改为二十五弦。"},{"w":"华年","v":"青春年华。"},{"w":"庄生晓梦","v":"《庄子》庄周梦为蝴蝶，醒后不知周之为蝶、蝶之为周。"},{"w":"望帝","v":"蜀王杜宇，魂化杜鹃，啼声悲切。"},{"w":"春心","v":"伤春之心，向往之情。"},{"w":"沧海","v":"南海鲛人泣泪成珠；月满则珠圆。"},{"w":"蓝田","v":"蓝田山产美玉，日光煦照，玉气上腾为烟。"},{"w":"惘然","v":"怅然若失。"}],"yi":"锦瑟无端五十弦，一弦一柱都令我思念华年。庄生晓梦里迷失了蝴蝶，望帝把春心托付给杜鹃。沧海月明之下，鲛人的泪化成了珠；蓝田日暖之中，良玉升起了烟。这份情岂待今日追忆？只是当时已是一片惘然。","shang":"义山诗之第一谜、第一美：庄生之梦是幻，望帝之托是怨，沧海之泪是悲，蓝田之烟是望——四象皆可意会而不可指实。结联「当时已惘然」翻进一层：非待追忆方觉，身在其中已自惘然，遂成千古诗心之叹。"},"209":{"ti":"李商隐无题其一。忆昨夜画楼之宴——身无彩凤双飞翼，心有灵犀一点通，情之通而身之隔，写尽相思。","zhu":[{"w":"画楼","v":"彩绘的楼。"},{"w":"桂堂","v":"桂木建的高堂。"},{"w":"灵犀","v":"犀角有白纹贯通两端，感应最灵。"},{"w":"送钩","v":"藏钩于手令人猜的酒戏。"},{"w":"分曹","v":"分组。"},{"w":"射覆","v":"器皿下覆物令猜的游戏。"},{"w":"听鼓","v":"听更鼓报到。"},{"w":"应官","v":"应官差。"},{"w":"兰台","v":"秘书省，诗人时任校书郎。"},{"w":"转蓬","v":"随风飘转的蓬草。"}],"yi":"昨夜的星辰、昨夜的风，画楼西畔、桂堂之东。身上没有彩凤那样的双翼，心里却有灵犀一点相通。隔座送钩，春酒暖人；分组射覆，蜡灯正红。可叹我听鼓应官而去，走马兰台，像一株转蓬。","shang":"「身无彩凤双飞翼，心有灵犀一点通」一「无」一「有」，隔与通的张力写尽两情，为爱情诗千古名联。前四句追忆之温，后四句「听鼓应官」之冷，欢会一散，人如转蓬——义山无题诗结构之妙在此。"},"210":{"ti":"李商隐过隋炀帝行宫而作。玉玺不缘归日角，锦帆应是到天涯——假设之笔，写尽炀帝荒淫之无度。","zhu":[{"w":"紫泉","v":"避唐高祖李渊讳（李虎字虎），改「紫渊」为紫泉，代指长安。"},{"w":"芜城","v":"扬州，隋炀帝江都行宫所在，鲍照《芜城赋》故称。"},{"w":"玉玺","v":"传国玉玺。"},{"w":"日角","v":"额骨隆起如日，帝王之相，指李渊。"},{"w":"锦帆","v":"炀帝南游龙舟锦帆。"},{"w":"腐草无萤火","v":"炀帝于景华宫征萤火虫夜游，腐草化萤之说；今萤火已绝。"},{"w":"垂杨","v":"隋堤柳上今惟暮鸦，繁华荡尽。"},{"w":"陈后主","v":"陈叔宝，亡国之君，炀帝在东宫曾见其鬼魂。"},{"w":"后庭花","v":"《玉树后庭花》，亡国之音。"}],"yi":"长安的宫殿锁在烟霞之中，却要把芜城当作家。玉玺若不是归于日角之相，锦帆定要驶到天涯。于今腐草里再无萤火，终古垂杨上只有暮鸦。地下若逢陈后主，哪还有脸再问《后庭花》？","shang":"「玉玺不缘归日角，锦帆应是到天涯」以一个「不缘」翻出炀帝欲望之无底，是咏史最毒的假设。「於今」「终古」一联今昔对照，萤火暮鸦，荒淫随时间荡尽。结以与陈后主问后庭花，冷峭入骨，讽意如刀。"},"211":{"ti":"李商隐无题其二。来是空言去绝踪——梦醒之后，书被催成墨未浓，相思到疾处，笔皆失度。","zhu":[{"w":"空言","v":"空话，约而不至。"},{"w":"绝踪","v":"踪影全无。"},{"w":"书被催成","v":"急急写成情书。"},{"w":"墨未浓","v":"墨还没磨浓——慌急之状。"},{"w":"金翡翠","v":"饰金翡翠的烛罩。"},{"w":"麝熏","v":"麝香气。"},{"w":"绣芙蓉","v":"绣着芙蓉的帐子。"},{"w":"刘郎","v":"汉刘晨入天台遇仙，再寻不得；兼指汉武帝求仙。"},{"w":"蓬山","v":"蓬莱仙山，喻所思之人居处之远。"}],"yi":"你说来却是空言，一去绝了踪影；月斜楼上，敲过五更的钟。梦里为远别啼哭难以唤醒，书信被催着写成、墨还未磨浓。蜡光半笼着金翡翠的灯罩，麝香微微透过绣芙蓉的帐。刘郎已恨蓬山之远，何况更隔蓬山一万重！","shang":"「梦为远别啼难唤，书被催成墨未浓」梦与书两件事把痴情写到失态——啼难唤是梦之不能自止，墨未浓是情之不容自缓。结以两个「蓬山」一层重一层，人愈远而情愈迫。义山无题，此篇最见「迫」字。"},"212":{"ti":"李商隐无题其三。飒飒东风细雨来——金蟾啮锁、玉虎牵丝，锁可开、丝可引，而春心莫共花争发，一寸相思一寸灰。","zhu":[{"w":"飒飒","v":"风声。"},{"w":"轻雷","v":"隐隐雷声（兼喻车声）。"},{"w":"金蟾啮锁","v":"蟾形门锁；啮，咬合。"},{"w":"玉虎牵丝","v":"玉虎形辘轳引井绳。"},{"w":"贾氏窥帘","v":"贾充之女窥帘见韩寿而悦之，后终成夫妇。"},{"w":"韩掾","v":"韩寿，掾为僚属。"},{"w":"宓妃留枕","v":"洛神宓妃留枕于曹植（《感甄记》附会）。"},{"w":"魏王","v":"曹植。"},{"w":"一寸相思一寸灰","v":"相思如香，寸寸烧成灰。"}],"yi":"飒飒东风送细雨来，芙蓉塘外有轻轻的雷。金蟾啮锁，香烟可入；玉虎牵丝，井水可回。贾氏窥帘，是爱韩掾年少；宓妃留枕，是慕魏王之才。春心啊莫与花争着发——一寸相思，一寸成灰。","shang":"「春心莫共花争发，一寸相思一寸灰」上句劝、下句证，把相思写成自焚，是义山情诗最痛的一联。中二联以「可入」「可回」之物反照人间之隔，典故四出而意脉不断。清人叹其「一寸」与「一寸」对，字字血痕。"},"213":{"ti":"李商隐经筹笔驿吊诸葛亮。猿鸟犹疑畏简书、风云常为护储胥——遗爱所及，草木风云皆有敬惧。","zhu":[{"w":"筹笔驿","v":"在今四川广元，诸葛亮出师运筹于此。"},{"w":"简书","v":"军中文书号令。《诗经》「畏此简书」。"},{"w":"储胥","v":"军中藩篱营垒。"},{"w":"上将","v":"诸葛亮。"},{"w":"神笔","v":"运筹之笔。"},{"w":"降王","v":"后主刘禅。"},{"w":"管乐","v":"管仲、乐毅，诸葛亮自比。"},{"w":"不忝","v":"不愧。"},{"w":"关张","v":"关羽、张飞，皆非寿终。"},{"w":"梁父吟","v":"诸葛亮好吟之曲。"}],"yi":"猿鸟还疑畏那军令文书，风云常为守护旧时藩篱。徒然令上将挥动神笔，终见降王被驿车载走。管仲乐毅之才原不辱没，关张无命又能如何！他年再到锦里经祠庙，一曲《梁父》吟成、遗恨有馀。","shang":"「猿鸟犹疑畏简书，风云常为护储胥」以草木风云之敬写武侯之威，起笔即高。「管乐有才原不忝，关张无命欲何如」——才可为而无命为之，天意二字写尽。结以他年重经祠庙之预想，恨长如江水。义山七律之学杜者，此篇最称。"},"214":{"ti":"李商隐无题其四。春蚕到死丝方尽，蜡炬成灰泪始干——以死别之情写至死之爱，为爱情诗的终极名句。","zhu":[{"w":"丝","v":"谐「思」，双关。"},{"w":"蜡炬","v":"蜡烛。"},{"w":"泪","v":"烛泪，谐人之泪。"},{"w":"晓镜","v":"晨起对镜。"},{"w":"云鬓改","v":"鬓发因愁而斑白。"},{"w":"月光寒","v":"夜吟时觉月色侵人。"},{"w":"蓬莱","v":"蓬莱山，喻所思者居处。"},{"w":"青鸟","v":"西王母传信之鸟。"},{"w":"探看","v":"探望音讯。"}],"yi":"相见本已难得，分别更是难舍；东风无力，百花凋残。春蚕到死，丝才吐尽；蜡炬成灰，泪方流干。晨起对镜，只愁云鬓改色；夜里吟诗，应觉月色生寒。此地到蓬莱已无多路，烦劳青鸟殷勤探看。","shang":"「春蚕到死丝方尽，蜡炬成灰泪始干」两句用两个至死方休的意象写情之无尽，遂成中国人爱情的公共语言。中二联体贴对方——你愁、你寒，皆代想之辞，情之细至此。结以青鸟探看，绝境中犹存一线之望。"},"215":{"ti":"李商隐春雨怀人。红楼隔雨相望冷，珠箔飘灯独自归——一「冷」一「独」，访而不遇之情尽在雨夜。","zhu":[{"w":"白袷衣","v":"白夹衣，春装。"},{"w":"白门","v":"金陵（一说指徐州，情人所居）。"},{"w":"寥落","v":"冷落。"},{"w":"意多违","v":"心意多不顺。"},{"w":"红楼","v":"所思女子居处。"},{"w":"珠箔","v":"珠帘。"},{"w":"晼晚","v":"日将暮，喻春光迟暮。"},{"w":"玉珰缄札","v":"玉耳饰与书信同寄。"},{"w":"云罗","v":"满天云气如罗网。"},{"w":"一雁","v":"孤雁传书。"}],"yi":"新春里怅卧白袷衣中，白门寥落，心意多违。红楼隔着雨望去只有清冷，珠帘映着飘摇的灯，我独自归去。远路之上应为春光迟暮而悲，残宵里还做得到依稀的梦。玉珰和书信凭什么叫得达？万里云罗中一只孤雁飞。","shang":"「红楼隔雨相望冷，珠箔飘灯独自归」雨、灯、帘、影，通篇只有一个「冷」字而冷彻全篇。结以「万里云罗一雁飞」——天如罗网、雁犹孤飞，书信不可达而痴念不灭。义山七律的缠绵悱恻，此为极笔。"},"216":{"ti":"李商隐无题其五。凤尾香罗夜深缝——扇裁月魄、车走雷声，一面之缘成永诀；何处西南任好风，托风寄愿。","zhu":[{"w":"凤尾香罗","v":"凤纹罗帐。"},{"w":"碧文圆顶","v":"青碧花纹的圆顶帐。"},{"w":"扇裁月魄","v":"团扇遮面如月。"},{"w":"羞难掩","v":"羞而难掩。"},{"w":"车走雷声","v":"车声如雷，匆匆而过。"},{"w":"语未通","v":"未及交谈。"},{"w":"金烬","v":"灯烛的余烬。"},{"w":"石榴红","v":"石榴花开，五月之候。"},{"w":"斑骓","v":"毛色斑驳的骏马，项羽所骑。"},{"w":"任好风","v":"一任好风相送。"}],"yi":"凤尾香的薄罗几重，碧纹圆顶夜深还在缝。团扇遮面如月，羞却难掩；车声如雷而过，一语未通。曾经守着寂寥，金烬暗暗燃尽；断绝消息直到石榴又红。斑骓就系在垂杨岸边——哪里得好风、从西南来？","shang":"「扇裁月魄羞难掩，车走雷声语未通」一面之惊以四物写之，永诀之痛正在「语未通」三字。颈联以「曾是」「断无」对举——烬暗之守候与榴红之无信。结托风寄愿，与《春雨》之雁同一痴绝。"},"217":{"ti":"李商隐无题其六。神女生涯原是梦——一出自慰，一以自伤；直道相思了无益，未妨惆怅是清狂。","zhu":[{"w":"重帷","v":"层层帷幕。"},{"w":"莫愁堂","v":"莫愁，古乐府中女子名，此指女子居处。"},{"w":"清宵","v":"静夜。"},{"w":"细细长","v":"夜长难捱。"},{"w":"神女","v":"楚王梦巫山神女，欢会如梦。"},{"w":"小姑","v":"乐府《清溪小姑曲》「小姑居处本无郎」。"},{"w":"风波","v":"喻摧残。"},{"w":"菱枝","v":"弱质之花，喻己。"},{"w":"月露","v":"月露本可润桂生香，谁教桂叶香？喻不得其人。"},{"w":"清狂","v":"疏狂不羁。"}],"yi":"重重帷幕深垂在莫愁堂，卧后清宵细细地长。神女的生涯原是一场梦，小姑的居处本就没有郎。风波不信菱枝之弱，月露谁教桂叶生香？直说这相思全然无益——也不妨碍惆怅，就算是清狂。","shang":"「直道相思了无益，未妨惆怅是清狂」——明知无益而甘之如饴，义山情诗的大勇在此。前六句梦也、无郎也、风波也、月露也，层层幻灭，逼出结联的固执，遂成绝望中最倔强的爱情宣言。"},"218":{"ti":"温庭筠利州南渡。波上马嘶看棹去，柳边人歇待船归——渡口群相，如一卷水乡行旅图；结以范蠡忘机，寄江湖之志。","zhu":[{"w":"利州","v":"今四川广元，嘉陵江畔。"},{"w":"澹然","v":"水波平静的样子。"},{"w":"翠微","v":"青翠的山色。"},{"w":"棹","v":"船桨，代指船。"},{"w":"数丛沙草","v":"沙洲上的草丛。"},{"w":"万顷江田","v":"江边大片的田。"},{"w":"范蠡","v":"助勾践灭吴后泛舟五湖而去。"},{"w":"忘机","v":"忘却机心。"}],"yi":"平静的空水对着斜晖，曲折的小岛苍茫连着翠微。波上马嘶，看渡船载去；柳边人歇，待船儿归来。数丛沙草群鸥散去，万顷江田一鹭高飞。谁解得乘舟去寻范蠡？五湖烟水，独自忘机。","shang":"「数丛沙草群鸥散，万顷江田一鹭飞」由密而疏、由动而静，一鹭独飞收尽全景，是温庭筠不常见的清疏之笔。结以范蠡泛湖，问「谁解」——渡口尽是奔忙之人，独忘机者谁？水乡画境中藏一声轻叹。"},"219":{"ti":"温庭筠过苏武庙而作。回日楼台非甲帐，去时冠剑是丁年——「回日」「去时」倒装一联，写尽十九年冰霜。","zhu":[{"w":"苏武","v":"汉武帝时出使匈奴被扣十九年，持节不屈，归拜典属国。"},{"w":"魂销","v":"激动之极。"},{"w":"雁断","v":"《汉书》汉使诈称天子射雁得苏武帛书。"},{"w":"陇上羊归","v":"苏武牧羊北海。"},{"w":"甲帐","v":"汉武帝以琉璃珠玉饰帐，甲乙二帐，此指宫殿一新。"},{"w":"丁年","v":"壮年。"},{"w":"茂陵","v":"汉武帝陵，武帝已不及见其归。"},{"w":"封侯印","v":"苏武归汉后受封典属国（后代封侯）。"},{"w":"逝川","v":"流水，喻逝去的岁月。《论语》「逝者如斯」。"}],"yi":"苏武在汉使面前魂销——古祠高树，两样茫然。云边雁断，胡天的月；陇上羊归，塞草的烟。回来时楼台已非甲帐，去时那冠剑还是丁年。茂陵里的人已不见封侯之印，空对着秋波哭这逝川。","shang":"「回日楼台非甲帐，去时冠剑是丁年」上下句倒装互见：去时丁年、回时物非，十九年只在一句转折之间，故为温诗七律之冠。「空向秋波哭逝川」——忠节归而君已葬，哭的是岁月，更是无赏之忠。"},"220":{"ti":"薛逢宫词。望仙楼上望君王——两个「望」字写尽宫人的痴；结「袍裤宫人扫御床」，一点现实击碎全部幻想。","zhu":[{"w":"十二楼","v":"仙人居所，代指宫中楼阁。"},{"w":"望仙楼","v":"唐宫楼名。"},{"w":"锁衔金兽","v":"门环衔着兽形锁。"},{"w":"铜龙","v":"龙首滴漏。"},{"w":"昼漏长","v":"白昼更漏觉长，写等待之久。"},{"w":"罢梳","v":"梳罢。"},{"w":"袍裤宫人","v":"着短袍绣裤的粗使宫女。"},{"w":"御床","v":"皇帝的床。"}],"yi":"十二楼中都在晓妆，望仙楼上望着君王。金兽连环锁得清冷，铜龙滴漏，昼间的更声正长。云髻梳罢还对着镜，罗衣欲换更添上香。远远窥见正殿帘开之处——穿袍裤的宫人，正在打扫御床。","shang":"全篇六句写盛妆之候：锁冷、漏长、对镜、添香，痴心层层加码；结句忽然揭底——御床是粗使宫人在扫。不言怨而怨深似海，一笔收尽宫怨。此即唐人所谓「末句一击，通体皆响」。"},"221":{"ti":"秦韬玉咏贫女。苦恨年年压金线，为他人作嫁衣裳——贫女之叹即寒士之叹，语意双成，千古共鸣。","zhu":[{"w":"蓬门","v":"柴门，贫家。"},{"w":"绮罗香","v":"富家女子衣饰。"},{"w":"良媒","v":"好媒人。"},{"w":"风流高格调","v":"高雅的品格气度。"},{"w":"俭梳妆","v":"时髦的梳妆（俭，「险」之省，高耸）。"},{"w":"斗画长","v":"比画眉的长。"},{"w":"压金线","v":"按捺金线刺绣。"}],"yi":"蓬门里没见过绮罗之香，想托良媒反添自伤。谁爱我风流高格调？人只怜那时髦的妆样。敢把十指夸作针巧，不把双眉去斗画长。苦恨年年压着金线——为他人作嫁衣裳！","shang":"「谁爱风流高格调」一问，把贞洁与流俗的冲突说尽；结句「为他人作嫁衣裳」七字，既是贫女实境，又是天下寒士怀才不遇的公论，双关至此，一诗而两用，故传诵不衰。"},"222":{"ti":"沈佺期独不见（乐府题）。九月寒砧催木叶，十年征戍忆辽阳——一联之内，时序与人事、闺中与塞外俱到。","zhu":[{"w":"卢家少妇","v":"乐府《河中之水歌》「卢家兰室桂为梁」之莫愁，此指长安少妇。"},{"w":"郁金香","v":"以郁金香和泥涂壁，言居室之华。"},{"w":"玳瑁梁","v":"玳瑁装饰的屋梁。"},{"w":"寒砧","v":"秋夜捣衣声。"},{"w":"辽阳","v":"唐东北边塞，征戍之地。"},{"w":"白狼河","v":"今辽宁大凌河。"},{"w":"丹凤城","v":"长安。"},{"w":"流黄","v":"黄绢，指帷帐。"}],"yi":"卢家少妇的堂上郁金飘香，海燕双双栖在玳瑁梁。九月寒砧催着木叶，十年征戍，忆着辽阳。白狼河北音书断绝，丹凤城南秋夜正长。谁教她这样含愁相见不得见？更教明月照着流黄帷帐。","shang":"「九月寒砧催木叶，十年征戍忆辽阳」以一「催」一「忆」，秋声与远人并至，为初唐七律名句。结联妙在明月「更教」二字——月本无知，偏来照愁，遂使长夜无所逃。此诗为七律成型之始，格律已全，情韵并茂。"},"223":{"ti":"王维辋川集《鹿柴》。空山人语、返景青苔，二十字写声光之动与山之静，禅境入画。","zhu":[{"w":"鹿柴","v":"辋川地名，王维别业二十景之一。柴，同「寨」，栅栏。"},{"w":"人语响","v":"偶尔的人声。"},{"w":"返景","v":"夕阳返照的光。景，同「影」。"},{"w":"青苔","v":"深林阴处的苔藓。"}],"yi":"空山里看不见人，只偶尔听得人语响。夕阳的返照射入深林，又照在那青苔上。","shang":"以「但闻人语响」衬空山之空，以「复照青苔」衬深林之深——声与光都是短暂的，空与静才是常在。王维以画家的眼睛与禅家的心写此二十字，遂成中国山水诗的极致小品。"},"224":{"ti":"王维辋川集《竹里馆》。独坐弹琴、明月相照，一「独」一「相」，孤独写成清赏。","zhu":[{"w":"幽篁","v":"幽深的竹林。篁，竹林。"},{"w":"长啸","v":"撮口出声，古人抒怀之举。"},{"w":"相照","v":"来照耀我。"}],"yi":"独坐幽深的竹林里，弹琴又长啸。深林里没有人知道，只有明月来相照。","shang":"「深林人不知，明月来相照」——人不解而我自有知音，是月。全篇不着一个愁字，孤独被月光照成了清福。二十字之内，人与月相知，是中国诗歌里最安静的一首。"},"225":{"ti":"王维山中送别。春草明年绿，王孙归不归？——别在今日，问在明年，一问之中离情无限。","zhu":[{"w":"柴扉","v":"柴门。"},{"w":"王孙","v":"游子。用《楚辞》「王孙游兮不归」语意。"},{"w":"春草明年绿","v":"设想来年春草重绿之期。"}],"yi":"在山中送走了你，日暮里掩上柴门。春草明年再绿的时候，王孙你归来不归来？","shang":"送罢掩扉，本已无事，偏生出「明年绿」与「归不归」一问——将今日之别放到明春的想象里，别情遂长出一岁。语浅而情曲，是送别五绝的绝唱。"},"226":{"ti":"王维咏红豆寄相思。愿君多采撷——以物之相思念人之相思，语浅情深，遂为相思第一诗。","zhu":[{"w":"红豆","v":"生于岭南，鲜红浑圆，古称相思子。"},{"w":"采撷","v":"采摘。"},{"w":"此物最相思","v":"古传佩红豆可寄相思。"}],"yi":"红豆生在南方，春天来了发几枝？愿你多采几颗，这东西最惹相思。","shang":"全篇似一首民歌：一问「发几枝」见念之殷，一劝「多采撷」见寄之切。安史乱后李龟年流落江南歌此曲，闻者无不动容——红豆自此成中国人相思的信物。"},"227":{"ti":"王维杂诗其二。君自故乡来，应知故乡事——急切一问，只问绮窗寒梅，乡思全在花事。","zhu":[{"w":"来日","v":"动身来的那天。"},{"w":"绮窗","v":"雕饰精美的窗。"},{"w":"著花未","v":"开花没有。著，开。"}],"yi":"你从故乡来，应该知道故乡的事。你来那天，绮窗前那株寒梅开花了没有？","shang":"故乡事千头万绪，独问一梅——花在窗前，窗在家中，家在乡里，一枝寒梅牵起整个故乡。不问父母而问花，情之深、语之妙俱到极处。此诗与《相思》并为王维五绝双璧。"},"228":{"ti":"裴迪送崔九归山。莫学武陵人，暂游桃源里——劝友真隐，不作泛泛惜别。","zhu":[{"w":"崔九","v":"崔兴宗，王维内弟，与裴迪善。"},{"w":"丘壑","v":"山丘沟壑，指山水。"},{"w":"武陵人","v":"陶渊明《桃花源记》中误入桃源的武陵渔人。"}],"yi":"归山无论深浅，都要尽赏丘壑之美。莫学武陵人那样，只在桃源暂游一回。","shang":"送归隐之友，不言珍重而言「须尽丘壑美」——以全幅生命付与山水，方是真隐。以桃源作反衬，「暂游」二字最见分寸：游即归心未死。裴迪存诗不多，此首足传。"},"229":{"ti":"祖咏应试《终南望余雪》。四句即止，意尽而不续——「意尽」二字为此诗本色，遂成科举史上最著名的「违规」。","zhu":[{"w":"阴岭","v":"山的北面。终南在长安之南，自城望之见其阴岭。"},{"w":"积雪浮云端","v":"山高雪明，似浮于云端。"},{"w":"林表","v":"林梢。"},{"w":"霁色","v":"雪后初晴的日光。"},{"w":"暮寒","v":"傍晚的寒气。"}],"yi":"终南山北岭秀丽，积雪像浮在云端。林梢分明透着霁色，城中增添了傍晚的寒意。","shang":"「积雪浮云端」一「浮」字，山之高、雪之明俱出。结句由「霁色」转「暮寒」，雪霁而寒反增，物理之中含世态之理。应试诗例须六韵十二句，祖咏四句掷笔曰「意尽」，此四句遂胜万人。"},"230":{"ti":"孟浩然宿建德江。野旷天低树，江清月近人——一「低」一「近」，把客愁写成一幅画。","zhu":[{"w":"建德江","v":"新安江流经建德（今浙江）一段。"},{"w":"烟渚","v":"雾气笼罩的小洲。"},{"w":"客愁新","v":"客居之愁又添新绪。"},{"w":"旷","v":"空阔。"},{"w":"月近人","v":"水中月影近人，似可相亲。"}],"yi":"移船泊在烟水小洲，日暮时分客愁又新。原野空旷，天比树还低；江水清澈，月与人相亲。","shang":"「野旷天低树」写旷，「江清月近人」写清——天地愈大，人愈孤；惟月可亲，人愈可哀。十字之内有画有情，唐人五绝写羁旅，此为极则。"},"231":{"ti":"孟浩然春晓。夜来风雨声，花落知多少？——不写所见而写所闻所想，春眠之适与惜花之念两相成。","zhu":[{"w":"春眠不觉晓","v":"春夜酣睡，天亮不觉。"},{"w":"闻啼鸟","v":"醒来闻鸟鸣。"},{"w":"知多少","v":"不知落了多少（花）。"}],"yi":"春夜里酣睡不觉天亮，处处听得啼鸟。想起夜来的风雨声，落下的花不知有多少？","shang":"全篇无一字雕琢，如儿歌之自然，而「花落知多少」一问，把春光之惜、流年之念都收进这轻轻一问里。此诗妇孺能诵而诗家不能仿，是为天籁。"},"232":{"ti":"李白静夜思。举头望明月，低头思故乡——一仰一俯之间，乡愁已成中国人共同的月光。","zhu":[{"w":"疑是地上霜","v":"月色皎洁，疑为秋霜。"},{"w":"床","v":"坐卧之具，一说井栏。"},{"w":"思故乡","v":"望月而生乡思。"}],"yi":"床前一片明月光，疑是地上铺了霜。抬起头来望明月，低下头去思故乡。","shang":"二十个字，无一僻字，无一典故，一疑、一望、一低——三个动作把客子的失眠与乡愁写尽。「霜」字最妙：月色之冷与心境之寒相叠。此诗为汉语中最广为人知的二十个字。"},"233":{"ti":"李白怨情。美人卷帘、深坐颦眉，但见泪痕、不知恨谁——不写怨而怨自深。","zhu":[{"w":"卷珠帘","v":"卷起珠帘望外。"},{"w":"深坐","v":"久久呆坐。"},{"w":"蹙蛾眉","v":"皱着眉。蹙，皱。"}],"yi":"美人卷起珠帘，深坐蹙着蛾眉。只见泪痕湿了，不知心里恨的是谁？","shang":"「不知心恨谁」妙在连恨的对象也不肯说出——恨之深而情之专，尽在这份不可说里。二十字如一幅仕女图，画中人永远是背影。太白写闺情，语极浅而意极曲。"},"234":{"ti":"杜甫咏八阵图。江流石不转——江水东逝而阵石不移，一块石头上压着一段兴亡。","zhu":[{"w":"八阵图","v":"诸葛亮所创军阵，遗址在夔州西南江滩。"},{"w":"三分国","v":"魏蜀吴三分天下。"},{"w":"石不转","v":"八阵图石堆江水冲激屹然不动。"},{"w":"失吞吴","v":"刘备伐吴失策，八阵之设乃为防吴，吞吴之志终成遗恨。"}],"yi":"功盖三分之国，名成八阵之图。江水奔流，阵石不转——遗恨的，是那场吞吴。","shang":"「江流石不转」五字兼写自然与人事：水奔流是时势，石不转是忠魂。结「遗恨失吞吴」四字，史论与诗情相合，二十字内把诸葛的一生与遗憾说尽。五绝而有千钧之力。"},"235":{"ti":"王之涣登鹳雀楼。欲穷千里目，更上一层楼——一联理趣，唐人进取精神的写照。","zhu":[{"w":"鹳雀楼","v":"蒲州（今山西永济）城楼，三层，前瞻中条山，下瞰黄河。"},{"w":"依山尽","v":"傍着中条山沉落。"},{"w":"穷","v":"尽。"}],"yi":"白日傍着山落尽，黄河向大海奔流。想穷尽千里的视野，就要再上一层楼。","shang":"前二句对仗天成——山与海、落日与奔河，一幅万里山河图；后二句翻出哲理：登高方能望远，欲望须再登。二十字之内景、情、理三绝，遂成唐五绝第一。"},"236":{"ti":"刘长卿送灵澈上人。荷笠带斜阳，青山独归远——送者目送，归者渐远，一幅水墨。","zhu":[{"w":"灵澈","v":"中唐诗僧。"},{"w":"竹林寺","v":"润州（今镇江）寺院，灵澈游方挂锡处。"},{"w":"杳杳","v":"深远的样子。"},{"w":"荷笠","v":"背着斗笠。"}],"yi":"苍苍竹林里的寺院，杳杳传来晚钟。你背着斗笠带着斜阳，独自归向远处的青山。","shang":"「荷笠带斜阳」——斜阳在笠上，人在画中；「青山独归远」——一个「独」字，僧之清与送者之情合而为一。全篇如水墨小品，声音（钟）与色彩（斜阳青山）俱在，五绝中罕见的画境。"},"237":{"ti":"刘长卿听弹琴。古调虽自爱，今人多不弹——琴语之外，尽是知音之叹。","zhu":[{"w":"泠泠","v":"琴声清越。"},{"w":"七弦","v":"古琴七弦。"},{"w":"松风寒","v":"琴曲有《风入松》，兼指琴声如松风之清冷。"}],"yi":"泠泠七弦之上，静听松风的清寒。古调虽然自爱，今人已多不弹。","shang":"「古调虽自爱，今人多不弹」——自爱而不能人爱，孤高者的寂寞只在这淡淡两句里。借琴喻志，一字不涉牢骚而牢骚自见。刘长卿「五言长城」的冷峻本色，此篇最纯。"},"238":{"ti":"刘长卿送上人归山。莫买沃洲山，时人已知处——讥时人以隐居为终南捷径，劝僧人真隐。","zhu":[{"w":"上人","v":"对僧人的尊称。"},{"w":"将","v":"与、共。"},{"w":"沃洲山","v":"在今浙江新昌，名僧支遁曾居，唐代名胜。"},{"w":"已知处","v":"已被世人所知，喧于俗世。"}],"yi":"孤云与野鹤相伴，岂肯向人间居住！莫去买那沃洲山——时人早知道了那处名胜。","shang":"「孤云将野鹤」五字画出僧人孤高出尘之姿；「莫买沃洲山」翻出冷眼——名山成热闹处，隐亦须逃名。全篇先赞后讽，规劝之意极深而不失风趣，唐人送僧诗之最警策者。"},"239":{"ti":"韦应物秋夜寄丘员外。空山松子落，幽人应未眠——两地之思凭想象一线牵通，遂为怀人诗的神品。","zhu":[{"w":"丘员外","v":"丘丹，隐居临平山，韦应物挚友。"},{"w":"属","v":"正值。"},{"w":"凉天","v":"秋天凉爽的天气。"},{"w":"幽人","v":"隐士，指丘丹。"}],"yi":"怀念你，正是这秋夜，我散步吟咏在这凉天。空山里松子该落了——幽居的你，想必也未眠。","shang":"前二句写我、后二句写你，而「松子落」是想象中临平山的秋声，一念之通，千里俱近。施补华叹其「清幽不减摩诘」。不着一字愁而怀人之深见于天籁。"},"240":{"ti":"李端听筝。欲得周郎顾，时时误拂弦——故意错弹以求一顾，女儿家的心思全在一「误」字。","zhu":[{"w":"金粟柱","v":"筝上系弦的柱，饰金粟纹。"},{"w":"素手","v":"弹筝女白皙的手。"},{"w":"周郎顾","v":"周瑜精音律，曲有误必回顾，故谣曰「曲有误，周郎顾」。"},{"w":"误拂弦","v":"故意弹错，引人回顾。"}],"yi":"鸣筝的金粟弦柱，素手在玉房之前。想得那周郎一顾，时时故意拂错琴弦。","shang":"「欲得」「时时」四字，把小女儿的心机写尽——错不在技而在心。以周郎顾曲之典写少女的娇黠，二十字如一幕小剧，人物声态并作。唐人绝句写情之巧，此为第一。"},"241":{"ti":"王建新嫁娘词。未谙姑食性，先遣小姑尝——新妇的机敏在三日之后的一碗羹汤里。","zhu":[{"w":"三日入厨","v":"古俗新妇婚后三日下厨。"},{"w":"谙","v":"熟悉。"},{"w":"姑","v":"婆母。"},{"w":"小姑","v":"丈夫的妹妹。"}],"yi":"三日进到厨下，洗手去作羹汤。还不熟悉婆婆的口味，先请小姑来尝一尝。","shang":"「洗手」二字极细——郑重其事也；「先遣小姑尝」更细——小姑是惟一知味又是同辈之人。二十字之内，一个新妇的小心与聪明跃然纸上。白描如话，是乐府「新嫁娘」题材的极致。"},"242":{"ti":"权德舆玉台体。昨夜裙带解，今朝蟢子飞——俗谚两应，皆主远人归来，喜而出俚语。","zhu":[{"w":"玉台体","v":"仿南朝《玉台新咏》艳体的闺情诗。"},{"w":"裙带解","v":"俗谓裙带自解主丈夫归。"},{"w":"蟢子","v":"蜘蛛。俗谓蟢子聚集主有喜。"},{"w":"铅华","v":"脂粉。"},{"w":"藁砧","v":"古乐府隐语，指丈夫。"}],"yi":"昨夜裙带自己解开，今朝蟢子又在飞。脂粉不可荒废——莫不是丈夫要归？","shang":"以两条俗谚的巧合写思妇的轻喜，痴态可掬。「铅华不可弃」——为了可能的归人而盛妆，一字一句皆是盼。民歌俚语入诗而不失其雅，唐人绝句的谐趣一格。"},"243":{"ti":"柳宗元江雪。千山鸟飞绝，万径人踪灭——天地俱寂之后，一舟一翁独钓寒江，是柳贬谪后精神的画像。","zhu":[{"w":"绝","v":"绝迹。"},{"w":"万径","v":"万条小路。"},{"w":"人踪","v":"人的足迹。"},{"w":"蓑笠","v":"蓑衣与斗笠。"}],"yi":"千山里鸟飞绝迹，万径上人踪灭尽。孤舟上一蓑笠老翁，独自钓着寒江的雪。","shang":"「千山」「万径」之后忽然一舟一翁，孤至极而静至极；「钓寒江雪」——钓的哪里是鱼，是天地间的清寒与自己。苏轼谓柳诗「忧中有乐」，此篇孤绝处正是倔强处，为五绝压卷之一。"},"244":{"ti":"元稹行宫。白头宫女在，闲坐说玄宗——盛世的余烬，全在这「闲坐」二字里。","zhu":[{"w":"行宫","v":"皇帝出行时居住的宫殿，此指洛阳上阳宫。"},{"w":"寥落","v":"冷落。"},{"w":"玄宗","v":"唐明皇。"}],"yi":"冷落的古旧行宫，宫花寂寞地红。白头的宫女还在，闲坐着说起玄宗。","shang":"「寥落」「寂寞」「白头」三重冷色之后，忽接「闲坐说玄宗」——说的人已老，说的事已远，一个「闲」字，几十年的青春都成闲话。二十字之内盛衰兴亡俱全，前人推为五绝中的《连昌宫词》。"},"245":{"ti":"白居易问刘十九。晚来天欲雪，能饮一杯无？——雪前的一杯酒之约，是中国诗里最暖的邀请。","zhu":[{"w":"刘十九","v":"白居易嵩阳处士友人，排行十九。"},{"w":"绿蚁","v":"新酿米酒上的浮沫，微绿如蚁。"},{"w":"醅","v":"未滤的酒。"},{"w":"无","v":"疑问语气词，么。"}],"yi":"绿蚁浮沫的新醅酒，红泥砌的小火炉。晚来天色将要下雪——能来喝一杯么？","shang":"「绿蚁」对「红泥」、「新醅酒」对「小火炉」，颜色与温度俱暖；「天欲雪」三字把寒冬变成邀约的理由。结句「能饮一杯无」，口语作结，亲切如面谈。二十字内有一炉火、一场雪、一个朋友——唐诗中的冬夜之暖。"},"246":{"ti":"张祜何满子。一声何满子，双泪落君前——三千里、二十年、一声、双泪，数字层层压下，泪终于一声之中。","zhu":[{"w":"故国","v":"故乡（一作「故国三千里」言离家之远）。"},{"w":"深宫二十年","v":"入宫之久。"},{"w":"何满子","v":"哀乐曲名。沧州歌者何满子临刑进此曲，声哀。"}],"yi":"离故国三千里，在深宫二十年。一声何满子的哀歌，双泪落在君王面前。","shang":"「三千里」「二十年」言空间与时间之隔，「一声」「双泪」言触发之速——四个数字，把宫女的积怨压缩在一声歌里。杜牧叹「可怜铜雀台」，非此诗不能传宫怨之痛。"},"247":{"ti":"李商隐登乐游原。夕阳无限好，只是近黄昏——十字之中有赏爱、有怅惘，遂成千古晚景之叹。","zhu":[{"w":"乐游原","v":"长安东南地势最高的游赏地，可俯瞰全城。"},{"w":"向晚","v":"傍晚。"},{"w":"意不适","v":"心里不畅快。"},{"w":"古原","v":"乐游原。"}],"yi":"傍晚时分意绪不适，驱车登上古原。夕阳无限的美好，只是已近黄昏。","shang":"「无限好」与「近黄昏」之间只隔一个「只是」——美好与消逝是同一事物，故纪昀叹其「百感茫茫，一时交集」。义山晚岁之作，既是对夕阳的赞叹，也是对自己一生迟暮的预感。二十字而有千钧。"},"248":{"ti":"贾岛寻隐者不遇。只在此山中，云深不知处——问而有答、答而无果，寻隐者的怅惘全在一片云里。","zhu":[{"w":"言","v":"童子答道。"},{"w":"云深","v":"山高云浓。"},{"w":"不知处","v":"不知道具体所在。"}],"yi":"松下问那童子，说师父采药去了。就在这座山中——云深，不知何处。","shang":"全篇以问答成章：问者急、答者闲。「云深不知处」既是实境又是隐者品格——可望而不可即。二十字之内有松、云、药、童，一派山间清气，而访者的怅惘尽在不言中。贾岛「推敲」之外，更有此等天成。"},"249":{"ti":"李频渡汉江。近乡情更怯，不敢问来人——「怯」字写尽久客还乡的复杂心情，为乡情诗第一名句。","zhu":[{"w":"岭外","v":"岭南，作者贬所。"},{"w":"音书绝","v":"家信断绝。"},{"w":"经冬复立春","v":"冬天过完又是春天，言日久。"},{"w":"来人","v":"从家乡方向来的人。"}],"yi":"岭外的音书断绝，经过了冬天又到立春。近乡情更胆怯——不敢问那来人。","shang":"情理之中是「近乡情更切」，诗人偏偏写「怯」——怕的是家中变故不敢听闻。一字之翻，写出天涯归人最真实的一瞬。宋之问同题名句之外，此篇别有沉痛。"},"250":{"ti":"金昌绪春怨。打起黄莺儿——莫教惊了梦，梦要飞到辽西。痴语之中是万里征戍之痛。","zhu":[{"w":"打起","v":"赶走。"},{"w":"莫教","v":"不让。"},{"w":"辽西","v":"唐东北边塞，征夫戍地。"}],"yi":"赶走那黄莺儿，别让它在枝上啼。它的啼声惊了我的梦——梦里正去辽西。","shang":"「打起黄莺儿」起得无理，第三句揭出原委——原来莺惊的是梦，梦到的是辽西。层层倒折，一气说破，把征妇之怨写成了只有梦里才可见面的痴情。存诗一首而名垂千古。"},"251":{"ti":"西鄙人哥舒歌。北斗七星高，哥舒夜带刀——以星喻人，胡人畏哥舒翰如畏北斗。","zhu":[{"w":"哥舒","v":"哥舒翰，突厥族名将，守陇右，吐蕃畏之。"},{"w":"窥牧马","v":"吐蕃牧马窥伺边地。"},{"w":"临洮","v":"今甘肃岷县，唐西陲要地。"}],"yi":"北斗七星高高，哥舒翰夜里带刀。至今那些窥伺的牧马，不敢越过临洮。","shang":"「北斗七星高」起得奇——以天象起兴，人在斗下，威严自见；「夜带刀」三字英气逼人。此为西部边地民歌，质朴无文而气概自雄，「至今」「不敢」见其威久在。唐人边塞五绝，以此篇最见民歌本色。"},"252":{"ti":"崔颢长干行其一。停船暂借问，或恐是同乡——一问之后又自寻退路，女儿家的聪慧与羞涩并见。","zhu":[{"w":"长干","v":"金陵里巷名，长干里。"},{"w":"横塘","v":"金陵堤名，在秦淮河南岸。"},{"w":"借问","v":"请问。"},{"w":"或恐","v":"也许、莫不是。"}],"yi":"你家住在哪里？我住在横塘。停船暂且借问一声——或许咱们是同乡。","shang":"「妾住在横塘」——不等对方回答先自报名里，急切之态可掬；「或恐」二字又把唐突掩饰过去。四句如口角 scene，声音笑貌都在纸上。乐府民歌的白描，唐人五绝之最活泼者。"},"253":{"ti":"崔颢长干行其二。同是长干人，生小不相识——一答一叹，初见之喜化为相识之憾。","zhu":[{"w":"九江","v":"泛指长江下游水系。"},{"w":"长干人","v":"长干里的同乡。"},{"w":"生小","v":"自小。"}],"yi":"家临着九江的水，来来去去在九江侧。同是长干里的人，自小却不相识。","shang":"承前首作答：同乡之「恐」一语成真，随即生出「生小不相识」的怅憾——喜与憾只隔一句。两首合观，一问一答之间一段乡情悄然萌生，江南水上的萍水之缘如画。"},"254":{"ti":"李白玉阶怨。却下水晶帘，玲珑望秋月——帘已下而月犹望，怨之深在望之痴。","zhu":[{"w":"玉阶","v":"玉石台阶。"},{"w":"罗袜","v":"丝罗袜，言其人久立，露湿罗袜。"},{"w":"却下","v":"退回放下。"},{"w":"水晶帘","v":"水晶珠帘。"},{"w":"玲珑","v":"隔帘望月，月影玲珑。"}],"yi":"玉阶上生了白露，夜久露水浸湿罗袜。退回屋里放下水晶帘，隔帘还望那玲珑的秋月。","shang":"「夜久侵罗袜」——久到露湿，不言立之久而自见；「却下」二字最妙——下帘是厌月，隔帘望月是舍不得月，一字一转，怨意愈折愈深。李白宫怨，二十字无一「怨」字而怨彻骨。"},"255":{"ti":"卢纶塞下曲其一。独立扬新令，千营共一呼——一声号令、万人齐应，写军容先声夺人。","zhu":[{"w":"鹫翎","v":"雕翎。"},{"w":"金仆姑","v":"箭名。"},{"w":"燕尾","v":"旗上燕尾状飘带。"},{"w":"蝥弧","v":"郑国旗名，泛指军旗。"},{"w":"独立","v":"将军独立阵前。"},{"w":"扬新令","v":"发布新命令。"}],"yi":"雕翎的金仆姑箭，燕尾的绣蝥弧旗。将军独立阵前发布新令——千营齐声一呼！","shang":"起手以箭、旗两种器物写将军之威，不着一句形容；「独立」对「千营」——一人与万众，力与势全在此对仗中。二十字如闻鼓角，唐人军旅诗先声之作。"},"256":{"ti":"卢纶塞下曲其二。平明寻白羽，没在石棱中——箭入石棱，用李广射虎典，将军之神力与夜之惊险俱见。","zhu":[{"w":"草惊风","v":"草被风吹动，疑有虎。"},{"w":"引弓","v":"拉弓。"},{"w":"平明","v":"天刚亮。"},{"w":"白羽","v":"箭尾羽毛，代指箭。"},{"w":"石棱","v":"石头的棱角处。"}],"yi":"林暗处草被风惊动，将军夜里拉弓。天亮寻那白羽箭——深深没进石棱之中！","shang":"「林暗草惊风」五字伏一夜之紧张；「没在石棱中」揭出结果——非人力所能及，而将军以为虎而射，神力与误认俱妙。用李广事而再造其境，二十字有小说之趣。"},"257":{"ti":"卢纶塞下曲其三。欲将轻骑逐，大雪满弓刀——追敌未发，大雪先至，一瞬的静写千军的动。","zhu":[{"w":"单于","v":"匈奴首领，指敌酋。"},{"w":"遁逃","v":"逃跑。"},{"w":"轻骑","v":"轻装的骑兵。"}],"yi":"月黑之夜雁飞得高，单于趁夜遁逃。正要带轻骑去追——大雪落满了弓刀。","shang":"「月黑雁飞高」——连雁都惊起，敌逃之状先声写出；「大雪满弓刀」以景截住「欲逐」，追与不追俱在言外，满纸肃杀。二十字无一字言战而战意凛然，故为塞下曲第一名。"},"258":{"ti":"卢纶塞下曲其四。醉和金甲舞，雷鼓动山川——凯旋之宴，醉舞而甲不解，写尽唐军的豪气。","zhu":[{"w":"野幕","v":"野外帐篷。"},{"w":"蔽琼筵","v":"设下华美筵席。"},{"w":"羌戎","v":"边疆少数民族。"},{"w":"贺劳旋","v":"庆贺慰劳凯旋。"},{"w":"雷鼓","v":"擂鼓。雷，通「擂」。"}],"yi":"野帐下摆开琼筵，羌戎各族来贺劳凯旋。醉了还和着金甲起舞——擂鼓声震动山川！","shang":"「醉和金甲舞」五字有酒气、有甲光、有舞姿，是唐军豪情的定格；「雷鼓动山川」以动山川收束，庆功之乐与军威之壮合一。四首塞下曲连读：令、猎、追、宴，一部边塞小史诗。"},"259":{"ti":"李益江南曲。早知潮有信，嫁与弄潮儿——怨极之语翻出奇想，商妇之怨遂有了人间温度。","zhu":[{"w":"江南曲","v":"乐府旧题。"},{"w":"瞿塘贾","v":"出入瞿塘峡的商人。贾，商。"},{"w":"潮有信","v":"潮水涨落有时，最讲信用。"},{"w":"弄潮儿","v":"钱塘江上迎潮戏水的少年。"}],"yi":"嫁了个瞿塘商人，天天误了我的期。早知潮水有信——不如嫁给那弄潮儿！","shang":"「早知潮有信」——怨商人之无信，竟及于潮水；「嫁与弄潮儿」——痴语愈无理，愈见其怨之深、情之真。贺裳评其「无理而妙」。以乐府白话作结，唐人商妇诗之最鲜活者。"},"260":{"ti":"贺知章八十六岁告老还乡，乡里儿童不识而笑问。少小离家老大回——五十年的岁月在「笑问」一语中翻涌。","zhu":[{"w":"偶书","v":"随意写成。"},{"w":"老大","v":"年岁已老。"},{"w":"鬓毛衰","v":"鬓发疏落变白。衰，稀疏之意。"},{"w":"笑问","v":"天真发问。"}],"yi":"少小时离家，老了才回来，乡音未改而鬓发已衰。儿童们见了不认识，笑着问：客人从哪里来？","shang":"「乡音无改」与「鬓毛衰」对举——改不了的与改了的，都写在一个回乡人身上。儿童「笑问」一句，天真之极而沉痛之极：他乡作客数十年的身份，竟由一个孩子一语点破。全篇无一感慨字而感慨至深。"},"261":{"ti":"张旭桃花溪问渔船。桃花尽日随流水，洞在清溪何处边？——以桃花源之问写溪山之幽，草圣的闲逸。","zhu":[{"w":"桃花溪","v":"在今湖南桃源（一说在浙江天台山）。"},{"w":"飞桥","v":"高桥。"},{"w":"石矶","v":"水边突出的岩石。"},{"w":"尽日","v":"整日。"}],"yi":"隐隐的高桥隔着野烟，石矶西畔问那渔船。桃花整日随着流水——桃源洞口在清溪哪一边？","shang":"「隐隐飞桥隔野烟」写远景如仙气缥缈；结句问渔船「洞在何处」，明知武陵故事不可寻而偏要问，问出满纸向往。草圣之诗如其草书，纵逸而有仙气。"},"262":{"ti":"王维十七岁重阳忆山东兄弟。独在异乡为异客——两个「异」字，把游子的孤独写到了骨头里。","zhu":[{"w":"山东","v":"华山以东，指蒲州（今永济），王维家乡。"},{"w":"佳节","v":"重阳节。"},{"w":"登高","v":"重阳登高避灾之俗。"},{"w":"茱萸","v":"香草，重阳日插茱萸辟邪。"},{"w":"少一人","v":"独缺我一人。"}],"yi":"独自在异乡做异客，每逢佳节加倍思亲。遥想兄弟们登高的地方，遍插茱萸——正少我一人。","shang":"「独」「异」「异」三字层层加重客居之孤；「倍思亲」之「倍」，人人心中有而人人笔下无。结句不写己之思，反写兄弟「少一人」——从对面落笔，倍增其情。此诗遂成天下游子佳节之共语。"},"263":{"ti":"王昌龄芙蓉楼送辛渐。洛阳亲友如相问，一片冰心在玉壶——以玉壶冰心明志，送别诗中最高洁的告白。","zhu":[{"w":"芙蓉楼","v":"润州（今镇江）城楼。"},{"w":"辛渐","v":"诗人友人，将北上洛阳。"},{"w":"寒雨连江","v":"秋雨弥漫江面。"},{"w":"平明","v":"天刚亮。"},{"w":"冰心","v":"如冰之心，喻高洁清白。"},{"w":"玉壶","v":"玉制之壶，喻清白之境。鲍照「清如玉壶冰」。"}],"yi":"寒雨连江，夜里进入吴地；平明送客，楚山显得孤单。洛阳亲友如果相问——就说我的心，一片冰在玉壶。","shang":"「寒雨」「楚山孤」写尽离情，结句忽然自明心迹——冰心玉壶，是抵御洛阳风言的清白之誓。送别诗到此，已非惜别而是托付。唐人七绝的高格，此为标尺之一。"},"264":{"ti":"王昌龄闺怨。忽见陌头杨柳色，悔教夫婿觅封侯——一个「忽」字，把人间最深的悔写活了。","zhu":[{"w":"凝妆","v":"盛妆。"},{"w":"翠楼","v":"华美的楼。"},{"w":"陌头","v":"路边。"},{"w":"杨柳色","v":"柳色青青，勾起春情。"},{"w":"觅封侯","v":"从军建功求封赏。"}],"yi":"闺中少妇本不知愁，春日里盛妆登上翠楼。忽然看见路边的杨柳色——悔教夫婿去觅封侯！","shang":"「不知愁」起、以「悔」字收，中间只隔一「忽见」——盛妆登楼是春兴，杨柳一色春愁顿生。全篇的心理转折只在一瞬，却把「功名」与「相守」的人间大选题轻轻放在了一个少妇眼前。七绝圣手，当之无愧。"},"265":{"ti":"王昌龄春宫曲。平阳歌舞新承宠——借汉武帝宠卫子夫事，写新人得宠、旧人失宠，一片冷眼。","zhu":[{"w":"露井桃","v":"无盖之井旁的桃树。"},{"w":"未央","v":"汉宫名。"},{"w":"平阳歌舞","v":"汉武帝卫子夫本平阳公主家歌女，因歌得宠。"},{"w":"赐锦袍","v":"新宠沐恩之状。"}],"yi":"昨夜风开了露井边的桃花，未央前殿月轮正高。平阳家的歌女新承恩宠——帘外春寒，赐下了锦袍。","shang":"全篇纯是客观镜头：桃花、月轮、新宠、锦袍——没有一个旧人出场，而旧人的失宠与寒心已浸透纸背。借汉写唐，含蓄之极。沈德潜谓其「极言得宠者之幸，而失宠者可想」。"},"266":{"ti":"李白黄鹤楼送孟浩然之广陵。孤帆远影碧空尽，惟见长江天际流——望着望着，人成了帆，帆成了江。","zhu":[{"w":"之广陵","v":"去扬州。广陵，扬州。"},{"w":"西辞","v":"黄鹤楼在西，扬州在东，故曰西辞。"},{"w":"烟花三月","v":"柳絮如烟、繁花似锦的暮春三月。"}],"yi":"故人辞别西边的黄鹤楼，烟花三月顺流下扬州。孤帆的远影在碧空尽头消失——只看见长江向天边流。","shang":"「孤帆远影碧空尽」是望的时间——直到帆影消失；「惟见长江天际流」是望的结果——人不见了，只剩江水。不写离情而离情与江水同流不尽。李白眼中，连送别都是壮阔的。"},"267":{"ti":"李白早发白帝城。千里江陵一日还——遇赦东归的轻快，两岸猿声都追不上轻舟。","zhu":[{"w":"白帝","v":"白帝城，在今重庆奉节，地势极高。"},{"w":"江陵","v":"今湖北荆州，距白帝千里。"},{"w":"还","v":"返回（李白流放夜郎途中遇赦）。"}],"yi":"清晨辞别彩云间的白帝城，千里外的江陵一日就能归还。两岸猿声啼个不住——轻舟已过了万重山。","shang":"「彩云间」写白帝之高，「一日还」写归程之疾；结句「轻舟已过万重山」，船轻是心情轻，山重是往事重。杨慎叹其「惊风雨而泣鬼神」。遇赦之喜与三峡之险，全化作一叶轻舟。"},"268":{"ti":"岑参逢入京使。马上相逢无纸笔，凭君传语报平安——西行万里，家书只剩一句口信。","zhu":[{"w":"入京使","v":"回长安的使者。"},{"w":"故园","v":"长安。"},{"w":"龙钟","v":"泪流纵横的样子。"},{"w":"凭","v":"托。"}],"yi":"向东遥望故园，路途漫漫；双袖龙钟，泪擦不干。马上相逢没有纸笔——托你捎话：报个平安。","shang":"「双袖龙钟泪不干」——泪之多以袖写之；「无纸笔」三个字最见行色匆匆。平安二字值万金，只是连写它的纸笔都无。岑参西行诗，家国之思都化作最朴素的托付。"},"269":{"ti":"杜甫江南逢李龟年。落花时节又逢君——岐王宅里的盛景与江南流落的人，都压在这一句里。","zhu":[{"w":"李龟年","v":"开元名歌手，深受玄宗恩遇，安史乱后流落江南。"},{"w":"岐王","v":"玄宗弟李范，好文。"},{"w":"崔九","v":"崔涤，玄宗宠臣。"},{"w":"落花时节","v":"暮春，兼喻国势与两人身世之衰。"}],"yi":"岐王宅里常常见到您，崔九堂前几度听您歌。正是江南风景好的时候——落花时节，又逢君。","shang":"前二句是开元盛世的名士风流，后二句是乱后江南的落花流水——四十年的盛衰，只用一个「又」字轻轻缝合。无一句言悲而悲不可胜，故为杜七绝之冠。"},"270":{"ti":"韦应物滁州西涧。春潮带雨晚来急，野渡无人舟自横——无人处的自横，是闲适也是寂寞。","zhu":[{"w":"滁州","v":"今安徽滁州，韦应物任刺史。"},{"w":"西涧","v":"滁州城西野涧。"},{"w":"独怜","v":"偏爱。"},{"w":"幽草","v":"幽谷的草。"},{"w":"深树","v":"枝叶茂密的树。"},{"w":"野渡","v":"荒僻的渡口。"}],"yi":"独爱幽草在涧边生长，上头有黄鹂在深树里鸣。春潮带着晚雨来得很急——野渡无人，小舟自横。","shang":"「独怜幽草」是诗人的自况——不与花争而自甘幽寂；「舟自横」是全篇之眼：潮急人无，舟不逐浪亦不系岸，自在即是禅意。此诗写于滁州，闲淡之中自有怀抱。"},"271":{"ti":"张继枫桥夜泊。夜半钟声到客船——科场失意的一夜失眠，成就了汉语里最著名的钟声。","zhu":[{"w":"枫桥","v":"在今苏州城外。"},{"w":"江枫","v":"江边枫树。"},{"w":"渔火","v":"渔船灯火。"},{"w":"姑苏","v":"苏州。"},{"w":"寒山寺","v":"枫桥附近名刹，相传寒山、拾得曾居。"}],"yi":"月落了，乌啼着，霜满天；江枫渔火，对着我这愁眠。姑苏城外的寒山寺——夜半的钟声到了客船。","shang":"「月落乌啼霜满天」三重声响与颜色先声夺人；「对愁眠」——愁的是人不眠，火与枫作陪。结句钟声「到」客船，一「到」字使钟声有了行程与重量。欧阳修疑夜半无钟，而江南实有夜半钟——诗境自可高于考据。此诗遂使寒山寺名传千年。"},"272":{"ti":"韩翃寒食。轻烟散入五侯家——太平春景之下，一点宦官得宠的讽意，深藏不露。","zhu":[{"w":"寒食","v":"清明前一二日，禁火冷食，纪念介子推。"},{"w":"春城","v":"春天的长安。"},{"w":"御柳","v":"皇城中的柳。"},{"w":"传蜡烛","v":"寒食禁火，唯宫中赐近臣蜡烛之火。"},{"w":"五侯","v":"汉成帝同日封王谭等五人为侯；此借指唐肃宗以来宦官权贵。"}],"yi":"春城无处不飞花，寒食的东风吹斜了御柳。日暮汉宫传赐蜡烛——轻烟散进了五侯之家。","shang":"「无处不飞花」写尽长安春色，得唐德宗激赏，韩翃因此复官。后二句只写赐火一幕，「五侯」二字轻轻一点，讽刺之意全在画外。含蓄到几乎不见，正是唐人讽喻的高品。"},"273":{"ti":"刘方平月夜。今夜偏知春气暖，虫声新透绿窗纱——深夜的虫声里，第一个报春的不是花，是耳朵。","zhu":[{"w":"更深","v":"夜深。"},{"w":"半人家","v":"月光斜照，半照楼阁半照地。"},{"w":"阑干","v":"横斜的样子。"},{"w":"偏知","v":"才感知。"},{"w":"新透","v":"初次透过。"}],"yi":"夜深了，月色斜照半个人家，北斗横斜、南斗也斜。今夜才感知春气已暖——虫声新透绿窗纱。","shang":"「北斗阑干南斗斜」以双星写夜之深；「偏知」之「偏」与「新透」之「新」——春暖是今夜的第一讯息，虫声是新绿的第一批信使。宋人称此诗「写物候天工，不涉理路」。唐人咏春夜，此为最敏锐的一首。"},"274":{"ti":"刘方平春怨。寂寞空庭春欲晚，梨花满地不开门——门不开，春就永远关在里面。","zhu":[{"w":"金屋","v":"汉武帝金屋藏娇事，借指宫中。"},{"w":"春欲晚","v":"春天将尽。"},{"w":"梨花满地","v":"梨花落尽，春将归去。"}],"yi":"纱窗日落渐渐黄昏，金屋里无人看见泪痕。寂寞空庭春将晚——梨花满地，也不开门。","shang":"「金屋无人见泪痕」——金屋是恩宠的许诺，「无人见」是许诺的破产。结句「不开门」三字：门外是落尽的春，门内是无人见的人，她把自己也锁进了春天。写宫怨全用 Silent 手法，愈静愈痛。"},"275":{"ti":"柳中庸征人怨。岁岁金河复玉关，朝朝马策与刀环——岁岁朝朝，把征人的时间写成了循环的地名与兵器。","zhu":[{"w":"金河","v":"黑河，在今内蒙古，唐单于都护府地。"},{"w":"玉关","v":"玉门关。"},{"w":"马策","v":"马鞭。"},{"w":"刀环","v":"刀柄环。「还」之谐音，隐思归。"},{"w":"青冢","v":"昭君墓。"},{"w":"黑山","v":"今内蒙古境内。"}],"yi":"岁岁是金河又是玉关，朝朝是马策与刀环。三春的白雪归了青冢，万里的黄河绕着黑山。","shang":"「岁岁」「朝朝」叠字开篇，时间被戍边凝固成循环；「马策」「刀环」以器物代生活，一「环」字暗含「还」音，怨在谐音里。后二句以青冢、黄河、黑山三地名铺成万里图画——景愈壮，人愈苦。唐人边塞七绝的工整之作。"},"276":{"ti":"顾况宫词。月殿影开闻夜漏，水晶帘卷近秋河——宫楼高近星河，人却远隔君侧。","zhu":[{"w":"玉楼","v":"华美的宫楼。"},{"w":"天半","v":"半天高处。"},{"w":"宫嫔","v":"宫女嫔妃。"},{"w":"月殿","v":"月光下的殿堂。"},{"w":"夜漏","v":"夜间的更漏。"},{"w":"秋河","v":"银河。"}],"yi":"玉楼在半天高处起笙歌，风送着宫嫔的笑语。月殿的影子分开，听得夜漏——水晶帘卷起，仿佛离银河很近。","shang":"「近秋河」三字——楼近星河而人远君王，天上人间只是一道帘的距离。笙歌笑语是别人的，夜漏是自己的。全篇不着「怨」字，只写一层帘、一条河，怨已无边。"},"277":{"ti":"李益夜上受降城闻笛。一夜征人尽望乡——一个「尽」字，万人的乡愁同一夜。","zhu":[{"w":"受降城","v":"唐灵州受降城，在今内蒙古。"},{"w":"回乐峰","v":"回乐县（今宁夏灵武）的山峰。"},{"w":"芦管","v":"芦笛。"}],"yi":"回乐峰前的沙像雪，受降城外的月如霜。不知何处吹起芦管——一夜之间，征人尽望故乡。","shang":"「沙似雪」「月如霜」两喻把边夜写成一片清冷的白；笛声起于「不知何处」，落在「一夜尽望乡」——声音与乡愁同时弥漫。李益自称「从军诗」，此篇为其七绝之冠，谱入乐府，天下传唱。"},"278":{"ti":"刘禹锡乌衣巷。旧时王谢堂前燕，飞入寻常百姓家——六朝金粉，被一只燕子轻轻收走。","zhu":[{"w":"朱雀桥","v":"秦淮河上桥名。"},{"w":"乌衣巷","v":"金陵城内，东晋王导、谢安等豪族聚居处。"},{"w":"王谢","v":"王导、谢安家族。"}],"yi":"朱雀桥边野草开花，乌衣巷口夕阳西斜。旧时王谢堂前的燕子——飞进了寻常百姓家。","shang":"「野草花」「夕阳斜」已见冷落，结句忽然借燕写史：堂前燕不辨贵贱，昔日王谢今入百姓——一「旧」一「寻常」，兴亡之巨与取材之小相激，遂成咏史第一名句。全篇无一字议论而议论至深。"},"279":{"ti":"刘禹锡春词。行到中庭数花朵，蜻蜓飞上玉搔头——人立花间久而不动，蜻蜓误以为玉簪是花，怨写得这样美。","zhu":[{"w":"宜面","v":"妆容与面相宜。"},{"w":"朱楼","v":"华美的楼。"},{"w":"玉搔头","v":"玉簪。"}],"yi":"新妆宜面走下朱楼，深锁的春光满院是愁。走到中庭数那花朵——蜻蜓飞上了玉搔头。","shang":"「深锁春光一院愁」——愁的是一院春色无人共赏；结句蜻蜓上簪，人已痴立如花，是全诗最惊艳的一笔。以美写怨，愈美愈怨，刘禹锡另有其《竹枝》的民歌风之外，此为雅致一路。"},"280":{"ti":"白居易后宫词。红颜未老恩先断，斜倚薰笼坐到明——坐到天明的不是等待，是绝望。","zhu":[{"w":"罗巾","v":"丝罗手巾。"},{"w":"按歌","v":"击节而歌。"},{"w":"薰笼","v":"熏衣的竹笼。"}],"yi":"泪水湿了罗巾，梦也做不成；夜深了，前殿还在按着歌声。红颜未老，恩宠先断——斜倚薰笼，坐到天明。","shang":"「梦不成」对「按歌声」——她想借梦自慰，前殿的歌声偏在提醒；「红颜未老」与「恩先断」的悖论，是宫怨最深的残忍。结「坐到明」三字，一夜的心理全部静止在一帧画面里。白诗浅语，此处最重。"},"281":{"ti":"张祜赠内人。斜拔玉钗灯影畔，剔开红焰救飞蛾——救蛾的一瞬，照见宫人自己的命运。","zhu":[{"w":"禁门","v":"宫门。"},{"w":"月痕","v":"月光痕迹。"},{"w":"宿鹭窠","v":"白鹭栖息的窝。"},{"w":"红焰","v":"灯焰。"}],"yi":"禁门宫树上月痕掠过，媚眼只看着宿鹭的窠。斜拔玉钗在灯影旁——剔开红焰，救那飞蛾。","shang":"「媚眼惟看宿鹭窠」——连鸟有巢也羡慕；「救飞蛾」——飞蛾扑火，与她一样。玉钗剔焰的细致动作里，是自怜也是自赎。二十字之内有两个「看」：看鹭、看蛾，看的全是自己。宫怨诗构思之奇，无过此篇。"},"282":{"ti":"张祜集灵台其一。太真含笑入帘来——杨妃授箓入道本是遮羞，张祜以「含笑」二字写尽讥讽。","zhu":[{"w":"集灵台","v":"即长生殿，在华清宫，祀神求仙之所。"},{"w":"上皇","v":"唐玄宗。"},{"w":"授箓","v":"道教授予符箓，杨玉环受度为女道士。"},{"w":"太真","v":"杨玉环的道号。"}],"yi":"日光斜照集灵台，红树花迎着晓露开。昨夜上皇新授箓——太真含笑，入了帘来。","shang":"求仙的灵台、受箓的道场，来的却是新册的贵妃——「含笑」二字，把一场神圣仪式写成了一场调笑。张祜宫词，冷眼最毒。讽玄宗夺子妃之丑事，全用白描，不着一句贬语。"},"283":{"ti":"张祜集灵台其二。却嫌脂粉污颜色，淡扫蛾眉朝至尊——虢国夫人的骄纵，一句写尽。","zhu":[{"w":"虢国夫人","v":"杨贵妃三姊，封虢国夫人，自恃美艳不施粉黛。"},{"w":"承主恩","v":"受玄宗恩宠（并传闻有私）。"},{"w":"平明","v":"天亮。"},{"w":"淡扫","v":"淡淡描画。"},{"w":"至尊","v":"皇帝。"}],"yi":"虢国夫人承着主恩，平明骑马直入宫门。却嫌脂粉污了颜色——淡扫蛾眉，来朝至尊。","shang":"「骑马入宫门」五字写尽骄纵——嫔妃车辇之制全不在她眼里；「嫌脂粉污颜色」更是自恃国色的极笔。诗无一字贬而讥讽入骨：淡扫蛾眉是她的美，也是玄宗的昏。张祜善以事实说话，此篇最见。"},"284":{"ti":"张祜题金陵渡。潮落夜江斜月里，两三星火是瓜州——一宿的旅愁，收在两三点渔火里。","zhu":[{"w":"金陵渡","v":"润州（今镇江）西津渡。"},{"w":"一宿","v":"住了一夜。"},{"w":"瓜州","v":"长江北岸渡口，与镇江相对。"}],"yi":"金陵津渡的小山楼，一宿行人自可愁。潮落夜江斜月里——两三星火，是瓜州。","shang":"「潮落」「夜江」「斜月」三层冷色铺满江面，忽然「两三星火」——对岸的瓜州人间灯火，隔水相望，愁人更愁。以「两三」之少写「万里」之隔，是小夜曲的笔法，比《枫桥》更轻，也更清。"},"285":{"ti":"朱庆馀宫词。含情欲说宫中事，鹦鹉前头不敢言——连倾诉都被鹦鹉听着，宫闱之压抑至此。","zhu":[{"w":"琼轩","v":"华美的长廊。"},{"w":"相并","v":"并肩。"},{"w":"鹦鹉前头不敢言","v":"鹦鹉学舌，恐泄密怨。"}],"yi":"花开时节寂寂闭着院门，美人相并立在琼轩。含着情欲说宫中之事——鹦鹉前头，不敢言。","shang":"「美人相并」——同病相怜者只能并立而不能私语；「不敢言」三字，把深宫的耳目写成一只鸟。满腹心事对着一只学舌的鹦鹉，怨之深、惧之切全在这份滑稽的禁忌里。唐人宫词构思之巧，此为极致。"},"286":{"ti":"朱庆馀近试上张水部。妆罢低声问夫婿：画眉深浅入时无？——以新妇自比考生，以夫婿比张籍，问的全是文章。","zhu":[{"w":"水部","v":"张籍时任水部员外郎。"},{"w":"停红烛","v":"点燃红烛。停，放置。"},{"w":"舅姑","v":"公婆。"},{"w":"入时无","v":"合不合时样。"}],"yi":"洞房昨夜停着红烛，待晓堂前去拜舅姑。妆罢低声问夫婿——画眉的深浅，合不合时样？","shang":"「低声」二字写尽新妇的忐忑——问的是画眉，忧的是前程。此诗借闺情行干谒，问得风雅；张籍答以「一曲菱歌敌万金」，一问一答遂成科场佳话。以比体作干谒诗，唐人无出其右。"},"287":{"ti":"杜牧将赴吴兴登乐游原一绝。清时有味是无能——自嘲的「有味」二字，藏着多少不平。","zhu":[{"w":"吴兴","v":"今浙江湖州，杜牧将赴任刺史。"},{"w":"乐游原","v":"长安东南高地。"},{"w":"无能","v":"无所作为（反语）。"},{"w":"一麾","v":"一面旌旗，指出任外郡。"},{"w":"昭陵","v":"唐太宗陵。"}],"yi":"清平时代「有味」的是我这无能之人，闲时爱孤云、静时爱僧。想把一麾掷向江海去——乐游原上，回头望一望昭陵。","shang":"「清时有味是无能」七个字三层：清时、有味、无能——生在「清时」而无用于世，自嘲里全是牢骚。结句望昭陵：太宗之世人才鼎盛，今则己须外放——望陵是望盛世，不平之气尽在不言中。"},"288":{"ti":"杜牧赤壁。东风不与周郎便，铜雀春深锁二乔——一场大战的成败，被两个女子轻轻断定。","zhu":[{"w":"折戟","v":"折断的戟。"},{"w":"销","v":"锈蚀。"},{"w":"前朝","v":"三国时代。"},{"w":"铜雀","v":"铜雀台，曹操所建，在邺城。"},{"w":"二乔","v":"大乔小乔，孙策周瑜之妻。"}],"yi":"折断的戟沉埋沙中，铁还没有锈尽；拿起来磨洗，认出是前朝的东西。东风若不给周郎方便——铜雀春深，锁的便是二乔。","shang":"「东风不与」四个字把赤壁的天意翻了个面——周郎之胜系于一阵风，历史只差一线；「锁二乔」以儿女之艳写家国之亡，想象力之奇为咏史之最。许顗讥其「不湖社稷存亡」，正见杜牧之史观：兴亡在细节，英雄系时运。"},"289":{"ti":"杜牧泊秦淮。商女不知亡国恨，隔江犹唱后庭花——唱的人未必不知，听的人未必在想。","zhu":[{"w":"秦淮","v":"秦淮河，金陵歌楼酒馆聚集地。"},{"w":"商女","v":"卖唱的歌女。"},{"w":"后庭花","v":"《玉树后庭花》，陈后主亡国之音。"}],"yi":"烟笼着寒水，月笼着沙；夜泊秦淮，近了酒家。商女不知亡国恨——隔江犹唱《后庭花》。","shang":"「烟笼寒水月笼沙」两个「笼」字，把夜色与历史都罩进迷雾；「隔江」二字最冷——亡国之音隔一条江还在唱，听歌的是谁？是晚唐的满座权贵。商女「不知」者，知者装作不知。杜牧咏史七绝的第一名。"},"290":{"ti":"杜牧寄扬州韩绰判官。二十四桥明月夜，玉人何处教吹箫——把一城风月都变成了对故人的调侃。","zhu":[{"w":"韩绰","v":"杜牧同事，判官为节度使僚属。"},{"w":"迢迢","v":"遥远。"},{"w":"草未凋","v":"一作「草木凋」，江南秋尽草犹青。"},{"w":"二十四桥","v":"扬州桥名（一说二十四座桥）。"},{"w":"玉人","v":"美人（一说指韩绰）。"}],"yi":"青山隐隐，江水迢迢；秋尽江南，草木未凋。二十四桥的明月夜里——玉人在何处教人吹箫？","shang":"「青山隐隐水迢迢」淡笔千里，「草未凋」三字点出江南之暖；结句问玉人吹箫，谐谑之中是深忆扬州。此诗使二十四桥成了扬州的别名。杜牧离开扬州后寄同事之作，风流而不轻佻。"},"291":{"ti":"杜牧遣怀。十年一觉扬州梦，赢得青楼薄幸名——十年繁华，自我清算成一纸账单。","zhu":[{"w":"落魄","v":"漂泊困顿。"},{"w":"载酒行","v":"携酒游冶。"},{"w":"楚腰","v":"楚灵王好细腰，代指美女。"},{"w":"掌中轻","v":"汉赵飞燕体轻能为掌上舞。"},{"w":"一觉","v":"一梦醒来。"},{"w":"薄幸","v":"薄情。"}],"yi":"落魄江湖，载酒而行；楚腰纤细，掌中轻盈。十年扬州梦一觉醒来——只赢得青楼一个薄幸之名。","shang":"「十年一觉扬州梦」——把十年繁华写成一场宿醉；「赢得」二字最痛：万般折腾，所得不过一个「薄幸」的虚名。杜牧自伤不遇而流连青楼，此篇是他对自己的判决书，率真处正在于不肯自恕。"},"292":{"ti":"杜牧秋夕。天阶夜色凉如水，坐看牵牛织女星——坐看双星，是宫女不敢言明的全部心事。","zhu":[{"w":"银烛","v":"白色蜡烛。"},{"w":"画屏","v":"彩绘屏风。"},{"w":"轻罗小扇","v":"轻薄丝罗的团扇。"},{"w":"流萤","v":"飞萤。"},{"w":"天阶","v":"宫中石阶（一作天街）。"},{"w":"牵牛织女","v":"隔银河相望的双星，七夕相会。"}],"yi":"银烛的秋光冷了画屏，轻罗小扇扑打流萤。夜色凉如水——坐着看那牵牛织女星。","shang":"「轻罗小扇」是秋扇见捐的旧典，一物已伏怨意；「凉如水」写夜色亦写心境；结句坐看双星——牛女尚能一年一会，而己永无会期。全篇不着一个怨字，一「坐」字胜过千言。"},"293":{"ti":"杜牧赠别其一。春风十里扬州路，卷上珠帘总不如——十里珠帘卷尽，无人比得上她。","zhu":[{"w":"娉娉袅袅","v":"体态轻盈美好。"},{"w":"豆蔻","v":"植物，二月初含苞，喻十三岁少女。"},{"w":"梢头","v":"枝头。"}],"yi":"娉娉袅袅十三有余，像豆蔻梢头二月初的花。春风十里的扬州路上，卷起珠帘——总不如她。","shang":"以「豆蔻梢头二月初」定年岁，比喻既美且新，遂有「豆蔻年华」一词。结句让十里长帘齐卷作陪衬——人人探头，不如一人。写少女之美至此，艳而不亵，是杜牧笔墨的分寸。"},"294":{"ti":"杜牧赠别其二。蜡烛有心还惜别，替人垂泪到天明——烛芯为「心」，烛泪「替人」，物我相怜。","zhu":[{"w":"多情却似总无情","v":"情深反而无话。"},{"w":"樽前","v":"酒筵前。"},{"w":"笑不成","v":"强颜无笑。"}],"yi":"多情却像总是无情，只觉得樽前连笑也笑不成。蜡烛有心，还知道惜别——替人垂泪，滴到天明。","shang":"「多情却似总无情」，道尽别筵上欲言又止的神理；结句以蜡炬「有心」自鉴——人不能流泪，烛来代劳。移情于物而物我莫辨，唐人写别情，此为巧绝。"},"295":{"ti":"杜牧金谷园。落花犹似坠楼人——绿珠坠楼与落花辞树，一瞬间定格成永恒。","zhu":[{"w":"金谷园","v":"西晋石崇的别墅，在洛阳。"},{"w":"香尘","v":"石崇屑沉香为尘，步迹成尘。"},{"w":"坠楼人","v":"石崇爱妓绿珠，权贵索之，坠楼而死。"}],"yi":"繁华的事散了，追逐着香尘；流水无情，草木自春。日暮东风里怨啼的鸟——落花，还像那坠楼的人。","shang":"「流水无情草自春」天地不仁，繁华自散；结句「落花犹似坠楼人」——以一瓣落花写一个烈女，轻与重、美与惨在一句里互证，遂成咏史七绝的奇笔。悼金谷园，亦是悼一切繁华。"},"296":{"ti":"李商隐夜雨寄北。何当共剪西窗烛，却话巴山夜雨时——把今夜的雨预支为来日的谈资，痴想成诗。","zhu":[{"w":"寄北","v":"寄给北方的妻子（一作友人）。"},{"w":"巴山","v":"巴蜀之山，作者滞留之地。"},{"w":"涨秋池","v":"秋雨使池水上涨。"},{"w":"何当","v":"何时能够。"},{"w":"共剪西窗烛","v":"一同剪去烛芯使烛明亮，喻秉烛夜话。"}],"yi":"你问归期，归期还没有期；巴山夜雨，涨满了秋池。什么时候能共剪西窗的烛——回过头来，说今晚这巴山夜雨？","shang":"「君问归期未有期」两个「期」字先见无奈；「巴山夜雨」在诗中两见——今夜是实景，来日是谈资，同一夜雨由苦变为甜。四句之内时间往复回环，是唐诗结构最奇妙的一首。纪昀称其「曲折顿宕，如不作意」。"},"297":{"ti":"李商隐寄令狐郎中。休问梁园旧宾客——昔日故人今为朝贵，一声「休问」，傲骨与旧情并存。","zhu":[{"w":"令狐郎中","v":"令狐绹，时为右丞（后拜相），作者旧交。"},{"w":"嵩云秦树","v":"嵩山之云、长安之树，分指两地。"},{"w":"双鲤","v":"书信。古乐府「客从远方来，遗我双鲤鱼」。"},{"w":"梁园","v":"汉梁孝王园，令狐楚曾聘作者入幕，故自称梁园宾客。"},{"w":"茂陵秋雨病相如","v":"司马相如晚岁病免居茂陵，自喻。"}],"yi":"嵩山的云、长安的树，久已离居；双鲤迢迢，寄来一纸书。休问那梁园的旧宾客——茂陵的秋雨里，病着的相如。","shang":"「休问」二字一折——不愿旧人看见自己的落魄，傲与痛都在这拒绝里。结以病相如自况，不诉苦而境自苦。义山与令狐家恩怨一生，此诗欲言又止，最见其委屈。"},"298":{"ti":"李商隐为有。无端嫁得金龟婿，辜负香衾事早朝——贵妇的娇嗔，写出「富贵」的另一面。","zhu":[{"w":"云屏","v":"云母屏风。"},{"w":"凤城","v":"长安。"},{"w":"无端","v":"没来由。"},{"w":"金龟婿","v":"佩金龟袋的高官。"},{"w":"香衾","v":"香被。"}],"yi":"只因为云屏后有无限娇媚，凤城寒尽，却怕那春宵。无端嫁得金龟之婿——辜负了香衾，去赶早朝。","shang":"「怕春宵」三字已见怨意；「无端」把嫁贵婿说成失误，娇嗔入妙。世人艳羡的金龟婿，在她笔下竟成了春宵之敌——唐人写闺情翻转处，义山最敏。小诗如一枚糖里的苦芯。"},"299":{"ti":"李商隐隋宫。春风举国裁宫锦，半作障泥半作帆——一国丝锦，一半垫马鞍一半做船帆，荒淫之账只用一笔。","zhu":[{"w":"南游","v":"炀帝三下江都。"},{"w":"不戒严","v":"自恃天下莫敢谏，不设警备。"},{"w":"九重","v":"皇宫。"},{"w":"谏书函","v":"谏书被扣（奉信郎崔民象等以谏被杀）。"},{"w":"障泥","v":"马鞍旁的挡泥布。"}],"yi":"乘兴南游，不设戒严；九重宫里，谁省那份谏书？春风里举国裁剪宫锦——一半做了障泥，一半做了船帆。","shang":"「举国裁宫锦」是何等声势，「半作障泥半作帆」是何等挥霍——国力在「半」「半」之间断送。数字的对仗把暴政写成了算术，李商隐咏史七绝的第一等笔力。"},"300":{"ti":"李商隐瑶池。八骏日行三万里，穆王何事不重来？——问得仙母无言，神仙之不可恃尽在其中。","zhu":[{"w":"瑶池阿母","v":"西王母。"},{"w":"黄竹歌","v":"周穆王作《黄竹》哀民冻馁，此借指穆王已死。"},{"w":"八骏","v":"穆王驾八骏西游，与西王母宴于瑶池，约定三年复来。"}],"yi":"瑶池上王母的绮窗开了，黄竹歌声动地悲哀。八骏日行三万里——穆王为何不重来？","shang":"「黄竹歌声动地哀」——穆王已崩，王母犹开窗等待；结句「何事不重来」直问到底，讽刺唐武宗等求仙之帝：神仙尚不能救人于死，求仙何为？以问作结而答在问中，咏史之含蓄至境。"},"301":{"ti":"李商隐嫦娥。嫦娥应悔偷灵药，碧海青天夜夜心——窃药成仙者，夜夜独对碧海青天。","zhu":[{"w":"云母屏风","v":"云母石制的屏风。"},{"w":"长河","v":"银河。"},{"w":"晓星沈","v":"晓星西沉，天将明。沈，同「沉」。"},{"w":"灵药","v":"后羿求得不死药，嫦娥窃之奔月。"},{"w":"夜夜心","v":"夜夜孤寂之心。"}],"yi":"云母屏风上烛影渐深，长河渐落，晓星西沉。嫦娥应悔偷了灵药——碧海青天，夜夜此心。","shang":"「应悔」二字替嫦娥设想，实为自道：修道、入幕、痴情——凡求「高」者皆孤。烛影、晓星写通宵不寐，碧海青天写无尽孤清。此诗或是悼亡、或是自伤、或是咏道，三解皆通——正因情在象外。"},"302":{"ti":"李商隐贾生。不问苍生问鬼神——文帝贤主之名与夜半虚席之诚，被最后一问戳破。","zhu":[{"w":"宣室","v":"未央宫前殿正室。"},{"w":"逐臣","v":"被贬之臣，贾谊自长沙被召回。"},{"w":"才调","v":"才气格调。"},{"w":"虚前席","v":"空出前面的座位凑近（膝行而前）。"},{"w":"苍生","v":"百姓。"}],"yi":"宣室求贤，访逐臣；贾生才调，更无伦。可怜夜半虚前席——不问苍生，问鬼神！","shang":"前三句层层抬举——求贤、无伦、虚席，全是「贤主」的铺垫；末句陡然一跌，「可怜」二字翻尽前面所有敬意。「问鬼神」三字，刺文帝更刺晚唐诸帝之崇佛道。二十八字一扬一抑，咏史绝句的章法典范。"},"303":{"ti":"温庭筠瑶瑟怨。雁声远过潇湘去，十二楼中月自明——瑟声、雁声俱远，月自照人。","zhu":[{"w":"冰簟","v":"凉席。簟，竹席。"},{"w":"银床","v":"银饰的床（一说井栏）。"},{"w":"潇湘","v":"二水名，在湖南，传水神居处。"},{"w":"十二楼","v":"仙人居所，借指女子居楼。"}],"yi":"冰簟银床上梦做不成，碧天如水，夜云很轻。雁声远远过了潇湘去——十二楼中，月自照人。","shang":"「梦不成」先定一夜之失意；雁「远过」、月「自明」——声与光都不为人留，天地自自在在，人自孤孤清清。「自」字是全诗之眼。不着一个「怨」字，题中之「怨」满纸清辉。"},"304":{"ti":"郑畋马嵬坡。终是圣明天子事——为玄宗回护，反衬出马嵬之变的无可如何。","zhu":[{"w":"回马","v":"玄宗自蜀返回。"},{"w":"云雨难忘","v":"与杨妃的恩情难忘。"},{"w":"日月新","v":"肃宗即位，局势更新。"},{"w":"景阳宫井","v":"陈后主与张丽华藏身之井，终被隋军擒辱。"},{"w":"又何人","v":"马嵬赐死较之景阳井受辱，孰为得体。"}],"yi":"玄宗回马，杨妃已死；云雨难忘，日月更新。终算是圣明天子的作为——景阳宫井，又算什么人？","shang":"「云雨难忘」与「日月新」一句并陈——私情与社稷只可取其一，玄宗取了社稷；结以陈后主对比，谓其死杨妃尚胜于辱井底。「圣明」二字是苦心回护，亦是深深叹息。唐人咏马嵬，此篇最见分寸。"},"305":{"ti":"韩偓已凉。八尺龙须方锦褥，已凉天气未寒时——一切陈设俱备，只待一个不在的人。","zhu":[{"w":"碧阑干","v":"碧玉栏杆。"},{"w":"猩色","v":"猩红色。"},{"w":"折枝","v":"花卉画。"},{"w":"龙须","v":"龙须草编的席。"}],"yi":"碧阑干外绣帘低垂，猩红屏风上画着折枝。八尺龙须席铺着锦褥——已凉的天气，还未寒的时候。","shang":"全篇四句只写一个闺房：帘、屏、席、褥，温度停在那「未寒时」——秋深而不寒，恰是需要人的时候。不着一句情语，而闺中人的一切心事都在这恰到好处的温度里。韩偓香奁诗，此为最蕴藉者。"},"306":{"ti":"韦庄台城。无情最是台城柳，依旧烟笼十里堤——六朝已矣，柳色年年，最「无情」的恰是最美的。","zhu":[{"w":"台城","v":"六朝宫城故址，在今南京鸡鸣山北。"},{"w":"六朝","v":"吴东晋宋齐梁陈。"},{"w":"烟笼","v":"柳色如烟笼罩。"}],"yi":"江上细雨霏霏，江草齐齐；六朝如梦，鸟儿空啼。最无情的，是那台城的柳——依旧烟一样笼着十里长堤。","shang":"「六朝如梦鸟空啼」一「梦」一「空」，兴亡先虚化；结句怨柳「无情」——正因柳太美太持久，反衬人事之速朽。以「无情」说「有情」，是诗人对历史的痴。韦庄晚唐身世，与金陵同悲。"},"307":{"ti":"陈陶陇西行。可怜无定河边骨，犹是深闺梦里人——枯骨与梦里人，一句写穿生死。","zhu":[{"w":"貂锦","v":"貂裘锦甲，代指精锐将士。"},{"w":"胡尘","v":"匈奴战场。"},{"w":"无定河","v":"黄河支流，流经陕西，边塞古战场。"}],"yi":"誓扫匈奴，奋不顾身；五千貂锦，丧于胡尘。可怜无定河边的白骨——还是深闺梦里那个人！","shang":"「河边骨」与「梦里人」是同一人——家人不知其死，梦里犹活。十四字之内，一边是现实之残酷，一边是幻想之温存，中间隔着一场无人报丧的战争。明王世贞推为唐人边塞诗压卷之一，反战之痛至此为极。"},"308":{"ti":"张泌寄人。多情只有春庭月，犹为离人照落花——梦里到过的地方，只有月光替人再照一遍。","zhu":[{"w":"谢家","v":"所恋女子家（以谢娘代称情人）。"},{"w":"回合","v":"环绕。"},{"w":"曲阑","v":"曲折栏杆。"}],"yi":"离别的梦依依到了谢家，小廊环绕，曲阑斜斜。多情的只有那春庭月——还为离人，照着落花。","shang":"「别梦依依」——梦犹恋恋；醒来无路可通，惟月多情。张泌自记：少年与邻女浣衣相恋，经年不复见，因赋诗——此诗背后是一段真实的离散。「犹为」二字，是把月亮当作了知己。"},"309":{"ti":"无名氏杂诗。等是有家归未得，杜鹃休向耳边啼——杜鹃啼「不如归去」，而归不得者最怕听它。","zhu":[{"w":"寒食","v":"节名，禁火冷食。"},{"w":"著麦苗风","v":"吹拂麦苗的风。著，附着。"},{"w":"等是","v":"同样是。"},{"w":"杜鹃","v":"子规鸟，啼声如「不如归去」。"}],"yi":"近寒食的雨里草长得萋萋，拂着麦苗的风里柳映着堤。同样是有家却归不得——杜鹃啊，休向耳边啼！","shang":"前二句写景，春色如画；后二句陡转——正是春色勾起乡愁。「休向耳边啼」对杜鹃的恳求近乎无理，却是最深的无奈。无名氏之诗而入《唐诗三百首》，足见其情真。"},"310":{"ti":"王翰凉州词。醉卧沙场君莫笑，古来征战几人回——明知必死而痛饮，悲凉到了极处反成豪放。","zhu":[{"w":"夜光杯","v":"周穆王时西胡献的玉杯，此指精美酒杯。"},{"w":"催","v":"催饮。"},{"w":"沙场","v":"战场。"}],"yi":"葡萄美酒斟满夜光杯，正要畅饮，琵琶马上催。醉卧沙场请君莫笑——古来征战，几人能回！","shang":"「欲饮琵琶马上催」——宴未成欢，战鼓已催；「几人回」三字是全诗的底色：杯中之酒原是诀别之饮。施补华谓「作悲伤语读便浅，作谐谑语读便妙」——豪放是它的面孔，悲凉是它的心。"},"311":{"ti":"王维渭城曲。劝君更尽一杯酒，西出阳关无故人——再一杯，因为出了阳关就没有故人陪你喝了。","zhu":[{"w":"渭城","v":"咸阳故城，在长安西北渭水北岸。"},{"w":"浥","v":"湿润。"},{"w":"阳关","v":"在今甘肃敦煌西南，出关即塞外。"},{"w":"更尽","v":"再饮完。"}],"yi":"渭城朝雨润湿轻尘，客舍青青，柳色一新。劝君再饮尽这一杯酒——西出阳关，就没有故人了。","shang":"「朝雨浥尘」「柳色新」——天公似在为行人洗尘，景愈清新，别愈难堪；结句「无故人」三字，把此后的万水千山都交给了孤独。此诗后谱为《阳关三叠》，千年送别只用它。"},"312":{"ti":"王维秋夜曲。银筝夜久殷勤弄，心怯空房不忍归——弹筝不为曲成，只为不归。","zhu":[{"w":"桂魄","v":"月亮。"},{"w":"轻罗","v":"轻薄丝衣。"},{"w":"殷勤弄","v":"反复弹奏。"},{"w":"心怯空房","v":"怕回那空房。"}],"yi":"月亮初升，秋露还微；轻罗已薄，懒得添衣。银筝夜深还在殷勤地弹——心怯空房，不忍归去！","shang":"「轻罗已薄未更衣」——夜凉而不觉，是心不在衣；「夜久殷勤弄」——曲不成曲，是心不在筝。弹到夜深的种种，只为推延推开那扇空房的门。闺情小诗，一层深一层。"},"313":{"ti":"王昌龄长信怨。玉颜不及寒鸦色，犹带昭阳日影来——人不如鸦，鸦尚沐昭阳日影。","zhu":[{"w":"长信怨","v":"乐府题。汉成帝妃班婕妤失宠，自请长信宫侍太后。"},{"w":"奉帚","v":"持帚洒扫。"},{"w":"团扇","v":"班婕妤《怨歌行》以秋扇自喻见弃。"},{"w":"寒鸦","v":"乌鸦。"},{"w":"昭阳","v":"汉宫，赵飞燕姊妹所居，代指得宠处。"}],"yi":"平明奉帚，金殿开；且将团扇，共徘徊。玉颜竟不及寒鸦的颜色——它还带着昭阳的日影飞来。","shang":"「玉颜不及寒鸦色」——美人之颜竟输给一只鸦，只因为鸦来自昭阳、沐过恩日的余光。全篇之怨凝在这荒谬的比较里，无理而痛极。王昌龄宫怨七绝，此为最奇之笔。"},"314":{"ti":"王昌龄出塞。秦时明月汉时关——互文之笔，把千年边患凝在一轮月一座关上，遂为七绝压卷。","zhu":[{"w":"但使","v":"只要。"},{"w":"龙城飞将","v":"飞将军李广（一说卫青奇袭龙城）；泛指英勇善战之将。"},{"w":"阴山","v":"今内蒙古阴山，汉唐北方屏障。"}],"yi":"秦时的明月，汉时的关；万里长征的人，未还。但使龙城的飞将在——不教胡马，渡过阴山！","shang":"「秦时明月汉时关」——月与关皆亘古之物，人在其中来去如流，起句便有千年之重；「人未还」三字紧承，写尽代代征人的命运。后二句翻出对良将的呼唤，既是信心也是讽刺。明李攀龙推为唐人七绝压卷之作。"},"315":{"ti":"王之涣出塞（凉州词）。羌笛何须怨杨柳，春风不度玉门关——笛在怨柳，春风已远，一片塞外天地。","zhu":[{"w":"万仞","v":"极言其高。仞，八尺。"},{"w":"羌笛","v":"羌族乐器。"},{"w":"怨杨柳","v":"笛曲《折杨柳》，怨别之曲。"},{"w":"春风不度","v":"塞外无春（杨应和未生）。"}],"yi":"黄河远上白云之间，一片孤城，万仞高山。羌笛何须怨那《杨柳》——春风本来不度玉门关。","shang":"「黄河远上白云间」起笔如画卷自下而上铺开，「一片孤城万仞山」以孤对万，天地之大衬人城之小。结二句以「何须」自宽——怨也无益，春风不到。悲凉至极而以旷语出之，遂成唐人边塞绝唱。"},"316":{"ti":"李白清平调其一。云想衣裳花想容——把杨妃写成云与花都想比拟的人，应制而能天成。","zhu":[{"w":"清平调","v":"李白奉诏于沉香亭新填之曲。"},{"w":"槛","v":"栏杆。"},{"w":"露华","v":"带露的花。"},{"w":"群玉山","v":"西王母所居仙山。"},{"w":"瑶台","v":"仙人居处。"}],"yi":"云想她的衣裳，花想她的容；春风拂着栏杆，露华正浓。若不是在群玉山头见过——那便是瑶台月下才相逢。","shang":"「云想衣裳花想容」——云与花都想「像她」，人遂在云花之上；后二句不直接写美，只说她只能在仙境见过。李白以天上写人间，应制诗至此而无一字谀词，故玄宗、贵妃皆喜。"},"317":{"ti":"李白清平调其二。借问汉宫谁得似？可怜飞燕倚新妆——以飞燕衬妃，一捧一贬皆在其中。","zhu":[{"w":"一枝红艳","v":"带露凝香的牡丹，兼指妃容。"},{"w":"云雨巫山","v":"楚王梦神女事，谓虚梦难比真身。"},{"w":"飞燕","v":"汉成帝后赵飞燕，绝色。"}],"yi":"一枝红艳凝着露香，巫山云雨，空教人断肠。借问汉宫里谁能相像？可怜飞燕，还要倚新妆。","shang":"「枉断肠」——神女之梦终究是空的，眼前才是真身；飞燕之美尚须「倚新妆」，而妃是天生的红艳。捧得愈高，愈见奉诏之作的分寸——玄宗亲调玉笛以倚曲，可见其赏。"},"318":{"ti":"李白清平调其三。解释春风无限恨，沈香亭北倚阑干——名花倾国、君王带笑，一倚之间盛唐全在。","zhu":[{"w":"倾国","v":"绝色美人，指杨妃。"},{"w":"解释","v":"消解。"},{"w":"沈香亭","v":"兴庆宫亭，以沉香木建。"}],"yi":"名花倾国两相欢，常得君王带笑看。解释得春风无限的恨——沈香亭北，倚着阑干。","shang":"「两相欢」——花与人互相成全；「带笑看」——帝王亦入画中。结句「倚阑干」三字最妙：无限恨被春风带去，倚栏的只有一瞬的太平。三首清平调至此收束，盛唐的黄昏，被李白写成了正午。"},"319":{"ti":"杜秋娘金缕衣。花开堪折直须折，莫待无花空折枝——三百首以之作结，把「惜时」放在最后一声。","zhu":[{"w":"金缕衣","v":"缀金线的华衣，喻贵重之物。"},{"w":"惜取","v":"珍惜。"},{"w":"堪","v":"可以。"},{"w":"直须","v":"就要。"},{"w":"空折枝","v":"空对无花之枝。"}],"yi":"劝君莫惜那金缕衣，劝君惜取少年时。花开堪折就要去折——莫待无花，空折花枝！","shang":"「莫惜」与「惜取」对举——金缕衣可再得，少年时不再来；两个「折」字一实一空，人生只在花开与花落之间。此诗辞浅意深，回环如歌，选三百首者以它压卷：读完三百首，最要紧的还是这一句。"},"001":{"ti":"开元间张九龄遭谗被贬荆州长史后作《感遇》十二首，此其一。以孤鸿自况，见双翠鸟得势而自守高洁。","zhu":[{"w":"池潢","v":"池塘的水。潢，积水池。"},{"w":"三珠树","v":"神话中珠玉所生之树，喻珍贵显要之地。"},{"w":"金丸","v":"金属弹丸，指射猎之险，喻谗构之患。"},{"w":"弋者","v":"用带绳箭射猎的人。末句谓高飞冥冥，射者无从施技。"}],"yi":"孤雁自海上飞来，连池塘的水也不敢回望。侧目瞥见一双翠鸟，把巢筑在三珠树上。它们立在珍木高巅，难道不怕金丸射来？衣裳华美招人指点，位高势显连神也忌恨。如今我飞在苍茫高天，射猎的人又如何能得手？","shang":"全篇用比，以孤鸿之远举反衬双翠鸟之据要，一「惧」一「慕」，讽刺与自守兼备。语淡而骨峻，开盛唐五古寄兴一路。"},"002":{"ti":"《感遇》其二。以兰、桂各抱本心自喻，谓君子修德在己，不慕荣遇，托讽林栖者的攀附之心。","zhu":[{"w":"葳蕤","v":"枝叶繁盛纷披的样子。"},{"w":"皎洁","v":"明净洁白，写桂花之色。"},{"w":"自尔","v":"自然如此。尔，如此。"},{"w":"林栖者","v":"山林隐居之人，此指希图援引者。"},{"w":"本心","v":"固有的本性，双关草木之性与君子之德。"}],"yi":"兰叶逢春而葳蕤，桂花遇秋而皎洁。这般欣欣生意，自然各成佳节。谁知那林间隐者，闻香而生欣羡。草木自有本心，何须求人来采折？","shang":"前半纯写物，后半转出议论，一问收束，理趣悠然。「草木有本心，何求美人折」为唐诗名句，君子自守之怀尽在其中。"},"003":{"ti":"《感遇》其三。写幽人独卧、孤清自持，欲借高鸟传情而不可得，抒忠悃无由上达之慨。","zhu":[{"w":"幽人","v":"幽居之人，作者自指。"},{"w":"滞虑","v":"郁结的思虑。"},{"w":"高鸟","v":"高飞之鸟，喻可通达上听者。"},{"w":"至精","v":"至诚之心。"},{"w":"飞沈","v":"飞鸟与沉鱼，喻上下悬隔、地位迥异。"}],"yi":"幽居的人独卧空斋，郁积的思虑被孤高清寂洗净。且以此心托付高飞的鸟，请它替我传递远方的深情。从早到晚怀抱着空想，又有谁能感动我这至诚？飞鸟与沉鱼本就隔越，拿什么来安慰我的真心？","shang":"以「飞沈理自隔」一语写尽君臣悬隔之痛，语意曲折，怨而不怒。张九龄贬谪诗多此沉郁之致。"},"004":{"ti":"《感遇》其四。借江南丹橘经冬不凋，喻己之节操与才德，慨叹阻隔难进、桃李易售。","zhu":[{"w":"丹橘","v":"橘树，其果丹红，江南名产。"},{"w":"岂伊","v":"难道只是。伊，语助词。"},{"w":"岁寒心","v":"耐寒之心，喻坚贞节操，本《论语》「岁寒然后知松柏之后凋」。"},{"w":"荐嘉客","v":"进献给贵宾，喻才德可供世用。"},{"w":"树桃李","v":"种植桃李。桃李成蹊，喻趋时易售。"}],"yi":"江南有丹红的橘树，经冬依然绿意成林。难道只因地气和暖，原是自有耐寒之心。本可荐给嘉宾，无奈阻隔重重。命运只看际遇，循环之理无从探寻。徒然说种桃李，难道这橘树就没有荫凉？","shang":"屈子《橘颂》之遗意。以橘自况，不怨天而问命，末句翻出一层，谓桃李有荫而橘独见弃，讽意深婉。"},"005":{"ti":"李白游终南山后过访隐士斛斯山人，留宿置酒而作。写山月随人、田家留客之乐，末以「忘机」收束，见超然物外之趣。","zhu":[{"w":"碧山","v":"苍翠的山，指终南山。"},{"w":"翠微","v":"青翠掩映的山色，亦指山腰幽深处。"},{"w":"荆扉","v":"柴门。荆，荆棘枝条。"},{"w":"青萝","v":"松萝，一种攀缘蔓生的植物。"},{"w":"河星","v":"银河中的星，点出夜已深沉。"},{"w":"忘机","v":"消除机巧之心，指与世无争、恬淡自适。"}],"yi":"暮色中从碧山下来，山月一路随人而归。回头望走过的路径，苍苍茫茫横着一片青翠。相携来到农家，孩童打开柴门。绿竹伸入幽静小路，青萝拂过行人衣衫。欢声笑语中得以歇息，美酒且共畅饮。长歌吟咏松风，曲终时银河星稀。我醉了你也快乐，陶然之间一同忘却机心。","shang":"写山月用「随」字，便觉月色有情；「绿竹入幽径，青萝拂行衣」以幽景衬幽人，清丽入画。结语「忘机」二字点出全诗之魂，是李白田园诗中最见闲适者。"},"006":{"ti":"李白于长安月夜独酌，无人对饮，遂邀月、影为伴。表面写行乐，内里是深切孤独，「永结无情游」一句尤为沉痛。","zhu":[{"w":"独酌","v":"独自饮酒。"},{"w":"三人","v":"指诗人、明月与自己的影子。"},{"w":"及春","v":"趁着春光。及，趁。"},{"w":"无情游","v":"超脱世俗情爱的交游，此指与月、影为友。"},{"w":"云汉","v":"银河，此指天上。"}],"yi":"花间摆一壶酒，独自酌饮没有亲近之人。举杯邀请明月，加上身影便成三人。月既不懂得饮酒，影也只会跟随我身。且暂伴月与影，行乐须趁春光。我歌时月徘徊，我舞时影零乱。清醒时同欢，醉后各自分散。愿永结这无情之游，相约在遥远的云天。","shang":"以「举杯邀明月，对影成三人」的奇想，把孤独写成热闹，热闹底下更见孤独。全篇由邀月到与月相约，想象愈奇而寂寞愈深，是李白豪放中的悲凉。"},"007":{"ti":"李白拟闺人口吻写春思。燕地草生、秦地桑绿，触景怀远；末以嗔问春风作结，含蓄见痴情。","zhu":[{"w":"燕草","v":"燕地的春草。燕，今河北一带，丈夫所在。"},{"w":"秦桑","v":"秦地的桑树。秦，今陕西一带，思妇所居。"},{"w":"断肠","v":"极言思念之痛。"},{"w":"罗帏","v":"丝罗制的帐幕，指闺房。"}],"yi":"燕地的春草细如碧丝，秦地的桑树低压着绿枝。当你在燕地动了归家之念，正是我在秦地柔肠寸断之时。春风啊我与你素不相识，为何要吹入我的罗帐？","shang":"起句两地双起，燕秦并写，以草丝桑枝的春信牵动两地相思。结句怪春风无端入帏，无理而妙，痴情毕现，为唐人闺怨绝唱。"},"008":{"ti":"杜甫早年望泰山而作。时年二十四五，未登而望，写出泰山的雄阔与凌顶之志。","zhu":[{"w":"岱宗","v":"泰山的尊称。岱为泰山古名，宗谓群山之长。"},{"w":"造化钟神秀","v":"天地把神奇秀丽都聚集于此。钟，聚集。"},{"w":"阴阳割昏晓","v":"山北为阴山南为阳，高峻使两侧明暗判然如割。"},{"w":"决眦","v":"眼眶睁裂。极言凝望之切。"},{"w":"会当","v":"定要、终当。"}],"yi":"泰山究竟怎样巍峨？齐鲁大地望不尽它的青青。天地把神秀都聚集在此，山势高峻，阴阳两面判若晨昏。层云荡涤着胸怀，睁裂眼眶送归鸟入山。定要登上那绝顶，看群山尽在脚下。","shang":"全篇不着一个「高」字而高不可及。「割」字奇警，写山之所未见。结句以凌顶小天下，气象已具杜甫一生格局。"},"009":{"ti":"杜甫于乱后与故友卫八重逢，一夕聚饮而作。二十载沧桑、故旧凋零，尽在一饭一觞之间，是杜诗中最见人情者。","zhu":[{"w":"参与商","v":"参星与商星此出彼没，喻朋友难以相见。"},{"w":"鬓发","v":"鬓角的头发，此写相看已老。"},{"w":"父执","v":"父亲的挚友，指诗人辈分。"},{"w":"春韭","v":"春日的韭菜，雨中剪来待客。"},{"w":"黄粱","v":"黄小米。新炊间黄粱，指掺黄米的饭。"},{"w":"十觞","v":"十杯酒。觞，酒杯。"}],"yi":"人生难得相见，动辄如参星商星。今夜是何等之夜，能共此灯烛之光。少壮能有多久，鬓发都已斑白。打听故旧半已为鬼，惊呼间心中灼痛。哪知二十年后，重登你的厅堂。昔别时你尚未婚娶，如今儿女忽已成行。孩子们欣然敬重父辈之交，问我来自何方。问答未完，便打发孩子摆上酒浆。夜雨中剪来春韭，新炊里掺着黄粱。你说会面太难，一举便是十觞。十觞也无醉意，感念你情意深长。明日又隔山岳，世事两茫茫。","shang":"全篇不用典、不着色，纯以家常语写聚散。「夜雨剪春韭，新炊间黄粱」写贫家待客之诚，朴拙动人；结句「世事两茫茫」，乱世之感沉入杯底。"},"010":{"ti":"杜甫于安史乱后作，写一位遭丧乱而弃的良家女子，幽居空谷、自守清节。借佳人寄慨，寓士君子不遇之悲。","zhu":[{"w":"绝代","v":"冠绝当代，举世无双。"},{"w":"良家子","v":"良家女子。"},{"w":"转烛","v":"风中摇曳的烛火，喻世事无常。"},{"w":"合昏","v":"合欢树，其叶朝开夜合，喻夫妇相守。"},{"w":"盈掬","v":"满把。掬，双手捧取。"},{"w":"翠袖","v":"青绿色的衣袖，指佳人衣衫。"}],"yi":"有一位绝代佳人，幽居在空寂的山谷。自称是良家女儿，零落飘泊依傍草木。关中当年遭丧乱，兄弟惨遭杀戮。官位再高又有何用，连尸骨都不能收殓。世情厌恶衰败，万事如风中残烛。丈夫是轻薄儿郎，新人美如玉。合欢尚知应时而合，鸳鸯尚且不肯独宿。只见新人欢笑，哪闻旧人啼哭！在山泉水清，出山泉水浊。侍女卖珠归来，牵藤补葺茅屋。摘花却不插在发间，采柏常常满把。天寒翠袖单薄，日暮倚着修长的竹子。","shang":"以「在山泉水清，出山泉水浊」一语双关，既写山泉又喻贞节，为全诗之眼。「天寒翠袖薄，日暮倚修竹」以景结情，孤高清绝，画尽佳人之骨。"},"011":{"ti":"杜甫闻李白流放夜郎、生死未卜，积思成梦而作。写梦魂来去、疑真疑幻，字字是关切之泪。","zhu":[{"w":"吞声","v":"咽住哭声，极言悲痛。"},{"w":"恻恻","v":"悲痛的样子。"},{"w":"瘴疠","v":"南方湿热蒸郁、易致疾病之气。"},{"w":"逐客","v":"被放逐的人，指李白。"},{"w":"罗网","v":"捕鸟的网，喻李白身陷祸难。"},{"w":"枫林","v":"枫树林。魂来枫林青，取《楚辞》招魂之意。"},{"w":"蛟龙","v":"水中的龙，喻江湖险恶。"}],"yi":"死别已让人咽泪无声，生别更常令人悲恻。江南是瘴疠之地，被逐之人杳无消息。故人入我梦中，是知我长相思念。你如今身在罗网，怎还能生出羽翼？恐怕不是平生之魂，路途遥远不可揣测。魂来时枫林青青，魂去时关塞昏黑。落月洒满屋梁，还疑心照着你的容颜。水深波浪阔，切莫让蛟龙把你攫去。","shang":"写梦而处处存疑，「恐非平生魂」写得惊疑不定，最见至情。「魂来枫林青，魂返关塞黑」以青黑二字作魂行之色，幽邃凄怆，是杜诗中的鬼笔。"},"012":{"ti":"承前篇，记三夜频梦李白。写梦中叮嘱、醒后慨叹，为李白坎坷一生作悲，亦自伤身世。","zhu":[{"w":"局促","v":"匆促不安的样子。"},{"w":"舟楫","v":"船和桨，指行舟。"},{"w":"冠盖","v":"冠冕车盖，指京城的显贵。"},{"w":"斯人","v":"此人，指李白。"},{"w":"网恢恢","v":"天网恢恢。此反用，谓天网不见得宽疏。"},{"w":"身后事","v":"死后之事。"}],"yi":"浮云终日飘行，游子却久盼不至。三夜频频梦见你，情谊深切见你心意。你告辞归去总是匆促，苦苦诉说前来不易。江湖多风波，行舟恐有失坠。出门搔着白发，仿佛辜负了平生之志。京城冠盖如云，唯你这般憔悴。谁说天网宽疏，你将要老去却反受牵累。纵有千秋万岁之名，也只是寂寞的身后之事。","shang":"「冠盖满京华，斯人独憔悴」以满城冠盖反衬一人憔悴，愤慨与怜惜并发。结句把千秋之名与寂寞身后对举，看似宽解，实为最深的悲凉。"},"013":{"ti":"王维送友人归隐而作。一问一答间见友人失意，末以「白云无尽」作结，叹羡与怅惘兼有。","zhu":[{"w":"饮君酒","v":"请你喝酒。饮，使……饮。"},{"w":"何所之","v":"去哪里。之，往。"},{"w":"归卧","v":"归隐闲居。"},{"w":"南山陲","v":"终南山的边陲。陲，边缘。"},{"w":"白云无尽时","v":"白云无穷无尽，喻归隐之乐无穷。"}],"yi":"下马请你喝一杯酒，问你将去哪里。你说仕途不得意，要归隐终南山边。你只管去吧我不再相问，那白云深处乐无穷尽。","shang":"短短六句，以问答写送别，一问「何所之」引出友人失意，一答「白云无尽」宕开去，不作挽留而挽留之意自深，含蓄之极。"},"014":{"ti":"王维送友人綦毋潜落第还乡。慰其不第、勉其勿馁，句句是温厚劝勉之意。","zhu":[{"w":"东山客","v":"指隐士。晋谢安曾隐居东山，后出仕。"},{"w":"采薇","v":"采薇而食，指隐居。用伯夷叔齐事。"},{"w":"金门","v":"金马门，汉代官署，代指朝廷。"},{"w":"吾道非","v":"我的主张错了吗。用《孔子家语》典。"},{"w":"桂棹","v":"桂木做的船桨，指行舟。"},{"w":"落晖","v":"落日余晖。"},{"w":"知音","v":"知己。末句谓莫因不遇便说知音稀少。"}],"yi":"圣明之世没有隐者，英才都来归附。于是使你这东山隐士，不得归去采薇。既到金门却离朝廷尚远，谁说你主张有错？江淮间过了寒食，京洛里缝制春衣。长安道上置酒相送，同心之友与我相违。你将要乘舟远去，不久便归返柴门。远树伴着行客，孤城对着落晖。你的谋略暂时不用，莫说知音稀少。","shang":"以「圣代无隐者」反起，先说盛世不容隐，再说落第非己之过，慰藉得体。「远树带行客，孤城当落晖」以疏淡之景写别情，是王维本色。"},"015":{"ti":"王维归隐辋川时游黄花川、逐青溪而作。写溪水随山万转、声喧色静，末以垂钓终老自许，见其闲澹。","zhu":[{"w":"黄花川","v":"水名，在今陕西凤县东北。"},{"w":"逐","v":"追随，沿着。"},{"w":"趣途","v":"前往的路程。趣，趋向。"},{"w":"菱荇","v":"菱与荇菜，都是水生植物。"},{"w":"葭苇","v":"芦苇。葭，初生的芦苇。"},{"w":"盘石","v":"同「磐石」，大而平的石。"}],"yi":"我走进黄花川，常顺着青溪而行。溪水随山千回万转，路程却不足百里。水声在乱石间喧响，山色在深松里静静。水波荡漾浮着菱荇，澄澈处映着芦苇。我心本就闲适，清川也如此淡泊。请让我留在盘石上，垂钓一生算了。","shang":"「声喧乱石中，色静深松里」以动写声、以静写色，声色相映，为写溪名句。末句将心之闲与川之澹合写，物我两忘，是王维「诗中有画」的典型。"},"016":{"ti":"王维晚年居辋川，见渭川农事晚归而作。写田家暮景之闲逸，末叹己不得归隐，反用《式微》。","zhu":[{"w":"墟落","v":"村落。"},{"w":"穷巷","v":"深僻的小巷。"},{"w":"雉雊","v":"野鸡鸣叫。雊，野鸡叫声。"},{"w":"蚕眠","v":"蚕蜕皮时不食不动，称蚕眠。"},{"w":"式微","v":"《诗经》篇名，有「式微式微，胡不归」句，表归隐之思。"}],"yi":"斜阳照着村落，深巷里牛羊归来。老人惦记牧童，倚杖等在柴门。野鸡鸣叫麦苗吐秀，蚕儿眠了桑叶稀疏。农夫扛锄而立，相见时话语依依。见此情景真羡其闲逸，怅然吟起《式微》。","shang":"全篇白描田家暮景，牛归、雉雊、蚕眠、荷锄，皆是寻常物事而生气盎然。结句「怅然吟式微」一转，闲逸之羡化为己之不得归，含蓄有味。"},"017":{"ti":"王维咏西施，借其由贱而贵的际遇，讽世间但重艳色、不辨真伪，并戒效颦者之妄求。","zhu":[{"w":"西施","v":"春秋越国美女，后被献于吴王夫差。"},{"w":"宁久微","v":"岂会长久卑微。"},{"w":"越溪","v":"若耶溪，西施浣纱处。"},{"w":"傅脂粉","v":"涂抹脂粉。傅，涂抹。"},{"w":"浣纱","v":"洗纱。西施贫贱时曾浣纱于溪。"},{"w":"效颦","v":"模仿西施捧心皱眉。丑女效之更丑，见《庄子》。"}],"yi":"艳色天下人看重，西施岂会长久卑微。早上还是越溪的浣纱女，傍晚便成了吴宫的王妃。贫贱时与众人何异，显贵后才觉其稀罕。她邀人替她敷粉，自己不肯穿罗衣。君宠越深越娇媚，君爱越甚便无是非。当年一同浣纱的伙伴，再不能同车而归。且告知邻家女子，效颦哪里可以希求！","shang":"「贱日岂殊众，贵来方悟稀」讽刺世态炎凉入骨。末以效颦作结，劝戒中带冷峻。王维此篇一改山水清音，笔锋见锋芒。"},"018":{"ti":"孟浩然秋日登岘山寄友张五。写登高怀人之情与清秋之景，末期重阳共醉，情深而语淡。","zhu":[{"w":"北山","v":"指岘山，在今湖北襄阳。"},{"w":"怡悦","v":"和悦自得。"},{"w":"薄暮","v":"傍晚。"},{"w":"荠","v":"荠菜，此喻远树细小如荠。"},{"w":"洲如月","v":"江中沙洲形如弯月。"},{"w":"重阳节","v":"农历九月初九，古有登高饮菊花酒之俗。"}],"yi":"北山白云深处，隐者怡然自悦。相望而登高，心随孤雁飞灭。愁绪因薄暮而起，兴致是清秋所发。时见归村之人，走过沙岸在渡口歇息。天边树木小如荠菜，江畔沙洲弯似月牙。何时你能载酒而来，同醉在这重阳佳节。","shang":"「天边树若荠，江畔洲如月」以极远极细之物写登高所见，视野空阔，是孟诗名句。由「相望」起，以「共醉」终，一望一期，情意自见。"},"019":{"ti":"孟浩然夏夜于南亭纳凉怀友辛大。写荷风竹露之清境，因无知音而怀人，笔致清幽。","zhu":[{"w":"辛大","v":"孟浩然友人，排行第一，名字不详。"},{"w":"散发","v":"披散头发，指闲适不拘。"},{"w":"开轩","v":"打开窗子。轩，有窗的长廊或小屋。"},{"w":"闲敞","v":"宽敞清凉。"},{"w":"中宵","v":"半夜。"}],"yi":"山光忽然西落，池月渐渐东升。披散头发乘夜凉，开窗躺在宽敞处。荷风送来香气，竹露滴下清响。想取琴来弹，恨无知音欣赏。念此怀念故人，夜半徒劳梦想。","shang":"「荷风送香气，竹露滴清响」以嗅觉写风、以听觉写露，清绝入微，为纳凉诗绝唱。由境之清转出音之无知，怀人之意自然流出，不着一字而情味无穷。"},"020":{"ti":"孟浩然于僧舍候友丁大不至而作。写待客不至的孤寂，末以孤琴候于萝径作结，闲淡而有韵味。","zhu":[{"w":"业师","v":"对僧人的敬称。"},{"w":"丁大","v":"孟浩然友人，排行第一。"},{"w":"倏","v":"忽然，很快。"},{"w":"清听","v":"清越的听觉感受，指风声泉声入耳。"},{"w":"之子","v":"这个人，指所候之人。"},{"w":"期宿","v":"约定留宿。"}],"yi":"夕阳越过西岭，群山忽然昏暗。松间月色生出夜凉，风泉之声充满耳畔。樵夫归来将尽，飞鸟归林初定。这人约定今夜来宿，孤琴空候在藤萝小径。","shang":"全篇不着一个「待」字，而待之不至自见。黄昏入夜、樵归鸟栖，层层写静，愈静愈显候人之孤。「孤琴候萝径」以物写人，空灵含蓄。"},"021":{"ti":"王昌龄于南斋玩月，忆远在越中的崔少府。写月之盈虚今古，因月怀人，情思渺远。","zhu":[{"w":"南斋","v":"南面的书斋。"},{"w":"帷","v":"帐幕、帘子。"},{"w":"演漾","v":"水波荡漾的样子，此写月光浮动。"},{"w":"盈虚","v":"月圆月缺。"},{"w":"越吟","v":"越地的吟唱。用越人庄舄仕楚而思乡作越吟事，喻思乡。"},{"w":"兰杜","v":"兰草与杜若，两种香草，喻美好情谊。"}],"yi":"闲卧南斋之时，拉开帷幕月儿初升。清辉淡照着水木，荡漾在窗上。月圆月缺几度，澄明之间今古已变。那人正在清江之畔，此时定在作越地之思。千里之遥又如何，微风送来兰杜之香。","shang":"由玩月而及月之盈虚今古，时空顿阔。「千里其如何，微风吹兰杜」以无形之香通千里之隔，化远为近，情韵悠长。"},"022":{"ti":"丘为访西山隐者不遇而作。虽不见人，却得山水清境，末言「兴尽方下山」，见求隐之趣。","zhu":[{"w":"茅茨","v":"茅草屋顶，指简陋的房舍。"},{"w":"扣关","v":"敲门。关，门闩，代指门。"},{"w":"巾柴车","v":"用布巾装饰柴车，指驾车出行。"},{"w":"差池","v":"参差不齐，此指错过、不遇。"},{"w":"黾勉","v":"勉力，此写空自仰慕。"},{"w":"之子","v":"这个人，指隐者。"}],"yi":"绝顶上一间茅屋，径直上去三十里。敲门却无僮仆，窥看室内只有几案。如非驾车出游，便是在秋水边垂钓。两地错过不相见，空自勉力仰慕。草色在新雨中青翠，松声在晚窗里清响。到此契合幽绝之意，自足以来荡涤心耳。虽无宾主之礼，颇得清净之理。兴尽方才下山，何必一定要等到他。","shang":"访人不遇而不以为憾，反以山水清境自足，立意已高人一等。「草色新雨中，松声晚窗里」十字写尽空山清境。结句洒脱，见隐者襟怀。"},"023":{"ti":"綦毋潜春夜泛若耶溪而作。写晚风花路、潭烟林月之景，末愿作持竿之叟，寄归隐之志。","zhu":[{"w":"若耶溪","v":"在今浙江绍兴，相传西施浣纱处。"},{"w":"幽意","v":"幽闲自适的情意。"},{"w":"所偶","v":"所遇。随所偶，谓随遇而安。"},{"w":"际夜","v":"入夜之时。际，接近。"},{"w":"南斗","v":"南斗六星，在南方。"},{"w":"持竿叟","v":"垂钓的老人，指隐者。"}],"yi":"幽闲之意无有断绝，此去随遇而安。晚风吹动行舟，花径通入溪口。入夜转入西壑，隔山遥望南斗。潭上烟雾飞腾溶溶，林间月儿低低后退。世事且任其纷繁，我愿做个持竿老翁。","shang":"「潭烟飞溶溶，林月低向后」写夜舟行进，烟月皆有动势，画笔所不能到。以「愿为持竿叟」作结，与开篇「幽意」呼应，归隐之志首尾一贯。"},"024":{"ti":"常建过访王昌龄隐居处而作。写清溪孤云、松月药院之幽，末言己亦将谢世归隐。","zhu":[{"w":"王昌龄","v":"盛唐诗人，常建友人，曾隐居石门山。"},{"w":"鸾鹤","v":"鸾鸟与仙鹤，喻仙侣、隐逸之伴。"},{"w":"谢时","v":"辞别时世，指归隐。"},{"w":"药院","v":"种药的庭院。"}],"yi":"清溪深不可测，隐居之处唯有孤云。松间露出微月，清光还似为你而照。茅亭里宿着花影，药院中滋长苔纹。我也想辞世归隐，去西山与鸾鹤为群。","shang":"「松际露微月，清光犹为君」写月有情，是待人亦是怀人，最见清妙。全篇清冷幽寂，「犹为君」三字把物与人绾合，隐者风神宛在。"},"025":{"ti":"岑参与高适、薛据同登长安慈恩寺大雁塔，写塔之高峻与登临之感，末悟佛理、欲挂冠归隐。","zhu":[{"w":"慈恩寺","v":"唐长安名寺，内有玄奘所建大雁塔。"},{"w":"浮图","v":"佛塔，即大雁塔。"},{"w":"磴道","v":"上塔的石阶之道。磴，石阶。"},{"w":"鬼工","v":"鬼斧神工，极言建造之精奇。"},{"w":"五陵","v":"汉代五座帝陵，在长安北。"},{"w":"净理","v":"佛家清净之理。"},{"w":"挂冠","v":"辞去官职。"}],"yi":"塔势如涌地而出，孤高耸入天宫。登临便出离尘世，蹬道盘旋虚空。突兀高耸压着神州，峥嵘好似鬼斧神工。四角遮住白日，七层摩着苍穹。下窥指点飞鸟，俯首听得惊风。群山如波涛，奔涌向东。青槐夹着驰道，宫馆何等玲珑！秋色从西而来，苍然布满关中。五陵在北原之上，万古青蒙一片。清净之理全然可悟，胜因本是我一向所宗。发誓将要挂冠而去，以觉道滋养无穷。","shang":"「塔势如涌出，孤高耸天宫」起笔即奇，「下窥指高鸟，俯听闻惊风」以俯仰写高，境界壮阔。由景入理，结以挂冠悟道，是岑参雄奇兼禅意的一篇。"},"026":{"ti":"元结任道州刺史时作。序述西原贼不犯道州而官府征敛更甚于贼，诗中直斥「使臣将王命，岂不如贼焉」，为新乐府运动之先声。","zhu":[{"w":"井税","v":"仿井田制的赋税，此指太平年代的轻税。"},{"w":"戎旃","v":"军旗，代指战事。旃，赤色曲柄旗。"},{"w":"典斯郡","v":"治理此郡。典，主管。"},{"w":"征敛","v":"征收赋税。"},{"w":"符节","v":"古代朝廷委任官员的信物，代指官职。"},{"w":"刺船","v":"撑船。"},{"w":"时世贤","v":"世俗所誉的「贤能」，此为反语。"}],"yi":"早年逢太平之世，在山林中过了二十年。泉源就在庭院，山洞当着门前。赋税有定期，天晚犹可安眠。忽然遭逢时变，几年间亲历战事。如今来掌管此郡，山夷又纷纷作乱。小城贼人不屑屠戮，百姓贫困实在可怜。因此邻境都遭攻陷，唯独此州得以保全。使臣奉王命来催征，岂能不如贼人狠毒！那班征敛之徒，把百姓逼入火煎。谁忍绝人之命，来博当世「贤名」！我要弃官委符节，拿竹竿自己撑船。带着家眷去渔麦之乡，归老江湖边。","shang":"与《舂陵行》同为杜诗所称的现实主义力作。「岂不如贼焉」直斥使臣酷于贼，语极激烈。结以弃官归老，愤世而不失刚正。诗风朴质，不事雕琢而意足。"},"027":{"ti":"韦应物任苏州刺史时，雨中宴集文士而作。自惭居崇而未睹民康，宴饮中见仁者之心，为名臣雅篇。","zhu":[{"w":"画戟","v":"彩饰的戟，官署陈列的仪仗。"},{"w":"宴寝","v":"休息安寝的便室。"},{"w":"烦疴","v":"烦闷不适之疾。"},{"w":"金玉章","v":"指文士的美好诗篇。"},{"w":"群彦","v":"众多才俊之士。"},{"w":"大蕃","v":"大郡，此指苏州。"}],"yi":"卫兵森列着画戟，便室凝聚清香。海上风雨骤至，池阁一派清凉。烦闷的病近于消散，嘉宾又已满堂。自惭居处崇隆，未见得百姓安康。通晓事理是非自遣，性情旷达形迹两忘。鲜肥之味正逢时禁，幸有蔬果可以品尝。低头饮下一杯酒，仰头聆听金玉之章。精神欢畅身体轻快，直想凌风飞翔。吴中文风兴盛，群彦如今浩瀚如汪洋。方知这大郡气象，岂止财赋之强。","shang":"「兵卫森画戟，宴寝凝清香」气象整肃，为白居易激赏。宴集中忽出「自惭居处崇，未睹斯民康」，一片惭愧之心使通篇雅宴有了筋骨。"},"028":{"ti":"韦应物离开扬州（广陵）溯江赴洛阳，舟中寄友元大而作。写别时凄凄、归途怅惘，结以人生如波上舟。","zhu":[{"w":"扬子","v":"扬子津，在长江北岸，今江苏扬州附近。"},{"w":"元大","v":"韦应物友人，排行第一。"},{"w":"校书","v":"校书郎，掌校勘典籍的官。"},{"w":"泛泛","v":"船行漂荡的样子。"},{"w":"归棹","v":"归去的船。棹，船桨。"},{"w":"残钟","v":"余钟，渐远的钟声。"},{"w":"沿洄","v":"顺流而下与逆流而上，喻人生顺逆。"}],"yi":"凄凄然辞别亲爱之人，船儿漂荡没入烟雾。乘船归去的洛阳人，回望广陵，只余钟声与树影。今朝在此相别，何处还能相遇？世事正如波上的船，顺流逆流哪里由得自己。","shang":"「归棹洛阳人，残钟广陵树」十个字，人已去而钟犹在，怅惘之情画不出来。「世事波上舟」以舟行喻身世，与开篇烟雾相应，淡语有远韵。"},"029":{"ti":"韦应物任滁州刺史，秋冷念山中道士而作。欲持酒远慰而迹不可寻，一篇尽是牵挂与惆怅。","zhu":[{"w":"全椒","v":"今安徽全椒县，唐属滁州。"},{"w":"郡斋","v":"郡守官署中的起居之所。"},{"w":"涧底","v":"山涧底下。"},{"w":"束荆薪","v":"捆扎柴草。荆薪，荆柴。"},{"w":"煮白石","v":"煮白石为粮。旧传神仙白石先生煮白石，此喻道士清苦。"},{"w":"空山","v":"空寂的山林。"}],"yi":"今天郡斋清冷，忽然想念山中的客人。你在涧底捆柴归来，回来煮那白石。想带上一瓢酒，远来慰你风雨之夕。可是落叶落满空山，何处寻你的行迹？","shang":"「落叶满空山，何处寻行迹」一片空灵，禅家以为悟境。前六句情愈热，末二句境愈空，牵挂尽在「何处」一问之中。苏轼欲续之而不能，可见其妙。"},"030":{"ti":"韦应物在长安遇故人冯著。以采山买斧写其失意归隐，末问鬓丝几缕，故人深情尽在闲谈中。","zhu":[{"w":"冯著","v":"韦应物友人，曾应征辟而仕途不遇。"},{"w":"灞陵","v":"即霸陵，汉文帝陵，在长安东，多植柳。"},{"w":"采山","v":"入山采伐，指隐居谋生。"},{"w":"买斧","v":"买斧入山，用《诗经》「取彼斧斨，以伐远扬」意，喻有所经营。"},{"w":"冥冥","v":"花悄然开放的样子。"},{"w":"扬扬","v":"燕子飞舞的样子。"},{"w":"燕新乳","v":"燕子初哺育新雏，指春深。"}],"yi":"客人从东方来，衣上带着灞陵的雨。问客为何而来，说是进山采樵要买斧。花儿冥冥正开，燕子扬扬初哺新雏。去年一别转眼又春，鬓边白丝生了几缕？","shang":"以「采山因买斧」代答失意，怨而不露；「冥冥花正开，扬扬燕新乳」以春光反照身世，兼含劝勉。末句一问，故人惦念尽在其中。"},"031":{"ti":"韦应物舟行夜泊盱眙而作。写孤驿风波之夕，忆秦关故园，见羁旅难眠之思。","zhu":[{"w":"盱眙","v":"县名，今属江苏，临淮水。"},{"w":"次","v":"停宿。"},{"w":"落帆","v":"卸下船帆。"},{"w":"淮镇","v":"淮水边的市镇，指盱眙。"},{"w":"孤驿","v":"孤零的驿站。"},{"w":"芦洲","v":"芦苇丛生的洲渚。"},{"w":"秦关","v":"指长安（作者家乡关中）。"}],"yi":"落帆停泊在淮上小镇，船傍着孤驿。浩浩风起浪涌，天色冥冥日沉西夕。人们归去山郭昏暗，雁下芦洲一片白。独夜忆念秦关，听着钟声，我这个未眠之客。","shang":"「人归山郭暗，雁下芦洲白」对仗天成，暮景如画。末二句「忆秦关」与「未眠客」并置，以听钟串起乡思，余音袅袅。"},"032":{"ti":"韦应物公务之余出郊散怀而作。写东郊春景之可乐，自叹吏事拘身，末期结庐学陶。","zhu":[{"w":"局终年","v":"终年被拘束在官署。"},{"w":"旷清曙","v":"在清朗的晨光中心胸开阔。"},{"w":"澹","v":"涤荡，使……澄清。"},{"w":"缘涧","v":"沿着山涧。"},{"w":"霭","v":"云气笼罩。"},{"w":"遵事","v":"遵守职守。遵，循。"},{"w":"慕陶","v":"仰慕陶渊明归隐田园。"}],"yi":"在官舍拘束终年，出郊在清晓光中胸怀顿开。杨柳间散着和风，青山涤荡我的思虑。靠着树丛随意歇息，沿着山涧走了又回。微雨笼罩芳草原，春鸠在何处鸣叫？爱幽之心屡屡涌起，碍于职守脚步匆匆。终当辞官在此结庐，归隐之心可以实现了。","shang":"「杨柳散和风，青山澹吾虑」一散一澹，物我互化，见韦诗清润本色。结句慕陶直白而出，与前文「乐幽心屡止」相应，仕隐之矛盾毕现。"},"033":{"ti":"韦应物送长女嫁往杨氏而作。写父女别离之情与嫁女之嘱，语重心长，为唐人送嫁名篇。","zhu":[{"w":"杨氏女","v":"韦应物长女，嫁与杨氏。"},{"w":"有行","v":"出嫁。《诗经》「女子有行，远父母兄弟」。"},{"w":"无恃","v":"失去依靠，指丧母。"},{"w":"阙内训","v":"缺少母亲在闺内的教导。阙，同「缺」。"},{"w":"事姑","v":"侍奉婆婆。姑，婆母。"},{"w":"令门","v":"好人家。"},{"w":"资从","v":"嫁妆。"},{"w":"猷","v":"规矩，准则。"}],"yi":"整日里正自忧伤，女儿出嫁更添怅惘。今日你有行远嫁，大江之上溯流轻舟。你们姐妹苦于无母，我抚念愈觉慈柔。幼者由姐姐养育，临别两两泣不成声。对此郁结中肠，义不容辞难以再留！自小缺少母训，侍奉婆母令我担忧。幸而托身好人家，仁爱体恤应无过失。贫俭实在是我所尚，嫁妆岂必求全。惟愿你孝恭遵妇道，容止顺从规矩。别离就在今晨，再见不知何秋。闲居时还能自遣，临到感伤忽难收束。归来望着小女，泪水顺着帽缨流淌。","shang":"通篇家常语，絮絮如话，而慈父之情字字恳挚。「居闲始自遣，临感忽难收」写情之不能自制，极真。此诗在送别诗别开生面，见杜诗以来的伦理诗传统。"},"034":{"ti":"柳宗元贬永州后，晨起读佛经而作。自悔于真源无取、世逐忘迹，以寺院清境收束，寓怀才被逐之愤。","zhu":[{"w":"贝叶书","v":"佛经。古印度以贝多罗树叶写经。"},{"w":"真源","v":"真正的本源，指佛理真谛。"},{"w":"忘迹","v":"忘却形迹，指俗世追名逐利的皮相。"},{"w":"冥","v":"暗合。"},{"w":"缮性","v":"修养本性。语出《庄子》。"},{"w":"膏沐","v":"润发油脂，此喻青松如洗过一般润泽。"},{"w":"离言说","v":"超乎言语之外。谓妙悟不可言传。"}],"yi":"汲来井水漱洗寒齿，清了心又拂去衣尘。闲持佛经一卷，步出东斋去读。真谛我却毫无领会，世人追逐的不过是皮相。先贤遗言本望暗合，修养之性何由纯熟？道人庭院幽静，苔色连着深竹。日出雾露未干，青松如膏沐一般。澹然超于言语之外，悟悦之心自足。","shang":"读经而不入，一转而入庭院清境，「日出雾露馀，青松如膏沐」以画境代禅理，无言而悟。「澹然离言说」收束全篇，贬谪之愤皆化于外，是柳诗以峻洁掩悲愤的一格。"},"035":{"ti":"柳宗元贬永州司马后作。以「幸」字自嘲贬谪，写溪居闲放，正话反说，愤懑见于言外。","zhu":[{"w":"簪组","v":"簪与冠带，官吏的服饰，代指官职。"},{"w":"南夷","v":"南方边远之地，指永州。"},{"w":"农圃","v":"农田园圃。"},{"w":"偶似","v":"偶然相像，貌似而实非。"},{"w":"榜","v":"划船。"},{"w":"楚天","v":"永州古属楚地，故称楚天。"}],"yi":"长久为官职所累，如今幸而贬到这南夷之地。闲来与农圃为邻，偶尔像山林中人。清晨耕作翻开带露的草，夜里划船响彻溪石。来往遇不到人，对着碧蓝楚天放声长歌。","shang":"「幸此南夷谪」一个「幸」字，满腹牢骚以反语出之，愈见沉痛。通篇似闲适，实则「来往不逢人」正写谪居之孤。此即苏轼所谓柳诗「外枯而中膏」者。"},"036":{"ti":"王昌龄边塞乐府。写八月萧关道上戍卒老于沙场，讽游侠儿的矜夸浮华，悲慨之中有规劝。","zhu":[{"w":"空桑林","v":"叶已落尽的桑林。"},{"w":"萧关","v":"关中通塞外要隘，在今宁夏固原。"},{"w":"幽并","v":"幽州、并州，古多慷慨侠士之地。"},{"w":"沙场老","v":"终老于沙场。"},{"w":"游侠儿","v":"自恃勇武、放荡不羁的人。"},{"w":"紫骝","v":"良马名，泛指骏马。"}],"yi":"蝉鸣在空了的桑林，八月的萧关道上。出塞又入塞，处处是枯黄的芦草。自古以来幽并的健儿，都在沙场上老去。莫学那游侠少年，只知夸耀骏马华服。","shang":"以「幽并客皆向沙场老」之沉痛，反衬游侠儿「矜夸紫骝好」之轻浮，一庄一谑，边塞诗中别具规劝之格。前四句写景苍凉，已含倦意。"},"037":{"ti":"王昌龄边塞乐府。写秋水饮马、临洮怀古，以长城旧战的白骨收束，反战之意深沉。","zhu":[{"w":"饮马","v":"给马喝水。"},{"w":"临洮","v":"今甘肃岷县，秦长城西端起处，古战场。"},{"w":"黯黯","v":"昏暗模糊的样子。"},{"w":"咸言","v":"都说。"},{"w":"黄尘足今古","v":"黄沙漫卷古今。足，充满。"},{"w":"蓬蒿","v":"蓬草与蒿草，指荒野。"}],"yi":"牵马渡过秋水，水寒风利如刀。平沙之上落日未沉，昏暗中望见临洮。昔日长城下的战事，都说将士意气高。黄尘亘古亘今，白骨散乱在蓬蒿。","shang":"前四句写景，寒水如刀、日色黯黯，已伏悲音；后四句今昔对照，「咸言意气高」与「白骨乱蓬蒿」相激，讽意全在对比之中。短章而深悲，边塞诗中当推上乘。"},"038":{"ti":"李白乐府《关山月》。以天山明月起兴，写万里边关征人未还、两地相思，气魄浩大。","zhu":[{"w":"天山","v":"今甘肃、新疆一带的祁连山，古称天山。"},{"w":"玉门关","v":"今甘肃敦煌西，古通西域要道。"},{"w":"白登","v":"白登山，在今山西大同，汉高祖曾被匈奴围于此。"},{"w":"胡窥","v":"胡人窥伺。"},{"w":"青海湾","v":"青海湖，唐与吐蕃争战之地。"},{"w":"戍客","v":"驻守边地的兵士。"}],"yi":"明月出天山，升起在苍茫云海之间。长风几万里，吹度玉门关。汉家兵士下白登道，胡人窥探青海湾。自古以来征战之地，不见有人生还。戍卒望着边地景色，思念归乡满面愁容。今夜高楼上的思妇，叹息应不曾停歇。","shang":"「明月出天山，苍茫云海间」十字便有万里之势，为唐人边塞月色之冠。由戍客之望转到高楼之思，两地相照，全篇悲而不促，浩气与柔情兼得。"},"039":{"ti":"李白乐府《子夜四时歌》春歌。写秦地采桑女罗敷的健美与机敏，民歌风味盎然。","zhu":[{"w":"罗敷","v":"汉乐府《陌上桑》中的采桑女，此泛指采桑女子。"},{"w":"素手","v":"白皙的手。"},{"w":"红妆","v":"指女子盛妆，此指其面容服饰。"},{"w":"蚕饥","v":"蚕饿需喂，采桑女急归之由。"},{"w":"五马","v":"太守的车驾五马，指追随调笑的贵官。"},{"w":"留连","v":"逗留，纠缠。"}],"yi":"秦地的罗敷姑娘，在绿水边采桑。素手攀着青条，红妆映得白日也鲜亮。蚕儿饿了我要回去，太守的车驾请莫纠缠。","shang":"「素手青条上，红妆白日鲜」设色明丽，人、物、光交映如画。末二句借罗敷之口拒官，爽利见性，与《陌上桑》一脉相承而更见唐人气象。"},"040":{"ti":"李白乐府《子夜四时歌》夏歌。写西施五月采莲若耶溪的盛景，以「不待月」见其急归王家的命运。","zhu":[{"w":"镜湖","v":"在今浙江绍兴，一名鉴湖。"},{"w":"菡萏","v":"荷花的花苞。"},{"w":"隘若耶","v":"围观者把若耶溪都挤窄了。隘，窄。"},{"w":"回舟","v":"回转船头。"},{"w":"越王家","v":"越王宫中，谓西施被选入宫。"}],"yi":"镜湖三百里，菡萏开遍荷花。五月里西施采莲，围观的人多得把若耶溪挤窄。她不等月出便回舟，归到越王家中去了。","shang":"三百里镜湖只为一双采莲手设色，以壮阔衬窈窕，是李白笔法。「人看隘若耶」极写倾城之貌，不着一字正面描写，结句归入王家，艳羡之下微含惋惜。"},"041":{"ti":"李白乐府《子夜四时歌》秋歌。以长安月夜捣衣声起，写征妇玉关之思，四时歌中最负盛名。","zhu":[{"w":"捣衣","v":"捣洗布帛使之平软，为寒衣备料，秋夜事。"},{"w":"玉关","v":"玉门关，征人戍守之地。"},{"w":"胡虏","v":"指北方入侵之敌。"},{"w":"良人","v":"丈夫。"},{"w":"罢远征","v":"停止远征，得以还家。"}],"yi":"长安一片明月，千家万户的捣衣声。秋风吹不尽的，总是玉门关的情思。何日平定胡虏，我的良人从此不再远征？","shang":"「长安一片月，万户捣衣声」以月为底、以声为纹，秋思如潮而不见愁字，故温婉而不哀苦。结以「何日平胡虏」，个人之思与家国之愿相合，遂成千古调。"},"042":{"ti":"李白乐府《子夜四时歌》冬歌。写思妇一夜絮袍、明朝寄远，以素手之冷写心情之热。","zhu":[{"w":"驿使","v":"传递公文的人，此指寄衣之使。"},{"w":"絮征袍","v":"往冬衣里铺絮。絮，动词。"},{"w":"素手","v":"白皙的手。"},{"w":"临洮","v":"征人戍守的边地。"}],"yi":"明朝驿使就要出发，一夜赶着为征袍絮棉。素手抽针已经冰冷，何况还要把住剪刀。裁缝好了寄往远方，几日才能到临洮？","shang":"全篇就一夜之间写尽思妇之情：「素手抽针冷」五字，针冷手寒而心热，字字可感。以问句收，急切之状如见，与秋歌合读，一歌月、一歌雪，两相辉映。"},"043":{"ti":"李白乐府《长干行》。以商妇自述，从总角之嬉写到离别之思，缠绵悱恻，与《孔雀东南飞》同调。","zhu":[{"w":"剧","v":"嬉戏。"},{"w":"竹马","v":"儿童跨竹为马的游戏。"},{"w":"青梅","v":"青的梅子，与竹马并称总角之谊。"},{"w":"抱柱信","v":"《庄子》尾生与女子期于桥下，水至不去，抱柱而死。喻坚守信约。"},{"w":"望夫台","v":"传说妇人登台望夫化石之处。"},{"w":"滟滪堆","v":"瞿塘峡口险滩，五月水涨最险。"},{"w":"三巴","v":"巴郡、巴东、巴西，今川东，泛指蜀地。"},{"w":"长风沙","v":"在今安徽安庆东，距金陵数百里，谓迎候之远。"}],"yi":"我发初覆额，折花门前戏。郎骑竹马来，绕床弄青梅。同居长干里，两小无嫌猜。十四为君妇，低头向暗壁，千唤不一回。十五始展眉，愿同尘与灰。常存抱柱信，岂上望夫台！十六君远行，瞿塘滟滪堆险不可触。猿声天上哀。门前君行迹，一一生绿苔。苔深不能扫，秋风落叶早。八月蝴蝶来，双飞西园草。感此伤妾心，坐愁红颜老。早晚下三巴，预将书报家。相迎不道远，直至长风沙。","shang":"由「折花门前剧」到「直至长风沙」，以年岁为经、以细节为纬，把一生写成了诗。斑苔、蝴蝶、秋风，处处以物寄情；「愿同尘与灰」与「岂上望夫台」两语，誓言与惊觉相照，痴情之至。六朝乐府之清新，盛唐歌行之奔放，兼而有之。"},"044":{"ti":"孟郊乐府《列女操》。以梧桐鸳鸯殉情起兴，喻贞妇之志，末以「井中水」自誓，寒瘦诗风中的贞刚之音。","zhu":[{"w":"梧桐相待老","v":"梧为雄树、桐为雌树，同生同死。"},{"w":"鸳鸯会双死","v":"鸳鸯成对，一死则双亡。"},{"w":"殉夫","v":"为丈夫守节而死。"},{"w":"波澜","v":"此指心的波动。"},{"w":"井中水","v":"井水不为风波所动，喻心志贞定。"}],"yi":"梧桐相守到老，鸳鸯注定同死。贞妇贵在殉夫，舍生也当如此。发誓心湖不起波澜，我的心是井中之水。","shang":"孟郊以苦吟称，此篇独见贞刚：「妾心井中水」五字凝定如铸。以物性之必然喻人情之当然，虽是旧调，却写出了金石之声。"},"045":{"ti":"孟郊《游子吟》。题下自注「迎母溧上作」，以缝衣细节写母爱，为千古写母恩第一诗。","zhu":[{"w":"临行","v":"临出门远行之际。"},{"w":"密密缝","v":"一针一线缝得细密，惟恐儿久出不归。"},{"w":"迟迟归","v":"迟迟不归。"},{"w":"寸草心","v":"小草的嫩心，喻儿女微薄的报答之心。"},{"w":"三春晖","v":"春天三个月的阳光，喻母恩浩大。"}],"yi":"慈母手中的线，缝在游子身上的衣。临行缝得密密实实，唯恐孩儿迟迟不归。谁说小草般的心意，报答得了三春的阳光？","shang":"以「密密缝」一个动作写尽母爱，不用一言颂词而慈恩如在目前。末二句以寸草对三春，比例悬殊处正是母恩无穷处。语浅情深，遂成千古母爱之歌。"},"046":{"ti":"陈子昂随武攸宜征契丹，进言不用反遭贬抑，登蓟北楼（幽州台）而作。怀才不遇之愤，一唱三叹。","zhu":[{"w":"幽州台","v":"即蓟北楼，故址在今北京，战国时燕昭王筑黄金台招贤于此。"},{"w":"古人","v":"前代的贤君与贤士。"},{"w":"来者","v":"后世有远见的明君。"},{"w":"悠悠","v":"长远无穷的样子。"},{"w":"怆然","v":"悲伤的样子。"},{"w":"涕下","v":"落泪。"}],"yi":"向前望不见古人，向后望不见来者。想到天地如此悠悠无极，独个儿怆然泪下！","shang":"寥寥二十二个字，直抒胸臆而无一景一物，却把整个宇宙的苍茫与一个人的孤独写尽了。不事雕琢、不落比喻，全凭时间的纵深撑开境界，是唐音中最具「风骨」的一章，一千三百年来无人能续。"},"047":{"ti":"李颀拟古乐府《古意》。写幽燕少年重然诺、轻生死，结以辽东小妇一曲羌笛，三军堕泪，刚极而柔极。","zhu":[{"w":"事长征","v":"从事远征戍边之事。"},{"w":"幽燕客","v":"幽州、燕地（今河北北部）的游侠。"},{"w":"轻七尺","v":"看轻七尺之躯，谓不怕死。"},{"w":"莫敢前","v":"敌人不敢上前。"},{"w":"猬毛磔","v":"胡须像刺猬毛一样张开。磔，张开。"},{"w":"陇底","v":"陇山之下。"}],"yi":"男儿从事远征，少年时就做了幽燕的客人。在马蹄下赌胜逞强，从来不把性命看重。杀人时无人敢近前，胡须根根如猬毛张开。黄云压着陇底白雪纷飞，未报国恩不肯还乡。辽东小妇年方十五，惯弹琵琶又能歌舞。今以羌笛吹出塞之声，使我三军泪落如雨！","shang":"前六句写豪侠，须发磔张如画；「黄云陇底白雪飞」一句塞外苍茫。结尾忽以一小妇一羌笛收束，铁血之泪为管弦所引，刚柔相激，余响无穷。"},"048":{"ti":"李颀送友人陈章甫罢官还乡而作。写其坦荡博学而不遇，罢官之叹以旷达出之，是送别诗中的豪宕之作。","zhu":[{"w":"虬须","v":"卷曲的胡须。"},{"w":"大颡","v":"宽大的额头。颡，额。"},{"w":"贮书","v":"贮藏书籍，谓学识渊博。"},{"w":"草莽","v":"草野，指民间。"},{"w":"酤酒","v":"买酒。"},{"w":"津口","v":"渡口。"},{"w":"郑国游人","v":"指陈章甫（原籍开封，古郑地）。"},{"w":"洛阳行子","v":"作者自指。"}],"yi":"四月南风吹黄了大麦，枣花未落桐叶正长。青山早晨辞别暮晚还见，出门的嘶马也思念故乡。陈侯立身何等坦荡，虬须虎眉又有宽额。腹中贮书一万卷，不肯低头处草莽。东门买酒与我一辈同饮，心轻万事如鸿毛。醉卧不知白日已暮，有时空望孤云之高。长河浪头连天皆黑，津口停舟渡不得。郑国游人还未到家，洛阳行子空自叹息。听说你故旧相识很多，昨日罢官今日又如何？","shang":"「腹中贮书一万卷，不肯低头在草莽」写尽狂士风骨。末句「罢官昨日今如何？」一问收束，不慰之慰最见深情。写景如「四月南风大麦黄」，化工之笔。"},"049":{"ti":"李颀奉使淮上，夜宴听琴而作。写月下听琴之静之妙，末句「敢告云山从此始」，遂萌归隐之志。","zhu":[{"w":"广陵客","v":"善琴之人。广陵散为古琴名曲，故以广陵客称琴师。"},{"w":"乌半飞","v":"乌鸦半起半飞，写夜静。"},{"w":"渌水","v":"古琴曲名。"},{"w":"楚妃","v":"《楚妃叹》，古琴曲名。"},{"w":"清淮","v":"清澈的淮水，作者奉使所往。"},{"w":"敢告","v":"冒昧相告。"}],"yi":"主人有酒欢乐今夕，请出善琴的广陵客奏琴。月照城头乌鸦半飞，霜侵万树寒风入衣。铜炉华烛烛光增辉，先弹《渌水》后奏《楚妃》。一声既出万物皆静，四座无言星光渐稀。奉使清淮千余里，请让我说：归隐云山从此开始！","shang":"「一声已动物皆静，四座无言星欲稀」写琴声之静，以宇宙之静写琴，是唐人写音乐的神来之笔。结句忽然收去，千般琴意化为归隐一念。"},"050":{"ti":"李颀听董庭兰弹胡笳声，兼寄语房琯给事。从蔡琰制曲写起，极状琴声之悲凉变化，末以凤凰池盼琴师日夕而至。","zhu":[{"w":"蔡女","v":"蔡琰（文姬），博学通音律，曾作《胡笳十八拍》。"},{"w":"一十有八拍","v":"《胡笳十八拍》共十八段。拍，乐曲的段落。"},{"w":"商弦","v":"古琴七弦分属宫商角徵羽五音，商弦为第二弦，角羽为其后各弦。"},{"w":"摵摵","v":"叶落声。"},{"w":"乌孙","v":"汉西域国名，此借指远嫁之思。"},{"w":"逻娑","v":"吐蕃都城逻些（今拉萨），借指边地哀怨。"},{"w":"东掖垣","v":"宫城东边的墙，指门下省。"},{"w":"凤凰池","v":"中书省的别称。"}],"yi":"当年蔡琰制《胡笳十八拍》，胡人闻之泪落边草，汉使断肠。今夜董夫子先拂商弦、后转角羽，一弹之间秋叶惊落。其声通于神明：迟速应手、往复有情，如空山百鸟散而复合、万里浮云阴而复晴；又如雏雁失群、胡儿恋母，令川静波停、众鸟罢鸣，乌孙之远、逻娑之怨俱在弦中。忽而变调飘洒，如长风吹林、雨落檐瓦，迸泉上树梢、野鹿下堂前。这样的琴，怎能不教凤凰池中那位脱略名利的高人，日夕盼着他抱琴而来？","shang":"以「通神明」「来妖精」极写琴艺，中段连用百鸟浮云、雏雁胡儿、川静鸟罢等意象摹声，字字是声又字字是情。结尾落到房琯之盼，由乐及人，章法奇绝。"},"051":{"ti":"李颀听乐师安万善吹觱篥而作。先写其声之悲，再写其声之奇之变，末以岁夜一杯声一曲，人乐相酬。","zhu":[{"w":"觱篥","v":"又作筚篥，簧管乐器，出西域龟兹。"},{"w":"龟兹","v":"古西域国名，今新疆库车一带。"},{"w":"凉州胡人","v":"凉州（今甘肃武威）的胡人乐师，指安万善。"},{"w":"长飙","v":"大风。"},{"w":"飕飗","v":"风声。"},{"w":"渔阳掺","v":"鼓曲名《渔阳掺挝》，声调悲壮。"},{"w":"杨柳春","v":"指曲调转为《杨柳》一样明媚如春。"}],"yi":"从南山截竹做成觱篥，此乐本出自龟兹。流传汉地曲调愈奇，凉州胡人替我吹奏。邻座闻者多叹息，远客思乡皆垂泪。世人只解听而不解赏，乐声如长风在大风中往来。枯桑老柏寒风飕飗，九只雏凤乱声啾啾。龙吟虎啸一时并发，万籁百泉共赴秋声。忽然更作《渔阳掺》，黄云萧条白日昏暗。变调又如闻杨柳春风，上林繁花照眼一新。岁末高堂列着明烛，美酒一杯声一曲。","shang":"写乐声博喻纷出：风雨龙虎、泉籁凰雏，穷形尽相；「变调如闻杨柳春」一转，由悲入媚。末句人声与乐声对举，「一杯声一曲」五字有至味。"},"052":{"ti":"孟浩然夜归襄阳鹿门山而作。由尘世渡头写到鹿门月照，一篇两境，隐者之心自见。","zhu":[{"w":"鹿门","v":"鹿门山，在襄阳东南，汉末庞德公隐居处。"},{"w":"渔梁","v":"渔梁洲，在襄阳汉水中。"},{"w":"争渡喧","v":"争着渡船，人声喧闹。"},{"w":"烟树","v":"烟雾笼罩的树。"},{"w":"庞公","v":"东汉庞德公，拒绝征辟携家隐鹿门山。"},{"w":"岩扉","v":"石洞的门。"}],"yi":"山寺钟鸣天已黄昏，渔梁渡头一片争渡喧声。人们沿着沙路走向江村，我也乘舟归向鹿门。鹿门月光照开烟树，忽然到了庞公栖隐之处。石门松径长年寂寥，唯有幽人自来自去。","shang":"前半人喧我静，两两对照；后半月照烟树、岩扉松径，一「开」一「寂」，尘心尽洗。「惟有幽人自来去」收束，孤怀与山月相融，是隐逸诗的绝唱。"},"053":{"ti":"李白游庐山，寄赠殿中侍御史卢虚舟。以楚狂自任，写庐山之奇与求仙之志，狂放之气贯注全篇。","zhu":[{"w":"楚狂人","v":"春秋楚人陆通，佯狂不仕，歌「凤兮凤兮」讥孔子。"},{"w":"绿玉杖","v":"镶绿玉的仙杖。"},{"w":"五岳","v":"东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山。"},{"w":"屏风九叠","v":"庐山五老峰东北的九叠云屏。"},{"w":"三石梁","v":"庐山屏风叠左有三叠泉如银河倒挂。"},{"w":"香炉","v":"香炉峰。"},{"w":"还丹","v":"道家炼丹，丹成可服食成仙。"},{"w":"玉京","v":"道教说元始天尊居于玉京。"}],"yi":"我这楚狂人笑傲孔丘，持仙杖辞黄鹤楼，五岳寻仙、遍游名山。庐山秀出南斗之旁：屏风九叠如云锦铺张，三石梁上银河倒挂，与香炉峰瀑布遥遥相望。登高壮观天地，大江茫茫东去，黄云万里、白波九道如流泻雪山。于是好为庐山之歌。闲窥石镜可清我心，谢公游处苔痕犹在。若早服还丹、道心初成，遥想仙人立于彩云，手持芙蓉朝玉京——愿约汗漫之游于九天，接引卢敖同上太清。","shang":"「登高壮观天地间」四句大江雪山，胸襟之阔与庐山之奇相称。以楚狂笑孔丘起，以接卢敖游太清结，狂放与仙气相终始，是李白山水歌行的代表作。"},"054":{"ti":"李白东游前留别东鲁诸公。借梦游天姥山写仙境幻灭，归结「安能摧眉折腰事权贵」，傲骨铮铮。","zhu":[{"w":"瀛洲","v":"传说中的海上仙山。"},{"w":"天姥","v":"山名，在今浙江新昌，道教以为福地。"},{"w":"赤城","v":"赤城山，在天台，土色皆赤。"},{"w":"谢公屐","v":"谢灵运发明的登山木屐，上山去前齿，下山去后齿。"},{"w":"天鸡","v":"神话中桃都山大树上的神鸡，日初出则鸣。"},{"w":"金银台","v":"传说仙人居所以金银筑成。"},{"w":"云之君","v":"云中仙人。"},{"w":"摧眉折腰","v":"低头弯腰，卑躬屈节。"}],"yi":"海客说瀛洲难求，越人说天姥可睹——其势连天横绝，压倒五岳。于是梦游吴越：一夜飞渡镜湖月，湖月送我至剡溪。著屐登梯，半壁见海日、空中闻天鸡；千岩万转中，熊咆龙吟震栗林壑。忽而霹雳裂空、洞天訇然中开：霓衣风马、仙人纷纷而下，列队如麻——忽魂悸魄动，惊起长嗟，枕席之外烟霞尽失。世间行乐原来如此，万事不过东流水。且放白鹿青崖，须行即骑、寻访名山。安能摧眉折腰事权贵，使我不得开心颜！","shang":"梦境愈奇，醒来愈冷，遂逼出「安能摧眉折腰事权贵」的绝叫，此全诗之骨。由梦入仙、由仙返真，章法如天马行空，是李白最见个性的歌行。"},"055":{"ti":"李白游金陵辞别而作。柳花酒香、子弟相送，结以东流水比别意，情深而语爽。","zhu":[{"w":"柳花","v":"柳絮。"},{"w":"吴姬","v":"吴地的女子，指金陵酒店侍女。"},{"w":"压酒","v":"榨酒。压取新酿的酒。"},{"w":"子弟","v":"年轻人。"},{"w":"尽觞","v":"干杯。"},{"w":"东流水","v":"向东南流入江的秦淮水。"}],"yi":"风吹柳花满店飘香，吴姬压出新酒唤客来尝。金陵子弟前来相送，欲行的不行各尽一觞。请君试问东流的江水，别意与它谁短谁长？","shang":"以流水问短长，把不可量的别情化作可较之物，妙问妙答。全篇酒香柳色、笑语骊歌，是李白送别诗中最明快的一首。"},"056":{"ti":"李白在宣州谢朓楼饯别族叔李云。弃我去者、乱我心者，胸中块垒喷薄而出，结以散发扁舟之志。","zhu":[{"w":"校书叔云","v":"李云，任秘书省校书郎，李白族叔。"},{"w":"谢朓楼","v":"南齐诗人谢朓任宣城太守时所建，在宣州。"},{"w":"蓬莱文章","v":"指汉代文章。蓬莱为汉东观藏书之喻。"},{"w":"建安骨","v":"建安年间（曹操父子）刚健遒劲的文风。"},{"w":"小谢","v":"谢朓，别于谢灵运称小谢。"},{"w":"清发","v":"清新秀发。"},{"w":"散发弄扁舟","v":"脱簪散发，驾一叶扁舟归隐江湖。"}],"yi":"弃我而去的，昨日之日不可留。乱我心的，今日之日多烦忧。长风万里送来秋雁，对此可以酣饮高楼。君家有蓬莱文章建安风骨，中间小谢更清新秀发。你我同怀逸兴壮思欲飞，欲上青天揽取明月。抽刀断水水更流，举杯销愁愁更愁。人生在世不称意，明朝散发弄扁舟。","shang":"起二句破空而来，不叙饯别而情绪先声夺人。中段兴会飙举，忽接「抽刀断水水更流」，工愁至此。结以扁舟散发，愤极而出，李白的傲岸全在此。"},"057":{"ti":"岑参奉送封常清出师西征而作。以轮台风吼、碎石乱走极写军行之苦，声势与豪气并盛。","zhu":[{"w":"走马川","v":"地名，在轮台之西。"},{"w":"封大夫","v":"封常清，时任安西节度使，御史大夫。"},{"w":"轮台","v":"在今新疆乌鲁木齐东北，唐置县。"},{"w":"金山","v":"阿尔泰山。"},{"w":"烟尘","v":"战事的烽烟。"},{"w":"戈相拨","v":"兵器相互碰击。"},{"w":"五花连钱","v":"名贵的宝马，其毛色呈五花、连钱之纹。"},{"w":"草檄","v":"起草讨敌文书。"}],"yi":"君不见走马川行营在雪海边，平沙莽莽黄沙连天。轮台九月风声夜吼，一川碎石大如斗。风卷石头满地乱走。匈奴草黄战马正肥，金山西面烟尘飞。汉家大将西出师。将军金甲夜里不脱，半夜行军兵器相击。风头如刀面如割，马毛带雪汗气蒸腾。五花连钱转眼结冰，幕中草檄砚水也凝。虏骑闻风应胆怯，料想短兵不敢相接。只等车师西门献捷报！","shang":"「随风满地石乱走」一笔写尽风力之奇，「风头如刀面如割」「马毛带雪汗气蒸」苦寒入骨。全篇三句一转韵，节奏如战鼓，是唐人边塞歌行的最高峰。"},"058":{"ti":"岑参再送封常清西征。夜角羽书、雪海阴山，写大军出师之雄，末以「功名胜古人」相期。","zhu":[{"w":"吹角","v":"吹响号角。"},{"w":"旄头","v":"星名，即昴星，古人以为主胡兵。"},{"w":"羽书","v":"插羽毛的紧急军书。"},{"w":"渠黎","v":"汉西域国名，在轮台东南。"},{"w":"拥旄","v":"持旄节为将。"},{"w":"阴山","v":"在今内蒙古，泛指北方边塞。"},{"w":"剑河","v":"西域河流名。"},{"w":"亚相","v":"指封常清，以御史大夫摄行相事。"}],"yi":"轮台城头夜里吹角，轮台城北旄头星落。羽书昨夜飞过渠黎，单于已在金山之西。戍楼西望烟尘一片黑，汉兵屯驻轮台北。上将持旄西出征，天明吹笛大军行进。四边伐鼓雪海翻涌，三军齐呼阴山震动。虏塞兵气连云屯聚，战场白骨缠着草根。剑河风急雪片宽阔，沙口石冻马蹄脱落。亚相勤王甘受苦辛，誓将报主平定边尘。古来青史谁人不见，今日功名胜过古人。","shang":"「四边伐鼓雪海涌，三军大呼阴山动」以鼓声呼声撼动天地，写尽唐军之雄。「战场白骨缠草根」一句冷笔，豪气之中自有悲悯。结句壮言，与《白雪歌》恰成一面。"},"059":{"ti":"岑参送武判官归京。以八月飞雪、千树梨花写胡天奇景，雪中送别，情深见于「雪上空留马行处」。","zhu":[{"w":"白草","v":"西域牧草名，秋熟变白。"},{"w":"胡天","v":"塞外的天空。"},{"w":"锦衾","v":"织锦的被子。"},{"w":"控","v":"拉开。"},{"w":"都护","v":"官名，安西都护府长官。"},{"w":"瀚海","v":"大沙漠。"},{"w":"阑干","v":"纵横交错的样子。"},{"w":"辕门","v":"军营大门。"}],"yi":"北风卷地而来百草折断，胡地八月就飞起大雪。忽如一夜春风来，千树万树梨花开。雪散入珠帘沾湿罗幕，狐裘不暖锦被也薄。将军角弓冻得拉不开，都护铁衣冷得难穿着。瀚海纵横百丈坚冰，愁云惨淡万里凝结。中军设酒宴饮归客，胡琴琵琶与羌笛齐奏。傍晚辕门外大雪纷纷，红旗冻得风吹不翻。轮台东门送君归去，去时大雪铺满天山路。山回路转不见君影，雪上空留马蹄的印迹。","shang":"「忽如一夜春风来，千树万树梨花开」化苦寒为奇丽，是咏雪千古第一名句。结句「雪上空留马行处」，以无言之景写无尽之情，深得送别之神。"},"060":{"ti":"杜甫在韦讽家观曹霸所画九马图而作。由画马追忆开元盛时天马之盛，收于金粟堆前龙媒去尽，盛衰之感极深。","zhu":[{"w":"江都王","v":"唐宗室李绪，善画鞍马。"},{"w":"乘黄","v":"传说中的神马，喻曹霸画艺。"},{"w":"照夜白","v":"唐玄宗所乘名马。"},{"w":"婕妤","v":"宫中女官名。"},{"w":"拳毛騧","v":"唐太宗六骏之一。"},{"w":"狮子花","v":"郭子仪进献的名马。"},{"w":"缟素","v":"白绢，指画绢。"},{"w":"长楸","v":"高大的楸树，借指大道。"},{"w":"腾骧","v":"马腾跃奔驰。"},{"w":"金粟堆","v":"唐玄宗泰陵所在金粟山。"}],"yi":"国初以来画鞍马，神妙独数江都王；将军得名三十载，人间又见真乘黄。曾貌先帝照夜白，龙池十日飞霹雳；内府玛瑙盘赐下，才人传诏来索取。盘赐将军拜舞归，贵戚权门得笔迹，始觉屏障生光辉。新图二马：一拟太宗拳毛騧，一拟郭家狮子花——皆骑战一敌万，缟素漠漠开风沙。其余七匹亦殊绝，迥若寒空杂烟雪；九马争神骏，顾视清高气深稳。忆昔巡幸新丰宫，三万匹腾骧磊落，皆与此图筋骨同。如今金粟堆前松柏里，龙媒去尽鸟呼风。","shang":"以九马之画与三万匹之盛对写，以「龙媒去尽鸟呼风」一寂收千笔之闹，盛衰全在此一笔。写马亦写时代，是杜诗「诗史」笔法在题画诗中的极致。"},"061":{"ti":"杜甫赠画马名家曹霸。曹霸为曹魏之后，开元中名重一时，安史乱后流落漂泊。诗写其画艺之绝与身世之穷，感慨深沉。","zhu":[{"w":"魏武","v":"魏武帝曹操，曹霸为其后裔。"},{"w":"卫夫人","v":"东晋女书法家，王羲之曾从其学书。"},{"w":"王右军","v":"王羲之，官右军将军。"},{"w":"南熏殿","v":"长安兴庆宫内殿名。"},{"w":"凌烟功臣","v":"唐太宗图画功臣于凌烟阁。"},{"w":"褒公鄂公","v":"褒国公段志玄、鄂国公尉迟敬德。"},{"w":"玉花骢","v":"玄宗的名马。"},{"w":"赤墀","v":"宫殿中丹漆的台阶。"},{"w":"韩干","v":"曹霸弟子，亦以画马名。"},{"w":"坎壈","v":"困顿不得志。"}],"yi":"将军是魏武子孙，今为庶人。英雄割据虽已矣，文采风流今尚存。丹青不知老将至，富贵于我如浮云。开元中承恩数上南熏殿：凌烟功臣少颜色，将军下笔开生面——英姿飒爽犹酣战。先帝天马玉花骢，画工如山貌不同；诏谓将军拂绢素，斯须九重真龙出，一洗万古凡马空！弟子韩干早入室，却画肉不画骨，忍使骅骝气凋丧。即今漂泊干戈际，屡貌寻常行路人；途穷反遭俗眼白，世上未有如公贫。但看古来盛名下，终日坎壈缠其身！","shang":"「斯须九重真龙出，一洗万古凡马空」赞画之极笔；「将军画善盖有神」一转，落到「屡貌寻常行路人」，盛衰两截，悲慨万千。结句「但看古来盛名下，终日坎壈缠其身」，为千古才人同声一哭。"},"062":{"ti":"杜甫寄韩注（谏议大夫）。以「美人娟娟隔秋水」起兴，比韩注为功成身退的张良，忧国之人与霞外之人相望而不得。","zhu":[{"w":"谏议","v":"谏议大夫，掌规谏之官。韩注，其人不详。"},{"w":"美人","v":"喻所思念的贤者。"},{"w":"娟娟","v":"秀美的样子。"},{"w":"八荒","v":"八方极远之地。"},{"w":"鸿飞冥冥","v":"鸿雁飞入高远的天空，喻贤者远引。"},{"w":"玉京","v":"道教天帝所居。"},{"w":"赤松子","v":"传说中的仙人，此以仙喻韩注之隐。"},{"w":"韩张良","v":"汉张良，功成后愿从赤松子游。"},{"w":"帷幄","v":"军中帐幕，「运筹帷幄」。"},{"w":"周南留滞","v":"汉武帝时太史公司马谈滞留周南，抱憾而终。喻贤者见弃。"}],"yi":"如今我不乐而思岳阳，欲奋飞而病在床。美人娟娟隔秋水，濯足洞庭、望尽八荒。鸿飞冥冥日月白，青枫叶赤天雨霜。玉京群帝集北斗，芙蓉旌旗影动潇湘；星宫之君醉琼浆，羽人稀少不在旁。似闻昨者赤松子，恐是汉代韩张良——昔随刘氏定长安，帷幄未改神惨伤。国家成败吾岂敢，色难腥腐餐枫香。周南留滞古所惜，南极老人应寿昌。美人胡为隔秋水？焉得置之贡玉堂！","shang":"全篇以仙家意象写朝政之思，「美人胡为隔秋水」首尾呼应，一唱三叹。以张良拟韩注，既颂其功成身退，又惜其遁世，忧国之情与慕隐之思交织，是杜诗七古中最幽婉的一篇。"},"063":{"ti":"杜甫咏夔州孔明庙前古柏。以柏之柯如青铜、根如石喻孔明之节，末叹「古来材大难为用」，自寓身世。","zhu":[{"w":"孔明庙","v":"夔州（今重庆奉节）的诸葛亮祠。"},{"w":"柯","v":"树枝。"},{"w":"四十围","v":"围，两手合抱之长，极言树粗。"},{"w":"黛色","v":"青黑色。"},{"w":"二千尺","v":"极言树高，非实数。"},{"w":"际会","v":"遇合。谓君臣遇合于时。"},{"w":"锦亭","v":"成都锦江亭。"},{"w":"閟宫","v":"祠庙。成都先主庙与武侯祠相邻。"},{"w":"崔嵬","v":"高大的样子。"},{"w":"落落","v":"独立不群的样子。"}],"yi":"孔明庙前有老柏，柯如青铜根如石——双皮溜雨四十围，黛色参天二千尺。君臣已与时际会，树木犹为人爱惜。云来气接巫峡长，月出寒通雪山白。忆昨路绕锦亭东，先主武侯同閟宫。落落盘踞虽得地，冥冥孤高多烈风；扶持自是神明力，正直元因造化功。大厦如倾要梁栋，万牛回首丘山重；不露文章世已惊，未辞剪伐谁能送？苦心岂免容蝼蚁？香叶终经宿鸾凤。志士幽人莫怨嗟——古来材大难为用！","shang":"以四十围、二千尺的夸饰立其形象，以烈风孤高立其精神。「古来材大难为用」一句翻作结语，全篇咏柏化为咏怀，与李白「天生我材必有用」恰成悲欣两面。"},"064":{"ti":"杜甫在夔州观开元名舞伎公孙大娘的弟子李十二娘舞剑器，感五十年兴衰而作。题下原有长序，此诗雄浑顿挫，为七古名篇。","zhu":[{"w":"公孙氏","v":"公孙大娘，开元第一舞人。"},{"w":"低昂","v":"起伏。"},{"w":"羿射九日","v":"后羿射落九日的传说，喻剑光之疾。"},{"w":"骖龙翔","v":"驾龙飞翔。"},{"w":"白帝","v":"夔州，公孙舞艺传于其地。"},{"w":"澒洞","v":"弥漫无际。"},{"w":"梨园子弟","v":"玄宗所设梨园中的乐工。"},{"w":"金粟堆","v":"玄宗泰陵所在。"},{"w":"玳筵","v":"以玳瑁装饰坐具的盛宴。"}],"yi":"昔有佳人公孙氏，一舞剑器动四方——观者如山色沮丧，天地为之久低昂。剑光如羿射九日，矫如群帝骖龙翔；来如雷霆收震怒，罢如江海凝清光。如今绛唇珠袖两寂寞，晚有弟子传芬芳。临颍美人在白帝，妙舞此曲神扬扬。先帝侍女八千人，公孙剑器初第一。五十年间似反掌，风尘澒洞昏王室；梨园子弟散如烟，女乐余姿映寒日。金粟堆前木已拱，瞿塘石城草萧瑟。玳筵急管曲复终，乐极哀来月东出——老夫不知其所往，足茧荒山转愁疾。","shang":"「来如雷霆收震怒，罢如江海凝清光」十字写舞，有雷霆之力、江海之静，为古今咏舞之冠。一舞系五十年兴衰，乐极哀来，正见杜甫晚岁「感时」二字。"},"065":{"ti":"元结泛舟石鱼湖上醉后作歌。题下有序。以湖比洞庭、以山为酒樽，写狂歌醉饮的疏放，内里是避世之愁。","zhu":[{"w":"漫叟","v":"元结自号。序中语。"},{"w":"君山","v":"洞庭湖中君山，此借指湖中山石。"},{"w":"沼","v":"水池，此指湖为酒池。"},{"w":"洲鸟","v":"水中小洲（「鸟」通「屿」）。"},{"w":"废","v":"阻止。"},{"w":"长瓢","v":"大酒瓢。"},{"w":"巴丘","v":"山名，在洞庭湖边，此借指湖边山岩。"}],"yi":"石鱼湖啊好似洞庭，夏日水涨、君山青青。以山为酒樽，以水为酒池，酒徒历历坐满洲屿。长风连日掀起大浪，也不能拦住人运酒的船。我持长瓢坐上巴丘，酌酒遍饮四座以散愁。","shang":"短歌而气象阔大，山樽水沼，把一湖秋水当作酒国。醉语之下有「不能废人」的倔强与「以散愁」的沉痛，疏放其表、郁结其里。"},"066":{"ti":"韩愈游洛阳惠林寺题记诗。记黄昏到寺、夜卧清月、晓行山涧之游，结叹人生如此可乐、何必为人所鞿，是韩诗平易一路的代表作。","zhu":[{"w":"荦确","v":"山石险峻不平的样子。"},{"w":"行径微","v":"山路狭窄。"},{"w":"稀","v":"依稀可见。"},{"w":"疏粝","v":"粗糙的饭食。"},{"w":"烟霏","v":"山间云气。"},{"w":"松枥","v":"松树与枥树。"},{"w":"十围","v":"极言粗大。"},{"w":"局束","v":"拘束。"},{"w":"鞿","v":"马缰绳，喻束缚。"},{"w":"吾党二三子","v":"我的同游几位友人。语本《论语》。"}],"yi":"山石荦确路狭难行，黄昏到寺蝙蝠乱飞。登堂坐阶新雨初足，芭蕉叶大栀子花肥。僧说古壁佛画绝好，举火来照依稀可见。铺床拂席备好羹饭，粗粝也足以饱我饥肠。夜深静卧百虫声绝，清月出岭光入门扉。天明独去不辨道路，出入高下穷尽烟霏。山红涧碧纷然烂漫，时见松枥粗逾十围。当着溪流赤足踏石，水声激激清风吹衣。人生如此自有其乐，何必局促受制于人！我的同游二三子啊，怎能到老还不归隐！","shang":"以散文笔法记游，时间从黄昏到天明，一步一景，是「以文为诗」的典型。结句忽作浩叹，由山水之乐逼出仕途之缚，韩愈的真性情尽露。"},"067":{"ti":"韩愈与张署同贬南方，永贞改元遇赦而移官荆蛮，中秋夜共饮悲歌。听张歌而泪如雨，继以己歌自解，一郁一旷。","zhu":[{"w":"属","v":"劝酒。"},{"w":"九嶷","v":"山名，在今湖南宁远。"},{"w":"猩鼯","v":"猩猩与鼯鼠，南方山中野兽。"},{"w":"十生九死","v":"形容历尽艰险。"},{"w":"嗣皇","v":"新继位的皇帝，指唐宪宗。"},{"w":"夔皋","v":"舜时贤臣夔与皋陶，喻新任贤相。"},{"w":"大辟","v":"死刑。"},{"w":"州家","v":"州刺史。使家，观察使。"},{"w":"判司","v":"唐代对诸曹参军的统称，卑职。"},{"w":"捶楚","v":"鞭笞。"}],"yi":"纤云四卷天无河，清风月舒波。沙平水息，一杯相属君当歌。君歌酸楚辞且苦，未及听终泪如雨：洞庭连天九嶷高，蛟龙出没猩鼯号；十生九死到官所，幽居默默如藏逃；下床畏蛇食畏药，海气湿蛰熏腥臊。昨者州前槌大鼓，嗣皇继圣登夔皋；赦书一日行万里，罪从大辟皆除死。州家申名使家抑，坎轲只得移荆蛮；判司卑官不堪说，未免捶楚尘埃间。君歌且休听我歌，我歌与君殊科：一年明月今宵多，人生由命非由他。有酒不饮奈明何！","shang":"前半听歌尽写贬谪之惨，后半自歌强作旷达，「人生由命」四字，是无可如何之语。清景与苦语相激，悲愤之深遂成千古名篇。"},"068":{"ti":"韩愈谒南岳衡山庙，因祷而云开，得以尽览诸峰，遂宿寺题诗。写神之灵与己之困，牢骚以庄语出之。","zhu":[{"w":"五岳","v":"五大名山，衡山为南岳。"},{"w":"三公","v":"最高官爵，五岳祀典与三公同。"},{"w":"火维","v":"南方属火，故称火维。"},{"w":"神柄","v":"神的权柄。"},{"w":"紫盖","v":"衡山高峰名，与天柱、石廪、祝融并称。"},{"w":"伛偻","v":"曲身恭谨。"},{"w":"杯珓","v":"占卜用具，掷地观其俯仰以定吉凶。"},{"w":"曈昽","v":"天将亮的样子。"}],"yi":"五岳祭秩同三公，南方地荒、天假神柄独雄。喷云泄雾藏半腹，虽有绝顶谁能穷？我来正逢秋雨，潜心默祷似有应——须臾静扫众峰出，仰见突兀撑青空：紫盖连延接天柱，石廪腾掷堆祝融。森然魄动下马拜，松柏一径趋灵宫。粉墙丹柱动光彩，鬼物图画填青红。升阶荐脯酒，庙令老人教我掷珓，云此最吉余难同。窜逐蛮荒幸不死，侯王将相望久绝，神纵欲福难为功！夜投佛寺上高阁，猿鸣钟动不知曙，杲杲寒日生于东。","shang":"「潜心默祷若有应」云开见山，写神与至诚相感，奇崛如画。后半以掷珓自嘲——「神纵欲福难为功」，满腹不平借庙令之口说出，谑而弥悲。"},"069":{"ti":"韩愈咏石鼓文而作。详述石鼓之来历、字体、遭际，力主移置太学保护，一篇之中有考据、有议论、有感慨，为其以文为诗的巨制。","zhu":[{"w":"石鼓文","v":"刻于十枚鼓形石上的先秦文字，记秦国君游猎事。"},{"w":"宣王","v":"周宣王，中兴之主。"},{"w":"岐阳","v":"岐山之南，宣王蒐猎处。"},{"w":"蛟鼍","v":"蛟龙与鼍龙，喻笔画之遒劲。"},{"w":"鸾翔凤翥","v":"喻字体飞动之美。"},{"w":"二雅","v":"《诗经》大小雅。"},{"w":"掎摭","v":"摘取。"},{"w":"羲娥","v":"羲和（日）与嫦娥（月），喻日月。遗羲娥，谓漏掉日月光华。"},{"w":"媕婀","v":"犹豫不决。"}],"yi":"张生持石鼓文劝我作歌——少陵谪仙皆逝，我奈石鼓何！忆周纲凌迟，宣王愤起挥天戈：蒐猎岐阳、勒功万世，凿石作鼓留在山阿。雨淋日炙，鬼物守护；纸本毫发无讹，字体如鸾翔凤翥。陋儒编诗竟不收——掎摭星宿遗日月。忆昔蒙征为博士，濯冠告祭酒：如此至宝存岂多！若许留太学，剜苔剔藓安置妥帖。奈何大官老于事，牧童敲火、牛砺其角，日销月铄就埋没。安能以此上论列？石鼓之歌止于此，呜呼吾意其蹉跎！","shang":"典重如诰、奇崛如画，写古文字而字字有金石声。「孔子西行不到秦，掎摭星宿遗羲娥」评骘经史，气魄惊人。篇末「呜呼吾意其蹉跎」，忧文物之忧直贯千年。"},"070":{"ti":"柳宗元永州所作山水小诗。夜宿晓汲、欸乃一声，山水俱绿，末以「无心云相逐」自写心境，有禅意。","zhu":[{"w":"西岩","v":"永州西山。"},{"w":"清湘","v":"清澈的湘江水。"},{"w":"楚烛","v":"楚地所产的柴烛，一作「竹」。"},{"w":"欸乃","v":"摇橹声或渔歌。"},{"w":"中流","v":"江心水中央。"}],"yi":"渔翁夜里傍着西岩安宿，清晨汲清湘之水、燃楚竹为火。日出烟消已不见人影，欸乃一声，山水忽然全绿。回看天际驾舟下中流，岩上无心白云相互追逐。","shang":"「烟销日出不见人，欸乃一声山水绿」十一个字，声、色、光俱动，为历代诗家倾服。苏东坡谓其有奇趣。末句「云无心」暗用陶渊明，人隐于渔，禅意自足。"},"071":{"ti":"白居易元和元年作。陈鸿《长恨歌传》记其与王质夫游仙游寺，感玄宗杨妃事而作。一气舒卷百二十句，从倾国之恋写到天上人间之恨。","zhu":[{"w":"汉皇","v":"借汉武帝指唐玄宗。"},{"w":"倾国","v":"倾国倾城的美人。"},{"w":"御宇","v":"统治天下。"},{"w":"凝脂","v":"凝洁的脂膏，喻肌肤。"},{"w":"金步摇","v":"缀金珠的首饰，行则摇动。"},{"w":"列士","v":"封官爵。杨氏姊妹兄弟皆受封。"},{"w":"鼙鼓","v":"战鼓，指安禄山叛军。"},{"w":"翠华","v":"以翠羽为饰的仪仗，指皇帝车驾。"},{"w":"六军","v":"皇帝的禁军。"},{"w":"蛾眉","v":"美人，指杨贵妃。"}],"yi":"汉皇重色，杨家女一朝选在君侧——回眸一笑百媚生，六宫粉黛无颜色。从此君王不早朝，三千宠爱在一身。渔阳鼙鼓动地来，惊破霓裳羽衣曲！六军不发，宛转蛾眉马前死——掩面救不得，血泪相和流。归来芙蓉如面柳如眉，对此如何不泪垂！孤灯挑尽未成眠，魂魄不入梦。方士上穷碧落下黄泉，海上觅得太真——梨花一枝春带雨。钿合寄情，重申长生殿私誓：在天愿作比翼鸟，在地愿为连理枝。天长地久有时尽，此恨绵绵无绝期！","shang":"以叙事之笔写情之极致：前半写盛，铺张至极；马嵬一转，字字血泪；后半仙境寻魂，恍惚缠绵。结句「天长地久有时尽，此恨绵绵无绝期」，以有限之天地衬无限之恨，成千古绝唱。"},"072":{"ti":"白居易贬江州司马，秋夜浔阳江头送客，闻长安倡女弹琵琶，自诉身世，遂有此篇。题下有序。","zhu":[{"w":"浔阳江","v":"长江流经浔阳（今九江）的一段。"},{"w":"荻花","v":"芦荻的花。"},{"w":"管弦","v":"管乐器与弦乐器，指音乐。"},{"w":"掩抑","v":"声音低沉压抑。"},{"w":"霓裳","v":"《霓裳羽衣曲》；六么，当时流行的曲子。"},{"w":"嘈嘈切切","v":"重弦声沉重、细弦声轻促。"},{"w":"间关","v":"鸟鸣声。"},{"w":"幽咽","v":"泉水受阻的呜咽声。"},{"w":"银瓶乍破","v":"乐声突然激越如银瓶破裂、铁骑冲出。"},{"w":"虾蟆陵","v":"长安东南曲坊，歌楼聚集之地。"}],"yi":"浔阳江头夜送客，忽闻水上琵琶声——主人忘归客不发。千呼万唤始出来，犹抱琵琶半遮面。未成曲调先有情：大珠小珠落玉盘，此时无声胜有声；曲终四弦一声如裂帛——唯见江心秋月白。倡女自言本京城女，名属教坊第一部；今年欢笑复明年，老大嫁作商人妇，绕船月明江水寒。同是天涯沦落人，相逢何必曾相识！我谪居浔阳，今夜闻君琵琶语，如听仙乐耳暂明。为君翻作琵琶行——满座皆掩泣。座中泣下谁最多？江州司马青衫湿！","shang":"写乐声以万物为喻，珠落玉盘、泉咽莺语，字字皆声；「同是天涯沦落人」一句，把乐伎之愁与逐臣之恨打通，故满座掩泣而青衫独湿。叙事、写声、抒怀三者交融，为唐人七古第一等文字。"},"073":{"ti":"李商隐咏韩愈所撰《平淮西碑》。裴度平淮西，韩愈奉诏撰碑，后因谗被磨；李商隐力排众议，盛推韩碑，以诗存史。","zhu":[{"w":"元和天子","v":"唐宪宗李纯。"},{"w":"法宫","v":"皇帝治事的正殿。"},{"w":"封狼生貙","v":"喻藩镇世代相承为恶。貙、罴皆猛兽。"},{"w":"度","v":"宰相裴度，平淮西统帅。"},{"w":"都统","v":"统帅诸道兵马之职。"},{"w":"仪曹外郎","v":"礼部员外郎李宗闵等，掌书记。"},{"w":"愈","v":"韩愈，时任行军司马。"},{"w":"稽首","v":"叩首。"},{"w":"尧典舜典","v":"《尚书》篇名，喻碑文之典重。"},{"w":"汤盘孔鼎","v":"商汤浴盘、孔子庙鼎，器亡而文存。"}],"yi":"元和天子誓雪列圣之耻，坐镇法宫、四夷来朝。淮西贼据五十年，帝得圣相裴度——遇刺不死、腰悬相印为都统，十四万众如虎貔。李愬入蔡缚贼，功居第一；帝命从事韩愈为辞。愈斋戒濡染大笔，文成再拜铺于丹墀。碑高三丈、灵鳌负之，句奇语重喻者少，谗言入于天子，百尺长绳拽碑倒。然公之斯文若元气，先已入人肝脾；汤盘孔鼎，无其器而存其辞。愿书万本诵万过，传之七十二代，以为封禅玉检、明堂之基。","shang":"以诗存碑、以碑存史，句摹韩文之奇重。「公之斯文若元气，先时已入人肝脾」，对文字之力推崇至极。义山素以深情绵邈称，此篇独见奇崛，足见其备众体。"},"074":{"ti":"高适开元二十六年作。序云「客有从御史大夫张公出塞而还者，作燕歌行以示适」。写征战之苦、军中之弊，为唐人边塞七古压卷。","zhu":[{"w":"汉家","v":"借汉指唐。"},{"w":"烟尘","v":"战火。"},{"w":"横行","v":"纵横驰骋，所向无阻。"},{"w":"榆关","v":"山海关。"},{"w":"瀚海","v":"大沙漠。"},{"w":"狼山","v":"今内蒙古境内之山。"},{"w":"半死生","v":"死伤过半。"},{"w":"玉筋","v":"玉箸，喻思妇之泪。"},{"w":"三时","v":"早、午、晚，整天。"},{"w":"李将军","v":"汉飞将军李广，与士卒同甘苦。"}],"yi":"汉家烟尘在东北，汉将辞家破残贼。男儿重横行，天子赐颜色——摐金伐鼓下榆关，校尉羽书飞瀚海。山川萧条，胡骑凭陵；战士军前半死生，美人帐下犹歌舞！穷秋塞草衰，孤城斗兵稀；身当恩遇常轻敌，力尽关山未解围。铁衣远戍久，玉箸啼别后；少妇城南肠断，征人蓟北空回首。杀气整天作阵云，寒声一夜传刁斗。相看白刃血纷纷，死节岂顾勋？君不见沙场征战苦，至今犹忆李将军！","shang":"「战士军前半死生，美人帐下犹歌舞」一联，把批判写进对比里，是全诗之骨。征人与思妇两地分写，苍凉至极；结句追怀李广，讽今之意深藏。气势沉雄，音节悲壮，七古歌行至此而极。"},"075":{"ti":"李颀拟古从军行。写征人终岁劳苦、思归不得，结以「空见葡萄入汉家」，讽穷兵黩武之无益。","zhu":[{"w":"烽火","v":"边警之火。"},{"w":"交河","v":"在今新疆吐鲁番，唐安西都护府地。"},{"w":"行人","v":"出征的战士。"},{"w":"刁斗","v":"军中巡更铜器。"},{"w":"公主琵琶","v":"汉武帝以江都王女嫁乌孙，途中使人马上弹琵琶解忧。"},{"w":"胡雁","v":"西北胡地之雁。"},{"w":"玉门犹被遮","v":"汉武帝遣兵遮玉门关，阻罢兵之请。"},{"w":"逐轻车","v":"跟随轻车将军出征。"},{"w":"葡萄","v":"汉使自西域带回的葡萄种。"}],"yi":"白日登山望烽火，黄昏饮马傍交河。行人刁斗风沙暗，公主琵琶幽怨多。野云万里无城郭，雨雪纷纷连大漠。胡雁哀鸣夜夜飞，胡儿眼泪双双落。闻道玉门犹被遮，应将性命逐轻车。年年战骨埋荒外，空见葡萄入汉家！","shang":"前六句写边地之苦，声色皆冷；「胡雁哀鸣」「胡儿眼泪」连异族也为之悲，则征人之惨可知。结句以一粒葡萄收万里白骨，轻轻一转，重逾千钧，是唐人反战诗最含蓄而最有力的收束。"},"076":{"ti":"王维拟乐府《洛阳女儿行》。极写洛阳贵妇的骄奢，末以贫贱浣纱的越女对照，讽意冷峻。","zhu":[{"w":"才可","v":"恰好。才可容颜十五馀，谓年方十五六。"},{"w":"良人","v":"丈夫。"},{"w":"玉勒","v":"玉饰的马笼头。"},{"w":"脍鲤鱼","v":"切细的鲤鱼，极言馔食之精。"},{"w":"七香车","v":"以七种香木制成的车。"},{"w":"季伦","v":"晋石崇字季伦，以豪奢著称。"},{"w":"碧玉","v":"南朝汝南王侍妾，此指爱妾。"},{"w":"九微火","v":"灯。"},{"w":"赵李家","v":"汉成帝时赵飞燕、李平的亲属，代指贵戚。"},{"w":"越女","v":"西施，浣纱于若耶溪。"}],"yi":"洛阳女儿对门而居，容颜正好十五有余。丈夫乘骢马饰玉勒，侍女捧金盘切鲤鱼。画阁朱楼尽相望，红桃绿柳垂檐相向。罗帷送上七香车，宝扇迎归九华帐。丈夫富贵正当青春，意气骄奢赛过石季伦：亲教爱妾习舞，不惜珊瑚持赠他人。春窗天亮才灭九微火，灯花片片飞落花琐。戏罢从无理曲之时，妆成只是熏香闲坐。城中相识尽是繁华，日夜出入赵李之家。谁怜越女容颜如玉，贫贱江头自浣纱！","shang":"铺陈贵家之豪至十二句，忽然收在江头浣纱一个「谁怜」，冷光逼人。全篇以富丽之词行讽刺之实，是王维早期涉世之作的锋芒。"},"077":{"ti":"王维拟乐府《老将行》。写老将少年立功、老来弃置，闻边警而复请缨。壮志与悲愤俱见，是唐人咏老将的压卷。","zhu":[{"w":"邺下黄须儿","v":"曹操之子曹彰，须黄而勇，曹操称「黄须儿竟大奇」。"},{"w":"蒺藜","v":"铁蒺藜，战地障碍物。"},{"w":"数奇","v":"命运不好。汉武帝以为李广「数奇」。"},{"w":"故侯瓜","v":"秦东陵侯召平，亡国后种瓜长安。"},{"w":"先生柳","v":"陶渊明宅边五柳，自称五柳先生。"},{"w":"疏勒出飞泉","v":"汉耿恭守疏勒，祷泉得涌。"},{"w":"颍川空使酒","v":"汉灌夫罢官后借酒使气。"},{"w":"羽檄","v":"紧急军事文书。"},{"w":"星文","v":"剑上七星纹饰。"},{"w":"云中守","v":"汉魏尚为云中守，被削职，冯唐谏而复用。"}],"yi":"少年十五二十时，步行夺得胡马骑；射杀山中白额虎，肯数邺下黄须儿！一身转战三千里，一剑曾当百万师。自从弃置便衰朽，世事蹉跎成白首：昔时飞箭无全目，今日垂杨生左肘；路旁时卖故侯瓜，门前学种先生柳。贺兰山下阵如云，羽檄交驰日夕闻；诏书五道出将军，老将试拂铁衣如雪色，聊持宝剑动星文。愿得燕弓射大将，耻令越甲鸣吾君。莫嫌旧日云中守，犹堪一战取功勋！","shang":"三段章法：少年之勇、弃置之悲、请缨之壮，一气贯注。用典密而不滞，「莫嫌旧日云中守，犹堪一战取功勋」掷地有声。为老将鸣不平，亦为自己写照，是王维歌行的另一副笔墨。"},"078":{"ti":"王维拟陶渊明《桃花源记》而作。写渔舟入桃源、仙源不可寻，山水明秀，是唐诗中「诗中有画」的典范。","zhu":[{"w":"逐水","v":"顺着溪流。"},{"w":"古津","v":"古渡口。"},{"w":"隈隩","v":"山崖曲折幽深处。"},{"w":"攒云树","v":"树木攒聚如云。"},{"w":"武陵源","v":"陶记中桃花源，在武陵。"},{"w":"物外","v":"世俗之外。"},{"w":"房栊","v":"窗户，指居室。"},{"w":"灵境","v":"仙境。"},{"w":"游衍","v":"游乐流连。"},{"w":"桃花水","v":"桃花开时的春汛。"}],"yi":"渔舟顺水贪看山春，两岸桃花夹着古渡。行尽青溪不见一人，山口潜行、豁然平陆——近入千家散花之竹，居人衣冠未改秦俗。月明松下房栊静，日出云中鸡犬喧。惊问俗客争相来集，竞引还家细问都邑。他们初因避秦离了人间，成仙之后遂不复还；峡里谁知人间事？世上遥望只见云山。渔人尘心未尽、思乡而出洞，自谓旧路不迷——安知峰壑早已改变！当时只记青溪几曲到云林，春来遍地桃花水，不辨仙源何处寻。","shang":"「月明松下房栊静，日出云中鸡犬喧」一句静一句喧，仙家居处如在目前。以「不辨仙源何处寻」收束，仙凡两隔的怅惘悠然不尽。王维以画笔写桃源，遂与陶文并传。"},"079":{"ti":"李白初入长安时作（一说天宝初）。以「蜀道之难难于上青天」三致意，写蜀道之险、山川之奇，兼寓对时局的忧虑。","zhu":[{"w":"噫吁戏","v":"蜀地方言的惊叹声。"},{"w":"蚕丛、鱼凫","v":"传说中古蜀国的开国君主。"},{"w":"太白","v":"秦岭主峰太白山，在长安西。"},{"w":"六龙回日","v":"神话：羲和驾六龙载日车，此言山高能挡日车回转。"},{"w":"青泥","v":"青泥岭，入蜀要道，泥泞难行。"},{"w":"扪参历井","v":"山高入天，伸手可摸参、井二星宿。参为蜀之分野，井为秦之分野。"},{"w":"子规","v":"杜鹃鸟，啼声悲切。"},{"w":"剑阁","v":"大小剑山之间的栈道，为蜀地门户。"},{"w":"锦城","v":"锦官城，成都。"}],"yi":"噫吁戏！蜀道之难，难于上青天！蚕丛鱼凫开国茫然，四万八千岁始通人烟。西有太白鸟道；地崩山摧壮士死，然后天梯石栈方钩连。上有六龙回日之高标，下有冲波逆折之回川；黄鹤飞不过，猿猱愁攀援。青泥百步九折，扪参历井、抚膺长叹。悲鸟号古木，子规啼夜月；枯松倒挂倚绝壁，冰崖转石万壑雷！剑阁峥嵘，一夫当关、万夫莫开；所守或匪亲，化为狼与豺。锦城虽云乐，不如早还家——侧身西望，长自咨嗟！","shang":"三呼「蜀道之难」，一唱三叹，把山川之险写成神话之力。想象自蚕丛鱼凫直贯五丁开山，写景则枯松绝壁、转石万雷，奇之又奇。殷璠谓其「奇之又奇，自骚人以还，鲜有此体调」。"},"080":{"ti":"李白《长相思》其一。秋夜思长安，美人如花隔云端，天长路远、梦魂难度，是寄意君国或怀人之作，两解并存。","zhu":[{"w":"络纬","v":"纺织娘，鸣如纺线声。"},{"w":"金井阑","v":"雕饰精美的井栏。"},{"w":"簟","v":"竹席。"},{"w":"青冥","v":"青色的天空。"},{"w":"渌水","v":"清澈的水。"},{"w":"关山难","v":"关山难越。"}],"yi":"长相思啊，在长安。络纬秋啼金井栏边，微霜凄凄、竹席生寒。孤灯不明思欲断，卷起帷帘望月空长叹——美人如花，远隔云端。上有青冥之长天，下有渌水之波澜；天长路远，魂飞也苦，梦魂不到关山难。长相思啊，摧心肝！","shang":"以「美人如花隔云端」立象，上下青天渌水一层层把人隔远，写尽可望不可即之痛。结句「摧心肝」三字直露无遗，反成至情。此诗或寓忠悃于男女，情辞双绝。"},"081":{"ti":"李白《长相思》其二。拟女子口吻，日暮月明、愁不能眠，愿以琴声随春风寄与远戍之人。","zhu":[{"w":"赵瑟","v":"赵地之瑟。古称赵女善瑟。"},{"w":"凤凰柱","v":"瑟柱雕作凤凰形。"},{"w":"蜀琴","v":"蜀地所产之琴，琴尾刻鸳鸯。"},{"w":"燕然","v":"燕然山，今蒙古杭爱山，代指远戍之地。"},{"w":"横波目","v":"顾盼流波的眼睛。"}],"yi":"日色已尽、花含轻烟，月明如素、愁不能眠。赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。此曲有意无人传递，愿随春风寄到燕然。想念你啊，迢迢隔在青天那边。昔日顾盼流波的眼，如今成了流泪的泉。不信我肠断，归来对着明镜看我！","shang":"「昔日横波目，今成流泪泉」以目之今昔写情之变极，语新而痛深。结句「归来看取明镜前」邀人自证，痴语而有情。其笔致近六朝乐府而气韵远过之。"},"082":{"ti":"李白《行路难》其一。天宝三载赐金放还、离长安时作。冰塞黄河、雪满太行，忽以「长风破浪」自振，是李白最著名的失意之歌。","zhu":[{"w":"斗十千","v":"一斗酒值十千钱，极言酒美。"},{"w":"珍羞","v":"珍贵的菜肴。羞，同「馐」。"},{"w":"投箸","v":"放下筷子。"},{"w":"太行","v":"太行山。"},{"w":"垂钓碧溪","v":"吕尚（姜太公）未遇文王时，垂钓于磻溪。"},{"w":"乘舟梦日","v":"伊尹受商汤聘前，梦乘舟过日月之边。"},{"w":"歧路","v":"岔路。"},{"w":"长风破浪","v":"南朝宗悫语「愿乘长风破万里浪」。"},{"w":"云帆","v":"高帆。"},{"w":"济沧海","v":"渡过大海。"}],"yi":"金樽清酒斗十千，玉盘珍羞值万钱。可我停杯投箸不能食，拔剑四顾心茫然。想渡黄河，冰塞川；将登太行，雪满山。闲来垂钓碧溪之上，忽又乘舟梦日之边。行路难！行路难！多歧路，今安在？长风破浪会有时，直挂云帆济沧海！","shang":"前四句写宴而不能下咽，苦闷之极；中二比喻仕途之阻，忽引吕尚伊尹自期，跌宕生姿。三叹行路难之后，猛然翻出「直挂云帆济沧海」——盛唐的自信终不被愁压倒，此其所以为李白。"},"083":{"ti":"李白《行路难》其二。大道如青天而我独不得出，历数古来君臣遇合之难，结以「归去来」，愤极之音。","zhu":[{"w":"社中儿","v":"长安社里的少年。"},{"w":"赤鸡白狗","v":"斗鸡走狗的游戏。"},{"w":"弹剑作歌","v":"冯谖客孟尝君，弹铗而歌食无鱼。"},{"w":"曳裾王门","v":"在权贵门下作食客。曳裾，拖着衣襟。"},{"w":"淮阴市井","v":"韩信受淮阴少年胯下之辱。"},{"w":"贾生","v":"贾谊，为汉公卿所忌，贬长沙。"},{"w":"郭隗","v":"战国燕人，燕昭王师事之，筑黄金台招贤。"},{"w":"拥彗","v":"手持扫帚先行，为长者扫路，极言敬贤。"},{"w":"剧辛、乐毅","v":"自赵、魏来投燕昭王的贤士。"},{"w":"黄金台","v":"燕昭王置千金于台上以延天下士，故址在今易县。"}],"yi":"大道如青天，我独不得出。羞逐长安社中儿，赤鸡白狗赌梨栗。弹剑作歌奏苦声，曳裾王门不称情。淮阴市井笑韩信，汉朝公卿忌贾生。君不见昔时燕家重郭隗，拥彗折节无嫌猜；剧辛乐毅感恩分，输肝剖胆效英才。昭王白骨萦蔓草，谁人更扫黄金台？行路难，归去来！","shang":"「大道如青天，我独不得出」九个字，把天下之大与一身之穷写尽了。中间以四古人自况，怨而不失身份；结句「归去来」三字戛然而止，愤懑之情冲口而出，是李白失意诗中最直切的一篇。"},"084":{"ti":"李白《行路难》其三。历数伍子胥、屈原、陆机、李斯之死，皆功成不退之祸；结以张翰秋风之达，主张生前一杯酒。","zhu":[{"w":"颍川水","v":"许由洗耳于颍水。"},{"w":"首阳蕨","v":"伯夷叔齐采薇首阳山。"},{"w":"子胥","v":"伍子胥，功谏吴王，被迫自刭，尸投吴江。"},{"w":"陆机","v":"西晋才士，为成都王所杀，临刑叹华亭鹤唳不可复闻。"},{"w":"李斯","v":"秦相，腰斩咸阳，临刑叹不能再牵黄犬出上蔡东门逐狡兔。"},{"w":"税驾","v":"解驾停车，喻功成隐退。税，同「脱」。"},{"w":"华亭鹤唳","v":"陆机故里华亭的鹤鸣。"},{"w":"上蔡苍鹰","v":"李斯故乡上蔡的牵犬苍鹰。"},{"w":"张翰","v":"西晋吴郡人，见秋风起，思鲈脍莼羹，即辞官归，时人以为达。"},{"w":"达生","v":"通达人生的人。"}],"yi":"有耳莫洗颍川水，有口莫食首阳蕨。含光混世贵无名，何用孤高比云月？我看自古贤达之人，功成不退都殒其身：伍子胥既弃吴江之上，屈原终投湘水之滨；陆机雄才岂能自保？李斯税驾苦不早——华亭鹤唳哪里还听得见，上蔡苍鹰又何足称道！君不见吴中张翰称达生，秋风忽起便忆江东之行。且乐生前一杯酒，何须身后千载名！","shang":"连举四案，皆为「功成不退皆殒身」作证，是李白阅尽世事后的一声长叹。结以张翰之达，「且乐生前一杯酒」，看似颓放，实是全身远祸的清醒。三首《行路难》至此收束，愤而趋旷。"},"085":{"ti":"李白乐府《将进酒》。以黄河之水天上来起兴，痛饮狂歌之中，是「与尔同销万古愁」的深悲。","zhu":[{"w":"将进酒","v":"汉乐府鼓吹曲旧题。将，请。"},{"w":"青丝","v":"黑发。"},{"w":"会须","v":"应当。"},{"w":"岑夫子","v":"岑勋，排行老人称夫子。"},{"w":"丹丘生","v":"元丹丘，李白至交，隐居嵩山。"},{"w":"钟鼓馔玉","v":"鸣钟列鼎、食如玉之美，指富贵生活。"},{"w":"陈王","v":"曹植，封陈王，其《名都篇》有「归来宴平乐，美酒斗十千」。"},{"w":"平乐","v":"平乐观。"},{"w":"径须","v":"只管。"},{"w":"五花马","v":"名贵的马，毛色呈五花纹。"}],"yi":"君不见，黄河之水天上来，奔流到海不复回！君不见，高堂明镜悲白发，朝如青丝暮成雪。人生得意须尽欢，莫使金樽空对月。天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。岑夫子，丹丘生，将进酒，杯莫停！与君歌一曲：钟鼓馔玉不足贵，但愿长醉不复醒；古来圣贤皆寂寞，惟有饮者留其名。陈王昔时宴平乐，斗酒十千恣欢谑。主人何为言少钱？径须沽取对君酌。五花马，千金裘，呼儿将出换美酒，与尔同销万古愁！","shang":"起手两组「君不见」，把时间的大江与人生的白发并置，全篇由此撑开。狂歌痛饮之表，是「古来圣贤皆寂寞」的大悲凉；「万古愁」三字收束，愁乃真愁，酒乃真酒。歌行至此，气吞一世。"},"086":{"ti":"杜甫天宝十载前后作。记征戍之惨、租税之困，君不见三呼，为民请命，是反对穷兵黩武的诗史名篇。","zhu":[{"w":"辚辚","v":"车轮声。"},{"w":"萧萧","v":"马嘶声。"},{"w":"耶娘","v":"爷娘。耶，同「爷」。"},{"w":"干云霄","v":"冲上云霄。干，冲犯。"},{"w":"点行频","v":"按名征调频繁。点行，按名册征兵。"},{"w":"防河","v":"防守黄河以西，御吐蕃。"},{"w":"里正","v":"里长，乡里小吏。"},{"w":"武皇","v":"汉武帝，借指唐玄宗。"},{"w":"开边","v":"以武力开拓边疆。"},{"w":"青海头","v":"青海湖边，唐与吐蕃交战之地。"}],"yi":"车辚辚，马萧萧，行人弓箭各在腰。爷娘妻子走相送，牵衣顿足拦道哭，哭声直上干云霄！行人但云点行频：去时里正与裹头，归来头白还戍边！边庭流血成海水，武皇开边意未已。千村万落生荆杞，纵有健妇把锄犁，禾生陇亩无东西。长者虽有问，役夫敢申恨？县官急索租，租税从何出？信知生男恶，反是生女好——生男埋没随百草！君不见青海头，古来白骨无人收；新鬼烦冤旧鬼哭，天阴雨湿声啾啾！","shang":"以送别场面起，以鬼哭之境收，「点行频」三字直指病根。生男生女之叹，把时代的颠倒写到极处。句法杂言，声情与哭声相乱，是杜甫新题乐府的开山之作。"},"087":{"ti":"杜甫天宝年间作。上巳日曲江之畔，写杨氏兄妹曲江游宴之奢，结以「炙手可热势绝伦，慎莫近前丞相嗔」，讽意全在铺陈之后。","zhu":[{"w":"三月三日","v":"上巳节，唐时长安士女游曲江之日。"},{"w":"态浓意远","v":"妆饰浓艳而神态娴雅。"},{"w":"蹙金","v":"拈金线刺绣。"},{"w":"腰衱","v":"裙腰。"},{"w":"虢与秦","v":"杨贵妃三姊分封韩国、虢国、秦国夫人。"},{"w":"紫驼之峰","v":"驼峰，名贵食品。"},{"w":"餍饫","v":"饱食生腻。"},{"w":"黄门飞鞚","v":"宦官驰马。鞚，马勒。"},{"w":"要津","v":"重要渡口，喻据要职。"},{"w":"丞相嗔","v":"杨国忠时任右丞相。"}],"yi":"三月三日天气新，长安水边多丽人：态浓意远淑且真，肌理细腻骨肉匀。绣罗衣裳照暮春，蹙金孔雀银麒麟；翠微盍叶垂鬓唇，珠压腰衱稳称身。就中云幕椒房亲，赐名大国虢与秦。紫驼之峰出翠釜，水精之盘行素鳞；犀箸餍饫久未下，鸾刀缕切空纷纶。黄门飞鞚不动尘，御厨络绎送八珍。箫鼓哀吟感鬼神，宾从杂沓实要津。后来鞍马何逡巡，当轩下马入锦茵；杨花雪落覆白苹，青鸟飞去衔红巾。炙手可热势绝伦，慎莫近前丞相嗔！","shang":"全篇工笔铺写丽人之态、宴馔之奢，不着一句贬语；至「炙手可热」忽作冷喝，前文愈富丽，此处愈锋利。「杨花雪落覆白苹，青鸟飞去衔红巾」以物象暗示丑行，含蓄之极。"},"088":{"ti":"杜甫陷长安时作。春日潜行曲江，忆玄宗贵妃游宴之盛，写马嵬之变，兴亡之泪倾于笔端。","zhu":[{"w":"吞声哭","v":"不敢放声而泣。"},{"w":"潜行","v":"偷偷地走。"},{"w":"细柳新蒲","v":"细柳抽芽、新蒲泛绿，春景依旧。"},{"w":"霓旌","v":"皇帝仪仗中云霓般的旗帜。"},{"w":"同辇","v":"妃子得与皇帝同车，极言宠爱。"},{"w":"才人","v":"宫中女官。"},{"w":"明眸皓齿","v":"指杨贵妃。"},{"w":"清渭","v":"渭水清，马嵬坡南滨渭水，指贵妃葬处。"},{"w":"臆","v":"胸。"},{"w":"胡骑","v":"叛军的马队。"}],"yi":"少陵野老吞声哭，春日潜行曲江曲。江头宫殿锁千门，细柳新蒲为谁绿？忆昔霓旌下南苑，苑中万物生颜色。昭阳殿里第一人，同辇随君侍君侧。辇前才人带弓箭，白马嚼啮黄金勒；翻身向天仰射云，一箭正坠双飞翼。明眸皓齿今何在？血污游魂归不得！清渭东流剑阁深，去住彼此无消息。人生有情泪沾臆，江水江花岂终极？黄昏胡骑尘满城，欲往城南望城北。","shang":"以「细柳新蒲为谁绿」一句问尽兴亡；忆昔射落双飞翼之乐，正照「血污游魂」之惨。结句「欲往城南望城北」，心迷神乱，千古兴亡之痛尽在恍惚一望之间。"},"089":{"ti":"杜甫陷长安时作。见王孙流离路隅而私语叮咛：慎勿出口、善保千金躯。一片忠爱，与《哀江头》并为诗史。","zhu":[{"w":"头白乌","v":"白头乌鸦，古人以为不祥。"},{"w":"延秋门","v":"唐长安禁苑西门，玄宗由此出奔。"},{"w":"宝玦","v":"环形佩玉。"},{"w":"乞为奴","v":"请求卖身为奴。"},{"w":"隆准","v":"高鼻。汉高祖隆准而龙颜，此以汉拟唐。"},{"w":"交衢","v":"大路交叉处。"},{"w":"立斯须","v":"站一会儿。斯须，须臾。"},{"w":"橐驼","v":"骆驼，指叛军运载的驼队。"},{"w":"五陵佳气","v":"五陵上空兴旺的气象，谓唐室中兴有兆。"}],"yi":"长安城头头白乌，夜飞延秋门上呼；又向人家啄大屋，屋底达官走避胡。金鞭断折九马死，骨肉不待同驰驱。腰下宝玦青珊瑚，可怜王孙泣路隅！问之不肯道姓名，但道困苦乞为奴。已经百日窜荆棘，身上无有完肌肤。高帝子孙尽隆准，龙种自与常人殊；豺狼在邑龙在野，王孙善保千金躯。不敢长语临交衢，且为王孙立斯须。昨夜东风吹血腥，东来橐驼满旧都；花门剺面请雪耻，慎勿出口他人狙！哀哉王孙慎勿疏，五陵佳气无时无。","shang":"全篇以「泣路隅」之王孙为主，以「不敢长语」之老人为线，一声声叮咛皆是血泪。「五陵佳气无时无」收束，于至暗处犹存中兴之望，正见杜甫之忠厚。白描纪实，字字是史。"},"090":{"ti":"唐玄宗开元间东封泰山还途经曲阜，祭孔子而作。叹孔子栖栖一代而道穷，结以两楹之奠得偿梦兆，帝王朝祭，庄雅得体。","zhu":[{"w":"栖栖","v":"忙碌不安的样子。《论语》「丘何为是栖栖者与」。"},{"w":"鄹氏邑","v":"孔子生于鄹（邹）邑，在今山东曲阜。"},{"w":"鲁王宫","v":"汉鲁恭王坏孔子宅欲广其宫，闻金石丝竹之声乃止，故云宅即王宫。"},{"w":"叹凤","v":"凤鸟不至，孔子叹「吾已矣夫」，伤时无圣君。"},{"w":"伤麟","v":"鲁哀公获麟，孔子曰「吾道穷矣」。"},{"w":"两楹奠","v":"孔子夜梦坐奠于两楹之间，自料将死，后果然。"}],"yi":"夫子为何这样栖栖遑遑，奔走忙碌于一代之中？出生之地犹是鄹氏之邑，故居竟成了鲁王的宫城。见凤不至而叹生不逢时，伤麟获而怨吾道已穷。如今看你两楹之间的奠祭，当与当年梦中所见相同。","shang":"帝王之笔而绝无官气，中二联用孔子三事（鄹邑、王宫、麟凤）概括一生行藏。结以梦兆验为身后哀荣，哀而不伤。玄宗能诗如此，开元气象亦可见一斑。"},"091":{"ti":"张九龄遭贬后望月怀人而作。海上明月、天涯共时，一联气象，千古怀人之祖。","zhu":[{"w":"怀远","v":"怀念远方的亲人。"},{"w":"情人","v":"有情之人，指所怀者。"},{"w":"遥夜","v":"长夜。"},{"w":"竟夕","v":"整夜。"},{"w":"怜光满","v":"爱惜满屋月光。"},{"w":"露滋","v":"露水打湿衣裳。"},{"w":"盈手赠","v":"满手掬月光相赠。陆机「照之有余辉，揽之不盈手」。"},{"w":"梦佳期","v":"在梦中相会。"}],"yi":"海上生起一轮明月，天涯之人共此时刻。有情之人怨这长夜，整夜为相思所苦！吹灭烛火爱那满屋月光，披衣出门又觉露湿。不堪掬满手月光相赠，回去睡下、梦里再会佳期。","shang":"「海上生明月，天涯共此时」不着一个情字，而天下离人皆是此心，故能成千古共感之句。「不堪盈手赠」翻用陆机语而更见痴。张曲江之诗，冲淡而有远神。"},"092":{"ti":"王勃送别杜少府赴蜀州而作。一反送别悲酸之态，「海内存知己，天涯若比邻」，初唐气象正在此。","zhu":[{"w":"少府","v":"县尉的别称。"},{"w":"城阙","v":"指长安宫阙。"},{"w":"辅三秦","v":"以三秦为辅卫。三秦，关中之地。"},{"w":"五津","v":"岷江五个渡口，代指蜀州。"},{"w":"宦游","v":"离乡做官。"},{"w":"海内","v":"四海之内。"},{"w":"无为","v":"无须、不要。"},{"w":"歧路","v":"分别的路口。"}],"yi":"长安宫阙以三秦为护卫，风烟之中遥望蜀地五津。与你离别的心意相同——我们同是宦游之人。四海之内有知己，天涯也像近邻。不要在岔路口上，像小儿女一样泪湿佩巾。","shang":"首联已自壮阔，颈联更以旷达破送别之常调，一扫悲酸。「天涯若比邻」化用曹植「四海一何局，九州安所如」而气象更开。五律至此，声骨俱完。"},"093":{"ti":"骆宾王侍御史任上遭诬下狱，闻蝉而作。序中详言托物之旨。以蝉之高洁自况，幽愤之情托于寒蝉。","zhu":[{"w":"西路蝉声唱","v":"秋天蝉声起于西陆（指秋天）。"},{"w":"南冠","v":"楚囚之冠，代指囚徒。用锺仪事。"},{"w":"玄鬓","v":"蝉的黑翅，喻指蝉；又暗指妇女发式，兼含讽意。"},{"w":"白头吟","v":"乐府曲名，喻忧思深重，又暗用卓文君事，指被弃之冤。"},{"w":"露重","v":"露水浓重，蝉翼难飞。"},{"w":"响易沉","v":"风大蝉声易被淹没。"},{"w":"高洁","v":"蝉栖高枝、餐风饮露，古人以为高洁。"}],"yi":"秋天的蝉声唱起，我这南冠之囚客思更深。哪堪那玄色的蝉翼，来对着我这白头之吟！露重，它想飞也难进；风多，它鸣声容易沉没。没有人相信它的高洁，谁能为我表白此心？","shang":"「露重飞难进，风多响易沉」字字是蝉、字字是己，物我合一到无迹。结句「无人信高洁，谁为表予心」，冤愤与孤贞并发。初唐咏物，至此方见寄托之深。"},"094":{"ti":"杜审言和晋陵陆丞《早春游望》。宦游之人才惊物候之新，写江南早春而归思忽起，是初唐五律名篇。","zhu":[{"w":"陆丞","v":"晋陵（今常州）县丞陆某。"},{"w":"物候","v":"节令气候与景物变化。"},{"w":"淑气","v":"温和之气。"},{"w":"黄鸟","v":"黄莺。"},{"w":"苹","v":"水中浮草。"},{"w":"古调","v":"指陆丞原作，赞其有古人之风。"}],"yi":"只有在外做官的人，才对节物气候的新变格外心惊。云霞从海上涌出曙色，梅柳渡过江来春意萌生。和暖之气催着黄莺啼鸣，晴光转绿了水中的浮苹。忽然听到你歌吟古调，归乡之思欲使泪沾衣巾。","shang":"「云霞出海曙，梅柳渡江春」十字写尽江南早春，气象宏丽，被推为初唐五律第一。「独有」「偏惊」二字，把宦游人的敏感写得入微，故归思之来有根。"},"095":{"ti":"沈佺期拟乐府《杂诗》。闻道黄龙戍频年不撤兵，以闺月汉营两地共照，写征戍离散，结以取龙城之愿。","zhu":[{"w":"黄龙戍","v":"在今辽宁开原北，唐东北要塞。"},{"w":"解兵","v":"撤兵。"},{"w":"闺里月","v":"闺中人仰望之月。"},{"w":"汉家营","v":"唐军营帐（以汉拟唐）。"},{"w":"良人","v":"丈夫。"},{"w":"将旗鼓","v":"统率军队。将，率领。"},{"w":"龙城","v":"匈奴祭天之处，代指敌巢。"}],"yi":"听说黄龙戍上，连年不撤兵。可怜闺中的月色，长照在汉家军营。少妇今春的心意，良人昨夜的情思。谁能统率旗鼓，一举攻取龙城？","shang":"「可怜闺里月，长在汉家营」以月为线牵两地，月圆人离，最见巧思。尾联忽作壮语，使前文之怨有了出路——反对黩武而不失唐人本色。"},"096":{"ti":"宋之问流放泷州途中题大庾岭北驿。传说雁到此岭而回，我却不得归，瘴雨蛮烟、望乡见梅，凄婉入骨。","zhu":[{"w":"大庾岭","v":"五岭之一，在今江西大余、广东南雄交界，古多梅。"},{"w":"阳月","v":"农历十月。"},{"w":"至此回","v":"传说北雁南飞至大庾岭而止，春则北归。"},{"w":"殊未已","v":"还没有停止，谓行程尚远。"},{"w":"瘴","v":"南方湿热致病的瘴气。"},{"w":"陇头梅","v":"大庾岭上之梅，早开早落。"}],"yi":"十月南飞的大雁，传闻到此岭就回头。我的行程却还未止，何日才能归来？江面平静潮水初落，山林昏暗瘴气不开。明朝望乡之处，应见岭头梅花。","shang":"以雁「至此回」起，人「殊未已」应，物之有情反衬人之无归。「明朝望乡处，应见陇头梅」，借岭梅寄意，含蓄有致，贬谪诗中之上品。"},"097":{"ti":"王湾游吴中，泊舟北固山下而作。潮平岸阔、海日江春，气象初唐未有；「乡书何处达」一问，归思悠然。","zhu":[{"w":"次","v":"停泊。"},{"w":"北固山","v":"在今江苏镇江，北临长江。"},{"w":"客路","v":"旅人前行的路。"},{"w":"残夜","v":"天将亮未亮之时。"},{"w":"江春入旧年","v":"江上春意闯入旧年，谓岁末已含春意。"},{"w":"乡书","v":"家信。"},{"w":"归雁","v":"北归之雁，古传雁足传书。"}],"yi":"客路在青山之外，行舟在绿水之前。潮水平稳两岸开阔，风势正顺一帆高悬。海日从残夜中生出，江春闯入旧年。家书要寄到哪里？愿归雁捎到洛阳城边。","shang":"「海日生残夜，江春入旧年」旧年未尽而春意已生、夜色未残而朝日已出，写尽时序交替之妙，张说手题于政事堂，令朝中文士奉为楷式。结以归雁寄书，景大而情真。"},"098":{"ti":"常建清晨游破山寺题后禅院。曲径通幽、山光潭影，以钟磬作结，禅意与诗境俱足。","zhu":[{"w":"破山寺","v":"即兴福寺，在今江苏常熟虞山。"},{"w":"禅院","v":"寺中僧人修行之所。"},{"w":"初日","v":"初升的太阳。"},{"w":"曲径","v":"弯曲的小路。"},{"w":"禅房","v":"僧房。"},{"w":"山光","v":"山间日光。"},{"w":"潭影","v":"潭中倒影。"},{"w":"万籁","v":"一切声响。"},{"w":"钟磬","v":"寺院中诵经、斋饭时所敲的法器。"}],"yi":"清晨走进古寺，初日照着高林。曲径通向幽深处，禅房藏在花木之间。山光使鸟性欢悦，潭影使人心中空明。此刻万物声响俱寂，只有钟磬之音回荡。","shang":"「曲径通幽处，禅房花木深」为园林美学千古名句；「山光悦鸟性，潭影空人心」以「悦」「空」二字使物我互感。末以钟磬收束，愈静愈远，是唐代山水禅诗第一等境界。"},"099":{"ti":"岑参任右补阙时赠杜拾遗（杜甫）。同朝为官、晨入暮归，讽刺「圣朝无阙事，自觉谏书稀」，皮里阳秋。","zhu":[{"w":"左省","v":"门下省，杜甫任左拾遗属之。"},{"w":"丹陛","v":"宫殿红漆台阶。"},{"w":"分曹","v":"分署办公。岑参属中书省，居右。"},{"w":"紫微","v":"中书省的别称。"},{"w":"天仗","v":"皇帝的仪仗。"},{"w":"惹御香","v":"沾染宫殿的香烟。"},{"w":"谏书","v":"向皇帝进谏的奏章。"}],"yi":"与你联步快走于丹陛，分曹办公各限紫微。清晨随天仗入宫，傍晚惹着御香而归。白发悲看花落，青云羡慕鸟飞。圣朝本无阙失之事，自然觉得谏书稀少。","shang":"「白发悲花落，青云羡鸟飞」写朝官的空落，已见厌倦；「圣朝无阙事」是极清醒的反语——朝廷讳言阙失，谏官便无谏可上。沉讽出于恭维，深得温柔敦厚之旨。"}},"poets":{"杜甫":{"dates":"712—770","alias":"字子美，自号少陵野老，襄阳人","bio":"诗坛集大成者，沉郁顿挫，人称「诗史」「诗圣」，唐音之极。"},"李白":{"dates":"701—762","alias":"字太白，号青莲居士，陇西成纪人","bio":"诗仙。想象奇崛、气概飘逸，七古七绝独步一时。"},"王维":{"dates":"701—761","alias":"字摩诘，河东蒲州人","bio":"诗中有画，画中有诗；山水田园与禅意相融，人称「诗佛」。"},"李商隐":{"dates":"约813—约858","alias":"字义山，号玉溪生、樊南生，怀州河内人","bio":"晚唐婉丽深隐之宗，无题诸作缠绵悱恻，用典绵密，解人难尽。"},"孟浩然":{"dates":"689—740","alias":"名浩，字浩然，襄州襄阳人","bio":"盛唐山水田园诗人，清旷冲淡，与王维并称「王孟」。"},"韦应物":{"dates":"约737—约792","alias":"京兆长安人","bio":"诗风闲淡简远，五言古诗清真雅正，庶几陶渊明。"},"刘长卿":{"dates":"约726—约786","alias":"字文房，宣城人","bio":"自诩「五言长城」，五律精工，情韵凄婉。"},"杜牧":{"dates":"803—852","alias":"字牧之，号樊川居士，京兆万年人","bio":"晚唐俊爽之才，七绝明丽俊逸，咏史寄慨，与李商隐并称「小李杜」。"},"王昌龄":{"dates":"698—757","alias":"字少伯，京兆长安人","bio":"七绝圣手。边塞诗雄浑高华，「诗家夫子王江宁」。"},"岑参":{"dates":"约715—770","alias":"荆州江陵人","bio":"边塞诗巨擘，奇峭壮丽，写塞外风光如异域仙境。"},"李颀":{"dates":"约690—约751","alias":"赵郡人，居颍阳","bio":"七古兼擅音乐与边塞题材，笔力雄健，声情并茂。"},"白居易":{"dates":"772—846","alias":"字乐天，号香山居士，新郑人","bio":"诗风平易浅近，主张「文章合为时而著」，为通俗诗派之宗。"},"卢纶":{"dates":"739—799","alias":"字允言，河中蒲州人","bio":"「大历十才子」之一，边塞小诗雄浑，五律清劲。"},"张九龄":{"dates":"678—740","alias":"字子寿，韶州曲江人","bio":"开元名相，诗风典雅冲和，《感遇》寄兴幽深，开盛唐先声。"},"柳宗元":{"dates":"773—819","alias":"字子厚，河东人","bio":"唐宋八大家之一，山水诗孤峭清峻，寄贬谪之思。"},"张祜":{"dates":"约785—约852","alias":"字承吉，清河人","bio":"宫词擅名，笔致婉丽，多写宫怨与人生慨叹。"},"韩愈":{"dates":"768—824","alias":"字退之，河南河阳人","bio":"古文运动领袖，以文为诗，奇险雄肆，气盛言宜。"},"刘禹锡":{"dates":"772—842","alias":"字梦得，洛阳人","bio":"诗豪。豪宕爽朗，竹枝词与怀古之作俱得民歌神理。"},"温庭筠":{"dates":"约812—约870","alias":"字飞卿，太原祁人","bio":"花间词派鼻祖，诗浓艳绵密，与李商隐并称「温李」。"},"崔颢":{"dates":"约704—754","alias":"汴州人","bio":"《黄鹤楼》被推为唐人七律第一，早年诗浮艳，晚节忽变常体。"},"元稹":{"dates":"779—831","alias":"字微之，河南洛阳人","bio":"与白居易共倡新乐府，情诗深挚，「元白」并称。"},"钱起":{"dates":"约722—约780","alias":"字仲文，吴兴人","bio":"「大历十才子」之冠，诗清秀婉丽，以《省试湘灵鼓瑟》知名。"},"韩翃":{"dates":"生卒年不详","alias":"字君平，南阳人","bio":"「大历十才子」之一，「春城无处不飞花」为一时名句。"},"李益":{"dates":"750—约830","alias":"字君虞，陇西姑臧人","bio":"边塞七绝凄婉动人，音节神韵俱佳，教坊乐人争唱。"},"司空曙":{"dates":"约720—约790","alias":"字文初，广平人","bio":"「大历十才子」之一，诗多羁旅赠别，情致婉转。"},"常建":{"dates":"生卒年不详","alias":"长安人","bio":"诗思清幽，《题破山寺后禅院》一联为千古静境名句。"},"元结":{"dates":"719—772","alias":"字次山，河南鲁山人","bio":"新乐府先驱，诗朴质刚健，关切民生疾苦。"},"孟郊":{"dates":"751—814","alias":"字东野，湖州武康人","bio":"与韩愈并称「韩孟」，诗寒瘦奇警，《游子吟》仁厚感人。"},"高适":{"dates":"约704—765","alias":"字达夫，渤海蓨人","bio":"边塞诗高亢雄浑，晚年位至节度使，唐代诗人功名之极。"},"沈佺期":{"dates":"约656—约715","alias":"字云卿，相州内黄人","bio":"与宋之问共定五七言律诗格律，并称「沈宋」。"},"许浑":{"dates":"约791—约858","alias":"字用晦，润州丹阳人","bio":"多登临怀古之作，「山雨欲来风满楼」为传世名句。"},"马戴":{"dates":"约799—约869","alias":"字虞臣，曲阳人","bio":"晚唐五律名家，诗思清峭，为时人所推。"},"崔涂":{"dates":"约854—？","alias":"字礼山，江南人","bio":"屡试不第，诗多羁旅叹老，《除夜有怀》凄恻动人。"},"韦庄":{"dates":"约836—910","alias":"字端己，京兆杜陵人","bio":"花间词大家，诗亦清丽，《台城》怀古苍茫。"},"祖咏":{"dates":"699—746","alias":"洛阳人","bio":"诗简淡有逸气，《终南望余雪》以四句成篇，意尽而止。"},"王之涣":{"dates":"688—742","alias":"字季凌，并州人","bio":"存诗仅六首而首首名世，《登鹳雀楼》《凉州词》俱为绝唱。"},"刘方平":{"dates":"生卒年不详","alias":"河南洛阳人","bio":"工诗善画，七绝清婉，写春夜闺情别有韵致。"},"朱庆馀":{"dates":"生卒年不详","alias":"名可久，字庆馀，越州人","bio":"《近试上张水部》以闺意问荐，比拟入妙，为唐人名作。"},"丘为":{"dates":"约694—约789","alias":"嘉兴人","bio":"盛唐山水田园诗人，诗清雅恬淡，年寿最高。"},"綦毋潜":{"dates":"约692—约749","alias":"字孝通，虔州人","bio":"诗风清丽，与王维、李颀唱和，多写山林隐逸。"},"陈子昂":{"dates":"661—702","alias":"字伯玉，梓州射洪人","bio":"力反齐梁绮靡，倡「汉魏风骨」，《登幽州台歌》苍茫独绝。"},"唐玄宗":{"dates":"685—762","alias":"李隆基，陇西成纪人","bio":"开元盛世之君，通音律、能诗，诗风雍容典重。"},"王勃":{"dates":"650—676","alias":"字子安，绛州龙门人","bio":"「初唐四杰」之首，才高命短，《送杜少府》气象开阔。"},"骆宾王":{"dates":"约619—约687","alias":"字观光，婺州义乌人","bio":"「初唐四杰」之一，七言歌行雄放，《在狱咏蝉》托物寄愤。"},"杜审言":{"dates":"约645—约708","alias":"字必简，襄阳人","bio":"杜甫祖父，五律精严，为近体定型名家。"},"宋之问":{"dates":"约656—712","alias":"字延清，虢州弘农人","bio":"与沈佺期齐名，律诗格律精整，写景清丽。"},"王湾":{"dates":"生卒年不详","alias":"洛阳人","bio":"《次北固山下》「海日生残夜」一联，为盛唐名句，张说手题政事堂。"},"刘昚虚":{"dates":"约714—约767","alias":"字全乙，洪州新吴人","bio":"诗清淡幽远，为盛唐山水诗一脉。"},"戴叔伦":{"dates":"732—789","alias":"字幼公，润州金坛人","bio":"诗多写乱离民瘼，质朴深沉。"},"张籍":{"dates":"约766—约830","alias":"字文昌，和州乌江人","bio":"乐府名家，与王建并称「张王」，诗风平易近人。"},"张乔":{"dates":"生卒年不详","alias":"池州人","bio":"晚唐诗人，与许棠等号「咸通十哲」，诗清雅有思致。"},"杜荀鹤":{"dates":"846—904","alias":"字彦之，号九华山人，池州石埭人","bio":"晚唐现实派诗人，宫词与悯农之作俱见关切。"},"皎然":{"dates":"约720—约800","alias":"僧人，俗姓谢，字清昼，湖州人","bio":"唐代诗僧之冠，论诗有《诗式》，诗清澹自然。"},"崔曙":{"dates":"生卒年不详","alias":"宋州人","bio":"开元状元，《九日登望仙台》气象开阔，为七律名篇。"},"皇甫冉":{"dates":"约717—约770","alias":"字茂政，润州丹阳人","bio":"诗清颖秀拔，为大历间才名之士。"},"薛逢":{"dates":"约806—约874","alias":"字陶臣，蒲州河东人","bio":"诗多感时伤事，笔致清健。"},"秦韬玉":{"dates":"生卒年不详","alias":"字仲明，京兆人","bio":"《贫女》托贫女自伤，为晚唐咏怀名作。"},"裴迪":{"dates":"约716—？","alias":"关中（一说绛州）人","bio":"王维辋川别业挚友，唱和《辋川集》，诗清幽简淡。"},"李端":{"dates":"生卒年不详","alias":"字正己，赵州人","bio":"「大历十才子」之一，诗才敏捷，五律清婉。"},"王建":{"dates":"约767—约830","alias":"字仲初，颍川人","bio":"乐府名家，宫词百首传世，与张籍并称「张王」。"},"权德舆":{"dates":"759—818","alias":"字载之，天水略阳人","bio":"中唐台阁诗人，诗雅正温厚，权倾一时而不失士节。"},"贾岛":{"dates":"779—843","alias":"字浪仙，范阳人","bio":"苦吟诗人，「推敲」典出其人，诗清奇僻苦。"},"李频":{"dates":"约818—约876","alias":"字德新，寿昌人","bio":"诗清婉有思致，《渡汉江》写乡情真切。"},"金昌绪":{"dates":"生卒年不详","alias":"余杭人","bio":"存诗仅一首《春怨》，「打起黄莺儿」为五绝名篇。"},"西鄙人":{"dates":"生卒年不详","alias":"西部边地人，姓名不传","bio":"《哥舒歌》为西部民歌，颂哥舒翰守边之功。"},"贺知章":{"dates":"659—744","alias":"字季真，号四明狂客，越州永兴人","bio":"性旷放，诗清新自然，《回乡偶书》传诵不衰。"},"张旭":{"dates":"生卒年不详","alias":"字伯高，苏州吴人","bio":"草圣，亦工诗，七绝清逸，写桃花溪幽境。"},"张继":{"dates":"生卒年不详","alias":"字懿孙，襄州人","bio":"《枫桥夜泊》以钟声写旅愁，千古绝唱。"},"柳中庸":{"dates":"生卒年不详","alias":"名淡，河东人","bio":"诗多写边愁征怨，《征人怨》四句皆「怨」而著。"},"顾况":{"dates":"约727—约815","alias":"字逋翁，苏州海盐人","bio":"诗风朴野奇崛，多讽世之作，为中唐变体先导。"},"郑畋":{"dates":"825—883","alias":"字台文，荥阳人","bio":"晚唐名相，诗典雅，《马嵬坡》一绝含蓄有致。"},"韩偓":{"dates":"844—约923","alias":"字致尧，京兆万年人","bio":"晚唐艳诗名家，词致婉丽，《已凉》一绝为上品。"},"陈陶":{"dates":"约812—约885","alias":"字嵩伯，鄱阳人","bio":"诗多写边塞与游仙，《陇西行》悲慨动人。"},"张泌":{"dates":"生卒年不详","alias":"字子澄，淮南人","bio":"花间词人，小诗清丽，《寄人》一绝情深宛转。"},"无名氏":{"dates":"生卒年不详","alias":"姓名失传","bio":"《杂诗》一首作者佚名，见于选本，风格近唐人闺怨。"},"王翰":{"dates":"生卒年不详","alias":"字子羽，并州晋阳人","bio":"性豪放，《凉州词》「葡萄美酒夜光杯」脍炙人口。"},"杜秋娘":{"dates":"生卒年不详","alias":"金陵人，节度使李锜妾","bio":"《金缕衣》劝惜时，为唐诗中最著名的女子之作。"}}};
